#[derive(Clone, Debug, Default)]
struct SelectiveReadSnapshot {
    read_calls: u64,
    read_bytes: u64,
    range_sizes: Vec<u64>,
    /// Exact positional source ranges in call order.  Cursor controls do not
    /// populate this field because they deliberately measure a different
    /// legacy source contract.
    ranges: Vec<[u64; 3]>,
}

#[derive(Debug, Default)]
struct SelectiveReadMetrics {
    read_calls: AtomicU64,
    read_bytes: AtomicU64,
    range_sizes: Mutex<Vec<u64>>,
    ranges: Mutex<Vec<[u64; 3]>>,
}

impl SelectiveReadMetrics {
    fn reset(&self) -> io::Result<()> {
        self.read_calls.store(0, Ordering::SeqCst);
        self.read_bytes.store(0, Ordering::SeqCst);
        self.range_sizes
            .lock()
            .map_err(|_| io::Error::other("selective CFB range metrics are poisoned"))?
            .clear();
        self.ranges
            .lock()
            .map_err(|_| io::Error::other("selective CFB positional ranges are poisoned"))?
            .clear();
        Ok(())
    }

    fn snapshot(&self) -> io::Result<SelectiveReadSnapshot> {
        let mut range_sizes = self
            .range_sizes
            .lock()
            .map_err(|_| io::Error::other("selective CFB range metrics are poisoned"))?
            .clone();
        let ranges = self
            .ranges
            .lock()
            .map_err(|_| io::Error::other("selective CFB positional ranges are poisoned"))?
            .clone();
        range_sizes.sort_unstable();
        Ok(SelectiveReadSnapshot {
            read_calls: self.read_calls.load(Ordering::SeqCst),
            read_bytes: self.read_bytes.load(Ordering::SeqCst),
            range_sizes,
            ranges,
        })
    }

    fn record(&self, count: usize) -> io::Result<()> {
        let count = u64::try_from(count)
            .map_err(|_| io::Error::other("selective CFB range does not fit u64"))?;
        self.read_calls.fetch_add(1, Ordering::SeqCst);
        self.read_bytes.fetch_add(count, Ordering::SeqCst);
        self.range_sizes
            .lock()
            .map_err(|_| io::Error::other("selective CFB range metrics are poisoned"))?
            .push(count);
        Ok(())
    }

    fn record_positional(&self, offset: u64, requested: usize, returned: usize) -> io::Result<()> {
        self.record(returned)?;
        let requested = u64::try_from(requested)
            .map_err(|_| io::Error::other("selective CFB requested range does not fit u64"))?;
        let returned = u64::try_from(returned)
            .map_err(|_| io::Error::other("selective CFB returned range does not fit u64"))?;
        self.ranges
            .lock()
            .map_err(|_| io::Error::other("selective CFB positional ranges are poisoned"))?
            .push([offset, requested, returned]);
        Ok(())
    }
}

#[derive(Debug, Default)]
struct ConcurrentReadGate {
    entered: Mutex<usize>,
    ready: Condvar,
}

impl ConcurrentReadGate {
    fn mark_entered(&self) -> io::Result<()> {
        let mut entered = self
            .entered
            .lock()
            .map_err(|_| io::Error::other("CFB concurrent read gate is poisoned"))?;
        *entered = entered
            .checked_add(1)
            .ok_or_else(|| io::Error::other("CFB concurrent read gate count overflowed"))?;
        self.ready.notify_all();
        Ok(())
    }

    fn wait_for_all(&self, workers: usize) -> io::Result<()> {
        let mut entered = self
            .entered
            .lock()
            .map_err(|_| io::Error::other("CFB concurrent read gate is poisoned"))?;
        while *entered < workers {
            entered = self
                .ready
                .wait(entered)
                .map_err(|_| io::Error::other("CFB concurrent read gate is poisoned"))?;
        }
        Ok(())
    }
}

#[derive(Debug)]
struct SelectiveReadAt {
    bytes: Arc<Vec<u8>>,
    metrics: Arc<SelectiveReadMetrics>,
    version: SourceVersion,
    gate: Option<Arc<ConcurrentReadGate>>,
    direct_request_bytes: Option<usize>,
}

impl SelectiveReadAt {
    fn new(bytes: Arc<Vec<u8>>, metrics: Arc<SelectiveReadMetrics>) -> Self {
        Self {
            bytes,
            metrics,
            version: SourceVersion::new(
                NEXT_INSTRUMENTED_SOURCE_ID.fetch_add(1, Ordering::Relaxed),
                0,
            ),
            gate: None,
            direct_request_bytes: None,
        }
    }

    fn with_concurrent_gate(
        bytes: Arc<Vec<u8>>,
        metrics: Arc<SelectiveReadMetrics>,
        gate: Arc<ConcurrentReadGate>,
        direct_request_bytes: usize,
    ) -> Self {
        let mut source = Self::new(bytes, metrics);
        source.gate = Some(gate);
        source.direct_request_bytes = Some(direct_request_bytes);
        source
    }
}

impl ReadAt for SelectiveReadAt {
    fn len(&self) -> io::Result<u64> {
        u64::try_from(self.bytes.len())
            .map_err(|_| io::Error::other("selective CFB source length does not fit u64"))
    }

    fn read_at(&self, offset: u64, output: &mut [u8]) -> io::Result<usize> {
        if self.direct_request_bytes == Some(output.len())
            && let Some(gate) = &self.gate
        {
            gate.wait_for_all(2)?;
        }
        let start = usize::try_from(offset).unwrap_or(usize::MAX);
        let count = self
            .bytes
            .get(start..)
            .map_or(0, |remaining| remaining.len().min(output.len()));
        if count != 0 {
            output[..count].copy_from_slice(&self.bytes[start..start + count]);
        }
        self.metrics
            .record_positional(offset, output.len(), count)?;
        Ok(count)
    }

    fn version(&self) -> io::Result<SourceVersion> {
        Ok(self.version)
    }
}

#[derive(Debug)]
struct SelectiveCursor {
    bytes: Arc<Vec<u8>>,
    position: u64,
    metrics: Arc<SelectiveReadMetrics>,
}

impl SelectiveCursor {
    fn new(bytes: Arc<Vec<u8>>, metrics: Arc<SelectiveReadMetrics>) -> Self {
        Self {
            bytes,
            position: 0,
            metrics,
        }
    }
}

impl io::Read for SelectiveCursor {
    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
        let start = usize::try_from(self.position).unwrap_or(usize::MAX);
        let count = self
            .bytes
            .get(start..)
            .map_or(0, |remaining| remaining.len().min(output.len()));
        if count != 0 {
            output[..count].copy_from_slice(&self.bytes[start..start + count]);
            self.position =
                self.position
                    .checked_add(u64::try_from(count).map_err(|_| {
                        io::Error::other("selective CFB cursor count does not fit u64")
                    })?)
                    .ok_or_else(|| io::Error::other("selective CFB cursor position overflows"))?;
        }
        self.metrics.record(count)?;
        Ok(count)
    }
}

impl Seek for SelectiveCursor {
    fn seek(&mut self, position: SeekFrom) -> io::Result<u64> {
        let length = u64::try_from(self.bytes.len())
            .map_err(|_| io::Error::other("selective CFB cursor length does not fit u64"))?;
        let next = match position {
            SeekFrom::Start(offset) => i128::from(offset),
            SeekFrom::Current(offset) => i128::from(self.position) + i128::from(offset),
            SeekFrom::End(offset) => i128::from(length) + i128::from(offset),
        };
        if next < 0 || next > i128::from(u64::MAX) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "selective CFB cursor seek is outside the source",
            ));
        }
        self.position = u64::try_from(next)
            .map_err(|_| io::Error::other("selective CFB cursor seek does not fit u64"))?;
        Ok(self.position)
    }
}

/// Harness-only delayed cursor used to keep the legacy `Read + Seek` control
/// subject to the same bounded physical-request model as the positional
/// adapter. It never changes the production reader or writer APIs.
#[derive(Debug)]
struct SimulatedCursor {
    bytes: Arc<Vec<u8>>,
    position: u64,
    config: RangeSimulationConfig,
    metrics: Arc<SimulatedRangeMetrics>,
}

impl SimulatedCursor {
    fn new(
        bytes: Arc<Vec<u8>>,
        config: RangeSimulationConfig,
        metrics: Arc<SimulatedRangeMetrics>,
    ) -> Self {
        Self {
            bytes,
            position: 0,
            config,
            metrics,
        }
    }
}

impl io::Read for SimulatedCursor {
    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
        if output.is_empty() {
            return Ok(0);
        }
        if self.config.max_physical_range_bytes == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "range simulator maximum physical request must be non-zero",
            ));
        }
        if self.config.bandwidth_bytes_per_second == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "range simulator bandwidth must be non-zero",
            ));
        }
        let start = usize::try_from(self.position).unwrap_or(usize::MAX);
        let mut copied = 0usize;
        while copied < output.len() {
            let requested = (output.len() - copied).min(self.config.max_physical_range_bytes);
            std::thread::sleep(simulated_request_delay(self.config, requested));
            let physical_start = start.saturating_add(copied);
            let returned = self
                .bytes
                .get(physical_start..)
                .map_or(0, |remaining| remaining.len().min(requested));
            if returned != 0 {
                output[copied..copied + returned]
                    .copy_from_slice(&self.bytes[physical_start..physical_start + returned]);
            }
            self.metrics.record_physical(
                u64::try_from(physical_start)
                    .map_err(|_| io::Error::other("simulated cursor offset does not fit u64"))?,
                requested,
                returned,
            )?;
            copied += returned;
            if returned < requested {
                break;
            }
        }
        self.metrics.record_logical(copied)?;
        self.position = self
            .position
            .checked_add(u64::try_from(copied).map_err(|_error| {
                io::Error::other("simulated CFB cursor count does not fit u64")
            })?)
            .ok_or_else(|| io::Error::other("simulated CFB cursor position overflows"))?;
        Ok(copied)
    }
}

impl Seek for SimulatedCursor {
    fn seek(&mut self, position: SeekFrom) -> io::Result<u64> {
        let length = u64::try_from(self.bytes.len())
            .map_err(|_error| io::Error::other("simulated CFB cursor length does not fit u64"))?;
        let next = match position {
            SeekFrom::Start(offset) => i128::from(offset),
            SeekFrom::Current(offset) => i128::from(self.position) + i128::from(offset),
            SeekFrom::End(offset) => i128::from(length) + i128::from(offset),
        };
        if next < 0 || next > i128::from(u64::MAX) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "simulated CFB cursor seek is outside the source",
            ));
        }
        self.position = u64::try_from(next)
            .map_err(|_error| io::Error::other("simulated CFB cursor seek does not fit u64"))?;
        Ok(self.position)
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RangeSimulationSnapshot {
    logical_read_calls: u64,
    logical_read_bytes: u64,
    physical_request_count: u64,
    physical_request_bytes: u64,
    physical_request_sizes: Vec<u64>,
    physical_ranges: Vec<[u64; 3]>,
    physical_request_size_buckets: RequestSizeBuckets,
}

#[derive(Debug, Default)]
struct SimulatedRangeMetrics {
    logical_read_calls: AtomicU64,
    logical_read_bytes: AtomicU64,
    physical_request_count: AtomicU64,
    physical_request_bytes: AtomicU64,
    physical_request_sizes: Mutex<Vec<u64>>,
    physical_ranges: Mutex<Vec<[u64; 3]>>,
}

impl SimulatedRangeMetrics {
    fn snapshot(&self) -> io::Result<RangeSimulationSnapshot> {
        let mut sizes = self
            .physical_request_sizes
            .lock()
            .map_err(|_error| io::Error::other("range simulator request sizes are poisoned"))?
            .clone();
        sizes.sort_unstable();
        let mut buckets = RequestSizeBuckets::default();
        for &size in &sizes {
            buckets.observe(size);
        }
        Ok(RangeSimulationSnapshot {
            logical_read_calls: self.logical_read_calls.load(Ordering::SeqCst),
            logical_read_bytes: self.logical_read_bytes.load(Ordering::SeqCst),
            physical_request_count: self.physical_request_count.load(Ordering::SeqCst),
            physical_request_bytes: self.physical_request_bytes.load(Ordering::SeqCst),
            physical_request_sizes: sizes,
            physical_ranges: self
                .physical_ranges
                .lock()
                .map_err(|_error| io::Error::other("range simulator physical ranges are poisoned"))?
                .clone(),
            physical_request_size_buckets: buckets,
        })
    }

    fn reset(&self) -> io::Result<()> {
        self.logical_read_calls.store(0, Ordering::SeqCst);
        self.logical_read_bytes.store(0, Ordering::SeqCst);
        self.physical_request_count.store(0, Ordering::SeqCst);
        self.physical_request_bytes.store(0, Ordering::SeqCst);
        self.physical_request_sizes
            .lock()
            .map_err(|_error| io::Error::other("range simulator request sizes are poisoned"))?
            .clear();
        self.physical_ranges
            .lock()
            .map_err(|_error| io::Error::other("range simulator physical ranges are poisoned"))?
            .clear();
        Ok(())
    }

    fn record_logical(&self, bytes: usize) -> io::Result<()> {
        self.logical_read_calls.fetch_add(1, Ordering::SeqCst);
        self.logical_read_bytes.fetch_add(
            u64::try_from(bytes)
                .map_err(|_error| io::Error::other("logical read size does not fit u64"))?,
            Ordering::SeqCst,
        );
        Ok(())
    }

    fn record_physical(&self, offset: u64, requested: usize, returned: usize) -> io::Result<()> {
        let requested = u64::try_from(requested)
            .map_err(|_error| io::Error::other("physical request size does not fit u64"))?;
        let returned = u64::try_from(returned)
            .map_err(|_error| io::Error::other("physical return size does not fit u64"))?;
        if requested == 0 || returned > requested {
            return Err(io::Error::other(
                "physical range result is inconsistent with its request",
            ));
        }
        self.physical_request_count.fetch_add(1, Ordering::SeqCst);
        self.physical_request_bytes
            .fetch_add(returned, Ordering::SeqCst);
        self.physical_request_sizes
            .lock()
            .map_err(|_error| io::Error::other("range simulator request sizes are poisoned"))?
            .push(requested);
        self.physical_ranges
            .lock()
            .map_err(|_error| io::Error::other("range simulator physical ranges are poisoned"))?
            .push([offset, requested, returned]);
        Ok(())
    }
}

