fn run_odt_media_structural_paragraph_edit_save(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let target = SemanticShape::Medium.docx_paragraphs() / 2;
    let inserted = match case {
        Case::OdtMediaInsertParagraphEditSave => true,
        Case::OdtMediaRemoveParagraphEditSave => false,
        _ => return Err("non-structural ODT case passed to structural runner".into()),
    };
    let operation = if inserted { "insert" } else { "remove" };
    let mut expected_output_digest = None;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let started = Instant::now();
        let source = litchi_odt::transaction::Snapshot::from_bytes(corpus.archive.clone())?;
        let mut edit = source.edit();
        if inserted {
            edit.insert_paragraph(Position::new(target), ODT_MEDIA_INSERT_PARAGRAPH_TEXT)?;
        } else {
            edit.remove_paragraph(Position::new(target))?;
        }
        let commit = edit.commit()?;
        let bytes = commit.snapshot().as_bytes().to_vec();
        let duration = started.elapsed();
        if bytes == corpus.archive {
            return Err(
                format!("media-rich ODT paragraph {operation} reported an exact no-op").into(),
            );
        }

        verify_odt_media_structural_paragraph_archive(&bytes, inserted)?;
        let replayed = commit.patch().apply(&source)?;
        if replayed.as_bytes() != bytes {
            return Err(format!(
                "media-rich ODT paragraph {operation} patch replay differs from commit"
            )
            .into());
        }
        let restored = commit.patch().inverse().apply(&replayed)?;
        if restored.as_bytes() != corpus.archive {
            return Err(format!(
                "media-rich ODT paragraph {operation} inverse did not restore the source"
            )
            .into());
        }
        if commit.patch().apply(&replayed).is_ok() {
            return Err(format!(
                "media-rich ODT paragraph {operation} patch accepted a stale source"
            )
            .into());
        }
        let digest = sha256_hex(&bytes);
        if let Some(expected) = &expected_output_digest {
            if expected != &digest {
                return Err(format!(
                    "media-rich ODT paragraph {operation} publication is not deterministic"
                )
                .into());
            }
        } else {
            expected_output_digest = Some(digest);
        }
        std::hint::black_box(bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    let mut measured = result(case, corpus, elapsed, None);
    measured.output_sha256 = expected_output_digest;
    Ok(measured)
}

fn publish_odt_embedded_resources(
    case: Case,
    source: &litchi_odt::transaction::Snapshot,
    replacements: &[litchi_odt::package::embedded::EmbeddedResource],
    changes: &[litchi_odt::package::embedded::EmbeddedResourceChange],
) -> Result<litchi_odt::transaction::Commit, Box<dyn Error>> {
    let mut edit = source.edit();
    match case {
        Case::OdtEmbeddedResourceScalarReplaceSave => {
            for (index, replacement) in replacements.iter().enumerate() {
                edit.replace_embedded_image(index, replacement)?;
            }
        },
        Case::OdtEmbeddedResourceBatchReplaceSave => {
            edit.edit_embedded_resources(changes)?;
        },
        _ => return Err("non-resource ODT case passed to resource publisher".into()),
    }
    Ok(edit.commit()?)
}

fn verify_odt_embedded_resource_commit(
    case: Case,
    source: &litchi_odt::transaction::Snapshot,
    commit: &litchi_odt::transaction::Commit,
    expected: &[u8],
) -> Result<OdtResourceProjection, Box<dyn Error>> {
    let results_match = match case {
        Case::OdtEmbeddedResourceScalarReplaceSave => {
            commit.results().len() == ODT_RESOURCE_BATCH_COUNT
                && commit
                    .results()
                    .iter()
                    .all(|result| result == &litchi_odt::transaction::OperationResult::Unit)
        },
        Case::OdtEmbeddedResourceBatchReplaceSave => {
            commit.results() == [litchi_odt::transaction::OperationResult::Indices(Vec::new())]
        },
        _ => false,
    };
    if commit.snapshot().as_bytes() != expected || expected == source.as_bytes() || !results_match {
        return Err(format!(
            "ODT embedded-resource commit differs: exact_output={}, changed={}, results={:?}",
            commit.snapshot().as_bytes() == expected,
            expected != source.as_bytes(),
            commit.results()
        )
        .into());
    }
    let projection = verify_odt_resource_batch_archive(expected, true)?;
    verify_odt_resource_batch_raw_members(source.as_bytes(), expected)?;

    let replayed = commit.patch().apply(source)?;
    if replayed.as_bytes() != expected {
        return Err("ODT embedded-resource volatile replay differs from publication".into());
    }
    if commit.patch().inverse().apply(&replayed)?.as_bytes() != source.as_bytes() {
        return Err("ODT embedded-resource volatile inverse did not restore source".into());
    }
    if commit.patch().apply(&replayed).is_ok() {
        return Err("ODT embedded-resource volatile patch accepted stale source".into());
    }

    let durable_json = commit.patch().durable()?.to_deterministic_json()?;
    let durable = litchi_odt::transaction::DurablePatch::from_deterministic_json(&durable_json)?;
    let durable_replayed = durable.apply(source)?;
    if durable_replayed.as_bytes() != expected {
        return Err("ODT embedded-resource durable replay differs from publication".into());
    }
    if durable.inverse().apply(&durable_replayed)?.as_bytes() != source.as_bytes() {
        return Err("ODT embedded-resource durable inverse did not restore source".into());
    }
    if durable.apply(&durable_replayed).is_ok() {
        return Err("ODT embedded-resource durable patch accepted stale source".into());
    }
    Ok(projection)
}

fn run_odt_embedded_resource_publication(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.uses_odt_resource_batch() {
        return Err("non-resource ODT case passed to resource publication runner".into());
    }
    let source = litchi_odt::transaction::Snapshot::from_bytes(corpus.archive.clone())?;
    let replacements = (0..ODT_RESOURCE_BATCH_COUNT)
        .map(|index| odt_resource_batch_image(index, true))
        .collect::<Vec<_>>();
    let changes = replacements
        .iter()
        .enumerate()
        .map(|(index, replacement)| {
            litchi_odt::package::embedded::EmbeddedResourceChange::replace_image(
                Position::new(index),
                replacement,
            )
        })
        .collect::<Vec<_>>();

    let batch = publish_odt_embedded_resources(
        Case::OdtEmbeddedResourceBatchReplaceSave,
        &source,
        &replacements,
        &changes,
    )?;
    let expected_batch = batch.snapshot().as_bytes().to_vec();
    let batch_projection = verify_odt_embedded_resource_commit(
        Case::OdtEmbeddedResourceBatchReplaceSave,
        &source,
        &batch,
        &expected_batch,
    )?;
    let scalar = publish_odt_embedded_resources(
        Case::OdtEmbeddedResourceScalarReplaceSave,
        &source,
        &replacements,
        &changes,
    )?;
    let expected_scalar = scalar.snapshot().as_bytes().to_vec();
    let scalar_projection = verify_odt_embedded_resource_commit(
        Case::OdtEmbeddedResourceScalarReplaceSave,
        &source,
        &scalar,
        &expected_scalar,
    )?;
    if scalar_projection != batch_projection {
        return Err("matched ODT scalar and batch resource projections differ".into());
    }
    let expected = match case {
        Case::OdtEmbeddedResourceScalarReplaceSave => expected_scalar,
        Case::OdtEmbeddedResourceBatchReplaceSave => expected_batch,
        _ => return Err("non-resource ODT case reached output selection".into()),
    };

    let sink_ceiling = u64::try_from(expected.len())?;
    let expected_digest = sha256_hex(&expected);
    let mut elapsed = Vec::with_capacity(samples);
    let mut sinks = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let mut sink = CountingSink::bounded(sink_ceiling, sink_ceiling);
        sink.reserve_budget()?;
        let started = Instant::now();
        let commit = publish_odt_embedded_resources(case, &source, &replacements, &changes)?;
        sink.write_all(commit.snapshot().as_bytes())?;
        let duration = started.elapsed();

        if sink.bytes != expected {
            return Err("measured ODT embedded-resource publication differs from oracle".into());
        }
        let replayed = commit.patch().apply(&source)?;
        if replayed.as_bytes() != expected
            || commit.patch().inverse().apply(&replayed)?.as_bytes() != source.as_bytes()
            || commit.patch().apply(&replayed).is_ok()
        {
            return Err("measured ODT embedded-resource patch contract differs".into());
        }
        sinks.push(sink.summary());
        std::hint::black_box(commit);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    let sink = deterministic_sink_summary(&sinks, "ODT embedded-resource publication")?;
    let mut measured = result(case, corpus, elapsed, Some(sink));
    measured.output_sha256 = Some(expected_digest);
    Ok(measured)
}

fn run_semantic_ods(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let shape = semantic_shape(corpus)?;
    let sheet = shape.ods_sheet_count() / 2;
    let row = shape.ods_rows_per_sheet() / 2;
    let column = shape.ods_columns_per_sheet() / 2;
    let sheet_name = semantic_ods_sheet_name(sheet);
    let single_update = [semantic_ods_flat_index(shape, sheet, row, column)];
    let one_percent_updates = semantic_update_indices(shape.ods_cell_count())?;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        match case {
            Case::OdsSemanticCreateSmall => {
                let started = Instant::now();
                let bytes = semantic_ods_bytes(SemanticShape::Tiny)?;
                let duration = started.elapsed();
                let reopened = litchi_ods::Spreadsheet::from_bytes(bytes.clone())?;
                verify_semantic_ods(&reopened, SemanticShape::Tiny, false)?;
                if bytes != corpus.archive && shape == SemanticShape::Tiny {
                    return Err(
                        "semantic ODS creation differs from its deterministic corpus".into(),
                    );
                }
                std::hint::black_box(bytes);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticOpen => {
                let owned = corpus.archive.clone();
                let started = Instant::now();
                let spreadsheet = litchi_ods::Spreadsheet::from_bytes(owned)?;
                let duration = started.elapsed();
                verify_semantic_ods(&spreadsheet, shape, false)?;
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticListSheets => {
                let spreadsheet = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let sheets = spreadsheet.sheets();
                let duration = started.elapsed();
                if sheets.len() != shape.ods_sheet_count() {
                    return Err("semantic ODS sheet list differs from specification".into());
                }
                verify_semantic_ods(&spreadsheet, shape, false)?;
                std::hint::black_box(sheets);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticOneCell => {
                let spreadsheet = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let cell = spreadsheet
                    .cell(&sheet_name, row, column)
                    .ok_or("semantic ODS selected sheet is missing")?;
                let duration = started.elapsed();
                let litchi_ods::CellView::Stored(cell) = cell else {
                    return Err("semantic ODS selected cell is missing".into());
                };
                if cell.text != semantic_ods_text(sheet, row, column, false) {
                    return Err("semantic ODS selected cell differs from specification".into());
                }
                verify_semantic_ods(&spreadsheet, shape, false)?;
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticCellSweep => {
                let spreadsheet = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let stored_cells = semantic_ods_cell_sweep(&spreadsheet, shape)?;
                let duration = started.elapsed();
                if stored_cells != shape.ods_cell_count() {
                    return Err("semantic ODS stored-cell count differs from specification".into());
                }
                verify_semantic_ods(&spreadsheet, shape, false)?;
                std::hint::black_box(stored_cells);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticFullCellText => {
                let spreadsheet = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let text = semantic_ods_full_cell_text(&spreadsheet, shape)?;
                let duration = started.elapsed();
                verify_semantic_ods(&spreadsheet, shape, false)?;
                std::hint::black_box(text);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdsSemanticNoopEditSave
            | Case::OdsSemanticOneEditSave
            | Case::OdsSemanticOnePercentEditSave => {
                let owned = corpus.archive.clone();
                let started = Instant::now();
                let snapshot = litchi_ods::document::Snapshot::from_bytes(owned)?;
                let mut edit = snapshot.edit();
                let updated_indices = match case {
                    Case::OdsSemanticNoopEditSave => &[][..],
                    Case::OdsSemanticOneEditSave => &single_update[..],
                    Case::OdsSemanticOnePercentEditSave => &one_percent_updates,
                    _ => unreachable!("ODS edit/save case was matched above"),
                };
                if case == Case::OdsSemanticOneEditSave {
                    let text = semantic_ods_text(sheet, row, column, true);
                    edit.worksheets(|worksheets| {
                        worksheets
                            .set_cell(
                                sheet_name.as_str(),
                                row,
                                column,
                                litchi_ods::Cell::new(
                                    litchi_ods::CellValue::Text(text.clone()),
                                    text,
                                ),
                            )?
                            .ok_or_else(|| {
                                litchi_core::Error::InvalidFormat(
                                    "semantic ODS selected sheet is missing".to_owned(),
                                )
                            })?;
                        Ok(())
                    })?;
                } else if case == Case::OdsSemanticOnePercentEditSave {
                    let rows_per_sheet = shape.ods_rows_per_sheet();
                    let columns_per_sheet = shape.ods_columns_per_sheet();
                    let cells_per_sheet = rows_per_sheet * columns_per_sheet;
                    edit.worksheets(|worksheets| {
                        let mut changed = 0usize;
                        for selected_sheet in 0..shape.ods_sheet_count() {
                            let start = selected_sheet * cells_per_sheet;
                            let end = start + cells_per_sheet;
                            let changes = updated_indices
                                .iter()
                                .copied()
                                .filter(|index| (start..end).contains(index))
                                .map(|index| {
                                    let local = index - start;
                                    let selected_row = local / columns_per_sheet;
                                    let selected_column = local % columns_per_sheet;
                                    let text = semantic_ods_text(
                                        selected_sheet,
                                        selected_row,
                                        selected_column,
                                        true,
                                    );
                                    litchi_ods::worksheet::CellChange::new(
                                        selected_row,
                                        selected_column,
                                        litchi_ods::Cell::new(
                                            litchi_ods::CellValue::Text(text.clone()),
                                            text,
                                        ),
                                    )
                                })
                                .collect();
                            let selected_sheet_name = semantic_ods_sheet_name(selected_sheet);
                            changed += worksheets
                                .set_cells(selected_sheet_name.as_str(), changes)?
                                .ok_or_else(|| {
                                    litchi_core::Error::InvalidFormat(
                                        "semantic ODS selected sheet is missing".to_owned(),
                                    )
                                })?;
                        }
                        if changed != updated_indices.len() {
                            return Err(litchi_core::Error::InvalidFormat(
                                "semantic ODS 1% batch changed an unexpected cell count".to_owned(),
                            ));
                        }
                        Ok(())
                    })?;
                }
                let commit = edit.commit()?;
                let bytes = commit.snapshot().as_bytes().to_vec();
                let duration = started.elapsed();
                let updated = !updated_indices.is_empty();
                if (bytes != corpus.archive) != updated || commit.changed() != updated {
                    return Err(
                        "semantic ODS edit/save changed-state differs from specification".into(),
                    );
                }
                let reopened = litchi_ods::Spreadsheet::from_bytes(bytes.clone())?;
                verify_semantic_ods_updates(&reopened, shape, updated_indices)?;
                std::hint::black_box(bytes);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            _ => return Err("non-ODS semantic case passed to ODS runner".into()),
        }
    }
    Ok(result(case, corpus, elapsed, None))
}

fn run_ods_media_one_edit_save(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let shape = SemanticShape::Medium;
    let sheet = shape.ods_sheet_count() / 2;
    let row = shape.ods_rows_per_sheet() / 2;
    let column = shape.ods_columns_per_sheet() / 2;
    let sheet_name = semantic_ods_sheet_name(sheet);
    let mut expected_output_digest = None;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let started = Instant::now();
        let snapshot = litchi_ods::document::Snapshot::from_bytes(corpus.archive.clone())?;
        let mut edit = snapshot.edit();
        let text = semantic_ods_text(sheet, row, column, true);
        edit.worksheets(|worksheets| {
            worksheets
                .set_cell(
                    sheet_name.as_str(),
                    row,
                    column,
                    litchi_ods::Cell::new(litchi_ods::CellValue::Text(text.clone()), text),
                )?
                .ok_or_else(|| {
                    litchi_core::Error::InvalidFormat(
                        "media-rich ODS selected sheet is missing".to_owned(),
                    )
                })?;
            Ok(())
        })?;
        let commit = edit.commit()?;
        let bytes = commit.snapshot().as_bytes().to_vec();
        let duration = started.elapsed();
        if !commit.changed() || bytes == corpus.archive {
            return Err("media-rich ODS one-cell edit reported an exact no-op".into());
        }

        verify_ods_media_archive(&bytes, true)?;
        let digest = sha256_hex(&bytes);
        if let Some(expected) = &expected_output_digest {
            if expected != &digest {
                return Err("media-rich ODS publication is not deterministic".into());
            }
        } else {
            expected_output_digest = Some(digest);
        }
        std::hint::black_box(bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result(Case::OdsMediaOneEditSave, corpus, elapsed, None))
}

fn ods_source_cell_updates(
    one_percent: bool,
) -> Result<Vec<(usize, usize, usize)>, Box<dyn Error>> {
    let shape = SemanticShape::Medium;
    if one_percent {
        Ok(semantic_update_indices(shape.ods_cell_count())?
            .into_iter()
            .map(|index| {
                let cells_per_sheet = shape.ods_rows_per_sheet() * shape.ods_columns_per_sheet();
                let sheet = index / cells_per_sheet;
                let local = index % cells_per_sheet;
                (
                    sheet,
                    local / shape.ods_columns_per_sheet(),
                    local % shape.ods_columns_per_sheet(),
                )
            })
            .collect())
    } else {
        Ok(vec![(
            shape.ods_sheet_count() / 2,
            shape.ods_rows_per_sheet() / 2,
            shape.ods_columns_per_sheet() / 2,
        )])
    }
}

fn ods_source_cell_value(sheet: usize, row: usize, column: usize) -> litchi_ods::Cell {
    let text = semantic_ods_text(sheet, row, column, true);
    litchi_ods::Cell::new(litchi_ods::CellValue::Text(text.clone()), text)
}

fn stage_ods_source_cell_changes(
    edit: &mut litchi_ods::SourceCellEdit<'_>,
    updates: &[(usize, usize, usize)],
    one_percent: bool,
) -> Result<usize, Box<dyn Error>> {
    if !one_percent {
        let &(sheet, row, column) = updates
            .first()
            .ok_or("ODS source cell edit has no selected cell")?;
        let sheet_name = semantic_ods_sheet_name(sheet);
        let changed = edit
            .set_cell(
                sheet_name.as_str(),
                row,
                column,
                ods_source_cell_value(sheet, row, column),
            )?
            .ok_or("ODS source cell edit selected worksheet is missing")?;
        return Ok(usize::from(changed));
    }

    let mut changed = 0usize;
    for sheet in 0..SemanticShape::Medium.ods_sheet_count() {
        let changes = updates
            .iter()
            .copied()
            .filter(|(selected_sheet, _, _)| *selected_sheet == sheet)
            .map(|(_, row, column)| {
                litchi_ods::worksheet::CellChange::new(
                    row,
                    column,
                    ods_source_cell_value(sheet, row, column),
                )
            })
            .collect::<Vec<_>>();
        if changes.is_empty() {
            continue;
        }
        let sheet_name = semantic_ods_sheet_name(sheet);
        changed += edit
            .set_cells(sheet_name.as_str(), changes)?
            .ok_or("ODS source cell edit selected worksheet is missing")?;
    }
    if changed != updates.len() {
        return Err("ODS source cell edit changed an unexpected cell count".into());
    }
    Ok(changed)
}

fn stage_ods_owned_cell_changes(
    edit: &mut litchi_ods::document::Edit,
    updates: &[(usize, usize, usize)],
    one_percent: bool,
) -> Result<usize, Box<dyn Error>> {
    let mut changed = 0usize;
    edit.worksheets(|worksheets| {
        if !one_percent {
            let &(sheet, row, column) = updates.first().ok_or_else(|| {
                litchi_core::Error::InvalidFormat("ODS owned cell edit has no selected cell".into())
            })?;
            let sheet_name = semantic_ods_sheet_name(sheet);
            worksheets
                .set_cell(
                    sheet_name.as_str(),
                    row,
                    column,
                    ods_source_cell_value(sheet, row, column),
                )?
                .ok_or_else(|| {
                    litchi_core::Error::InvalidFormat(
                        "ODS owned cell edit selected worksheet is missing".into(),
                    )
                })?;
            changed = 1;
            return Ok(());
        }

        for sheet in 0..SemanticShape::Medium.ods_sheet_count() {
            let changes = updates
                .iter()
                .copied()
                .filter(|(selected_sheet, _, _)| *selected_sheet == sheet)
                .map(|(_, row, column)| {
                    litchi_ods::worksheet::CellChange::new(
                        row,
                        column,
                        ods_source_cell_value(sheet, row, column),
                    )
                })
                .collect::<Vec<_>>();
            if changes.is_empty() {
                continue;
            }
            let sheet_name = semantic_ods_sheet_name(sheet);
            changed += worksheets
                .set_cells(sheet_name.as_str(), changes)?
                .ok_or_else(|| {
                    litchi_core::Error::InvalidFormat(
                        "ODS owned cell edit selected worksheet is missing".into(),
                    )
                })?;
        }
        Ok(())
    })?;
    if changed != updates.len() {
        return Err("ODS owned cell edit changed an unexpected cell count".into());
    }
    Ok(changed)
}

fn ods_source_cell_update_indices(updates: &[(usize, usize, usize)]) -> Vec<usize> {
    updates
        .iter()
        .map(|&(sheet, row, column)| {
            semantic_ods_flat_index(SemanticShape::Medium, sheet, row, column)
        })
        .collect()
}

fn expected_ods_source_cell_output(
    corpus: &Corpus,
    updates: &[(usize, usize, usize)],
    one_percent: bool,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let source = Arc::new(OwnedSource::new(corpus.archive.clone()));
    let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source)?;
    let mut edit = owner.edit_cells()?;
    let changed = stage_ods_source_cell_changes(&mut edit, updates, one_percent)?;
    let commit = edit.commit()?;
    if changed != commit.changed_cells() {
        return Err("ODS source cell commit changed an unexpected cell count".into());
    }
    let mut output = Vec::new();
    let report = commit.write_to(&mut output)?;
    if report.changed_cells() != updates.len() || report.bytes() != output.len() as u64 {
        return Err("ODS source cell publication report differs from output".into());
    }
    Ok(output)
}

fn expected_ods_owned_cell_output(
    corpus: &Corpus,
    updates: &[(usize, usize, usize)],
    one_percent: bool,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let snapshot = litchi_ods::document::Snapshot::from_bytes(corpus.archive.clone())?;
    let mut edit = snapshot.edit();
    stage_ods_owned_cell_changes(&mut edit, updates, one_percent)?;
    let commit = edit.commit()?;
    if !commit.changed() {
        return Err("ODS owned cell edit unexpectedly reported an exact no-op".into());
    }
    Ok(commit.snapshot().as_bytes().to_vec())
}

fn verify_ods_source_cell_output(
    corpus: &Corpus,
    output: &[u8],
    updates: &[(usize, usize, usize)],
    source_backed: bool,
) -> Result<(), Box<dyn Error>> {
    let indices = ods_source_cell_update_indices(updates);
    let reopened = litchi_ods::Spreadsheet::from_bytes(output.to_vec())?;
    verify_semantic_ods_updates(&reopened, SemanticShape::Medium, &indices)?;
    let package = litchi_odf_common::core::OwnedPackage::from_bytes(output.to_vec())?;
    let package = package.package()?;
    for index in 0..ODS_MEDIA_ENTRY_COUNT {
        let path = ods_media_path(index);
        if package.manifest().get_media_type(&path) != Some("application/octet-stream")
            || package.get_file(&path)? != ods_media_payload(index)
        {
            return Err(format!("ODS source cell media payload differs for '{path}'").into());
        }
    }
    if sha256_hex(semantic_ods_full_cell_text(&reopened, SemanticShape::Medium)?.as_bytes())
        != sha256_hex(
            expected_semantic_ods_full_cell_text(SemanticShape::Medium, &indices).as_bytes(),
        )
    {
        return Err("ODS source cell semantic digest differs from the expected update set".into());
    }
    if source_backed {
        let identical = litchi_odf_common::package::raw_identical_members(&corpus.archive, output)
            .ok_or("ODS source cell raw-member comparison was unavailable")?;
        if identical.contains("content.xml") {
            return Err("ODS source cell publication left content.xml raw-identical".into());
        }
        for path in ArchiveReader::new(&corpus.archive)?.file_names() {
            if path != "content.xml" && !identical.contains(path) {
                return Err(format!(
                    "ODS source cell publication changed untouched member '{path}'"
                )
                .into());
            }
        }
    }
    Ok(())
}

fn verify_ods_source_cell_gates(
    corpus: &Corpus,
    updates: &[(usize, usize, usize)],
    one_percent: bool,
    expected_output: &[u8],
) -> Result<(), Box<dyn Error>> {
    let source = Arc::new(OwnedSource::new(corpus.archive.clone()));
    let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source)?;
    let before = owner.cell_snapshot()?;
    let mut edit = before.edit()?;
    stage_ods_source_cell_changes(&mut edit, updates, one_percent)?;
    let commit = edit.commit()?;

    let applied = commit.patch().apply(&before)?;
    if applied.content_xml() != commit.snapshot().content_xml()
        || applied.sheets() != commit.snapshot().sheets()
    {
        return Err("ODS source cell forward patch differs from its commit".into());
    }
    let restored = commit.patch().inverse().apply(&applied)?;
    if restored.content_xml() != before.content_xml() || restored.sheets() != before.sheets() {
        return Err("ODS source cell inverse patch did not restore its source".into());
    }
    let foreign_owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(Arc::new(
        OwnedSource::new(corpus.archive.clone()),
    ))?;
    if commit
        .patch()
        .apply(&foreign_owner.cell_snapshot()?)
        .is_ok()
    {
        return Err("ODS source cell patch accepted a foreign source snapshot".into());
    }

    let noop = owner.edit_cells()?.commit()?;
    let mut noop_output = Vec::new();
    let report = noop.write_to(&mut noop_output)?;
    if !report.is_no_op() || noop_output != corpus.archive {
        return Err("ODS source cell exact no-op gate failed".into());
    }

    let replacement_limit = commit.snapshot().content_xml().len().saturating_sub(1) as u64;
    let mut limited = Vec::new();
    let limit_error = commit
        .write_to_with_options(
            &mut limited,
            litchi_odf_common::core::SourceContentPublicationOptions::new()
                .with_max_replacement_bytes(replacement_limit),
        )
        .expect_err("ODS source cell replacement limit must reject");
    if !matches!(
        limit_error,
        litchi_odf_common::core::SourceContentPublicationError::LimitExceeded { .. }
    ) || !limited.is_empty()
    {
        return Err("ODS source cell replacement limit gate was not untouched".into());
    }

    let mut partial = PrefixFailSink {
        accepted: 0,
        fail_after: 7,
    };
    let partial_error = commit
        .write_to(&mut partial)
        .expect_err("ODS source cell partial sink must fail after its accepted prefix");
    if !matches!(
        partial_error,
        litchi_odf_common::core::SourceContentPublicationError::Sink {
            progress: litchi_odf_common::core::SourceContentPublicationProgress::Indeterminate {
                accepted_before: 7
            },
            ..
        }
    ) || partial_error.written() != 7
        || partial.accepted != 7
    {
        return Err("ODS source cell partial-sink gate lost exact progress".into());
    }
    verify_ods_source_cell_output(corpus, expected_output, updates, true)?;
    if sha256_hex(&corpus.archive) != corpus.manifest.archive_sha256
        || sha256_hex(expected_output).is_empty()
    {
        return Err("ODS source cell source/output hash gate failed".into());
    }
    Ok(())
}

fn run_ods_source_cell_edit_save(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != ODS_MEDIA_CORPUS_GENERATOR {
        return Err("ODS source cell selectors require the fixed media-rich corpus".into());
    }
    let source_backed = matches!(
        case,
        Case::OdsSourceBackedOneEditSave | Case::OdsSourceBackedOnePercentEditSave
    );
    let one_percent = matches!(
        case,
        Case::OdsSourceEagerOnePercentEditSave | Case::OdsSourceBackedOnePercentEditSave
    );
    let updates = ods_source_cell_updates(one_percent)?;
    let eager_output = expected_ods_owned_cell_output(corpus, &updates, one_percent)?;
    let source_output = expected_ods_source_cell_output(corpus, &updates, one_percent)?;
    verify_ods_source_cell_output(corpus, &eager_output, &updates, false)?;
    verify_ods_source_cell_output(corpus, &source_output, &updates, true)?;
    verify_ods_source_cell_gates(corpus, &updates, one_percent, &source_output)?;

    let expected_output = if source_backed {
        &source_output
    } else {
        &eager_output
    };
    let expected_digest = sha256_hex(expected_output);
    let expected_bytes = u64::try_from(expected_output.len())?;
    let update_indices = ods_source_cell_update_indices(&updates);
    let semantic_digest = sha256_hex(
        expected_semantic_ods_full_cell_text(SemanticShape::Medium, &update_indices).as_bytes(),
    );
    let source_archive_sha256 = corpus.manifest.archive_sha256.clone();
    let mut elapsed = Vec::with_capacity(samples);
    let mut lifecycle_ns = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut stage_ns = Vec::with_capacity(samples);
    let mut commit_ns = Vec::with_capacity(samples);
    let mut publication_ns = Vec::with_capacity(samples);
    let mut sinks = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let mut sink = WindowedHashingSink::new(expected_bytes, ODF_CONTENT_COW_SINK_WINDOW_BYTES)?;
        let started = Instant::now();
        let open_started = Instant::now();
        let open_duration;
        let stage_duration;
        let commit_duration;
        let publication_duration;
        if source_backed {
            let source = Arc::new(OwnedSource::new(corpus.archive.clone()));
            let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source)?;
            open_duration = open_started.elapsed();
            let stage_started = Instant::now();
            let mut edit = owner.edit_cells()?;
            let changed = stage_ods_source_cell_changes(&mut edit, &updates, one_percent)?;
            stage_duration = stage_started.elapsed();
            let commit_started = Instant::now();
            let commit = edit.commit()?;
            commit_duration = commit_started.elapsed();
            if changed != commit.changed_cells() {
                return Err("ODS source cell timed commit changed an unexpected cell count".into());
            }
            let publication_started = Instant::now();
            let report = commit.write_to(&mut sink)?;
            if report.changed_cells() != updates.len() || report.bytes() != expected_bytes {
                return Err("ODS source cell timed publication report differs".into());
            }
            publication_duration = publication_started.elapsed();
            std::hint::black_box(commit);
        } else {
            let snapshot = litchi_ods::document::Snapshot::from_bytes(corpus.archive.clone())?;
            open_duration = open_started.elapsed();
            let stage_started = Instant::now();
            let mut edit = snapshot.edit();
            stage_ods_owned_cell_changes(&mut edit, &updates, one_percent)?;
            stage_duration = stage_started.elapsed();
            let commit_started = Instant::now();
            let commit = edit.commit()?;
            commit_duration = commit_started.elapsed();
            let bytes = commit.snapshot().as_bytes();
            if u64::try_from(bytes.len())? != expected_bytes {
                return Err("ODS owned timed output length differs from its oracle".into());
            }
            let publication_started = Instant::now();
            sink.write_all(bytes)?;
            publication_duration = publication_started.elapsed();
            std::hint::black_box(commit);
        }
        let duration = started.elapsed();
        let (summary, digest) = sink.finish();
        if digest != expected_digest || summary.accepted_bytes != expected_bytes {
            return Err("ODS source cell timed publication hash differs".into());
        }
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        if iteration >= warmup_iterations {
            let lifecycle = elapsed_ns(duration)?;
            let open = elapsed_ns(open_duration)?;
            let stage = elapsed_ns(stage_duration)?;
            let commit = elapsed_ns(commit_duration)?;
            let publication = elapsed_ns(publication_duration)?;
            let phase_sum = open
                .checked_add(stage)
                .and_then(|sum| sum.checked_add(commit))
                .and_then(|sum| sum.checked_add(publication))
                .ok_or("ODS source cell phase duration sum overflowed")?;
            if phase_sum > lifecycle {
                return Err("ODS source cell phases exceed their aligned lifecycle".into());
            }
            lifecycle_ns.push(lifecycle);
            open_ns.push(open);
            stage_ns.push(stage);
            commit_ns.push(commit);
            publication_ns.push(publication);
            sinks.push(summary);
        }
    }
    if [
        lifecycle_ns.len(),
        open_ns.len(),
        stage_ns.len(),
        commit_ns.len(),
        publication_ns.len(),
    ]
    .iter()
    .any(|length| *length != samples)
    {
        return Err("ODS source cell phase evidence has an incomplete sample vector".into());
    }
    let sink = deterministic_sink_summary(&sinks, "ODS source cell publication")?;
    if sink.retained_output_bytes != Some(0)
        || sink.retained_authoring_window_bytes
            != Some(u64::try_from(ODF_CONTENT_COW_SINK_WINDOW_BYTES)?)
        || sink.accepted_bytes != expected_bytes
        || sink.largest_write > u64::try_from(ODF_CONTENT_COW_SINK_WINDOW_BYTES)?
    {
        return Err("ODS source cell publication exceeded the retained sink bound".into());
    }

    let mut source_read_calls = Vec::new();
    let mut source_read_bytes = Vec::new();
    let mut source_read_range_overlap_bytes = Vec::new();
    let mut content_source_read_calls = Vec::new();
    let mut content_source_read_bytes = Vec::new();
    let mut untouched_source_read_calls = Vec::new();
    let mut untouched_source_read_bytes = Vec::new();
    let mut pictures_source_read_calls = Vec::new();
    let mut pictures_source_read_bytes = Vec::new();
    let mut source_version_calls = Vec::new();
    let mut source_immutability_verified = true;
    let mut source_replay_gates_verified = true;
    if source_backed {
        let (content_range, untouched_ranges, picture_ranges, _untouched_names) =
            odf_content_cow_ranges(&corpus.archive)?;
        for _sample in 0..samples {
            let instrumented_source = Arc::new(InstrumentedSource::new_odf(
                corpus.archive.clone(),
                vec![content_range.clone()],
                untouched_ranges.clone(),
                picture_ranges.clone(),
            ));
            let read_at: Arc<dyn ReadAt> = instrumented_source.clone();
            let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(read_at)?;
            let mut edit = owner.edit_cells()?;
            let changed = stage_ods_source_cell_changes(&mut edit, &updates, one_percent)?;
            let commit = edit.commit()?;
            if changed != commit.changed_cells() {
                return Err("ODS source cell replay changed an unexpected cell count".into());
            }
            let mut replay_sink =
                WindowedHashingSink::new(expected_bytes, ODF_CONTENT_COW_SINK_WINDOW_BYTES)?;
            let report = commit.write_to(&mut replay_sink)?;
            let (replay_sink_summary, replay_digest) = replay_sink.finish();
            let replay_snapshot = instrumented_source.snapshot();
            let version_calls = instrumented_source.version_calls();
            let source_unchanged =
                sha256_hex(instrumented_source.bytes.as_slice()) == source_archive_sha256;
            let replay_gates = report.changed_cells() == updates.len()
                && report.bytes() == expected_bytes
                && replay_digest == expected_digest
                && replay_sink_summary.accepted_bytes == expected_bytes
                && replay_sink_summary.retained_output_bytes == Some(0)
                && replay_sink_summary.retained_authoring_window_bytes
                    == Some(u64::try_from(ODF_CONTENT_COW_SINK_WINDOW_BYTES)?)
                && replay_sink_summary.largest_write
                    <= u64::try_from(ODF_CONTENT_COW_SINK_WINDOW_BYTES)?
                && replay_snapshot.read_calls != 0
                && replay_snapshot.read_bytes != 0
                && replay_snapshot.read_range_overlap_bytes <= replay_snapshot.read_bytes
                && replay_snapshot.odf.content.read_calls != 0
                && replay_snapshot.odf.content.read_bytes != 0
                && replay_snapshot.odf.untouched.read_calls != 0
                && replay_snapshot.odf.untouched.read_bytes != 0
                && replay_snapshot.odf.pictures.read_calls != 0
                && replay_snapshot.odf.pictures.read_bytes != 0
                && version_calls != 0
                && source_unchanged;
            if !replay_gates {
                return Err(
                    "ODS source cell InstrumentedSource replay failed its logical-read gates"
                        .into(),
                );
            }
            source_read_calls.push(replay_snapshot.read_calls);
            source_read_bytes.push(replay_snapshot.read_bytes);
            source_read_range_overlap_bytes.push(replay_snapshot.read_range_overlap_bytes);
            content_source_read_calls.push(replay_snapshot.odf.content.read_calls);
            content_source_read_bytes.push(replay_snapshot.odf.content.read_bytes);
            untouched_source_read_calls.push(replay_snapshot.odf.untouched.read_calls);
            untouched_source_read_bytes.push(replay_snapshot.odf.untouched.read_bytes);
            pictures_source_read_calls.push(replay_snapshot.odf.pictures.read_calls);
            pictures_source_read_bytes.push(replay_snapshot.odf.pictures.read_bytes);
            source_version_calls.push(version_calls);
            source_immutability_verified &= source_unchanged;
            source_replay_gates_verified &= replay_gates;
            std::hint::black_box(commit);
        }
    }
    if source_backed
        && [
            source_read_calls.len(),
            source_read_bytes.len(),
            source_read_range_overlap_bytes.len(),
            content_source_read_calls.len(),
            content_source_read_bytes.len(),
            untouched_source_read_calls.len(),
            untouched_source_read_bytes.len(),
            pictures_source_read_calls.len(),
            pictures_source_read_bytes.len(),
            source_version_calls.len(),
        ]
        .iter()
        .any(|length| *length != samples)
    {
        return Err("ODS source cell source evidence has an incomplete sample vector".into());
    }

    let source_hash_verified = sha256_hex(&corpus.archive) == source_archive_sha256;
    let output_hash_verified = sha256_hex(expected_output) == expected_digest;
    let semantic_hash_verified = {
        let reopened = litchi_ods::Spreadsheet::from_bytes(expected_output.to_vec())?;
        sha256_hex(semantic_ods_full_cell_text(&reopened, SemanticShape::Medium)?.as_bytes())
            == semantic_digest
    };
    if !source_hash_verified || !output_hash_verified || !semantic_hash_verified {
        return Err("ODS source cell hash gates failed".into());
    }
    let ods_source_cell = OdsSourceCellSummary {
        implementation: if source_backed {
            "source_backed"
        } else {
            "owned_snapshot"
        },
        workload: if one_percent {
            "one_percent_existing_cells"
        } else {
            "one_existing_cell"
        },
        update_count: updates.len(),
        timing_scope: "open + stage + commit + sequential publication through the fixed-window hashing sink",
        performance_claim: "none; correctness and phase evidence only",
        source_evidence_scope: if source_backed {
            "untimed InstrumentedSource full lifecycle replay after timed samples; logical ReadAt range overlap only"
        } else {
            "not applicable to owned eager snapshot"
        },
        safety_evidence_scope: if source_backed {
            "untimed source-backed gates: patch forward/inverse, foreign-source refusal, exact no-op, replacement limit, and exact partial-sink progress"
        } else {
            "eager selector verifies deterministic output, semantic reopen, media preservation, source/output hashes, and bounded sink only"
        },
        production_contracts_outside_selector: "stale/version and cancellation refusal, signed/protected packages, formulas, unknown or repeated rows, and transaction bounds remain production-test evidence and are not re-proved by this selector",
        source_bytes: u64::try_from(corpus.archive.len())?,
        output_bytes: expected_bytes,
        source_archive_sha256,
        output_sha256: expected_digest.clone(),
        semantic_sha256: semantic_digest,
        lifecycle_ns,
        open_ns,
        stage_ns,
        commit_ns,
        publication_ns,
        source_read_calls,
        source_read_bytes,
        source_read_range_overlap_bytes,
        content_source_read_calls,
        content_source_read_bytes,
        untouched_source_read_calls,
        untouched_source_read_bytes,
        pictures_source_read_calls,
        pictures_source_read_bytes,
        source_version_calls,
        source_hash_verified,
        output_hash_verified,
        semantic_hash_verified,
        semantic_reopen_verified: true,
        media_payloads_verified: true,
        patch_forward_inverse_verified: source_backed.then_some(true),
        raw_untouched_member_identity_verified: source_backed.then_some(true),
        source_immutability_verified: source_backed.then_some(source_immutability_verified),
        exact_output_verified: true,
        exact_sink_verified: true,
        exact_noop_verified: source_backed.then_some(true),
        foreign_source_refusal_verified: source_backed.then_some(true),
        replacement_limit_verified: source_backed.then_some(true),
        partial_sink_verified: source_backed.then_some(true),
        source_replay_gates_verified: source_backed.then_some(source_replay_gates_verified),
        sink_summary: Some(sink),
    };
    let root_read_calls = ods_source_cell.source_read_calls.clone();
    let root_read_bytes = ods_source_cell.source_read_bytes.clone();
    let mut measured = result_with_source(
        case,
        corpus,
        elapsed,
        SourceSummary {
            read_calls: root_read_calls,
            read_bytes: root_read_bytes,
            ods_source_cell: Some(ods_source_cell),
            ..SourceSummary::default()
        },
    );
    measured.sink = Some(sink);
    measured.output_sha256 = Some(expected_digest);
    Ok(measured)
}

/// Flat cell indices (sheet-major over the medium two-sheet 32x32 corpus) for
/// the four sequential repeated-edit transactions.
const ODS_REPEATED_EDIT_FLAT_INDICES: [usize; 4] = [0, 683, 1365, 2047];

fn verify_ods_repeated_edit_media_identity(
    source: &[u8],
    output: &[u8],
) -> Result<(), Box<dyn Error>> {
    let source_archive = ArchiveReader::new(source)?;
    let output_archive = ArchiveReader::new(output)?;
    let mut picture_members = 0usize;
    for path in source_archive.file_names() {
        if !path.starts_with("Pictures/") {
            continue;
        }
        picture_members = picture_members
            .checked_add(1)
            .ok_or("ODS source repeated-edit media member count overflowed")?;
        if output_archive.read(path)? != source_archive.read(path)? {
            return Err(
                format!("ODS source repeated-edit media payload differs for '{path}'").into(),
            );
        }
    }
    if picture_members != ODS_MEDIA_ENTRY_COUNT {
        return Err(
            "ODS source repeated-edit media identity found an unexpected Pictures count".into(),
        );
    }
    Ok(())
}

fn run_ods_source_repeated_edit(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != ODS_MEDIA_CORPUS_GENERATOR {
        return Err(
            "ODS source repeated-edit selector requires the fixed media-rich corpus".into(),
        );
    }
    let shape = SemanticShape::Medium;
    let updates = ODS_REPEATED_EDIT_FLAT_INDICES
        .iter()
        .map(|&flat| {
            let sheet = flat / 1024;
            let remainder = flat % 1024;
            (sheet, remainder / 32, remainder % 32)
        })
        .collect::<Vec<_>>();
    for &(sheet, row, column) in &updates {
        if sheet >= shape.ods_sheet_count()
            || row >= shape.ods_rows_per_sheet()
            || column >= shape.ods_columns_per_sheet()
        {
            return Err("ODS source repeated-edit coordinate is outside the corpus".into());
        }
    }
    let transaction_count = updates.len();
    let source_archive_sha256 = corpus.manifest.archive_sha256.clone();
    if sha256_hex(&corpus.archive) != source_archive_sha256 {
        return Err(
            "ODS source repeated-edit source archive hash differs from its manifest".into(),
        );
    }

    // Untimed per-variant oracles: the eager owned path is the reference, and
    // the source-backed path must reproduce it byte-exactly.
    let mut expected_outputs = Vec::with_capacity(transaction_count);
    for &update in &updates {
        let eager = expected_ods_owned_cell_output(corpus, &[update], false)?;
        let source_backed = expected_ods_source_cell_output(corpus, &[update], false)?;
        if source_backed != eager {
            return Err(
                "ODS source repeated-edit source-backed output differs from the eager oracle"
                    .into(),
            );
        }
        expected_outputs.push(eager);
    }
    let expected_bytes = expected_outputs
        .iter()
        .map(|output| u64::try_from(output.len()))
        .collect::<Result<Vec<u64>, _>>()?;
    let expected_digests = expected_outputs
        .iter()
        .map(|output| sha256_hex(output))
        .collect::<Vec<_>>();

    // Untimed semantic reopen gate on variant 0: the edited cell carries the
    // updated text and an untouched cell keeps its exact source text.
    let &(edited_sheet, edited_row, edited_column) = updates
        .first()
        .ok_or("ODS source repeated-edit has no selected cell")?;
    let reopened = litchi_ods::Spreadsheet::from_bytes(expected_outputs[0].clone())?;
    let edited_name = semantic_ods_sheet_name(edited_sheet);
    let edited = reopened
        .cell(&edited_name, edited_row, edited_column)
        .ok_or("ODS source repeated-edit reopened sheet is missing")?;
    let litchi_ods::CellView::Stored(edited) = edited else {
        return Err("ODS source repeated-edit reopened edited cell is missing".into());
    };
    if edited.text != semantic_ods_text(edited_sheet, edited_row, edited_column, true) {
        return Err("ODS source repeated-edit reopened edited cell text differs".into());
    }
    let untouched_name = semantic_ods_sheet_name(1);
    let untouched = reopened
        .cell(&untouched_name, 5, 5)
        .ok_or("ODS source repeated-edit reopened untouched sheet is missing")?;
    let litchi_ods::CellView::Stored(untouched) = untouched else {
        return Err("ODS source repeated-edit reopened untouched cell is missing".into());
    };
    if untouched.text != semantic_ods_text(1, 5, 5, false) {
        return Err("ODS source repeated-edit reopened untouched cell text differs".into());
    }

    // Untimed media identity gate on variant 1: every `Pictures/` member is
    // byte-identical to the source archive.
    verify_ods_repeated_edit_media_identity(&corpus.archive, &expected_outputs[1])?;

    let mut elapsed = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut stage_ns = Vec::with_capacity(samples);
    let mut commit_ns = Vec::with_capacity(samples);
    let mut publication_ns = Vec::with_capacity(samples);
    let mut sinks = (0..transaction_count)
        .map(|_| Vec::with_capacity(samples))
        .collect::<Vec<Vec<SinkSummary>>>();
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = Arc::new(OwnedSource::new(corpus.archive.clone()));
        let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source)?;
        let mut iteration_sinks = expected_bytes
            .iter()
            .map(|&expected| WindowedHashingSink::new(expected, ODF_CONTENT_COW_SINK_WINDOW_BYTES))
            .collect::<Result<Vec<_>, _>>()?;
        let mut stage_total = Duration::ZERO;
        let mut commit_total = Duration::ZERO;
        let mut publication_total = Duration::ZERO;
        let started = Instant::now();
        for (variant, &(sheet, row, column)) in updates.iter().enumerate() {
            let stage_started = Instant::now();
            let mut edit = owner.edit_cells()?;
            let sheet_name = semantic_ods_sheet_name(sheet);
            let changed = edit
                .set_cell(
                    sheet_name.as_str(),
                    row,
                    column,
                    ods_source_cell_value(sheet, row, column),
                )?
                .ok_or("ODS source repeated-edit selected worksheet is missing")?;
            if !changed {
                return Err("ODS source repeated-edit did not change the selected cell".into());
            }
            stage_total += stage_started.elapsed();
            let commit_started = Instant::now();
            let commit = edit.commit()?;
            commit_total += commit_started.elapsed();
            if commit.changed_cells() != 1 {
                return Err(
                    "ODS source repeated-edit commit changed an unexpected cell count".into(),
                );
            }
            let publication_started = Instant::now();
            let report = commit.write_to(&mut iteration_sinks[variant])?;
            if report.changed_cells() != 1 || report.bytes() != expected_bytes[variant] {
                return Err(
                    "ODS source repeated-edit publication report differs from its oracle".into(),
                );
            }
            publication_total += publication_started.elapsed();
            std::hint::black_box(&commit);
        }
        let duration = started.elapsed();
        for (variant, sink) in iteration_sinks.into_iter().enumerate() {
            let (summary, digest) = sink.finish();
            if digest != expected_digests[variant]
                || summary.accepted_bytes != expected_bytes[variant]
            {
                return Err("ODS source repeated-edit timed publication hash differs".into());
            }
            if iteration >= warmup_iterations {
                sinks[variant].push(summary);
            }
        }
        owner.check_source()?;
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        if iteration >= warmup_iterations {
            let total = elapsed_ns(duration)?;
            let stage = elapsed_ns(stage_total)?;
            let commit = elapsed_ns(commit_total)?;
            let publication = elapsed_ns(publication_total)?;
            let phase_sum = stage
                .checked_add(commit)
                .and_then(|sum| sum.checked_add(publication))
                .ok_or("ODS source repeated-edit phase duration sum overflowed")?;
            if phase_sum > total {
                return Err("ODS source repeated-edit phases exceed their timed total".into());
            }
            total_ns.push(total);
            stage_ns.push(stage);
            commit_ns.push(commit);
            publication_ns.push(publication);
        }
    }
    if [
        total_ns.len(),
        stage_ns.len(),
        commit_ns.len(),
        publication_ns.len(),
    ]
    .iter()
    .any(|length| *length != samples)
    {
        return Err(
            "ODS source repeated-edit phase evidence has an incomplete sample vector".into(),
        );
    }
    let window_bytes = u64::try_from(ODF_CONTENT_COW_SINK_WINDOW_BYTES)?;
    for (variant, variant_sinks) in sinks.iter().enumerate() {
        let sink =
            deterministic_sink_summary(variant_sinks, "ODS source repeated-edit publication")?;
        if sink.retained_output_bytes != Some(0)
            || sink.retained_authoring_window_bytes != Some(window_bytes)
            || sink.accepted_bytes != expected_bytes[variant]
            || sink.largest_write > window_bytes
        {
            return Err(
                "ODS source repeated-edit publication exceeded the retained sink bound".into(),
            );
        }
    }

    // One untimed instrumented replay over a fresh owner: preparation counters
    // cover the open, then the four transactions are replayed after a counter
    // reset. These are logical `ReadAt` counters, not physical I/O.
    let (content_range, untouched_ranges, picture_ranges, _untouched_names) =
        odf_content_cow_ranges(&corpus.archive)?;
    let instrumented_source = Arc::new(InstrumentedSource::new_odf(
        corpus.archive.clone(),
        vec![content_range],
        untouched_ranges,
        picture_ranges,
    ));
    let read_at: Arc<dyn ReadAt> = instrumented_source.clone();
    let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(read_at)?;
    let preparation = instrumented_source.snapshot();
    instrumented_source.reset();
    for (variant, &(sheet, row, column)) in updates.iter().enumerate() {
        let mut edit = owner.edit_cells()?;
        let sheet_name = semantic_ods_sheet_name(sheet);
        let changed = edit
            .set_cell(
                sheet_name.as_str(),
                row,
                column,
                ods_source_cell_value(sheet, row, column),
            )?
            .ok_or("ODS source repeated-edit replay selected worksheet is missing")?;
        if !changed {
            return Err("ODS source repeated-edit replay did not change the selected cell".into());
        }
        let commit = edit.commit()?;
        if commit.changed_cells() != 1 {
            return Err("ODS source repeated-edit replay changed an unexpected cell count".into());
        }
        let mut replay_sink =
            WindowedHashingSink::new(expected_bytes[variant], ODF_CONTENT_COW_SINK_WINDOW_BYTES)?;
        let report = commit.write_to(&mut replay_sink)?;
        let (replay_sink_summary, replay_digest) = replay_sink.finish();
        let replay_gates = report.changed_cells() == 1
            && report.bytes() == expected_bytes[variant]
            && replay_digest == expected_digests[variant]
            && replay_sink_summary.accepted_bytes == expected_bytes[variant]
            && replay_sink_summary.retained_output_bytes == Some(0)
            && replay_sink_summary.retained_authoring_window_bytes == Some(window_bytes)
            && replay_sink_summary.largest_write <= window_bytes;
        if !replay_gates {
            return Err(
                "ODS source repeated-edit replay publication differs from its oracle".into(),
            );
        }
        std::hint::black_box(&commit);
    }
    owner.check_source()?;
    let replay = instrumented_source.snapshot();
    let replay_version_calls = instrumented_source.version_calls();
    let source_unchanged =
        sha256_hex(instrumented_source.bytes.as_slice()) == source_archive_sha256;
    if preparation.read_calls == 0
        || preparation.read_bytes == 0
        || replay.read_calls == 0
        || replay.read_bytes == 0
        || replay.read_range_overlap_bytes > replay.read_bytes
        || replay.odf.untouched.read_calls == 0
        || replay.odf.untouched.read_bytes == 0
        || replay.odf.pictures.read_calls == 0
        || replay.odf.pictures.read_bytes == 0
        || replay_version_calls == 0
        || !source_unchanged
    {
        return Err(
            "ODS source repeated-edit InstrumentedSource replay failed its logical-read gates"
                .into(),
        );
    }

    let summary = OdsSourceRepeatedEditSummary {
        implementation: "source_backed_repeated_edit_transactions",
        phase: "four_sequential_one_cell_edit_commit_publish_transactions",
        timing_scope: "one source-backed owner and four fixed-window hashing sinks prepared outside the timer; the timer covers exactly four sequential edit_cells + set_cell + commit + write_to transactions with per-transaction stage/commit/publication durations summed per sample",
        source_evidence_scope: "single untimed InstrumentedSource replay after the timed samples; preparation and replay counters are logical ReadAt observations, not physical I/O",
        production_contracts_outside_selector: "stale/version and cancellation refusal, replacement-limit, and exact partial-sink progress contracts remain production-test evidence and are not re-proved by this selector",
        performance_claim: "correctness and phase evidence only; no latency claim is made by this selector alone",
        transaction_count,
        update_coordinates: updates.clone(),
        source_bytes: u64::try_from(corpus.archive.len())?,
        source_archive_sha256,
        output_bytes_per_variant: expected_bytes,
        output_sha256_per_variant: expected_digests,
        total_ns,
        stage_ns,
        commit_ns,
        publication_ns,
        source_preparation_read_calls: preparation.read_calls,
        source_preparation_read_bytes: preparation.read_bytes,
        source_replay_read_calls: replay.read_calls,
        source_replay_read_bytes: replay.read_bytes,
        source_replay_range_overlap_bytes: replay.read_range_overlap_bytes,
        source_replay_content_read_calls: replay.odf.content.read_calls,
        source_replay_content_read_bytes: replay.odf.content.read_bytes,
        source_replay_pictures_read_calls: replay.odf.pictures.read_calls,
        source_replay_pictures_read_bytes: replay.odf.pictures.read_bytes,
        source_replay_version_calls: replay_version_calls,
        output_hash_verified: true,
        semantic_reopen_verified: true,
        media_payloads_verified: true,
        exact_output_verified: true,
        exact_sink_verified: true,
        source_immutability_verified: true,
    };
    let root_read_calls = vec![summary.source_replay_read_calls];
    let root_read_bytes = vec![summary.source_replay_read_bytes];
    Ok(result_with_source(
        Case::OdsSourceBackedRepeatedEdit,
        corpus,
        elapsed,
        SourceSummary {
            read_calls: root_read_calls,
            read_bytes: root_read_bytes,
            ods_source_repeated_edit: Some(summary),
            ..SourceSummary::default()
        },
    ))
}

fn run_semantic_odp(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let shape = semantic_shape(corpus)?;
    let index = shape.pptx_slides() / 2;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        match case {
            Case::OdpSemanticCreateSmall => {
                let started = Instant::now();
                let bytes = semantic_odp_bytes(SemanticShape::Tiny)?;
                let duration = started.elapsed();
                let reopened = litchi_odp::Presentation::from_bytes(bytes.clone())?;
                verify_semantic_odp(&reopened, SemanticShape::Tiny, false)?;
                if bytes != corpus.archive && shape == SemanticShape::Tiny {
                    return Err(
                        "semantic ODP creation differs from its deterministic corpus".into(),
                    );
                }
                std::hint::black_box(bytes);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdpSemanticOpen => {
                let owned = corpus.archive.clone();
                let started = Instant::now();
                let presentation = litchi_odp::Presentation::from_bytes(owned)?;
                let duration = started.elapsed();
                verify_semantic_odp(&presentation, shape, false)?;
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdpSemanticListSlides => {
                let presentation = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let slides = presentation.slides()?;
                let duration = started.elapsed();
                if slides.len() != shape.pptx_slides() {
                    return Err("semantic ODP slide list differs from specification".into());
                }
                verify_semantic_odp(&presentation, shape, false)?;
                std::hint::black_box(slides);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdpSemanticOneSlide => {
                let presentation = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let slide = presentation
                    .slide(index)?
                    .ok_or("semantic ODP selected slide is missing")?;
                let text = slide.all_text();
                let duration = started.elapsed();
                let expected = format!(
                    "{}\n{}",
                    semantic_odp_title(index, false),
                    semantic_odp_text(index, false)
                );
                if text != expected {
                    return Err("semantic ODP selected slide differs from specification".into());
                }
                verify_semantic_odp(&presentation, shape, false)?;
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdpSemanticFullText => {
                let presentation = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let text = presentation.text()?;
                let duration = started.elapsed();
                verify_semantic_odp(&presentation, shape, false)?;
                std::hint::black_box(text);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            Case::OdpSemanticNoopEditSave | Case::OdpSemanticOneEditSave => {
                let presentation = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
                let snapshot = presentation.snapshot()?;
                let started = Instant::now();
                let mut transaction = snapshot.transaction()?;
                let updated = matches!(case, Case::OdpSemanticOneEditSave);
                if updated {
                    let index = shape.pptx_slides();
                    transaction.add(
                        &semantic_odp_title(index, true),
                        &semantic_odp_text(index, true),
                    )?;
                }
                let commit = transaction.commit()?;
                let bytes = commit.snapshot().bytes().to_vec();
                let duration = started.elapsed();
                if (bytes != corpus.archive) != updated || commit.changed() != updated {
                    return Err(
                        "semantic ODP edit/save changed-state differs from specification".into(),
                    );
                }
                let reopened = litchi_odp::Presentation::from_bytes(bytes.clone())?;
                verify_semantic_odp(&reopened, shape, updated)?;
                std::hint::black_box(bytes);
                record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
            },
            _ => return Err("non-ODP semantic case passed to ODP runner".into()),
        }
    }
    Ok(result(case, corpus, elapsed, None))
}

fn run_odp_media_textbox_edit_save(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let text_box = litchi_odp::content::TextBox::new(
        ODP_MEDIA_TEXT_BOX_NAME,
        litchi_odp::content::RichText::plain(odp_media_text())?,
    )?;
    let mut expected_output_digest = None;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let started = Instant::now();
        let source = litchi_odp::authoring::edit::Snapshot::from_bytes(corpus.archive.clone())?;
        let mut transaction = source.transaction()?;
        transaction.add_text_box(0usize, &text_box)?;
        let commit = transaction.commit()?;
        let bytes = commit.snapshot().bytes().to_vec();
        let duration = started.elapsed();
        if !commit.changed() || bytes == corpus.archive || commit.patch().is_noop() {
            return Err("media-rich ODP text-box edit reported an exact no-op".into());
        }

        verify_odp_media_archive(&bytes, true)?;
        let replayed = commit.patch().apply(&source)?;
        if replayed.bytes() != bytes {
            return Err("media-rich ODP text-box patch replay differs from commit".into());
        }
        let restored = commit.patch().inverse().apply(&replayed)?;
        if restored.bytes() != corpus.archive {
            return Err("media-rich ODP text-box inverse did not restore the source".into());
        }
        if commit.patch().apply(&replayed).is_ok() {
            return Err("media-rich ODP text-box patch accepted a stale source".into());
        }
        let digest = sha256_hex(&bytes);
        if let Some(expected) = &expected_output_digest {
            if expected != &digest {
                return Err("media-rich ODP text-box publication is not deterministic".into());
            }
        } else {
            expected_output_digest = Some(digest);
        }
        std::hint::black_box(bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result(Case::OdpMediaTextBoxEditSave, corpus, elapsed, None))
}

fn odp_media_case_parameters(
    case: Case,
) -> Result<(&'static str, &'static str, bool), Box<dyn Error>> {
    match case {
        Case::OdpMediaEagerOpen => Ok(("eager", "presentation_open_no_slide_query", false)),
        Case::OdpMediaSourceBackedOpen => {
            Ok(("source_backed", "presentation_open_no_slide_query", false))
        },
        Case::OdpMediaEagerOneSlide => Ok(("eager", "one_middle_slide_query", true)),
        Case::OdpMediaSourceBackedOneSlide => Ok(("source_backed", "one_middle_slide_query", true)),
        _ => Err("non-media ODP source case passed to ODP media case parameters".into()),
    }
}

fn verify_odp_media_selected_slide(
    slide: &litchi_odp::model::Slide,
    target_slide: usize,
) -> Result<(), Box<dyn Error>> {
    if slide.index() != target_slide
        || slide.all_text()
            != format!(
                "{}\n{}",
                semantic_odp_title(target_slide, false),
                semantic_odp_text(target_slide, false)
            )
    {
        return Err("ODP media-rich selected slide differs from the deterministic corpus".into());
    }
    Ok(())
}

fn verify_odp_media_source_semantics(
    presentation: &litchi_odp::SourceBackedPresentation,
    expected_slides: &[litchi_odp::model::Slide],
    expected_digest: &str,
) -> Result<(), Box<dyn Error>> {
    if presentation.slide_count()? != expected_slides.len() {
        return Err("ODP source-backed slide count differs from eager semantic oracle".into());
    }
    let mut slides = Vec::with_capacity(expected_slides.len());
    for index in 0..expected_slides.len() {
        slides.push(
            presentation
                .slide(index)?
                .ok_or("ODP source-backed semantic slide is missing")?,
        );
    }
    let digest = odp_media_semantic_digest(&slides)?;
    if digest != expected_digest || slides != expected_slides {
        return Err("ODP source-backed full semantic projection differs from eager oracle".into());
    }
    Ok(())
}

fn collect_odp_media_source_phase(
    archive: &[u8],
    picture_ranges: &[Range<u64>],
    target_slide: usize,
    query: bool,
) -> Result<SourceSnapshot, Box<dyn Error>> {
    let source = odp_media_instrumented_source(archive, picture_ranges);
    let presentation = litchi_odp::SourceBackedPresentation::from_read_at(source.clone())?;
    if query {
        // The source-backed facade pins the validated content XML at open;
        // selecting one slide therefore performs no additional ReadAt call.
        source.reset();
        let slide = presentation
            .slide(target_slide)?
            .ok_or("ODP source-backed evidence target slide is missing")?;
        verify_odp_media_selected_slide(&slide, target_slide)?;
    }
    Ok(source.snapshot())
}

fn collect_odp_media_selected_media(
    archive: &[u8],
    picture_ranges: &[Range<u64>],
    selected_range: Range<u64>,
    selected_path: &str,
) -> Result<(SourceSnapshot, SourceSnapshot), Box<dyn Error>> {
    let reference = litchi_odp::model::Reference::new(selected_path)?;
    let all_source = odp_media_instrumented_source(archive, picture_ranges);
    let all_pictures = litchi_odp::SourceBackedPresentation::from_read_at(all_source.clone())?;
    all_source.reset();
    let payload = all_pictures
        .media_data(&reference)?
        .ok_or("ODP source-backed selected media payload is missing")?;
    let expected_index = ODS_MEDIA_ENTRY_COUNT / 2;
    if payload != odp_media_payload(expected_index) {
        return Err("ODP source-backed selected media payload differs from corpus".into());
    }
    let all_snapshot = all_source.snapshot();

    let selected_source = odp_media_instrumented_source(archive, &[selected_range]);
    let selected_pictures =
        litchi_odp::SourceBackedPresentation::from_read_at(selected_source.clone())?;
    selected_source.reset();
    let payload = selected_pictures
        .media_data(&reference)?
        .ok_or("ODP selected-range media payload is missing")?;
    if payload != odp_media_payload(expected_index) {
        return Err("ODP selected-range media payload differs from corpus".into());
    }
    Ok((all_snapshot, selected_source.snapshot()))
}

fn verify_odp_media_source_phase(
    snapshot: SourceSnapshot,
    phase: &str,
) -> Result<(), Box<dyn Error>> {
    if phase == "one_middle_slide_query" {
        if snapshot.read_calls != 0 || snapshot.read_bytes != 0 {
            return Err("ODP source-backed selected-slide replay performed a source read".into());
        }
    } else if snapshot.read_calls == 0 || snapshot.read_bytes == 0 {
        return Err("ODP source-backed open replay has no logical reads".into());
    }
    Ok(())
}

fn run_odp_media_source_access(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != ODP_MEDIA_CORPUS_GENERATOR {
        return Err("ODP media source cases require the fixed media-rich corpus".into());
    }
    let (implementation, phase, query) = odp_media_case_parameters(case)?;
    let target_slide = SemanticShape::Medium.pptx_slides() / 2;
    let (expected_slides, canonical_semantic_sha256) = odp_media_eager_semantics(&corpus.archive)?;
    verify_odp_media_selected_slide(&expected_slides[target_slide], target_slide)?;
    let (picture_members, selected_range) = odp_media_payload_inventory(corpus)?;
    let selected_media_path = odp_media_path(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected_media_payload = odp_media_payload(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected_media_uncompressed_bytes = u64::try_from(selected_media_payload.len())?;
    let selected_media_compressed_range_bytes =
        selected_range.end.saturating_sub(selected_range.start);
    let pictures_compressed_range_bytes =
        picture_members
            .iter()
            .try_fold(0_u64, |total, (_name, range)| {
                total
                    .checked_add(range.end.saturating_sub(range.start))
                    .ok_or("ODP compressed Pictures byte count overflows u64")
            })?;
    let pictures_uncompressed_payload_bytes = u64::try_from(
        ODS_MEDIA_ENTRY_COUNT
            .checked_mul(ODS_MEDIA_ENTRY_BYTES)
            .ok_or("ODP uncompressed Pictures byte count overflows usize")?,
    )?;
    let pictures_uncompressed_payload_sha256 = odp_media_payload_digest();
    let mut elapsed = Vec::with_capacity(samples);
    let mut source_summary = OdpMediaSourceSummary {
        implementation,
        phase,
        timing_scope: if query {
            if implementation == "source_backed" {
                "one_middle_slide_query_after_untimed_source_open"
            } else {
                "one_middle_slide_query_after_untimed_eager_open"
            }
        } else if implementation == "source_backed" {
            "source_backed_presentation_open"
        } else {
            "eager_presentation_open"
        },
        timed_source_adapter: if implementation == "source_backed" {
            "litchi_core::OwnedSource"
        } else {
            "std::io::Cursor<&[u8]>"
        },
        read_evidence_adapter: if implementation == "source_backed" {
            "harness::InstrumentedSource"
        } else {
            "not_applicable"
        },
        read_evidence_scope: if implementation == "source_backed" {
            "separate_untimed_replays_per_measured_sample"
        } else {
            "not_applicable"
        },
        target_slide,
        selected_media_path: selected_media_path.clone(),
        selected_media_compressed_range_bytes,
        selected_media_uncompressed_bytes,
        selected_media_uncompressed_payload_sha256: sha256_hex(&selected_media_payload),
        pictures_count: picture_members.len(),
        pictures_compressed_range_bytes,
        pictures_uncompressed_payload_bytes,
        pictures_uncompressed_payload_sha256,
        canonical_semantic_sha256: canonical_semantic_sha256.clone(),
        ..OdpMediaSourceSummary::default()
    };

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let duration = if implementation == "source_backed" {
            let source = Arc::new(OwnedSource::new(corpus.archive.clone()));
            if query {
                let presentation = litchi_odp::SourceBackedPresentation::from_read_at(source)?;
                let started = Instant::now();
                let slide = presentation
                    .slide(target_slide)?
                    .ok_or("ODP source-backed target slide is missing")?;
                let duration = started.elapsed();
                verify_odp_media_selected_slide(&slide, target_slide)?;
                verify_odp_media_source_semantics(
                    &presentation,
                    &expected_slides,
                    &canonical_semantic_sha256,
                )?;
                duration
            } else {
                let started = Instant::now();
                let presentation = litchi_odp::SourceBackedPresentation::from_read_at(source)?;
                let duration = started.elapsed();
                verify_odp_media_source_semantics(
                    &presentation,
                    &expected_slides,
                    &canonical_semantic_sha256,
                )?;
                duration
            }
        } else if query {
            let presentation = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
            let started = Instant::now();
            let slide = presentation
                .slide(target_slide)?
                .ok_or("ODP eager target slide is missing")?;
            let duration = started.elapsed();
            verify_odp_media_selected_slide(&slide, target_slide)?;
            verify_odp_media_eager_semantics_and_media(
                &presentation,
                &expected_slides,
                &canonical_semantic_sha256,
                &selected_media_path,
                &selected_media_payload,
            )?;
            duration
        } else {
            let owned = corpus.archive.clone();
            let started = Instant::now();
            let presentation = litchi_odp::Presentation::from_bytes(owned)?;
            let duration = started.elapsed();
            verify_odp_media_eager_semantics_and_media(
                &presentation,
                &expected_slides,
                &canonical_semantic_sha256,
                &selected_media_path,
                &selected_media_payload,
            )?;
            duration
        };
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    if implementation == "source_backed" {
        let selected_range_len = selected_range.end.saturating_sub(selected_range.start);
        let mut exact_phase = None;
        let mut exact_media = None;
        for _ in 0..samples {
            let snapshot = collect_odp_media_source_phase(
                &corpus.archive,
                &picture_members
                    .iter()
                    .map(|(_name, range)| range.clone())
                    .collect::<Vec<_>>(),
                target_slide,
                query,
            )?;
            verify_odp_media_source_phase(snapshot, phase)?;
            if let Some(expected) = exact_phase {
                if expected != snapshot {
                    return Err("ODP source phase counters are not deterministic".into());
                }
            } else {
                exact_phase = Some(snapshot);
            }
            source_summary.source_read_calls.push(snapshot.read_calls);
            source_summary.source_read_bytes.push(snapshot.read_bytes);
            source_summary
                .source_read_range_overlap_bytes
                .push(snapshot.read_range_overlap_bytes);
            source_summary
                .pictures_read_calls
                .push(snapshot.ordinary_payload_read_calls);
            source_summary
                .pictures_read_compressed_range_bytes
                .push(snapshot.ordinary_payload_read_bytes);

            let (all_snapshot, selected_snapshot) = collect_odp_media_selected_media(
                &corpus.archive,
                &picture_members
                    .iter()
                    .map(|(_name, range)| range.clone())
                    .collect::<Vec<_>>(),
                selected_range.clone(),
                &selected_media_path,
            )?;
            if all_snapshot.ordinary_payload_read_bytes != selected_range_len
                || selected_snapshot.ordinary_payload_read_bytes != selected_range_len
                || all_snapshot.ordinary_payload_read_calls == 0
                || selected_snapshot.ordinary_payload_read_calls == 0
            {
                return Err(
                    "ODP selected media replay did not cover exactly one Pictures range".into(),
                );
            }
            if let Some(expected) = exact_media {
                if expected != (all_snapshot, selected_snapshot) {
                    return Err("ODP selected media counters are not deterministic".into());
                }
            } else {
                exact_media = Some((all_snapshot, selected_snapshot));
            }
            source_summary
                .selected_media_read_calls
                .push(all_snapshot.read_calls);
            source_summary
                .selected_media_read_bytes
                .push(all_snapshot.read_bytes);
            source_summary
                .selected_media_read_prior_range_overlap_bytes
                .push(all_snapshot.read_range_overlap_bytes);
            source_summary
                .selected_media_read_compressed_range_overlap_bytes
                .push(all_snapshot.ordinary_payload_read_bytes);
            source_summary
                .selected_media_read_non_picture_overlap_bytes
                .push(
                    all_snapshot
                        .read_bytes
                        .saturating_sub(all_snapshot.ordinary_payload_read_bytes),
                );
        }
    }

    let source = SourceSummary {
        odp_media: Some(source_summary),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn odp_root_file_case_parameters(
    case: Case,
) -> Result<(&'static str, &'static str, bool), Box<dyn Error>> {
    match case {
        Case::OdpFileEagerOpen => Ok(("eager_root", "presentation_open_no_slide_query", false)),
        Case::OdpFileSourceOpen => Ok((
            "source_backed_root",
            "presentation_open_no_slide_query",
            false,
        )),
        Case::OdpFileEagerSelectedSlide => Ok(("eager_root", "one_middle_slide_query", true)),
        Case::OdpFileSourceSelectedSlide => {
            Ok(("source_backed_root", "one_middle_slide_query", true))
        },
        _ => Err("non-root ODP case passed to root ODP case parameters".into()),
    }
}

fn odp_root_semantic_projection(
    presentation: &litchi::Presentation,
) -> Result<(Vec<String>, String), Box<dyn Error>> {
    let slides = presentation.slides()?;
    let mut texts = Vec::with_capacity(slides.len());
    let mut digest = Sha256::new();
    for (index, slide) in slides.iter().enumerate() {
        let text = slide.text()?;
        digest.update((index as u64).to_le_bytes());
        digest.update((text.len() as u64).to_le_bytes());
        digest.update(text.as_bytes());
        texts.push(text);
    }
    Ok((texts, fingerprint_hex(&digest.finalize().into())))
}

fn odp_root_metadata_digest(
    metadata: &Option<litchi_core::Metadata>,
) -> Result<String, Box<dyn Error>> {
    Ok(sha256_hex(&serde_json::to_vec(metadata)?))
}

fn create_odp_root_source_file(archive: &[u8]) -> Result<PathBuf, Box<dyn Error>> {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| format!("ODP root source timestamp is before epoch: {error}"))?
        .as_nanos();
    let path = std::env::temp_dir().join(format!(
        "litchi-perf-baseline-odp-root-{}-{stamp}.odp",
        std::process::id()
    ));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&path)?;
    file.write_all(archive)?;
    file.flush()?;
    Ok(path)
}

fn verify_odp_root_postconditions(
    presentation: &litchi::Presentation,
    source_path: &std::path::Path,
    corpus: &Corpus,
    expected_texts: &[String],
    expected_semantic_sha256: &str,
    expected_metadata_sha256: &str,
    expected_typed_slides: &[litchi_odp::model::Slide],
    expected_typed_semantic_sha256: &str,
    target_slide: usize,
    selected_media_path: &str,
    selected_media_payload: &[u8],
) -> Result<(), Box<dyn Error>> {
    let (texts, semantic_sha256) = odp_root_semantic_projection(presentation)?;
    if texts != expected_texts || semantic_sha256 != expected_semantic_sha256 {
        return Err("ODP unified root semantic projection differs from eager oracle".into());
    }
    let selected = presentation
        .slide(target_slide)?
        .ok_or("ODP unified root selected slide is missing")?;
    if selected.text()? != expected_texts[target_slide] {
        return Err("ODP unified root selected slide differs from corpus".into());
    }
    if odp_root_metadata_digest(&presentation.metadata()?)? != expected_metadata_sha256 {
        return Err("ODP unified root metadata differs between matched controls".into());
    }

    let bytes = fs::read(source_path)?;
    if bytes != corpus.archive
        || sha256_hex(&bytes) != corpus.manifest.archive_sha256
        || bytes.len() != corpus.manifest.archive_bytes
    {
        return Err("ODP unified root source file differs from deterministic archive".into());
    }
    verify_odp_media_archive(&bytes, false)?;
    let typed = litchi_odp::Presentation::from_bytes(bytes)?;
    verify_odp_media_eager_semantics_and_media(
        &typed,
        expected_typed_slides,
        expected_typed_semantic_sha256,
        selected_media_path,
        selected_media_payload,
    )?;
    Ok(())
}

fn run_odp_root_file_access(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != ODP_MEDIA_CORPUS_GENERATOR {
        return Err("ODP root filesystem cases require the fixed media-rich corpus".into());
    }
    let (implementation, phase, query) = odp_root_file_case_parameters(case)?;
    let target_slide = SemanticShape::Medium.pptx_slides() / 2;
    let expected_root = litchi::Presentation::from_bytes(corpus.archive.clone())?;
    let (expected_texts, canonical_semantic_sha256) = odp_root_semantic_projection(&expected_root)?;
    let canonical_metadata_sha256 = odp_root_metadata_digest(&expected_root.metadata()?)?;
    let (expected_typed_slides, canonical_typed_semantic_sha256) =
        odp_media_eager_semantics(&corpus.archive)?;
    if canonical_semantic_sha256 != canonical_typed_semantic_sha256 {
        return Err("ODP unified root and typed semantic digests differ".into());
    }
    if expected_texts.len() != SemanticShape::Medium.pptx_slides()
        || expected_texts[target_slide]
            != format!(
                "{}\n{}",
                semantic_odp_title(target_slide, false),
                semantic_odp_text(target_slide, false)
            )
    {
        return Err("ODP unified root canonical corpus projection differs".into());
    }
    let (picture_members, selected_range) = odp_media_payload_inventory(corpus)?;
    let picture_ranges = picture_members
        .iter()
        .map(|(_name, range)| range.clone())
        .collect::<Vec<_>>();
    let selected_media_path = odp_media_path(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected_media_payload = odp_media_payload(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected_media_uncompressed_bytes = u64::try_from(selected_media_payload.len())?;
    let selected_media_compressed_range_bytes =
        selected_range.end.saturating_sub(selected_range.start);
    let pictures_compressed_range_bytes =
        picture_members
            .iter()
            .try_fold(0_u64, |total, (_name, range)| {
                total
                    .checked_add(range.end.saturating_sub(range.start))
                    .ok_or("ODP compressed Pictures byte count overflows u64")
            })?;
    let pictures_uncompressed_payload_bytes = u64::try_from(
        ODS_MEDIA_ENTRY_COUNT
            .checked_mul(ODS_MEDIA_ENTRY_BYTES)
            .ok_or("ODP uncompressed Pictures byte count overflows usize")?,
    )?;
    let pictures_uncompressed_payload_sha256 = odp_media_payload_digest();
    let source_path = create_odp_root_source_file(&corpus.archive)?;
    let result = (|| {
        let mut elapsed = Vec::with_capacity(samples);
        let mut source_summary = OdpRootSourceSummary {
            implementation,
            phase,
            timing_scope: if query {
                "one_middle_slide_query_after_untimed_root_open"
            } else {
                "unified_root_presentation_open"
            },
            timed_root_adapter: if implementation == "source_backed_root" {
                "litchi::Presentation::open(Path)"
            } else {
                "litchi::Presentation::from_bytes(Vec<u8>)"
            },
            read_evidence_adapter: if implementation == "source_backed_root" {
                "litchi_odp::SourceBackedPresentation+harness::InstrumentedSource"
            } else {
                "not_applicable"
            },
            read_evidence_scope: if implementation == "source_backed_root" {
                "separate_untimed_direct_typed_replay_per_measured_sample"
            } else {
                "not_applicable"
            },
            source_path_bytes: u64::try_from(corpus.archive.len())?,
            source_path_sha256: corpus.manifest.archive_sha256.clone(),
            target_slide,
            canonical_semantic_sha256: canonical_semantic_sha256.clone(),
            metadata_sha256: canonical_metadata_sha256.clone(),
            selected_media_path: selected_media_path.clone(),
            selected_media_compressed_range_bytes,
            selected_media_uncompressed_bytes,
            selected_media_uncompressed_payload_sha256: sha256_hex(&selected_media_payload),
            pictures_count: picture_members.len(),
            pictures_compressed_range_bytes,
            pictures_uncompressed_payload_bytes,
            pictures_uncompressed_payload_sha256,
            ..OdpRootSourceSummary::default()
        };

        for iteration in 0..iteration_count(warmup_iterations, samples)? {
            let duration = if implementation == "source_backed_root" {
                if query {
                    let presentation = litchi::Presentation::open(&source_path)?;
                    let started = Instant::now();
                    let slide = presentation
                        .slide(target_slide)?
                        .ok_or("ODP unified source root selected slide is missing")?;
                    let duration = started.elapsed();
                    verify_odp_root_postconditions(
                        &presentation,
                        &source_path,
                        corpus,
                        &expected_texts,
                        &canonical_semantic_sha256,
                        &canonical_metadata_sha256,
                        &expected_typed_slides,
                        &canonical_typed_semantic_sha256,
                        target_slide,
                        &selected_media_path,
                        &selected_media_payload,
                    )?;
                    if slide.text()? != expected_texts[target_slide] {
                        return Err("ODP unified source root selected slide differs".into());
                    }
                    duration
                } else {
                    let started = Instant::now();
                    let presentation = litchi::Presentation::open(&source_path)?;
                    let duration = started.elapsed();
                    verify_odp_root_postconditions(
                        &presentation,
                        &source_path,
                        corpus,
                        &expected_texts,
                        &canonical_semantic_sha256,
                        &canonical_metadata_sha256,
                        &expected_typed_slides,
                        &canonical_typed_semantic_sha256,
                        target_slide,
                        &selected_media_path,
                        &selected_media_payload,
                    )?;
                    duration
                }
            } else if query {
                let presentation = litchi::Presentation::from_bytes(corpus.archive.clone())?;
                let started = Instant::now();
                let slide = presentation
                    .slide(target_slide)?
                    .ok_or("ODP unified eager root selected slide is missing")?;
                let duration = started.elapsed();
                verify_odp_root_postconditions(
                    &presentation,
                    &source_path,
                    corpus,
                    &expected_texts,
                    &canonical_semantic_sha256,
                    &canonical_metadata_sha256,
                    &expected_typed_slides,
                    &canonical_typed_semantic_sha256,
                    target_slide,
                    &selected_media_path,
                    &selected_media_payload,
                )?;
                if slide.text()? != expected_texts[target_slide] {
                    return Err("ODP unified eager root selected slide differs".into());
                }
                duration
            } else {
                let owned = corpus.archive.clone();
                let started = Instant::now();
                let presentation = litchi::Presentation::from_bytes(owned)?;
                let duration = started.elapsed();
                verify_odp_root_postconditions(
                    &presentation,
                    &source_path,
                    corpus,
                    &expected_texts,
                    &canonical_semantic_sha256,
                    &canonical_metadata_sha256,
                    &expected_typed_slides,
                    &canonical_typed_semantic_sha256,
                    target_slide,
                    &selected_media_path,
                    &selected_media_payload,
                )?;
                duration
            };
            record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        }

        if implementation == "source_backed_root" {
            let selected_range_len = selected_media_compressed_range_bytes;
            let mut exact_phase = None;
            let mut exact_media = None;
            for _ in 0..samples {
                let snapshot = collect_odp_media_source_phase(
                    &corpus.archive,
                    &picture_ranges,
                    target_slide,
                    query,
                )?;
                verify_odp_media_source_phase(snapshot, phase)?;
                if let Some(expected) = exact_phase {
                    if expected != snapshot {
                        return Err("ODP root source phase counters are not deterministic".into());
                    }
                } else {
                    exact_phase = Some(snapshot);
                }
                source_summary.source_read_calls.push(snapshot.read_calls);
                source_summary.source_read_bytes.push(snapshot.read_bytes);
                source_summary
                    .source_read_range_overlap_bytes
                    .push(snapshot.read_range_overlap_bytes);
                source_summary
                    .pictures_read_calls
                    .push(snapshot.ordinary_payload_read_calls);
                source_summary
                    .pictures_read_compressed_range_bytes
                    .push(snapshot.ordinary_payload_read_bytes);

                let (all_snapshot, selected_snapshot) = collect_odp_media_selected_media(
                    &corpus.archive,
                    &picture_ranges,
                    selected_range.clone(),
                    &selected_media_path,
                )?;
                if all_snapshot.ordinary_payload_read_bytes != selected_range_len
                    || selected_snapshot.ordinary_payload_read_bytes != selected_range_len
                    || all_snapshot.ordinary_payload_read_calls == 0
                    || selected_snapshot.ordinary_payload_read_calls == 0
                {
                    return Err(
                        "ODP root selected media replay did not cover exactly one Pictures range"
                            .into(),
                    );
                }
                if let Some(expected) = exact_media {
                    if expected != (all_snapshot, selected_snapshot) {
                        return Err("ODP root selected media counters are not deterministic".into());
                    }
                } else {
                    exact_media = Some((all_snapshot, selected_snapshot));
                }
                source_summary
                    .selected_media_read_calls
                    .push(all_snapshot.read_calls);
                source_summary
                    .selected_media_read_bytes
                    .push(all_snapshot.read_bytes);
                source_summary
                    .selected_media_read_prior_range_overlap_bytes
                    .push(all_snapshot.read_range_overlap_bytes);
                source_summary
                    .selected_media_read_compressed_range_overlap_bytes
                    .push(all_snapshot.ordinary_payload_read_bytes);
                source_summary
                    .selected_media_read_non_picture_overlap_bytes
                    .push(
                        all_snapshot
                            .read_bytes
                            .saturating_sub(all_snapshot.ordinary_payload_read_bytes),
                    );
            }
        }

        Ok(result_with_source(
            case,
            corpus,
            elapsed,
            SourceSummary {
                odp_root: Some(source_summary),
                ..SourceSummary::default()
            },
        ))
    })();
    let cleanup = fs::remove_file(&source_path);
    match (result, cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Ok(_), Err(error)) => Err(error.into()),
        (Err(error), _) => Err(error),
    }
}

fn odt_repeated_text_ranges(
    corpus: &Corpus,
) -> Result<(Range<u64>, Vec<Range<u64>>, Vec<Range<u64>>), Box<dyn Error>> {
    let (content_range, untouched_ranges, picture_ranges, _untouched_names) =
        odf_content_cow_ranges(&corpus.archive)?;
    if picture_ranges.len() != ODS_MEDIA_ENTRY_COUNT {
        return Err("ODT repeated-text source evidence found an unexpected Pictures count".into());
    }
    if content_range.is_empty() {
        return Err("ODT repeated-text source evidence found an empty content.xml range".into());
    }
    if picture_ranges.iter().any(Range::is_empty) {
        return Err("ODT repeated-text source evidence found an empty Pictures range".into());
    }
    Ok((content_range, untouched_ranges, picture_ranges))
}

fn odt_root_case_parameters(case: Case) -> Result<(&'static str, bool), Box<dyn Error>> {
    match case {
        Case::OdtFileEagerOpen => Ok(("eager_root", false)),
        Case::OdtFileSourceOpen => Ok(("source_backed_root", false)),
        Case::OdtFileEagerOpenFullTextLifecycle => Ok(("eager_root", true)),
        Case::OdtFileSourceOpenFullTextLifecycle => Ok(("source_backed_root", true)),
        _ => Err("non-root ODT case passed to ODT root case parameters".into()),
    }
}

fn odt_root_table_text(table: &litchi::document::Table) -> Result<String, Box<dyn Error>> {
    let mut text = String::new();
    for row in table.rows()? {
        for cell in row.cells()? {
            text.push_str(&cell.text()?);
        }
    }
    Ok(text)
}

fn odt_root_semantic_projection(
    document: &litchi::Document,
) -> Result<OdtRootSemanticProjection, Box<dyn Error>> {
    let text = document.text()?;
    let paragraphs = document
        .paragraphs()?
        .into_iter()
        .map(|paragraph| paragraph.text())
        .collect::<Result<Vec<_>, _>>()?;
    let tables = document
        .tables()?
        .into_iter()
        .map(|table| odt_root_table_text(&table))
        .collect::<Result<Vec<_>, _>>()?;
    let elements = document
        .elements()?
        .into_iter()
        .map(|element| {
            if let Some(paragraph) = element.as_paragraph() {
                Ok(format!("paragraph:{}", paragraph.text()?))
            } else if let Some(table) = element.as_table() {
                Ok(format!("table:{}", odt_root_table_text(table)?))
            } else {
                Err("ODT unified root returned an unsupported document element".into())
            }
        })
        .collect::<Result<Vec<_>, Box<dyn Error>>>()?;
    let metadata_sha256 = sha256_hex(&serde_json::to_vec(&document.metadata()?)?);
    Ok(OdtRootSemanticProjection {
        text,
        paragraphs,
        tables,
        elements,
        metadata_sha256,
    })
}

fn odt_root_values_digest(values: &[String]) -> String {
    let mut digest = Sha256::new();
    for (index, value) in values.iter().enumerate() {
        digest.update((index as u64).to_le_bytes());
        digest.update((value.len() as u64).to_le_bytes());
        digest.update(value.as_bytes());
    }
    fingerprint_hex(&digest.finalize().into())
}

fn odt_root_names_digest(names: &[String]) -> String {
    odt_root_values_digest(names)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct OdtRootArchiveIdentity {
    archive_member_count: usize,
    archive_member_names_sha256: String,
    pictures_count: usize,
    pictures_member_names_sha256: String,
    pictures_compressed_range_bytes: u64,
    pictures_uncompressed_payload_bytes: u64,
    pictures_uncompressed_payload_sha256: String,
}

fn odt_root_archive_identity(bytes: &[u8]) -> Result<OdtRootArchiveIdentity, Box<dyn Error>> {
    let archive = ArchiveReader::new(bytes)?;
    let mut member_names = archive.file_names().map(str::to_owned).collect::<Vec<_>>();
    member_names.sort();

    let mut picture_members = zip_member_ranges(bytes)?
        .into_iter()
        .filter(|(name, _range)| name.starts_with("Pictures/"))
        .collect::<Vec<_>>();
    picture_members.sort_by(|left, right| left.0.cmp(&right.0));
    if picture_members.len() != ODS_MEDIA_ENTRY_COUNT {
        return Err("ODT unified root archive has an unexpected Pictures count".into());
    }
    let picture_names = picture_members
        .iter()
        .map(|(name, _range)| name.clone())
        .collect::<Vec<_>>();
    let pictures_compressed_range_bytes =
        picture_members
            .iter()
            .try_fold(0_u64, |total, (_name, range)| {
                total
                    .checked_add(range.end.saturating_sub(range.start))
                    .ok_or("ODT unified root compressed Pictures byte count overflows u64")
            })?;

    let package = litchi_odf_common::core::OwnedPackage::from_bytes(bytes.to_vec())?;
    let package = package.package()?;
    for index in 0..ODS_MEDIA_ENTRY_COUNT {
        let path = odt_media_path(index);
        if package.manifest().get_media_type(&path) != Some("application/octet-stream") {
            return Err(format!("ODT unified root manifest entry differs for '{path}'").into());
        }
        if package.get_file(&path)? != odt_media_payload(index) {
            return Err(format!("ODT unified root payload differs for '{path}'").into());
        }
    }

    Ok(OdtRootArchiveIdentity {
        archive_member_count: member_names.len(),
        archive_member_names_sha256: odt_root_names_digest(&member_names),
        pictures_count: picture_members.len(),
        pictures_member_names_sha256: odt_root_names_digest(&picture_names),
        pictures_compressed_range_bytes,
        pictures_uncompressed_payload_bytes: u64::try_from(
            ODS_MEDIA_ENTRY_COUNT
                .checked_mul(ODS_MEDIA_ENTRY_BYTES)
                .ok_or("ODT unified root uncompressed Pictures byte count overflows usize")?,
        )?,
        pictures_uncompressed_payload_sha256: odt_repeated_text_media_payload_digest(),
    })
}

fn create_odt_root_source_file(archive: &[u8]) -> Result<PathBuf, Box<dyn Error>> {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| format!("ODT root source timestamp is before epoch: {error}"))?
        .as_nanos();
    let path = std::env::temp_dir().join(format!(
        "litchi-perf-baseline-odt-root-{}-{stamp}.odt",
        std::process::id()
    ));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&path)?;
    if let Err(error) = file.write_all(archive).and_then(|()| file.flush()) {
        drop(file);
        let _ = fs::remove_file(&path);
        return Err(error.into());
    }
    Ok(path)
}

#[derive(Clone, Copy, Debug)]
struct OdtRootReplay {
    preparation: SourceSnapshot,
    query: SourceSnapshot,
}

fn replay_odt_root_source(
    corpus: &Corpus,
    expected_text: &str,
) -> Result<OdtRootReplay, Box<dyn Error>> {
    let (content_range, untouched_ranges, picture_ranges) = odt_repeated_text_ranges(corpus)?;
    let source = Arc::new(InstrumentedSource::new_odf(
        corpus.archive.clone(),
        vec![content_range],
        untouched_ranges,
        picture_ranges,
    ));
    let document = litchi_odt::SourceBackedDocument::from_read_at(source.clone())?;
    let preparation = source.snapshot();
    if preparation.read_calls == 0
        || preparation.read_bytes == 0
        || preparation.odf.content.read_calls == 0
        || preparation.odf.content.read_bytes == 0
        || preparation.odf.pictures.read_calls != 0
        || preparation.odf.pictures.read_bytes != 0
    {
        return Err("ODT unified root source preparation failed source-range gates".into());
    }
    source.reset();
    if document.text()? != expected_text {
        return Err("ODT unified root source query differs from eager text".into());
    }
    let query = source.snapshot();
    if query.odf.pictures.read_calls != 0 || query.odf.pictures.read_bytes != 0 {
        return Err("ODT unified root source query overlapped Pictures payload".into());
    }
    Ok(OdtRootReplay { preparation, query })
}

fn run_odt_file_root(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_odt_root_file() {
        return Err("non-root ODT case passed to ODT root runner".into());
    }
    if corpus.manifest.generator != ODT_REPEATED_TEXT_CORPUS_GENERATOR {
        return Err("ODT root filesystem cases require the fixed large media-rich corpus".into());
    }
    let (implementation, lifecycle) = odt_root_case_parameters(case)?;
    let source_path = create_odt_root_source_file(&corpus.archive)?;
    let result = (|| {
        let source_bytes = fs::read(&source_path)?;
        if source_bytes != corpus.archive
            || sha256_hex(&source_bytes) != corpus.manifest.archive_sha256
            || source_bytes.len() != corpus.manifest.archive_bytes
        {
            return Err("ODT unified root source file differs from deterministic archive".into());
        }
        let archive_identity = odt_root_archive_identity(&corpus.archive)?;
        let source_identity = odt_root_archive_identity(&source_bytes)?;
        if source_identity != archive_identity
            || archive_identity.archive_member_count != corpus.manifest.archive_member_count
        {
            return Err("ODT unified root source archive identity differs from corpus".into());
        }

        let eager = litchi::Document::from_bytes(corpus.archive.clone())?;
        let source = litchi::Document::open(&source_path)?;
        let eager_semantics = odt_root_semantic_projection(&eager)?;
        let source_semantics = odt_root_semantic_projection(&source)?;
        if source_semantics != eager_semantics {
            return Err("ODT unified root eager/source semantic parity failed".into());
        }
        if eager_semantics.paragraphs.len() != SemanticShape::Large.docx_paragraphs()
            || eager_semantics
                .paragraphs
                .iter()
                .enumerate()
                .any(|(index, value)| value != &semantic_odt_text(index, false))
        {
            return Err("ODT unified root paragraph content differs from corpus".into());
        }
        if eager_semantics.text != eager_semantics.paragraphs.join("\n") {
            return Err("ODT unified root text differs from paragraph content".into());
        }

        let mut elapsed = Vec::with_capacity(samples);
        let mut summary = OdtFileRootSummary {
            implementation,
            phase: if lifecycle {
                "open_and_full_text_lifecycle"
            } else {
                "open_only"
            },
            timing_scope: if lifecycle {
                "filesystem_read_or_path_open_and_unified_document_full_text_query_inside_timer; corpus, temporary-file setup, semantic parity, archive identity, and source replay outside timer"
            } else {
                "filesystem_read_or_path_open_and_unified_document_ownership_inside_timer; corpus, temporary-file setup, semantic parity, archive identity, and source replay outside timer"
            },
            timed_root_adapter: if implementation == "source_backed_root" {
                if lifecycle {
                    "litchi::Document::open(Path)+Document::text"
                } else {
                    "litchi::Document::open(Path)"
                }
            } else if lifecycle {
                "fs::read(Path)+litchi::Document::from_bytes(Vec<u8>)+Document::text"
            } else {
                "fs::read(Path)+litchi::Document::from_bytes(Vec<u8>)"
            },
            read_evidence_adapter: if implementation == "source_backed_root" {
                "litchi_odt::SourceBackedDocument+harness::InstrumentedSource"
            } else {
                "not_applicable"
            },
            read_evidence_scope: if implementation == "source_backed_root" {
                "separate_untimed_instrumented_source_replay_per_measured_sample"
            } else {
                "not_applicable"
            },
            source_path_bytes: u64::try_from(source_bytes.len())?,
            source_path_sha256: sha256_hex(&source_bytes),
            archive_member_count: archive_identity.archive_member_count,
            archive_member_names_sha256: archive_identity.archive_member_names_sha256.clone(),
            pictures_count: archive_identity.pictures_count,
            pictures_member_names_sha256: archive_identity.pictures_member_names_sha256.clone(),
            pictures_compressed_range_bytes: archive_identity.pictures_compressed_range_bytes,
            pictures_uncompressed_payload_bytes: archive_identity
                .pictures_uncompressed_payload_bytes,
            pictures_uncompressed_payload_sha256: archive_identity
                .pictures_uncompressed_payload_sha256
                .clone(),
            canonical_text_sha256: sha256_hex(eager_semantics.text.as_bytes()),
            paragraph_count: eager_semantics.paragraphs.len(),
            paragraph_text_sha256: odt_root_values_digest(&eager_semantics.paragraphs),
            table_count: eager_semantics.tables.len(),
            element_count: eager_semantics.elements.len(),
            element_text_sha256: odt_root_values_digest(&eager_semantics.elements),
            metadata_sha256: eager_semantics.metadata_sha256.clone(),
            semantic_parity_verified: true,
            archive_identity_verified: true,
            media_identity_verified: true,
            source_ranges_verified: implementation != "source_backed_root",
            zero_picture_payload_overlap_verified: implementation != "source_backed_root",
            ..OdtFileRootSummary::default()
        };

        for iteration in 0..iteration_count(warmup_iterations, samples)? {
            let started = Instant::now();
            let document = if implementation == "source_backed_root" {
                litchi::Document::open(&source_path)?
            } else {
                let bytes = fs::read(&source_path)?;
                litchi::Document::from_bytes(bytes)?
            };
            let text = if lifecycle {
                Some(document.text()?)
            } else {
                None
            };
            let duration = started.elapsed();
            if let Some(text) = text.as_deref()
                && text != eager_semantics.text
            {
                return Err(
                    "ODT unified root timed full-text lifecycle differs from oracle".into(),
                );
            }
            std::hint::black_box(document);
            std::hint::black_box(text);
            record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        }

        if implementation == "source_backed_root" {
            let mut expected_replay = None;
            for _ in 0..samples {
                let replay = replay_odt_root_source(corpus, &eager_semantics.text)?;
                let tuple = (replay.preparation, replay.query);
                if let Some(expected) = expected_replay {
                    if expected != tuple {
                        return Err(
                            "ODT unified root source replay counters are not deterministic".into(),
                        );
                    }
                } else {
                    expected_replay = Some(tuple);
                }
                summary
                    .source_preparation_read_calls
                    .push(replay.preparation.read_calls);
                summary
                    .source_preparation_read_bytes
                    .push(replay.preparation.read_bytes);
                summary
                    .source_preparation_content_read_calls
                    .push(replay.preparation.odf.content.read_calls);
                summary
                    .source_preparation_content_read_bytes
                    .push(replay.preparation.odf.content.read_bytes);
                summary
                    .source_preparation_untouched_read_calls
                    .push(replay.preparation.odf.untouched.read_calls);
                summary
                    .source_preparation_untouched_read_bytes
                    .push(replay.preparation.odf.untouched.read_bytes);
                summary
                    .source_preparation_pictures_read_calls
                    .push(replay.preparation.odf.pictures.read_calls);
                summary
                    .source_preparation_pictures_read_bytes
                    .push(replay.preparation.odf.pictures.read_bytes);
                summary
                    .source_query_read_calls
                    .push(replay.query.read_calls);
                summary
                    .source_query_read_bytes
                    .push(replay.query.read_bytes);
                summary
                    .source_query_content_read_calls
                    .push(replay.query.odf.content.read_calls);
                summary
                    .source_query_content_read_bytes
                    .push(replay.query.odf.content.read_bytes);
                summary
                    .source_query_untouched_read_calls
                    .push(replay.query.odf.untouched.read_calls);
                summary
                    .source_query_untouched_read_bytes
                    .push(replay.query.odf.untouched.read_bytes);
                summary
                    .source_query_pictures_read_calls
                    .push(replay.query.odf.pictures.read_calls);
                summary
                    .source_query_pictures_read_bytes
                    .push(replay.query.odf.pictures.read_bytes);
            }
            summary.source_ranges_verified = true;
            summary.zero_picture_payload_overlap_verified = summary
                .source_preparation_pictures_read_calls
                .iter()
                .chain(summary.source_query_pictures_read_calls.iter())
                .all(|&calls| calls == 0)
                && summary
                    .source_preparation_pictures_read_bytes
                    .iter()
                    .chain(summary.source_query_pictures_read_bytes.iter())
                    .all(|&bytes| bytes == 0);
            if !summary.zero_picture_payload_overlap_verified {
                return Err("ODT unified root source replay picture overlap gate failed".into());
            }
        }

        Ok(result_with_source(
            case,
            corpus,
            elapsed,
            SourceSummary {
                read_calls: summary.source_preparation_read_calls.clone(),
                read_bytes: summary.source_preparation_read_bytes.clone(),
                ordinary_payload_read_calls: vec![0; summary.source_preparation_read_calls.len()],
                ordinary_payload_read_bytes: vec![0; summary.source_preparation_read_calls.len()],
                odt_root: Some(summary),
                ..SourceSummary::default()
            },
        ))
    })();
    let cleanup = fs::remove_file(&source_path);
    match (result, cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Ok(_), Err(error)) => Err(error.into()),
        (Err(error), _) => Err(error),
    }
}

fn odt_repeated_text_media_payload_digest() -> String {
    let mut digest = Sha256::new();
    for index in 0..ODS_MEDIA_ENTRY_COUNT {
        digest.update((index as u64).to_le_bytes());
        digest.update(odt_media_payload(index));
    }
    fingerprint_hex(&digest.finalize().into())
}

fn odt_repeated_text_digest(values: &[String]) -> String {
    let mut digest = Sha256::new();
    for (index, value) in values.iter().enumerate() {
        digest.update((index as u64).to_le_bytes());
        digest.update((value.len() as u64).to_le_bytes());
        digest.update(value.as_bytes());
    }
    fingerprint_hex(&digest.finalize().into())
}

fn odt_repeated_text_uncached(
    document: &litchi_odt::SourceBackedDocument,
    content_xml: &str,
) -> Result<String, Box<dyn Error>> {
    document.check_source()?;
    let result = litchi_odt::elements::text::TextElements::extract_text(content_xml);
    document.check_source()?;
    Ok(result?)
}

fn run_odt_repeated_text(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_odt_repeated_text() {
        return Err("non-repeated-text ODT case passed to repeated-text runner".into());
    }
    if corpus.manifest.generator != ODT_REPEATED_TEXT_CORPUS_GENERATOR {
        return Err("ODT repeated-text cases require the fixed large media-rich corpus".into());
    }

    let eager = litchi_odt::Document::from_bytes(corpus.archive.clone())?;
    let expected_text = eager.text()?;
    let expected_paragraph_count = eager.paragraph_count()?;
    if expected_paragraph_count != SemanticShape::Large.docx_paragraphs() {
        return Err("ODT repeated-text eager paragraph count differs from corpus shape".into());
    }
    let content_xml = odf_content_xml(&corpus.archive)?;
    let canonical_text_sha256 = sha256_hex(expected_text.as_bytes());
    let content_xml_sha256 = sha256_hex(&content_xml);
    let (content_range, untouched_ranges, picture_ranges) = odt_repeated_text_ranges(corpus)?;
    let archive_member_count = ArchiveReader::new(&corpus.archive)?.file_names().count();
    if archive_member_count != corpus.manifest.archive_member_count {
        return Err("ODT repeated-text archive member count differs from manifest".into());
    }
    verify_odt_repeated_text_archive(&corpus.archive)?;
    let pictures_uncompressed_payload_bytes = u64::try_from(
        ODS_MEDIA_ENTRY_COUNT
            .checked_mul(ODS_MEDIA_ENTRY_BYTES)
            .ok_or("ODT repeated-text Pictures byte count overflows usize")?,
    )?;
    let pictures_uncompressed_payload_sha256 = odt_repeated_text_media_payload_digest();

    let mut expected_outputs = Vec::new();
    expected_outputs
        .try_reserve_exact(ODT_REPEATED_TEXT_CALLS)
        .map_err(|error| format!("ODT repeated-text expected-output allocation failed: {error}"))?;
    for _ in 0..ODT_REPEATED_TEXT_CALLS {
        expected_outputs.push(expected_text.clone());
    }
    let expected_repeated_digest = odt_repeated_text_digest(&expected_outputs);
    let implementation = match case {
        Case::OdtSourceBackedRepeatedTextUncached => "source_backed_uncached_public_control",
        Case::OdtSourceBackedRepeatedTextCached => "source_backed_text_cache_candidate",
        _ => unreachable!("repeated-text case validated above"),
    };
    let mut elapsed = Vec::new();
    elapsed
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODT repeated-text elapsed allocation failed: {error}"))?;
    let mut summary = OdtRepeatedTextSummary {
        implementation,
        phase: "four_repeated_full_text_projections",
        timing_scope: "source-backed owner and four output slots prepared outside timer; four public full-text projections inside timer; semantic, archive, media, source-range, freshness, and zero-post-preparation-read gates outside timer",
        source_evidence_scope: "separate untimed InstrumentedSource replay per measured sample",
        projection_calls: ODT_REPEATED_TEXT_CALLS,
        paragraph_count: expected_paragraph_count,
        archive_member_count,
        pictures_count: picture_ranges.len(),
        pictures_uncompressed_payload_bytes,
        canonical_text_sha256,
        content_xml_sha256,
        source_archive_bytes: u64::try_from(corpus.archive.len())?,
        source_archive_sha256: corpus.manifest.archive_sha256.clone(),
        pictures_uncompressed_payload_sha256,
        freshness_shape: "pending".to_owned(),
        ..OdtRepeatedTextSummary::default()
    };

    macro_rules! reserve_summary_vec {
        ($field:ident, $message:literal) => {
            summary.$field.try_reserve_exact(samples).map_err(|error| {
                format!(
                    concat!("ODT repeated-text ", $message, " allocation failed: {}"),
                    error
                )
            })?;
        };
    }
    reserve_summary_vec!(projection_text_sha256, "digest");
    reserve_summary_vec!(source_preparation_read_calls, "preparation-call");
    reserve_summary_vec!(source_preparation_read_bytes, "preparation-byte");
    reserve_summary_vec!(
        source_preparation_content_read_calls,
        "preparation-content-call"
    );
    reserve_summary_vec!(
        source_preparation_content_read_bytes,
        "preparation-content-byte"
    );
    reserve_summary_vec!(
        source_preparation_untouched_read_calls,
        "preparation-untouched-call"
    );
    reserve_summary_vec!(
        source_preparation_untouched_read_bytes,
        "preparation-untouched-byte"
    );
    reserve_summary_vec!(
        source_preparation_pictures_read_calls,
        "preparation-pictures-call"
    );
    reserve_summary_vec!(
        source_preparation_pictures_read_bytes,
        "preparation-pictures-byte"
    );
    reserve_summary_vec!(
        source_preparation_version_observations,
        "preparation-version"
    );
    reserve_summary_vec!(source_replay_read_calls, "replay-call");
    reserve_summary_vec!(source_replay_read_bytes, "replay-byte");
    reserve_summary_vec!(source_replay_range_overlap_bytes, "replay-overlap");
    reserve_summary_vec!(source_replay_content_read_calls, "replay-content-call");
    reserve_summary_vec!(source_replay_content_read_bytes, "replay-content-byte");
    reserve_summary_vec!(source_replay_untouched_read_calls, "replay-untouched-call");
    reserve_summary_vec!(source_replay_untouched_read_bytes, "replay-untouched-byte");
    reserve_summary_vec!(source_replay_pictures_read_calls, "replay-pictures-call");
    reserve_summary_vec!(source_replay_pictures_read_bytes, "replay-pictures-byte");
    reserve_summary_vec!(source_replay_version_observations, "replay-version");
    summary
        .source_replay_version_observations_per_call
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODT repeated-text per-call version allocation failed: {error}")
        })?;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
        let document = litchi_odt::SourceBackedDocument::from_read_at(source)?;
        // Acquire the retained XML before timing.  The control below only
        // performs its two freshness observations around extraction, matching
        // the public `text()` boundary without moving XML acquisition into
        // the four-projection interval.
        let content_xml = document.content_xml()?;
        let mut outputs = Vec::new();
        outputs
            .try_reserve_exact(ODT_REPEATED_TEXT_CALLS)
            .map_err(|error| format!("ODT repeated-text output allocation failed: {error}"))?;

        let started = Instant::now();
        for _ in 0..ODT_REPEATED_TEXT_CALLS {
            let text = match case {
                Case::OdtSourceBackedRepeatedTextUncached => {
                    odt_repeated_text_uncached(&document, content_xml)?
                },
                Case::OdtSourceBackedRepeatedTextCached => document.text()?,
                _ => unreachable!("repeated-text case validated above"),
            };
            outputs.push(text);
        }
        let duration = started.elapsed();

        if outputs.len() != ODT_REPEATED_TEXT_CALLS
            || outputs.iter().any(|value| value != &expected_text)
            || odt_repeated_text_digest(&outputs) != expected_repeated_digest
        {
            return Err("ODT repeated-text timed projection differs from canonical text".into());
        }
        // This is intentionally outside the measured projection interval:
        // it is a semantic parity gate, not part of the query timing.
        let source_projection = odt_repeated_text_uncached(&document, content_xml)?;
        if source_projection != expected_text {
            return Err("ODT repeated-text source semantic parity differs from eager text".into());
        }
        document.check_source()?;
        if iteration >= warmup_iterations {
            summary
                .projection_text_sha256
                .push(odt_repeated_text_digest(&outputs));
        }
        std::hint::black_box(outputs);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let mut expected_preparation = None;
    let mut expected_replay = None;
    let freshness_verified = true;
    let zero_reads_verified = true;
    for _ in 0..samples {
        let source = Arc::new(InstrumentedSource::new_odf(
            corpus.archive.clone(),
            vec![content_range.clone()],
            untouched_ranges.clone(),
            picture_ranges.clone(),
        ));
        let document = litchi_odt::SourceBackedDocument::from_read_at(source.clone())?;
        // Retain the validated XML before resetting counters.  This is owner
        // preparation, not one of the four measured/replayed projections.
        let content_xml = document.content_xml()?;
        let preparation = source.snapshot();
        let preparation_versions = source.version_calls();
        if preparation.read_calls == 0
            || preparation.read_bytes == 0
            || preparation.odf.content.read_calls == 0
            || preparation.odf.content.read_bytes == 0
            || preparation.odf.pictures.read_calls != 0
            || preparation.odf.pictures.read_bytes != 0
        {
            return Err("ODT repeated-text preparation failed source-range gates".into());
        }
        source.reset();

        let mut outputs = Vec::new();
        outputs
            .try_reserve_exact(ODT_REPEATED_TEXT_CALLS)
            .map_err(|error| {
                format!("ODT repeated-text replay output allocation failed: {error}")
            })?;
        let mut per_call_version_observations = Vec::new();
        per_call_version_observations
            .try_reserve_exact(ODT_REPEATED_TEXT_CALLS)
            .map_err(|error| {
                format!("ODT repeated-text per-call replay allocation failed: {error}")
            })?;
        for _ in 0..ODT_REPEATED_TEXT_CALLS {
            let before_versions = source.version_calls();
            let text = match case {
                Case::OdtSourceBackedRepeatedTextUncached => {
                    odt_repeated_text_uncached(&document, content_xml)?
                },
                Case::OdtSourceBackedRepeatedTextCached => document.text()?,
                _ => unreachable!("repeated-text case validated above"),
            };
            let after_versions = source.version_calls();
            let observed = after_versions
                .checked_sub(before_versions)
                .ok_or("ODT repeated-text version counter moved backwards")?;
            per_call_version_observations.push(observed);
            outputs.push(text);
        }
        let replay = source.snapshot();
        let replay_versions = source.version_calls();
        let no_post_preparation_reads = replay.read_calls == 0
            && replay.read_bytes == 0
            && replay.read_range_overlap_bytes == 0
            && replay.ordinary_payload_read_calls == 0
            && replay.ordinary_payload_read_bytes == 0
            && replay.odf.content.read_calls == 0
            && replay.odf.content.read_bytes == 0
            && replay.odf.untouched.read_calls == 0
            && replay.odf.untouched.read_bytes == 0
            && replay.odf.pictures.read_calls == 0
            && replay.odf.pictures.read_bytes == 0;
        if !no_post_preparation_reads {
            return Err("ODT repeated-text replay performed a post-preparation ReadAt".into());
        }
        let freshness_shape = if per_call_version_observations.as_slice()
            == ODT_REPEATED_TEXT_VERSION_OBSERVATIONS_PER_CALL.as_slice()
        {
            if replay_versions != ODT_REPEATED_TEXT_EXPECTED_VERSION_OBSERVATIONS {
                return Err(format!(
                    "ODT repeated-text baseline replay observed {replay_versions} freshness checks, expected {ODT_REPEATED_TEXT_EXPECTED_VERSION_OBSERVATIONS}"
                )
                .into());
            }
            "baseline_two_checks"
        } else if case == Case::OdtSourceBackedRepeatedTextCached
            && per_call_version_observations.as_slice()
                == ODT_REPEATED_TEXT_CACHE_VERSION_OBSERVATIONS_PER_CALL.as_slice()
        {
            let expected = ODT_REPEATED_TEXT_CACHE_VERSION_OBSERVATIONS_PER_CALL
                .iter()
                .sum::<u64>();
            if replay_versions != expected {
                return Err(format!(
                    "ODT repeated-text cache replay observed {replay_versions} freshness checks, expected {expected}"
                )
                .into());
            }
            "cache_enabled_publication_window"
        } else {
            return Err(format!(
                "ODT repeated-text replay observed unsupported per-call freshness checks {:?}",
                per_call_version_observations
            )
            .into());
        };
        if summary.freshness_shape == "pending" {
            summary.freshness_shape = freshness_shape.to_owned();
        } else if summary.freshness_shape != freshness_shape {
            return Err("ODT repeated-text freshness shape changed across samples".into());
        }
        if outputs.len() != ODT_REPEATED_TEXT_CALLS
            || outputs.iter().any(|value| value != &expected_text)
            || odt_repeated_text_digest(&outputs) != expected_repeated_digest
        {
            return Err("ODT repeated-text source replay differs from canonical text".into());
        }
        // The source owner has already been fully prepared.  This final
        // content projection is outside the exact four-call freshness window
        // and proves the retained XML still agrees with the eager oracle.
        if odt_repeated_text_uncached(&document, content_xml)? != expected_text {
            return Err("ODT repeated-text source replay semantic parity failed".into());
        }

        let preparation_tuple = (
            preparation.read_calls,
            preparation.read_bytes,
            preparation.odf.content,
            preparation.odf.untouched,
            preparation.odf.pictures,
            preparation_versions,
        );
        if let Some(expected) = expected_preparation {
            if expected != preparation_tuple {
                return Err("ODT repeated-text preparation counters are not deterministic".into());
            }
        } else {
            expected_preparation = Some(preparation_tuple);
        }
        let replay_tuple = (
            replay.read_calls,
            replay.read_bytes,
            replay.read_range_overlap_bytes,
            replay.odf.content,
            replay.odf.untouched,
            replay.odf.pictures,
            replay_versions,
        );
        if let Some(expected) = expected_replay {
            if expected != replay_tuple {
                return Err("ODT repeated-text replay counters are not deterministic".into());
            }
        } else {
            expected_replay = Some(replay_tuple);
        }

        summary
            .source_preparation_read_calls
            .push(preparation.read_calls);
        summary
            .source_preparation_read_bytes
            .push(preparation.read_bytes);
        summary
            .source_preparation_content_read_calls
            .push(preparation.odf.content.read_calls);
        summary
            .source_preparation_content_read_bytes
            .push(preparation.odf.content.read_bytes);
        summary
            .source_preparation_untouched_read_calls
            .push(preparation.odf.untouched.read_calls);
        summary
            .source_preparation_untouched_read_bytes
            .push(preparation.odf.untouched.read_bytes);
        summary
            .source_preparation_pictures_read_calls
            .push(preparation.odf.pictures.read_calls);
        summary
            .source_preparation_pictures_read_bytes
            .push(preparation.odf.pictures.read_bytes);
        summary
            .source_preparation_version_observations
            .push(preparation_versions);
        summary.source_replay_read_calls.push(replay.read_calls);
        summary.source_replay_read_bytes.push(replay.read_bytes);
        summary
            .source_replay_range_overlap_bytes
            .push(replay.read_range_overlap_bytes);
        summary
            .source_replay_content_read_calls
            .push(replay.odf.content.read_calls);
        summary
            .source_replay_content_read_bytes
            .push(replay.odf.content.read_bytes);
        summary
            .source_replay_untouched_read_calls
            .push(replay.odf.untouched.read_calls);
        summary
            .source_replay_untouched_read_bytes
            .push(replay.odf.untouched.read_bytes);
        summary
            .source_replay_pictures_read_calls
            .push(replay.odf.pictures.read_calls);
        summary
            .source_replay_pictures_read_bytes
            .push(replay.odf.pictures.read_bytes);
        summary
            .source_replay_version_observations
            .push(replay_versions);
        summary
            .source_replay_version_observations_per_call
            .push(per_call_version_observations);
    }

    let semantic_parity_verified = {
        let source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
        let document = litchi_odt::SourceBackedDocument::from_read_at(source)?;
        let paragraphs = document.paragraphs()?;
        paragraphs.len() == expected_paragraph_count
            && paragraphs.iter().enumerate().all(|(index, paragraph)| {
                paragraph.text().ok().as_deref() == Some(semantic_odt_text(index, false).as_str())
            })
            && document.text()? == expected_text
    };
    if !semantic_parity_verified {
        return Err("ODT repeated-text exact semantic parity gate failed".into());
    }
    summary.semantic_parity_verified = true;
    summary.archive_topology_verified = true;
    summary.media_payloads_verified = true;
    summary.source_ranges_verified = true;
    summary.source_freshness_verified = freshness_verified;
    summary.zero_post_preparation_reads_verified = zero_reads_verified;
    if !summary.source_freshness_verified || !summary.zero_post_preparation_reads_verified {
        return Err("ODT repeated-text evidence gates are incomplete".into());
    }

    Ok(result_with_source(
        case,
        corpus,
        elapsed,
        SourceSummary {
            read_calls: summary.source_replay_read_calls.clone(),
            read_bytes: summary.source_replay_read_bytes.clone(),
            ordinary_payload_read_calls: vec![0; samples],
            ordinary_payload_read_bytes: vec![0; samples],
            odt_repeated_text: Some(summary),
            ..SourceSummary::default()
        },
    ))
}

fn odp_repeated_text_uncached(
    presentation: &litchi_odp::SourceBackedPresentation,
) -> Result<String, Box<dyn Error>> {
    let slides = presentation.slides()?;
    let mut all_text = Vec::new();
    for slide in slides {
        let text = slide.all_text();
        if !text.is_empty() {
            all_text.push(text);
        }
    }
    // Keep the control's source-freshness work identical to the old
    // source-backed `text_uncached` path, including its trailing check.
    presentation.check_source()?;
    Ok(all_text.join("\n\n"))
}

fn odp_repeated_text_digest(values: &[String]) -> String {
    let mut digest = Sha256::new();
    for (index, value) in values.iter().enumerate() {
        digest.update((index as u64).to_le_bytes());
        digest.update((value.len() as u64).to_le_bytes());
        digest.update(value.as_bytes());
    }
    fingerprint_hex(&digest.finalize().into())
}

fn verify_odp_repeated_text_archive(corpus: &Corpus) -> Result<(), Box<dyn Error>> {
    if ArchiveReader::new(&corpus.archive)?.file_names().count()
        != corpus.manifest.archive_member_count
    {
        return Err("ODP repeated-text archive member topology differs from corpus".into());
    }
    verify_odp_media_archive(&corpus.archive, false)
}

fn run_odp_repeated_text(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !matches!(
        case,
        Case::OdpSourceBackedRepeatedTextUncached | Case::OdpSourceBackedRepeatedTextCached
    ) {
        return Err("non-repeated-text ODP case passed to repeated-text runner".into());
    }
    if corpus.manifest.generator != ODP_MEDIA_CORPUS_GENERATOR {
        return Err("ODP repeated-text cases require the fixed media-rich corpus".into());
    }

    let eager = litchi_odp::Presentation::from_bytes(corpus.archive.clone())?;
    let expected_text = eager.text()?;
    let expected_slides = eager.slides()?;
    let expected_single_text_sha256 = sha256_hex(expected_text.as_bytes());
    let mut expected_outputs = Vec::new();
    expected_outputs
        .try_reserve_exact(ODP_REPEATED_TEXT_CALLS)
        .map_err(|error| format!("ODP repeated-text expected-output allocation failed: {error}"))?;
    for _ in 0..ODP_REPEATED_TEXT_CALLS {
        expected_outputs.push(expected_text.clone());
    }
    let expected_repeated_digest = odp_repeated_text_digest(&expected_outputs);
    let (picture_members, _selected_range) = odp_media_payload_inventory(corpus)?;
    let mut picture_ranges = Vec::new();
    picture_ranges
        .try_reserve_exact(picture_members.len())
        .map_err(|error| format!("ODP repeated-text picture-range allocation failed: {error}"))?;
    for (_name, range) in &picture_members {
        picture_ranges.push(range.clone());
    }
    let pictures_uncompressed_payload_sha256 = odp_media_payload_digest();
    let pictures_uncompressed_payload_bytes = u64::try_from(
        ODS_MEDIA_ENTRY_COUNT
            .checked_mul(ODS_MEDIA_ENTRY_BYTES)
            .ok_or("ODP repeated-text Pictures byte count overflows usize")?,
    )?;
    // This is a complete untimed semantic/package/media preservation gate for
    // the exact corpus used by both matched selectors.
    verify_odp_repeated_text_archive(corpus)?;

    let implementation = match case {
        Case::OdpSourceBackedRepeatedTextUncached => "source_backed_uncached_public_control",
        Case::OdpSourceBackedRepeatedTextCached => "source_backed_text_cache_candidate",
        _ => unreachable!("repeated-text case validated above"),
    };
    let mut elapsed = Vec::new();
    elapsed
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text elapsed allocation failed: {error}"))?;
    let mut summary = OdpRepeatedTextSummary {
        implementation,
        phase: "four_repeated_full_text_projections",
        timing_scope: "source-backed owner and four output slots prepared outside timer; four public text projections inside timer; parity, digest, freshness, and package/media gates outside timer",
        source_evidence_scope: "separate_untimed_instrumented_source_replay_per_measured_sample",
        projection_calls: ODP_REPEATED_TEXT_CALLS,
        slide_count: expected_slides.len(),
        archive_member_count: corpus.manifest.archive_member_count,
        pictures_count: picture_members.len(),
        pictures_uncompressed_payload_bytes,
        canonical_text_sha256: expected_single_text_sha256,
        source_path_bytes: u64::try_from(corpus.archive.len())?,
        source_path_sha256: corpus.manifest.archive_sha256.clone(),
        pictures_uncompressed_payload_sha256,
        ..OdpRepeatedTextSummary::default()
    };
    summary
        .projection_text_sha256
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text digest allocation failed: {error}"))?;
    summary
        .source_preparation_read_calls
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text preparation-call allocation failed: {error}")
        })?;
    summary
        .source_preparation_read_bytes
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text preparation-byte allocation failed: {error}")
        })?;
    summary
        .source_preparation_payload_read_calls
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text preparation-payload-call allocation failed: {error}")
        })?;
    summary
        .source_preparation_payload_read_bytes
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text preparation-payload-byte allocation failed: {error}")
        })?;
    summary
        .source_preparation_version_observations
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text preparation-version allocation failed: {error}")
        })?;
    summary
        .source_replay_read_calls
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text replay-call allocation failed: {error}"))?;
    summary
        .source_replay_read_bytes
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text replay-byte allocation failed: {error}"))?;
    summary
        .source_replay_range_overlap_bytes
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text replay-overlap allocation failed: {error}"))?;
    summary
        .source_replay_payload_read_calls
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text replay-payload-call allocation failed: {error}")
        })?;
    summary
        .source_replay_payload_read_bytes
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text replay-payload-byte allocation failed: {error}")
        })?;
    summary
        .source_replay_version_observations
        .try_reserve_exact(samples)
        .map_err(|error| format!("ODP repeated-text replay-version allocation failed: {error}"))?;
    summary
        .source_replay_version_observations_per_call
        .try_reserve_exact(samples)
        .map_err(|error| {
            format!("ODP repeated-text per-call version allocation failed: {error}")
        })?;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
        let presentation = litchi_odp::SourceBackedPresentation::from_read_at(source)?;
        let mut outputs = Vec::new();
        outputs
            .try_reserve_exact(ODP_REPEATED_TEXT_CALLS)
            .map_err(|error| format!("ODP repeated-text output allocation failed: {error}"))?;

        let started = Instant::now();
        for _ in 0..ODP_REPEATED_TEXT_CALLS {
            let text = match case {
                Case::OdpSourceBackedRepeatedTextUncached => {
                    odp_repeated_text_uncached(&presentation)?
                },
                Case::OdpSourceBackedRepeatedTextCached => presentation.text()?,
                _ => unreachable!("repeated-text case validated above"),
            };
            outputs.push(text);
        }
        let duration = started.elapsed();

        if outputs.len() != ODP_REPEATED_TEXT_CALLS
            || outputs.iter().any(|value| value != &expected_text)
        {
            return Err("ODP repeated-text projection differs from canonical text".into());
        }
        let digest = odp_repeated_text_digest(&outputs);
        if digest != expected_repeated_digest {
            return Err("ODP repeated-text projection digest differs from canonical text".into());
        }
        if presentation.slides()? != expected_slides {
            return Err(
                "ODP repeated-text full slide projection differs from canonical slides".into(),
            );
        }
        presentation.check_source()?;
        verify_odp_repeated_text_archive(corpus)?;
        if iteration >= warmup_iterations {
            summary.projection_text_sha256.push(digest);
        }
        std::hint::black_box(outputs);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let mut expected_preparation = None;
    let mut expected_replay = None;
    for _ in 0..samples {
        let source = odp_media_instrumented_source(&corpus.archive, &picture_ranges);
        let presentation = litchi_odp::SourceBackedPresentation::from_read_at(source.clone())?;
        let preparation = source.snapshot();
        let preparation_versions = source.version_calls();
        if preparation_versions == 0 {
            return Err("ODP repeated-text source preparation observed no version checks".into());
        }
        source.reset();

        let mut outputs = Vec::new();
        outputs
            .try_reserve_exact(ODP_REPEATED_TEXT_CALLS)
            .map_err(|error| {
                format!("ODP repeated-text replay output allocation failed: {error}")
            })?;
        let mut per_call_version_observations = Vec::new();
        per_call_version_observations
            .try_reserve_exact(ODP_REPEATED_TEXT_CALLS)
            .map_err(|error| {
                format!("ODP repeated-text per-call replay allocation failed: {error}")
            })?;
        for _ in 0..ODP_REPEATED_TEXT_CALLS {
            let before_versions = source.version_calls();
            let text = match case {
                Case::OdpSourceBackedRepeatedTextUncached => {
                    odp_repeated_text_uncached(&presentation)?
                },
                Case::OdpSourceBackedRepeatedTextCached => presentation.text()?,
                _ => unreachable!("repeated-text case validated above"),
            };
            let after_versions = source.version_calls();
            per_call_version_observations.push(
                after_versions
                    .checked_sub(before_versions)
                    .ok_or("ODP repeated-text version counter moved backwards")?,
            );
            outputs.push(text);
        }
        let replay = source.snapshot();
        let replay_versions = source.version_calls();
        if replay.read_calls != 0
            || replay.read_bytes != 0
            || replay.ordinary_payload_read_calls != 0
            || replay.ordinary_payload_read_bytes != 0
            || replay.read_range_overlap_bytes != 0
        {
            return Err(
                "ODP repeated-text replay read source or media payload after preparation".into(),
            );
        }
        if replay_versions != ODP_REPEATED_TEXT_EXPECTED_VERSION_OBSERVATIONS {
            return Err(format!(
                "ODP repeated-text replay observed {replay_versions} version checks, expected {ODP_REPEATED_TEXT_EXPECTED_VERSION_OBSERVATIONS}"
            )
            .into());
        }
        let expected_per_call = match case {
            Case::OdpSourceBackedRepeatedTextUncached => {
                &ODP_REPEATED_TEXT_CONTROL_VERSION_OBSERVATIONS
            },
            Case::OdpSourceBackedRepeatedTextCached => {
                &ODP_REPEATED_TEXT_CANDIDATE_VERSION_OBSERVATIONS
            },
            _ => unreachable!("repeated-text case validated above"),
        };
        if per_call_version_observations.as_slice() != expected_per_call.as_slice() {
            return Err(format!(
                "ODP repeated-text replay observed per-call version checks {:?}, expected {:?}",
                per_call_version_observations, expected_per_call
            )
            .into());
        }
        if outputs.len() != ODP_REPEATED_TEXT_CALLS
            || outputs.iter().any(|value| value != &expected_text)
            || odp_repeated_text_digest(&outputs) != expected_repeated_digest
        {
            return Err("ODP repeated-text source replay differs from canonical text".into());
        }
        // The semantic parity check is deliberately after the exact four-call
        // freshness observation, so it does not alter the recorded 12-check
        // replay contract.
        if presentation.slides()? != expected_slides {
            return Err(
                "ODP repeated-text source replay slides differ from canonical slides".into(),
            );
        }
        let final_replay = source.snapshot();
        if final_replay.read_calls != 0 || final_replay.read_bytes != 0 {
            return Err("ODP repeated-text semantic parity replay read source bytes".into());
        }
        verify_odp_repeated_text_archive(corpus)?;

        let preparation_tuple = (
            preparation.read_calls,
            preparation.read_bytes,
            preparation.ordinary_payload_read_calls,
            preparation.ordinary_payload_read_bytes,
            preparation_versions,
        );
        if let Some(expected) = expected_preparation {
            if expected != preparation_tuple {
                return Err("ODP repeated-text preparation counters are not deterministic".into());
            }
        } else {
            expected_preparation = Some(preparation_tuple);
        }
        let replay_tuple = (
            replay.read_calls,
            replay.read_bytes,
            replay.read_range_overlap_bytes,
            replay.ordinary_payload_read_calls,
            replay.ordinary_payload_read_bytes,
            replay_versions,
        );
        if let Some(expected) = expected_replay {
            if expected != replay_tuple {
                return Err("ODP repeated-text replay counters are not deterministic".into());
            }
        } else {
            expected_replay = Some(replay_tuple);
        }

        summary
            .source_preparation_read_calls
            .push(preparation.read_calls);
        summary
            .source_preparation_read_bytes
            .push(preparation.read_bytes);
        summary
            .source_preparation_payload_read_calls
            .push(preparation.ordinary_payload_read_calls);
        summary
            .source_preparation_payload_read_bytes
            .push(preparation.ordinary_payload_read_bytes);
        summary
            .source_preparation_version_observations
            .push(preparation_versions);
        summary.source_replay_read_calls.push(replay.read_calls);
        summary.source_replay_read_bytes.push(replay.read_bytes);
        summary
            .source_replay_range_overlap_bytes
            .push(replay.read_range_overlap_bytes);
        summary
            .source_replay_payload_read_calls
            .push(replay.ordinary_payload_read_calls);
        summary
            .source_replay_payload_read_bytes
            .push(replay.ordinary_payload_read_bytes);
        summary
            .source_replay_version_observations
            .push(replay_versions);
        summary
            .source_replay_version_observations_per_call
            .push(per_call_version_observations);
    }

    // The source owner is immutable, but retain a final complete package and
    // media check alongside the untimed semantic parity gates.
    verify_odp_repeated_text_archive(corpus)?;
    Ok(result_with_source(
        case,
        corpus,
        elapsed,
        SourceSummary {
            odp_repeated_text: Some(summary),
            ..SourceSummary::default()
        },
    ))
}

fn ods_root_file_case_parameters(
    case: Case,
) -> Result<(&'static str, &'static str, bool, bool), Box<dyn Error>> {
    match case {
        Case::OdsFileEagerOpen => Ok(("eager_root", "workbook_open", false, false)),
        Case::OdsFileSourceOpen => Ok(("source_backed_root", "workbook_open", false, false)),
        Case::OdsFileEagerSelectedCell => Ok(("eager_typed", "selected_cell_query", true, false)),
        Case::OdsFileSourceSelectedCell => {
            Ok(("source_backed_typed", "selected_cell_query", true, false))
        },
        Case::OdsFileEagerSelectedMedia => Ok(("eager_typed", "selected_media_query", true, true)),
        Case::OdsFileSourceSelectedMedia => {
            Ok(("source_backed_typed", "selected_media_query", true, true))
        },
        _ => Err("non-root ODS case passed to ODS root case parameters".into()),
    }
}

fn ods_root_text_digest(text: &str) -> String {
    sha256_hex(text.as_bytes())
}

fn ods_root_metadata_digest(metadata: &litchi_core::Metadata) -> Result<String, Box<dyn Error>> {
    Ok(sha256_hex(&serde_json::to_vec(metadata)?))
}

fn ods_root_typed_cell(
    spreadsheet: &litchi_ods::Spreadsheet,
    sheet: &str,
    row: usize,
    column: usize,
) -> Result<String, Box<dyn Error>> {
    let cell = spreadsheet
        .cell(sheet, row, column)
        .ok_or("ODS selected cell is missing")?;
    let litchi_ods::CellView::Stored(cell) = cell else {
        return Err("ODS selected cell is not stored".into());
    };
    Ok(cell.text.clone())
}

#[derive(Clone, Copy, Debug)]
struct OdsCellSweepCoordinate {
    sheet: usize,
    row: usize,
    column: usize,
}

fn ods_cell_sweep_coordinates() -> Vec<OdsCellSweepCoordinate> {
    let shape = SemanticShape::Medium;
    (0..shape.ods_sheet_count())
        .flat_map(|sheet| {
            (0..shape.ods_rows_per_sheet()).flat_map(move |row| {
                (0..shape.ods_columns_per_sheet()).map(move |column| OdsCellSweepCoordinate {
                    sheet,
                    row,
                    column,
                })
            })
        })
        .collect()
}

fn ods_cell_batch_selectors<'a>(
    sheet_names: &'a [String],
    coordinates: &[OdsCellSweepCoordinate],
) -> Result<Vec<litchi_ods::CellSelector<'a>>, Box<dyn Error>> {
    if coordinates.len() > litchi_ods::MAX_CELL_SELECTORS {
        return Err(format!(
            "ODS cell batch selector count {} exceeds {}",
            coordinates.len(),
            litchi_ods::MAX_CELL_SELECTORS
        )
        .into());
    }
    let mut selectors = Vec::new();
    selectors
        .try_reserve_exact(coordinates.len())
        .map_err(|error| format!("ODS cell batch selector allocation failed: {error}"))?;
    for coordinate in coordinates {
        let sheet_name = sheet_names
            .get(coordinate.sheet)
            .ok_or("ODS cell batch selector sheet index is out of bounds")?;
        selectors.push(litchi_ods::CellSelector::new(
            sheet_name,
            coordinate.row,
            coordinate.column,
        ));
    }
    Ok(selectors)
}

fn ods_cell_sweep_digest_field(digest: &mut Sha256, value: Option<&str>) -> usize {
    match value {
        Some(value) => {
            digest.update([1]);
            digest.update((value.len() as u64).to_le_bytes());
            digest.update(value.as_bytes());
            1
        },
        None => {
            digest.update([0]);
            0
        },
    }
}

fn ods_owned_cell_sweep_digest(
    spreadsheet: &litchi_ods::Spreadsheet,
    sheet_names: &[String],
    coordinates: &[OdsCellSweepCoordinate],
) -> Result<(usize, String), Box<dyn Error>> {
    let mut digest = Sha256::new();
    let mut stored_cells = 0usize;
    for _ in 0..ODS_CELL_SWEEP_REPETITIONS {
        for coordinate in coordinates {
            digest.update((coordinate.sheet as u64).to_le_bytes());
            digest.update((coordinate.row as u64).to_le_bytes());
            digest.update((coordinate.column as u64).to_le_bytes());
            let value = match spreadsheet.cell(
                &sheet_names[coordinate.sheet],
                coordinate.row,
                coordinate.column,
            ) {
                Some(litchi_ods::CellView::Stored(cell)) => Some(cell.text.as_str()),
                Some(litchi_ods::CellView::Missing) | None => None,
            };
            stored_cells = stored_cells
                .checked_add(ods_cell_sweep_digest_field(&mut digest, value))
                .ok_or("ODS owned sweep stored-cell count overflows usize")?;
        }
    }
    Ok((stored_cells, fingerprint_hex(&digest.finalize().into())))
}

fn ods_source_cell_sweep_digest(
    spreadsheet: &litchi_ods::SourceBackedSpreadsheet,
    sheet_names: &[String],
    coordinates: &[OdsCellSweepCoordinate],
) -> Result<(usize, String), Box<dyn Error>> {
    let mut digest = Sha256::new();
    let mut stored_cells = 0usize;
    for _ in 0..ODS_CELL_SWEEP_REPETITIONS {
        for coordinate in coordinates {
            digest.update((coordinate.sheet as u64).to_le_bytes());
            digest.update((coordinate.row as u64).to_le_bytes());
            digest.update((coordinate.column as u64).to_le_bytes());
            let value = match spreadsheet.cell(
                &sheet_names[coordinate.sheet],
                coordinate.row,
                coordinate.column,
            )? {
                Some(litchi_ods::CellView::Stored(cell)) => Some(cell.text.as_str()),
                Some(litchi_ods::CellView::Missing) | None => None,
            };
            stored_cells = stored_cells
                .checked_add(ods_cell_sweep_digest_field(&mut digest, value))
                .ok_or("ODS source sweep stored-cell count overflows usize")?;
        }
    }
    Ok((stored_cells, fingerprint_hex(&digest.finalize().into())))
}

fn run_ods_owned_cell_sweep(
    spreadsheet: &litchi_ods::Spreadsheet,
    sheet_names: &[String],
    coordinates: &[OdsCellSweepCoordinate],
) -> Result<(), Box<dyn Error>> {
    for _ in 0..ODS_CELL_SWEEP_REPETITIONS {
        for coordinate in coordinates {
            let value = spreadsheet.cell(
                &sheet_names[coordinate.sheet],
                coordinate.row,
                coordinate.column,
            );
            std::hint::black_box(value);
        }
    }
    Ok(())
}

