fn run_ods_cell_sweep(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !matches!(
        case,
        Case::OdsFileEagerCellSweep | Case::OdsFileSourceCellSweep
    ) {
        return Err("non-sweep ODS case passed to cell-sweep runner".into());
    }
    if corpus.manifest.generator != ODS_MEDIA_CORPUS_GENERATOR {
        return Err("ODS cell-sweep cases require the fixed media-rich corpus".into());
    }
    let coordinates = ods_cell_sweep_coordinates();
    let sheet_names = (0..SemanticShape::Medium.ods_sheet_count())
        .map(semantic_ods_sheet_name)
        .collect::<Vec<_>>();
    let expected_stored_cells = coordinates
        .len()
        .checked_mul(ODS_CELL_SWEEP_REPETITIONS)
        .ok_or("ODS cell-sweep query count overflows usize")?;
    let expected = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
    let (expected_stored, expected_digest) =
        ods_owned_cell_sweep_digest(&expected, &sheet_names, &coordinates)?;
    if expected_stored != expected_stored_cells {
        return Err("ODS eager cell-sweep oracle has missing cells".into());
    }
    let source_path = create_ods_root_source_file(&corpus.archive)?;
    let result = (|| {
        let mut elapsed = Vec::with_capacity(samples);
        let mut summary = OdsCellSweepSummary {
            implementation: if matches!(case, Case::OdsFileSourceCellSweep) {
                "source_backed"
            } else {
                "eager"
            },
            phase: "repeated_cell_sweep",
            timing_scope: "typed_owner_open_outside_timer; adaptive_locator_transition_and_repeated_cell_queries_inside_timer",
            source_evidence_scope: if matches!(case, Case::OdsFileSourceCellSweep) {
                "separate_untimed_instrumented_replay_after_owner_preparation_per_measured_sample"
            } else {
                "not_applicable"
            },
            query_count: coordinates.len(),
            sweep_repetitions: ODS_CELL_SWEEP_REPETITIONS,
            worksheet_count: sheet_names.len(),
            stored_cell_count: coordinates.len(),
            canonical_cell_digest_sha256: expected_digest.clone(),
            source_path_bytes: u64::try_from(corpus.archive.len())?,
            source_path_sha256: corpus.manifest.archive_sha256.clone(),
            ..OdsCellSweepSummary::default()
        };

        for iteration in 0..iteration_count(warmup_iterations, samples)? {
            let duration;
            let (stored_cells, digest) = match case {
                Case::OdsFileEagerCellSweep => {
                    let owner = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                    let started = Instant::now();
                    run_ods_owned_cell_sweep(&owner, &sheet_names, &coordinates)?;
                    duration = started.elapsed();
                    ods_owned_cell_sweep_digest(&owner, &sheet_names, &coordinates)?
                },
                Case::OdsFileSourceCellSweep => {
                    let owner = litchi_ods::SourceBackedSpreadsheet::from_path(&source_path)?;
                    let started = Instant::now();
                    run_ods_source_cell_sweep(&owner, &sheet_names, &coordinates)?;
                    duration = started.elapsed();
                    ods_source_cell_sweep_digest(&owner, &sheet_names, &coordinates)?
                },
                _ => return Err("non-sweep ODS case passed to measured loop".into()),
            };
            if stored_cells != expected_stored_cells || digest != expected_digest {
                return Err("ODS cell-sweep result differs from eager oracle".into());
            }
            let source_bytes = fs::read(&source_path)?;
            if source_bytes != corpus.archive
                || sha256_hex(&source_bytes) != corpus.manifest.archive_sha256
                || source_bytes.len() != corpus.manifest.archive_bytes
            {
                return Err("ODS cell-sweep source archive changed during measurement".into());
            }
            if ArchiveReader::new(&source_bytes)?.file_names().count()
                != corpus.manifest.archive_member_count
            {
                return Err("ODS cell-sweep source member topology changed".into());
            }
            verify_ods_media_archive(&source_bytes, false)?;
            if iteration >= warmup_iterations {
                summary.sweep_stored_cell_counts.push(stored_cells);
                summary.sweep_cell_digest_sha256.push(digest);
            }
            record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        }

        if matches!(case, Case::OdsFileSourceCellSweep) {
            let mut expected_preparation = None;
            for _ in 0..samples {
                let source = Arc::new(InstrumentedSource::new(corpus.archive.clone(), Vec::new()));
                let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source.clone())?;
                let preparation = source.snapshot();
                source.reset();
                run_ods_source_cell_sweep(&owner, &sheet_names, &coordinates)?;
                let sweep = source.snapshot();
                if sweep.read_calls != 0 || sweep.read_bytes != 0 {
                    return Err(
                        "ODS source cell sweep performed a source read after preparation".into(),
                    );
                }
                let preparation_counters = (preparation.read_calls, preparation.read_bytes);
                if let Some(expected) = expected_preparation {
                    if expected != preparation_counters {
                        return Err("ODS source preparation counters are not deterministic".into());
                    }
                } else {
                    expected_preparation = Some(preparation_counters);
                }
                summary
                    .source_preparation_read_calls
                    .push(preparation.read_calls);
                summary
                    .source_preparation_read_bytes
                    .push(preparation.read_bytes);
                summary.source_sweep_read_calls.push(sweep.read_calls);
                summary.source_sweep_read_bytes.push(sweep.read_bytes);
                summary
                    .source_sweep_read_range_overlap_bytes
                    .push(sweep.read_range_overlap_bytes);
            }
        }

        Ok(CaseResult {
            case: case.name(),
            cache_state: None,
            corpus: corpus.manifest.clone(),
            elapsed_ns: statistics(elapsed),
            sink: None,
            source: Some(SourceSummary {
                ods_cell_sweep: Some(summary),
                ..SourceSummary::default()
            }),
            execution: None,
            output_sha256: None,
            operation_metrics: None,
        })
    })();
    let cleanup = fs::remove_file(&source_path);
    match (result, cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Ok(_), Err(error)) => Err(error.into()),
        (Err(error), _) => Err(error),
    }
}

fn run_ods_cell_batch_sweep(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !matches!(
        case,
        Case::OdsFileEagerCellBatchSweep | Case::OdsFileSourceCellBatchSweep
    ) {
        return Err("non-batch-sweep ODS case passed to batch-sweep runner".into());
    }
    if corpus.manifest.generator != ODS_MEDIA_CORPUS_GENERATOR {
        return Err("ODS cell batch sweep cases require the fixed media-rich corpus".into());
    }
    let coordinates = ods_cell_sweep_coordinates();
    let sheet_names = (0..SemanticShape::Medium.ods_sheet_count())
        .map(semantic_ods_sheet_name)
        .collect::<Vec<_>>();
    let selectors = ods_cell_batch_selectors(&sheet_names, &coordinates)?;
    let expected_stored_cells = coordinates
        .len()
        .checked_mul(ODS_CELL_SWEEP_REPETITIONS)
        .ok_or("ODS cell batch sweep result count overflows usize")?;
    let expected = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
    let (expected_stored, expected_digest) =
        ods_owned_cell_sweep_digest(&expected, &sheet_names, &coordinates)?;
    if expected_stored != expected_stored_cells {
        return Err("ODS eager cell batch sweep oracle has missing cells".into());
    }
    let (batch_stored, batch_digest) =
        ods_owned_cell_batch_sweep_digest(&expected, &coordinates, &selectors)?;
    if batch_stored != expected_stored_cells || batch_digest != expected_digest {
        return Err("ODS cell batch sweep differs from scalar eager oracle".into());
    }

    let source_path = create_ods_root_source_file(&corpus.archive)?;
    let result = (|| {
        let mut elapsed = Vec::new();
        elapsed
            .try_reserve_exact(samples)
            .map_err(|error| format!("ODS cell batch elapsed allocation failed: {error}"))?;
        let mut summary = OdsCellBatchSweepSummary {
            implementation: if matches!(case, Case::OdsFileSourceCellBatchSweep) {
                "source_backed"
            } else {
                "eager"
            },
            phase: "ordered_cell_batch_sweep",
            timing_scope: "typed_owner_and_2048_selector_preparation_outside_timer; four_cell_batch_calls_and_result_black_box_inside_timer",
            source_evidence_scope: if matches!(case, Case::OdsFileSourceCellBatchSweep) {
                "separate_untimed_instrumented_replay_after_owner_preparation_per_measured_sample"
            } else {
                "not_applicable"
            },
            selector_count: selectors.len(),
            batch_calls: ODS_CELL_SWEEP_REPETITIONS,
            result_slots_per_sample: expected_stored_cells,
            worksheet_count: sheet_names.len(),
            stored_cell_count: coordinates.len(),
            canonical_cell_digest_sha256: expected_digest.clone(),
            source_path_bytes: u64::try_from(corpus.archive.len())?,
            source_path_sha256: corpus.manifest.archive_sha256.clone(),
            ..OdsCellBatchSweepSummary::default()
        };
        summary
            .sweep_stored_cell_counts
            .try_reserve_exact(samples)
            .map_err(|error| format!("ODS cell batch result-count allocation failed: {error}"))?;
        summary
            .sweep_cell_digest_sha256
            .try_reserve_exact(samples)
            .map_err(|error| format!("ODS cell batch digest allocation failed: {error}"))?;
        if matches!(case, Case::OdsFileSourceCellBatchSweep) {
            summary
                .source_preparation_read_calls
                .try_reserve_exact(samples)
                .map_err(|error| {
                    format!("ODS cell batch preparation-call allocation failed: {error}")
                })?;
            summary
                .source_preparation_read_bytes
                .try_reserve_exact(samples)
                .map_err(|error| {
                    format!("ODS cell batch preparation-byte allocation failed: {error}")
                })?;
            summary
                .source_sweep_read_calls
                .try_reserve_exact(samples)
                .map_err(|error| format!("ODS cell batch read-call allocation failed: {error}"))?;
            summary
                .source_sweep_read_bytes
                .try_reserve_exact(samples)
                .map_err(|error| format!("ODS cell batch read-byte allocation failed: {error}"))?;
            summary
                .source_sweep_read_range_overlap_bytes
                .try_reserve_exact(samples)
                .map_err(|error| {
                    format!("ODS cell batch overlap-byte allocation failed: {error}")
                })?;
            summary
                .source_sweep_version_observations
                .try_reserve_exact(samples)
                .map_err(|error| format!("ODS cell batch version allocation failed: {error}"))?;
        }

        for iteration in 0..iteration_count(warmup_iterations, samples)? {
            let duration;
            let (stored_cells, digest) = match case {
                Case::OdsFileEagerCellBatchSweep => {
                    let owner = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                    let started = Instant::now();
                    run_ods_owned_cell_batch_sweep(&owner, &selectors)?;
                    duration = started.elapsed();
                    ods_owned_cell_batch_sweep_digest(&owner, &coordinates, &selectors)?
                },
                Case::OdsFileSourceCellBatchSweep => {
                    let owner = litchi_ods::SourceBackedSpreadsheet::from_path(&source_path)?;
                    let started = Instant::now();
                    run_ods_source_cell_batch_sweep(&owner, &selectors)?;
                    duration = started.elapsed();
                    ods_source_cell_batch_sweep_digest(&owner, &coordinates, &selectors)?
                },
                _ => return Err("non-batch-sweep ODS case passed to measured loop".into()),
            };
            if stored_cells != expected_stored_cells || digest != expected_digest {
                return Err("ODS cell batch sweep result differs from eager oracle".into());
            }
            let source_bytes = fs::read(&source_path)?;
            if source_bytes != corpus.archive
                || sha256_hex(&source_bytes) != corpus.manifest.archive_sha256
                || source_bytes.len() != corpus.manifest.archive_bytes
            {
                return Err(
                    "ODS cell batch sweep source archive changed during measurement".into(),
                );
            }
            if ArchiveReader::new(&source_bytes)?.file_names().count()
                != corpus.manifest.archive_member_count
            {
                return Err("ODS cell batch sweep source member topology changed".into());
            }
            verify_ods_media_archive(&source_bytes, false)?;
            if iteration >= warmup_iterations {
                summary.sweep_stored_cell_counts.push(stored_cells);
                summary.sweep_cell_digest_sha256.push(digest);
            }
            record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        }

        if matches!(case, Case::OdsFileSourceCellBatchSweep) {
            let mut expected_preparation = None;
            for _ in 0..samples {
                let source = Arc::new(InstrumentedSource::new(corpus.archive.clone(), Vec::new()));
                let owner = litchi_ods::SourceBackedSpreadsheet::from_read_at(source.clone())?;
                let preparation = source.snapshot();
                source.reset();
                let (stored_cells, digest) =
                    ods_source_cell_batch_sweep_digest(&owner, &coordinates, &selectors)?;
                let sweep = source.snapshot();
                if sweep.read_calls != 0 || sweep.read_bytes != 0 {
                    return Err(
                        "ODS source cell batch sweep performed a source read after preparation"
                            .into(),
                    );
                }
                let expected_versions = u64::try_from(ODS_CELL_SWEEP_REPETITIONS)? * 2;
                let version_calls = source.version_calls();
                if version_calls != expected_versions {
                    return Err(format!(
                        "ODS source cell batch sweep observed {} version calls, expected {expected_versions}",
                        version_calls
                    )
                    .into());
                }
                if stored_cells != expected_stored_cells || digest != expected_digest {
                    return Err("ODS source cell batch replay differs from eager oracle".into());
                }
                let preparation_counters = (preparation.read_calls, preparation.read_bytes);
                if let Some(expected) = expected_preparation {
                    if expected != preparation_counters {
                        return Err(
                            "ODS source batch preparation counters are not deterministic".into(),
                        );
                    }
                } else {
                    expected_preparation = Some(preparation_counters);
                }
                summary
                    .source_preparation_read_calls
                    .push(preparation.read_calls);
                summary
                    .source_preparation_read_bytes
                    .push(preparation.read_bytes);
                summary.source_sweep_read_calls.push(sweep.read_calls);
                summary.source_sweep_read_bytes.push(sweep.read_bytes);
                summary
                    .source_sweep_read_range_overlap_bytes
                    .push(sweep.read_range_overlap_bytes);
                summary
                    .source_sweep_version_observations
                    .push(version_calls);
            }
        }

        Ok(CaseResult {
            case: case.name(),
            cache_state: None,
            corpus: corpus.manifest.clone(),
            elapsed_ns: statistics(elapsed),
            sink: None,
            source: Some(SourceSummary {
                ods_cell_batch_sweep: Some(summary),
                ..SourceSummary::default()
            }),
            execution: None,
            output_sha256: None,
            operation_metrics: None,
        })
    })();
    let cleanup = fs::remove_file(&source_path);
    match (result, cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Ok(_), Err(error)) => Err(error.into()),
        (Err(error), _) => Err(error),
    }
}

fn ods_root_source_cell(
    spreadsheet: &litchi_ods::SourceBackedSpreadsheet,
    sheet: &str,
    row: usize,
    column: usize,
) -> Result<String, Box<dyn Error>> {
    let cell = spreadsheet
        .cell(sheet, row, column)?
        .ok_or("ODS source selected cell is missing")?;
    let litchi_ods::CellView::Stored(cell) = cell else {
        return Err("ODS source selected cell is not stored".into());
    };
    Ok(cell.text.to_owned())
}

fn create_ods_root_source_file(archive: &[u8]) -> Result<PathBuf, Box<dyn Error>> {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| format!("ODS root source timestamp is before epoch: {error}"))?
        .as_nanos();
    let path = std::env::temp_dir().join(format!(
        "litchi-perf-baseline-ods-root-{}-{stamp}.ods",
        std::process::id()
    ));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&path)?;
    file.write_all(archive)?;
    file.flush()?;
    Ok(path)
}

fn ods_media_payload_inventory(
    corpus: &Corpus,
) -> Result<(Vec<(String, Range<u64>)>, Range<u64>), Box<dyn Error>> {
    let mut media = zip_member_ranges(&corpus.archive)?
        .into_iter()
        .filter(|(name, _range)| name.starts_with("Pictures/"))
        .collect::<Vec<_>>();
    media.sort_by(|left, right| left.0.cmp(&right.0));
    if media.len() != ODS_MEDIA_ENTRY_COUNT {
        return Err("ODS media source evidence found an unexpected Pictures count".into());
    }
    let selected_path = ods_media_path(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected = media
        .iter()
        .find(|(name, _range)| name == &selected_path)
        .map(|(_name, range)| range.clone())
        .ok_or("ODS selected media source range is missing")?;
    Ok((media, selected))
}

fn ods_media_payload_digest() -> String {
    let mut digest = Sha256::new();
    for index in 0..ODS_MEDIA_ENTRY_COUNT {
        digest.update((index as u64).to_le_bytes());
        digest.update(ods_media_payload(index));
    }
    fingerprint_hex(&digest.finalize().into())
}

fn ods_media_instrumented_source(
    archive: &[u8],
    picture_ranges: &[Range<u64>],
) -> Arc<InstrumentedSource> {
    let mut source = InstrumentedSource::new(archive.to_vec(), picture_ranges.to_vec());
    source.track_read_ranges = true;
    Arc::new(source)
}

fn verify_ods_source_phase(snapshot: SourceSnapshot, phase: &str) -> Result<(), Box<dyn Error>> {
    match phase {
        "workbook_open" => {
            if snapshot.read_calls == 0 || snapshot.read_bytes == 0 {
                return Err("ODS source-backed open replay has no logical reads".into());
            }
            if snapshot.ordinary_payload_read_calls != 0
                || snapshot.ordinary_payload_read_bytes != 0
            {
                return Err(
                    "ODS source-backed open replay read unrelated Pictures payload bytes".into(),
                );
            }
        },
        "selected_cell_query" => {
            if snapshot.read_calls != 0 || snapshot.read_bytes != 0 {
                return Err(
                    "ODS source-backed selected-cell replay performed a source read".into(),
                );
            }
        },
        "selected_media_query" => {
            if snapshot.ordinary_payload_read_calls == 0
                || snapshot.ordinary_payload_read_bytes == 0
            {
                return Err("ODS source-backed selected-media replay read no media range".into());
            }
        },
        _ => return Err("unknown ODS source evidence phase".into()),
    }
    Ok(())
}

fn collect_ods_source_phase(
    archive: &[u8],
    picture_ranges: &[Range<u64>],
    phase: &str,
    target_sheet: &str,
    target_row: usize,
    target_column: usize,
) -> Result<SourceSnapshot, Box<dyn Error>> {
    let source = ods_media_instrumented_source(archive, picture_ranges);
    let spreadsheet = litchi_ods::SourceBackedSpreadsheet::from_read_at(source.clone())?;
    if phase != "workbook_open" {
        source.reset();
    }
    match phase {
        "workbook_open" => {},
        "selected_cell_query" => {
            let text = ods_root_source_cell(&spreadsheet, target_sheet, target_row, target_column)?;
            if text != semantic_ods_text(1, target_row, target_column, false) {
                return Err("ODS source selected-cell replay differs from corpus".into());
            }
        },
        "selected_media_query" => {
            return Err("ODS selected-media replay requires exact selected-range tracking".into());
        },
        _ => return Err("unknown ODS source evidence phase".into()),
    }
    Ok(source.snapshot())
}

fn collect_ods_media_selected_media(
    archive: &[u8],
    picture_ranges: &[Range<u64>],
    selected_range: Range<u64>,
    selected_media_path: &str,
    selected_media_payload: &[u8],
) -> Result<(SourceSnapshot, SourceSnapshot), Box<dyn Error>> {
    let all_source = ods_media_instrumented_source(archive, picture_ranges);
    let all_spreadsheet = litchi_ods::SourceBackedSpreadsheet::from_read_at(all_source.clone())?;
    all_source.reset();
    let payload = all_spreadsheet
        .media_data(selected_media_path)?
        .ok_or("ODS source selected media member is missing")?;
    if payload != selected_media_payload {
        return Err("ODS source selected media payload differs from corpus".into());
    }
    let all_snapshot = all_source.snapshot();

    let selected_source = ods_media_instrumented_source(archive, &[selected_range]);
    let selected_spreadsheet =
        litchi_ods::SourceBackedSpreadsheet::from_read_at(selected_source.clone())?;
    selected_source.reset();
    let payload = selected_spreadsheet
        .media_data(selected_media_path)?
        .ok_or("ODS selected-range media member is missing")?;
    if payload != selected_media_payload {
        return Err("ODS selected-range media payload differs from corpus".into());
    }
    Ok((all_snapshot, selected_source.snapshot()))
}

struct OdsRootExpectations<'a> {
    source_path: &'a std::path::Path,
    corpus: &'a Corpus,
    worksheet_names: &'a [String],
    worksheet_count: usize,
    text: &'a str,
    metadata_sha256: &'a str,
    typed: &'a litchi_ods::Spreadsheet,
    target_sheet: &'a str,
    target_row: usize,
    target_column: usize,
    cell_text: &'a str,
    selected_media_path: &'a str,
    selected_media_payload: &'a [u8],
}

struct OdsTypedQueryProjection {
    worksheet_names: Vec<String>,
    worksheet_count: usize,
    text: String,
    metadata_sha256: String,
    cell_text: String,
}

fn verify_ods_typed_query_projection(
    actual: OdsTypedQueryProjection,
    expected: &OdsRootExpectations<'_>,
) -> Result<(), Box<dyn Error>> {
    if actual.worksheet_names != expected.worksheet_names {
        return Err("ODS typed query worksheet names differ from eager oracle".into());
    }
    if actual.worksheet_count != expected.worksheet_count {
        return Err("ODS typed query worksheet count differs from eager oracle".into());
    }
    if actual.text != expected.text {
        return Err("ODS typed query text differs from eager oracle".into());
    }
    if actual.metadata_sha256 != expected.metadata_sha256 {
        return Err("ODS typed query metadata differs from eager oracle".into());
    }
    if actual.cell_text != expected.cell_text {
        return Err("ODS typed query selected cell differs from eager oracle".into());
    }
    Ok(())
}

fn ods_typed_query_projection(
    owner: &litchi_ods::Spreadsheet,
    expected: &OdsRootExpectations<'_>,
) -> Result<OdsTypedQueryProjection, Box<dyn Error>> {
    Ok(OdsTypedQueryProjection {
        worksheet_names: owner.sheet_names(),
        worksheet_count: owner.sheet_count(),
        text: owner.text()?,
        metadata_sha256: ods_root_metadata_digest(owner.metadata())?,
        cell_text: ods_root_typed_cell(
            owner,
            expected.target_sheet,
            expected.target_row,
            expected.target_column,
        )?,
    })
}

fn ods_source_query_projection(
    owner: &litchi_ods::SourceBackedSpreadsheet,
    expected: &OdsRootExpectations<'_>,
) -> Result<OdsTypedQueryProjection, Box<dyn Error>> {
    Ok(OdsTypedQueryProjection {
        worksheet_names: owner.sheet_names()?,
        worksheet_count: owner.sheet_count()?,
        text: owner.text()?,
        metadata_sha256: ods_root_metadata_digest(owner.metadata()?)?,
        cell_text: ods_root_source_cell(
            owner,
            expected.target_sheet,
            expected.target_row,
            expected.target_column,
        )?,
    })
}

fn verify_ods_source_identity_postconditions(
    expected: &OdsRootExpectations<'_>,
) -> Result<(), Box<dyn Error>> {
    let bytes = fs::read(expected.source_path)?;
    if bytes != expected.corpus.archive
        || sha256_hex(&bytes) != expected.corpus.manifest.archive_sha256
        || bytes.len() != expected.corpus.manifest.archive_bytes
    {
        return Err("ODS unified root source file differs from deterministic archive".into());
    }
    if ArchiveReader::new(&bytes)?.file_names().count()
        != expected.corpus.manifest.archive_member_count
    {
        return Err("ODS unified root archive member count differs from corpus".into());
    }
    verify_ods_media_archive(&bytes, false)?;
    let package = litchi_odf_common::core::OwnedPackage::from_bytes(bytes)?;
    if package.package()?.get_file(expected.selected_media_path)? != expected.selected_media_payload
    {
        return Err("ODS unified root selected media payload differs from corpus".into());
    }
    Ok(())
}

fn verify_ods_root_postconditions(
    workbook: &litchi::Workbook,
    expected: &OdsRootExpectations<'_>,
) -> Result<(), Box<dyn Error>> {
    let names = workbook
        .worksheet_names()
        .map_err(|error| error.to_string())?;
    if names != expected.worksheet_names {
        return Err("ODS unified root worksheet names differ from eager oracle".into());
    }
    if workbook
        .worksheet_count()
        .map_err(|error| error.to_string())?
        != expected.worksheet_count
    {
        return Err("ODS unified root worksheet count differs from eager oracle".into());
    }
    let text = workbook.text().map_err(|error| error.to_string())?;
    if text != expected.text {
        return Err("ODS unified root text differs from eager oracle".into());
    }
    if ods_root_metadata_digest(&workbook.metadata().map_err(|error| error.to_string())?)?
        != expected.metadata_sha256
    {
        return Err("ODS unified root metadata differs from eager oracle".into());
    }

    verify_semantic_ods(expected.typed, SemanticShape::Medium, false)?;
    let typed_cell = ods_root_typed_cell(
        expected.typed,
        expected.target_sheet,
        expected.target_row,
        expected.target_column,
    )?;
    if typed_cell != expected.cell_text {
        return Err("ODS typed selected cell differs from canonical oracle".into());
    }
    if expected.cell_text
        != semantic_ods_text(1, expected.target_row, expected.target_column, false)
    {
        return Err("ODS typed selected cell differs from deterministic corpus".into());
    }

    verify_ods_source_identity_postconditions(expected)?;
    Ok(())
}

fn run_ods_root_file_access(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != ODS_MEDIA_CORPUS_GENERATOR {
        return Err("ODS root filesystem cases require the fixed media-rich corpus".into());
    }
    let (implementation, phase, query, media_query) = ods_root_file_case_parameters(case)?;
    let target_sheet = semantic_ods_sheet_name(1);
    let target_row = SemanticShape::Medium.ods_rows_per_sheet() / 2;
    let target_column = SemanticShape::Medium.ods_columns_per_sheet() / 2;
    let selected_media_path = ods_media_path(ODS_MEDIA_ENTRY_COUNT / 2);
    let selected_media_payload = ods_media_payload(ODS_MEDIA_ENTRY_COUNT / 2);
    let expected_root =
        litchi::Workbook::from_bytes(corpus.archive.clone()).map_err(|error| error.to_string())?;
    let expected_names = expected_root
        .worksheet_names()
        .map_err(|error| error.to_string())?;
    let expected_count = expected_root
        .worksheet_count()
        .map_err(|error| error.to_string())?;
    let expected_text = expected_root.text().map_err(|error| error.to_string())?;
    let expected_metadata_sha256 = ods_root_metadata_digest(
        &expected_root
            .metadata()
            .map_err(|error| error.to_string())?,
    )?;
    let expected_typed = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
    let expected_cell_text =
        ods_root_typed_cell(&expected_typed, &target_sheet, target_row, target_column)?;
    let (picture_members, selected_range) = ods_media_payload_inventory(corpus)?;
    let picture_ranges = picture_members
        .iter()
        .map(|(_name, range)| range.clone())
        .collect::<Vec<_>>();
    let selected_media_compressed_range_bytes =
        selected_range.end.saturating_sub(selected_range.start);
    let pictures_compressed_range_bytes =
        picture_members
            .iter()
            .try_fold(0_u64, |total, (_name, range)| {
                total
                    .checked_add(range.end.saturating_sub(range.start))
                    .ok_or("ODS compressed Pictures byte count overflows u64")
            })?;
    let pictures_uncompressed_payload_bytes = u64::try_from(
        ODS_MEDIA_ENTRY_COUNT
            .checked_mul(ODS_MEDIA_ENTRY_BYTES)
            .ok_or("ODS uncompressed Pictures byte count overflows usize")?,
    )?;
    let source_path = create_ods_root_source_file(&corpus.archive)?;
    let expectations = OdsRootExpectations {
        source_path: &source_path,
        corpus,
        worksheet_names: &expected_names,
        worksheet_count: expected_count,
        text: &expected_text,
        metadata_sha256: &expected_metadata_sha256,
        typed: &expected_typed,
        target_sheet: &target_sheet,
        target_row,
        target_column,
        cell_text: &expected_cell_text,
        selected_media_path: &selected_media_path,
        selected_media_payload: &selected_media_payload,
    };
    let result = (|| {
        let mut elapsed = Vec::with_capacity(samples);
        let mut source_summary = OdsRootSourceSummary {
            implementation,
            phase,
            timing_scope: if media_query {
                "selected_media_query_after_untimed_typed_owner_open"
            } else if query {
                "selected_cell_query_after_untimed_typed_owner_open"
            } else {
                "unified_root_workbook_open"
            },
            timed_root_adapter: match implementation {
                "source_backed_root" => "litchi::Workbook::open(Path)",
                "eager_root" => "litchi::Workbook::from_bytes(Vec<u8>)",
                _ => "not_applicable",
            },
            typed_query_adapter: if media_query {
                if implementation == "source_backed_typed" {
                    "litchi_ods::SourceBackedSpreadsheet::media_data"
                } else {
                    "OwnedPackage::get_file (owned Spreadsheet preparation outside timer)"
                }
            } else if query {
                if implementation == "source_backed_typed" {
                    "litchi_ods::SourceBackedSpreadsheet::cell"
                } else {
                    "litchi_ods::Spreadsheet::cell"
                }
            } else {
                "not_applicable"
            },
            read_evidence_adapter: if implementation.starts_with("source_backed") {
                "litchi_ods::SourceBackedSpreadsheet+harness::InstrumentedSource"
            } else {
                "not_applicable"
            },
            read_evidence_scope: if implementation.starts_with("source_backed") {
                "separate_untimed_direct_typed_replay_per_measured_sample"
            } else {
                "not_applicable"
            },
            source_path_bytes: u64::try_from(corpus.archive.len())?,
            source_path_sha256: corpus.manifest.archive_sha256.clone(),
            worksheet_names: expected_names.clone(),
            worksheet_count: expected_count,
            canonical_text_sha256: ods_root_text_digest(&expected_text),
            metadata_sha256: expected_metadata_sha256.clone(),
            target_sheet: target_sheet.clone(),
            target_row,
            target_column,
            target_cell_text_sha256: sha256_hex(expected_cell_text.as_bytes()),
            selected_media_path: selected_media_path.clone(),
            selected_media_compressed_range_bytes,
            selected_media_uncompressed_bytes: u64::try_from(selected_media_payload.len())?,
            selected_media_uncompressed_payload_sha256: sha256_hex(&selected_media_payload),
            pictures_count: picture_members.len(),
            pictures_compressed_range_bytes,
            pictures_uncompressed_payload_bytes,
            pictures_uncompressed_payload_sha256: ods_media_payload_digest(),
            ..OdsRootSourceSummary::default()
        };

        for iteration in 0..iteration_count(warmup_iterations, samples)? {
            let duration = match implementation {
                "source_backed_root" => {
                    let started = Instant::now();
                    let workbook =
                        litchi::Workbook::open(&source_path).map_err(|error| error.to_string())?;
                    let duration = started.elapsed();
                    verify_ods_root_postconditions(&workbook, &expectations)?;
                    duration
                },
                "eager_root" => {
                    let owned = corpus.archive.clone();
                    let started = Instant::now();
                    let workbook =
                        litchi::Workbook::from_bytes(owned).map_err(|error| error.to_string())?;
                    let duration = started.elapsed();
                    verify_ods_root_postconditions(&workbook, &expectations)?;
                    duration
                },
                "source_backed_typed" => {
                    let owner = litchi_ods::SourceBackedSpreadsheet::from_path(&source_path)?;
                    let started = Instant::now();
                    let value = if media_query {
                        owner
                            .media_data(&selected_media_path)?
                            .ok_or("ODS source selected media member is missing")?
                    } else {
                        ods_root_source_cell(&owner, &target_sheet, target_row, target_column)?
                            .into_bytes()
                    };
                    let duration = started.elapsed();
                    if media_query {
                        if value != selected_media_payload {
                            return Err("ODS source selected media query differs".into());
                        }
                    } else if String::from_utf8(value)? != expected_cell_text {
                        return Err("ODS source selected cell query differs".into());
                    }
                    verify_ods_typed_query_projection(
                        ods_source_query_projection(&owner, &expectations)?,
                        &expectations,
                    )?;
                    verify_ods_source_identity_postconditions(&expectations)?;
                    duration
                },
                "eager_typed" => {
                    let owner = litchi_ods::Spreadsheet::from_bytes(corpus.archive.clone())?;
                    if media_query {
                        verify_ods_typed_query_projection(
                            ods_typed_query_projection(&owner, &expectations)?,
                            &expectations,
                        )?;
                        verify_ods_source_identity_postconditions(&expectations)?;
                        let owned = owner.into_bytes();
                        let package = litchi_odf_common::core::OwnedPackage::from_bytes(owned)?;
                        let package = package.package()?;
                        let started = Instant::now();
                        let value = package.get_file(&selected_media_path)?;
                        let duration = started.elapsed();
                        if value != selected_media_payload {
                            return Err("ODS eager selected media query differs".into());
                        }
                        duration
                    } else {
                        let started = Instant::now();
                        let value =
                            ods_root_typed_cell(&owner, &target_sheet, target_row, target_column)?;
                        let duration = started.elapsed();
                        if value != expected_cell_text {
                            return Err("ODS eager selected cell query differs".into());
                        }
                        verify_ods_typed_query_projection(
                            ods_typed_query_projection(&owner, &expectations)?,
                            &expectations,
                        )?;
                        verify_ods_source_identity_postconditions(&expectations)?;
                        duration
                    }
                },
                _ => return Err("unknown ODS root implementation".into()),
            };
            record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
        }

        if implementation.starts_with("source_backed") {
            let mut exact_phase = None;
            for _ in 0..samples {
                let (snapshot, selected_snapshot) = if phase == "selected_media_query" {
                    collect_ods_media_selected_media(
                        &corpus.archive,
                        &picture_ranges,
                        selected_range.clone(),
                        &selected_media_path,
                        &selected_media_payload,
                    )?
                } else {
                    let snapshot = collect_ods_source_phase(
                        &corpus.archive,
                        &picture_ranges,
                        phase,
                        &target_sheet,
                        target_row,
                        target_column,
                    )?;
                    (snapshot, snapshot)
                };
                verify_ods_source_phase(snapshot, phase)?;
                if phase == "selected_media_query" {
                    verify_ods_source_phase(selected_snapshot, phase)?;
                    if snapshot.ordinary_payload_read_bytes != selected_media_compressed_range_bytes
                        || selected_snapshot.ordinary_payload_read_bytes
                            != selected_media_compressed_range_bytes
                    {
                        return Err(
                            "ODS selected-media replay did not cover exactly one compressed member range"
                                .into(),
                        );
                    }
                }
                let exact_snapshots = (snapshot, selected_snapshot);
                if let Some(expected) = &exact_phase {
                    if expected != &exact_snapshots {
                        return Err("ODS source phase counters are not deterministic".into());
                    }
                } else {
                    exact_phase = Some(exact_snapshots);
                }
                source_summary.source_read_calls.push(snapshot.read_calls);
                source_summary.source_read_bytes.push(snapshot.read_bytes);
                source_summary
                    .source_read_range_overlap_bytes
                    .push(snapshot.read_range_overlap_bytes);
                source_summary
                    .pictures_read_calls
                    .push(snapshot.ordinary_payload_read_calls);
                source_summary
                    .pictures_read_compressed_range_bytes
                    .push(snapshot.ordinary_payload_read_bytes);
                if phase == "selected_media_query" {
                    source_summary
                        .selected_media_read_calls
                        .push(selected_snapshot.read_calls);
                    source_summary
                        .selected_media_read_bytes
                        .push(selected_snapshot.read_bytes);
                    source_summary
                        .selected_media_read_prior_range_overlap_bytes
                        .push(selected_snapshot.read_range_overlap_bytes);
                    source_summary
                        .selected_media_read_compressed_range_overlap_bytes
                        .push(selected_snapshot.ordinary_payload_read_bytes);
                    source_summary
                        .selected_media_read_non_picture_overlap_bytes
                        .push(
                            selected_snapshot
                                .read_bytes
                                .saturating_sub(selected_snapshot.ordinary_payload_read_bytes),
                        );
                }
            }
        }

        Ok(result_with_source(
            case,
            corpus,
            elapsed,
            SourceSummary {
                ods_root: Some(source_summary),
                ..SourceSummary::default()
            },
        ))
    })();
    let cleanup = fs::remove_file(&source_path);
    match (result, cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Ok(_), Err(error)) => Err(error.into()),
        (Err(error), _) => Err(error),
    }
}

fn odp_text_box_batch_models(
    source: &litchi_odp::authoring::edit::Snapshot,
) -> Result<Vec<litchi_odp::content::TextBoxModel>, Box<dyn Error>> {
    let inventory = source.rich_content()?;
    let mut models = Vec::with_capacity(ODP_TEXT_BOX_BATCH_COUNT);
    for index in 0..ODP_TEXT_BOX_BATCH_COUNT {
        let name = odp_text_box_batch_name(index);
        let mut matching = inventory
            .text_boxes()
            .iter()
            .filter(|model| model.page() == odp_text_box_batch_page(index) && model.name() == name);
        let mut model = matching
            .next()
            .ok_or_else(|| format!("ODP text-box batch source owner '{name}' is missing"))?
            .clone();
        if matching.next().is_some() {
            return Err(format!("ODP text-box batch source owner '{name}' is ambiguous").into());
        }
        model.replace_paragraph(
            0,
            &litchi_odp::content::Paragraph::plain(odp_text_box_batch_text(index, true))?,
        )?;
        if model.name() != name {
            return Err("ODP text-box batch model unexpectedly renamed its owner".into());
        }
        models.push(model);
    }
    Ok(models)
}

fn publish_odp_text_box_models(
    case: Case,
    source: &litchi_odp::authoring::edit::Snapshot,
    replacements: &[litchi_odp::content::TextBoxModelReplacement<'_>],
) -> Result<litchi_odp::authoring::edit::Commit, Box<dyn Error>> {
    let mut transaction = source.transaction()?;
    match case {
        Case::OdpMediaTextBoxScalarReplaceSave => {
            for replacement in replacements {
                transaction.replace_text_box_model(replacement.name(), replacement.model())?;
            }
        },
        Case::OdpMediaTextBoxBatchReplaceSave => {
            let changed = transaction.replace_text_box_models(replacements)?;
            if changed != ODP_TEXT_BOX_BATCH_COUNT {
                return Err("ODP text-box batch changed-owner count differs".into());
            }
        },
        _ => return Err("non-model ODP case passed to text-box publisher".into()),
    }
    Ok(transaction.commit()?)
}

fn verify_odp_text_box_model_commit(
    case: Case,
    source: &litchi_odp::authoring::edit::Snapshot,
    commit: &litchi_odp::authoring::edit::Commit,
    expected: &[u8],
) -> Result<(), Box<dyn Error>> {
    if !commit.changed()
        || commit.patch().is_noop()
        || commit.patch().domains() != [litchi_odp::authoring::edit::Domain::Content]
        || commit.snapshot().bytes() != expected
    {
        return Err(format!(
            "ODP text-box model commit differs: changed={}, noop={}, domains={:?}, exact_output={}",
            commit.changed(),
            commit.patch().is_noop(),
            commit.patch().domains(),
            commit.snapshot().bytes() == expected
        )
        .into());
    }
    verify_odp_text_box_batch_archive(expected, true)?;
    verify_odp_text_box_batch_raw_members(
        source.bytes(),
        expected,
        case == Case::OdpMediaTextBoxBatchReplaceSave,
    )?;

    let replayed = commit.patch().apply(source)?;
    if replayed.bytes() != expected {
        return Err("ODP text-box model patch replay differs from publication".into());
    }
    let restored = commit.patch().inverse().apply(&replayed)?;
    if restored.bytes() != source.bytes() {
        return Err("ODP text-box model inverse did not restore exact source bytes".into());
    }
    if commit.patch().apply(&replayed).is_ok() {
        return Err("ODP text-box model patch accepted a stale source".into());
    }

    let durable = litchi_odp::authoring::edit::Patch::from_durable_bytes(
        &commit.patch().to_durable_bytes()?,
    )?;
    let durable_replayed = durable.apply(source)?;
    if durable_replayed.bytes() != expected {
        return Err("durable ODP text-box model replay differs from publication".into());
    }
    let durable_restored = durable.inverse().apply(&durable_replayed)?;
    if durable_restored.bytes() != source.bytes() {
        return Err("durable ODP text-box model inverse did not restore source".into());
    }
    if durable.apply(&durable_replayed).is_ok() {
        return Err("durable ODP text-box model patch accepted a stale source".into());
    }
    Ok(())
}

fn run_odp_text_box_model_publication(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.uses_odp_text_box_batch() {
        return Err("non-model ODP case passed to text-box publication runner".into());
    }
    let source = litchi_odp::authoring::edit::Snapshot::from_bytes(corpus.archive.clone())?;
    let models = odp_text_box_batch_models(&source)?;
    let replacements = models
        .iter()
        .enumerate()
        .map(|(index, model)| {
            litchi_odp::content::TextBoxModelReplacement::at(
                odp_text_box_batch_page(index),
                model.name(),
                model,
            )
        })
        .collect::<Vec<_>>();

    let batch = publish_odp_text_box_models(
        Case::OdpMediaTextBoxBatchReplaceSave,
        &source,
        &replacements,
    )?;
    let expected_batch = batch.snapshot().bytes().to_vec();
    verify_odp_text_box_model_commit(
        Case::OdpMediaTextBoxBatchReplaceSave,
        &source,
        &batch,
        &expected_batch,
    )?;
    let scalar = publish_odp_text_box_models(
        Case::OdpMediaTextBoxScalarReplaceSave,
        &source,
        &replacements,
    )?;
    let expected_scalar = scalar.snapshot().bytes().to_vec();
    verify_odp_text_box_model_commit(
        Case::OdpMediaTextBoxScalarReplaceSave,
        &source,
        &scalar,
        &expected_scalar,
    )?;
    let scalar_projection =
        litchi_odp::Presentation::from_bytes(expected_scalar.clone())?.text()?;
    let batch_projection = litchi_odp::Presentation::from_bytes(expected_batch.clone())?.text()?;
    if scalar_projection != batch_projection {
        return Err("matched ODP scalar and batch semantic projections differ".into());
    }
    let expected = match case {
        Case::OdpMediaTextBoxScalarReplaceSave => expected_scalar,
        Case::OdpMediaTextBoxBatchReplaceSave => expected_batch,
        _ => return Err("non-model ODP case reached output selection".into()),
    };

    let sink_ceiling = u64::try_from(expected.len())?;
    let expected_digest = sha256_hex(&expected);
    let mut elapsed = Vec::with_capacity(samples);
    let mut sinks = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let mut sink = CountingSink::bounded(sink_ceiling, sink_ceiling);
        sink.reserve_budget()?;
        let started = Instant::now();
        let commit = publish_odp_text_box_models(case, &source, &replacements)?;
        sink.write_all(commit.snapshot().bytes())?;
        let duration = started.elapsed();

        if !commit.changed()
            || commit.patch().is_noop()
            || commit.patch().domains() != [litchi_odp::authoring::edit::Domain::Content]
            || sink.bytes != expected
        {
            return Err("measured ODP text-box model publication differs from oracle".into());
        }
        let replayed = commit.patch().apply(&source)?;
        if replayed.bytes() != expected
            || commit.patch().inverse().apply(&replayed)?.bytes() != source.bytes()
            || commit.patch().apply(&replayed).is_ok()
        {
            return Err("measured ODP text-box model patch contract differs".into());
        }
        sinks.push(sink.summary());
        std::hint::black_box(commit);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    let sink = deterministic_sink_summary(&sinks, "ODP text-box model publication")?;
    let mut measured = result(case, corpus, elapsed, Some(sink));
    measured.output_sha256 = Some(expected_digest);
    Ok(measured)
}

fn run_xlsx_open_owned(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let spec = xlsx_spec(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let owned = corpus.archive.clone();
        let started = Instant::now();
        let workbook = Workbook::from_bytes(owned)?;
        let duration = started.elapsed();
        if workbook.len() != spec.sheet_count {
            return Err("owned XLSX open sheet count differs from corpus specification".into());
        }
        std::hint::black_box(&workbook);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result(Case::XlsxOpenOwned, corpus, elapsed, None))
}

