fn pptx_batch_replacements(texts: &[String]) -> Vec<litchi_pptx::ShapeTextReplacement<'_>> {
    texts
        .iter()
        .enumerate()
        .map(|(index, text)| litchi_pptx::ShapeTextReplacement::at(index, text))
        .collect()
}

fn publish_pptx_batch_edit<W: Write>(
    source: Arc<dyn ReadAt>,
    writer: &mut W,
    source_backed: bool,
) -> Result<usize, Box<dyn Error>> {
    let target_slide = PPTX_SOURCE_SLIDE_COUNT / 2;
    let texts = (0..PPTX_SOURCE_TEXT_BOXES_PER_SLIDE)
        .map(|shape| semantic_pptx_text(target_slide, shape, true))
        .collect::<Vec<_>>();
    let replacements = pptx_batch_replacements(&texts);
    if source_backed {
        let editor = litchi_pptx::SourceBackedPresentationEditor::from_read_at(source)?;
        let mut edit = editor.edit_slide(target_slide)?;
        if edit.set_shape_texts(&replacements)? != PPTX_SOURCE_TEXT_BOXES_PER_SLIDE {
            return Err("PPTX source-backed batch changed an unexpected shape count".into());
        }
        let commit = edit.commit();
        if !commit.is_changed() {
            return Err("PPTX source-backed batch produced an unchanged commit".into());
        }
        let replayed = commit.patch().apply(commit.patch().source())?;
        if commit.patch().inverse().apply(&replayed).is_err() {
            return Err("PPTX source-backed batch inverse rejected its candidate".into());
        }
        let materializations = usize::try_from(editor.cache_diagnostics().successful_loads)?;
        let published = editor.publish_slide_commit_to_stream(writer, &commit)?;
        if commit.patch().inverse().apply(&published).is_err()
            || commit.patch().apply(&published).is_ok()
        {
            return Err("PPTX source-backed batch published another snapshot".into());
        }
        Ok(materializations)
    } else {
        let package = SourceBackedPackage::from_read_at(source)?;
        let opc = package.into_opc_package()?;
        let materializations = opc.part_count();
        let mut package = litchi_pptx::Package::from_opc_package(opc)?;
        let mut edit = package.opened_presentation_transaction()?;
        if edit.set_shape_texts(target_slide, &replacements)? != PPTX_SOURCE_TEXT_BOXES_PER_SLIDE {
            return Err("PPTX eager batch changed an unexpected shape count".into());
        }
        let commit = edit.commit()?;
        if !commit.is_changed() {
            return Err("PPTX eager batch produced an unchanged commit".into());
        }
        let inverse = commit.patch().inverse();
        let published = package.apply_opened_presentation_commit(commit)?;
        if package
            .apply_opened_presentation_patch(&inverse)
            .and_then(|_| package.apply_opened_presentation_patch(&inverse.inverse()))
            .is_err()
        {
            return Err("PPTX eager batch inverse/forward replay failed".into());
        }
        if published.slides().len() != PPTX_SOURCE_SLIDE_COUNT {
            return Err("PPTX eager batch changed the slide graph".into());
        }
        let output = package.to_bytes()?;
        for chunk in output.chunks(64 * 1024) {
            writer.write_all(chunk)?;
        }
        Ok(materializations)
    }
}

fn run_pptx_batch_edit_save(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != PPTX_SOURCE_EDIT_CORPUS_GENERATOR
        || !matches!(
            case,
            Case::PptxEagerBatchEditSave | Case::PptxSourceBackedBatchEditSave
        )
    {
        return Err("PPTX batch case requires its fixed media-rich corpus".into());
    }
    if sha256_hex(&corpus.archive) != corpus.manifest.archive_sha256 {
        return Err("PPTX batch source digest differs from corpus manifest".into());
    }
    let source_backed = case == Case::PptxSourceBackedBatchEditSave;
    let expected_source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
    let mut expected = Vec::new();
    let expected_materializations =
        publish_pptx_batch_edit(expected_source, &mut expected, source_backed)?;
    let required_materializations = if source_backed {
        2
    } else {
        corpus.manifest.entry_count
    };
    if expected == corpus.archive || expected_materializations != required_materializations {
        return Err("PPTX batch materialized an unexpected Part count".into());
    }
    verify_pptx_source_edit_output(corpus, &expected, PPTX_SOURCE_TEXT_BOXES_PER_SLIDE)?;
    let expected_digest = sha256_hex(&expected);
    let maximum = u64::try_from(expected.len())?
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("PPTX batch sequential output ceiling overflows u64")?;
    let payload_ranges = pptx_source_payload_ranges(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut sink_summaries = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    let mut measured_digests = Vec::with_capacity(samples);

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = Arc::new(InstrumentedSource::new(
            corpus.archive.clone(),
            payload_ranges.clone(),
        ));
        let read_at: Arc<dyn ReadAt> = source.clone();
        let mut sink = CountingSink::bounded(maximum, 64 * 1024);
        sink.reserve_budget()?;
        let started = Instant::now();
        let materializations = publish_pptx_batch_edit(read_at, &mut sink, source_backed)?;
        let duration = started.elapsed();

        if materializations != expected_materializations || sink.bytes != expected {
            return Err("PPTX batch differs between iterations".into());
        }
        if sink.summary().largest_write > 64 * 1024 {
            return Err("PPTX batch exceeded the sequential sink write bound".into());
        }
        verify_pptx_source_edit_output(corpus, &sink.bytes, PPTX_SOURCE_TEXT_BOXES_PER_SLIDE)?;
        let digest = sha256_hex(&sink.bytes);
        if digest != expected_digest {
            return Err("PPTX batch output digest differs from expected output".into());
        }
        let metrics = source.snapshot();
        if metrics.ordinary_payload_read_calls == 0 || metrics.ordinary_payload_read_bytes == 0 {
            return Err("PPTX batch performed no ordinary source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record_opc(metrics, u64::try_from(materializations)?);
            sink_summaries.push(sink.summary());
            measured_digests.push(digest);
        }
        std::hint::black_box(&sink.bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let sink = deterministic_sink_summary(&sink_summaries, case.name())?;
    if measured_digests
        .iter()
        .any(|digest| digest != &expected_digest)
    {
        return Err("PPTX batch measured output digests are not stable".into());
    }
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: Some(source_summary),
        execution: None,
        output_sha256: Some(expected_digest),
        operation_metrics: None,
    })
}

fn publish_pptx_multi_slide_batch_edit<W: Write>(
    source: Arc<dyn ReadAt>,
    writer: &mut W,
    source_backed: bool,
) -> Result<usize, Box<dyn Error>> {
    if source_backed {
        let editor = litchi_pptx::SourceBackedPresentationEditor::from_read_at(source)?;
        let mut edit = editor.edit_slides();
        for slide_position in pptx_multi_slide_positions() {
            let texts = (0..PPTX_SOURCE_TEXT_BOXES_PER_SLIDE)
                .map(|shape| semantic_pptx_text(slide_position, shape, true))
                .collect::<Vec<_>>();
            let replacements = pptx_batch_replacements(&texts);
            if edit.set_shape_texts(slide_position, &replacements)?
                != PPTX_SOURCE_TEXT_BOXES_PER_SLIDE
            {
                return Err(
                    "PPTX source-backed multi-slide batch changed an unexpected shape count".into(),
                );
            }
        }
        let commit = edit.commit()?;
        if !commit.is_changed() {
            return Err("PPTX source-backed multi-slide batch produced no changes".into());
        }
        let replayed = commit.patch().apply(commit.patch().source())?;
        if commit.patch().inverse().apply(&replayed).is_err() {
            return Err("PPTX source-backed multi-slide inverse rejected its candidate".into());
        }
        let materializations = usize::try_from(editor.cache_diagnostics().successful_loads)?;
        let published = editor.publish_slide_batch_commit_to_stream(writer, &commit)?;
        if commit.patch().inverse().apply(&published).is_err()
            || commit.patch().apply(&published).is_ok()
        {
            return Err("PPTX source-backed multi-slide published another snapshot".into());
        }
        return Ok(materializations);
    }

    let package = SourceBackedPackage::from_read_at(source)?;
    let opc = package.into_opc_package()?;
    let materializations = opc.part_count();
    let mut package = litchi_pptx::Package::from_opc_package(opc)?;
    let mut edit = package.opened_presentation_transaction()?;
    for slide_position in pptx_multi_slide_positions() {
        let texts = (0..PPTX_SOURCE_TEXT_BOXES_PER_SLIDE)
            .map(|shape| semantic_pptx_text(slide_position, shape, true))
            .collect::<Vec<_>>();
        let replacements = pptx_batch_replacements(&texts);
        if edit.set_shape_texts(slide_position, &replacements)? != PPTX_SOURCE_TEXT_BOXES_PER_SLIDE
        {
            return Err("PPTX eager multi-slide batch changed an unexpected shape count".into());
        }
    }
    let commit = edit.commit()?;
    if !commit.is_changed() {
        return Err("PPTX eager multi-slide batch produced an unchanged commit".into());
    }
    let inverse = commit.patch().inverse();
    let published = package.apply_opened_presentation_commit(commit)?;
    if package
        .apply_opened_presentation_patch(&inverse)
        .and_then(|_| package.apply_opened_presentation_patch(&inverse.inverse()))
        .is_err()
    {
        return Err("PPTX eager multi-slide batch inverse/forward replay failed".into());
    }
    if published.slides().len() != PPTX_SOURCE_SLIDE_COUNT {
        return Err("PPTX eager multi-slide batch changed the slide graph".into());
    }
    let output = package.to_bytes()?;
    for chunk in output.chunks(64 * 1024) {
        writer.write_all(chunk)?;
    }
    Ok(materializations)
}

fn run_pptx_multi_slide_batch_edit_save(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != PPTX_SOURCE_EDIT_CORPUS_GENERATOR
        || !matches!(
            case,
            Case::PptxEagerMultiSlideBatchEditSave | Case::PptxSourceBackedMultiSlideBatchEditSave
        )
    {
        return Err("PPTX multi-slide batch requires its fixed media-rich corpus".into());
    }
    if sha256_hex(&corpus.archive) != corpus.manifest.archive_sha256 {
        return Err("PPTX multi-slide source digest differs from corpus manifest".into());
    }
    let expected_source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
    let mut expected = Vec::new();
    let source_backed = case == Case::PptxSourceBackedMultiSlideBatchEditSave;
    let expected_materializations =
        publish_pptx_multi_slide_batch_edit(expected_source, &mut expected, source_backed)?;
    let required_materializations = if source_backed {
        PPTX_MULTI_SLIDE_BATCH_COUNT + 1
    } else {
        corpus.manifest.entry_count
    };
    if expected == corpus.archive || expected_materializations != required_materializations {
        return Err("PPTX multi-slide materialized an unexpected Part count".into());
    }
    verify_pptx_multi_slide_edit_output(corpus, &expected)?;
    let expected_digest = sha256_hex(&expected);
    let maximum = u64::try_from(expected.len())?
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("PPTX multi-slide sequential output ceiling overflows u64")?;
    let payload_ranges = pptx_source_payload_ranges(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut sink_summaries = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    let mut measured_digests = Vec::with_capacity(samples);

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = Arc::new(InstrumentedSource::new(
            corpus.archive.clone(),
            payload_ranges.clone(),
        ));
        let read_at: Arc<dyn ReadAt> = source.clone();
        let mut sink = CountingSink::bounded(maximum, 64 * 1024);
        sink.reserve_budget()?;
        let started = Instant::now();
        let materializations =
            publish_pptx_multi_slide_batch_edit(read_at, &mut sink, source_backed)?;
        let duration = started.elapsed();

        if materializations != expected_materializations || sink.bytes != expected {
            return Err("PPTX multi-slide batch differs between iterations".into());
        }
        if sink.summary().largest_write > 64 * 1024 {
            return Err("PPTX multi-slide batch exceeded the sink write bound".into());
        }
        verify_pptx_multi_slide_edit_output(corpus, &sink.bytes)?;
        let digest = sha256_hex(&sink.bytes);
        if digest != expected_digest {
            return Err("PPTX multi-slide output digest differs from expected".into());
        }
        let metrics = source.snapshot();
        if metrics.ordinary_payload_read_calls == 0 || metrics.ordinary_payload_read_bytes == 0 {
            return Err("PPTX multi-slide batch performed no ordinary source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record_opc(metrics, u64::try_from(materializations)?);
            sink_summaries.push(sink.summary());
            measured_digests.push(digest);
        }
        std::hint::black_box(&sink.bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let sink = deterministic_sink_summary(&sink_summaries, case.name())?;
    if measured_digests
        .iter()
        .any(|digest| digest != &expected_digest)
    {
        return Err("PPTX multi-slide measured output digests are not stable".into());
    }
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: Some(source_summary),
        execution: None,
        output_sha256: Some(expected_digest),
        operation_metrics: None,
    })
}

fn run_pptx_cross_copy(
    case: Case,
    corpus: &PptxCrossCopyCorpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_pptx_cross_copy() || corpus.manifest.name != case.name() {
        return Err("PPTX cross-copy case requires its matching fixed corpus".into());
    }
    if sha256_hex(&corpus.source_archive) != corpus.source_archive_sha256
        || sha256_hex(&corpus.destination_archive) != corpus.manifest.archive_sha256
        || corpus.source_archive_sha256 == corpus.manifest.archive_sha256
    {
        return Err("PPTX cross-copy source and destination archive identity is invalid".into());
    }
    let gates = &corpus.gates;
    if !gates.semantic_output_verified
        || !gates.package_topology_verified
        || !gates.dependency_closure_verified
        || !gates.source_immutability_verified
        || !gates.collision_remap_verified
        || !gates.durable_patch_round_trip_verified
        || !gates.borrowed_provenance_refusal_verified
        || !gates.stale_source_refusal_verified
        || !gates.stale_destination_refusal_verified
        || !gates.foreign_source_refusal_verified
    {
        return Err("PPTX cross-copy corpus has an incomplete untimed gate set".into());
    }
    if corpus.destination_slide_count == 0
        || corpus.source_slide >= PPTX_CROSS_COPY_SOURCE_SLIDE_COUNT
        || corpus.destination_slide >= corpus.destination_slide_count
        || corpus.insertion_position > corpus.destination_slide_count
    {
        return Err("PPTX cross-copy corpus has an invalid slide selector".into());
    }
    let expected_digest = sha256_hex(&corpus.expected_output);
    let maximum = u64::try_from(corpus.expected_output.len())?
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("PPTX cross-copy sequential output ceiling overflows u64")?;
    let iterations = iteration_count(warmup_iterations, samples)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut plan_ns = Vec::with_capacity(samples);
    let mut commit_ns = Vec::with_capacity(samples);
    let mut publication_ns = Vec::with_capacity(samples);
    let mut reopen_ns = Vec::with_capacity(samples);
    let mut sink_summaries = Vec::with_capacity(samples);
    let mut output_digests = Vec::with_capacity(samples);
    let source_text = {
        let source = litchi_pptx::Package::from_vec(corpus.source_archive.clone())?;
        source
            .presentation()?
            .slides()?
            .get(corpus.source_slide)
            .ok_or("PPTX cross-copy source semantic slide is missing")?
            .text()?
    };

    for iteration in 0..iterations {
        let mut source = litchi_pptx::Package::from_vec(corpus.source_archive.clone())?;
        let mut destination = litchi_pptx::Package::from_vec(corpus.destination_archive.clone())?;
        let source_snapshot = source.opened_presentation()?;
        let destination_snapshot = destination.opened_presentation()?;

        let started = Instant::now();
        let plan = destination_snapshot.plan_cross_slide_copy(
            &source_snapshot,
            corpus.source_slide,
            corpus.destination_slide,
            corpus.insertion_position,
        )?;
        let plan_duration = started.elapsed();
        if plan.source().name() != corpus.source_slide_name
            || plan.destination().name() != corpus.destination_slide_name
            || plan.position() != corpus.insertion_position
            || plan.parts().len() != corpus.plan_parts
            || plan.planned_bytes() != corpus.planned_bytes
            || plan.external_relationship_count() != corpus.external_relationships
            || plan.source_layout() != plan.destination_layout()
            || plan
                .parts()
                .iter()
                .filter(|part| part.source() != part.target())
                .count()
                != corpus.collision_remapped_parts
        {
            return Err("PPTX cross-copy plan metadata is not deterministic".into());
        }

        let started = Instant::now();
        let published = destination.apply_cross_slide_copy_plan(&source, &plan)?;
        let commit_duration = started.elapsed();
        if published.slides().len() != corpus.destination_slide_count + 1 {
            return Err("PPTX cross-copy commit changed the wrong slide count".into());
        }

        let mut sink = CountingSink::bounded(maximum, 64 * 1024);
        sink.reserve_budget()?;
        let destination_opc = destination.opc()?;
        let started = Instant::now();
        destination_opc.to_stream(&mut sink)?;
        let publication_duration = started.elapsed();
        if sink.bytes != corpus.expected_output
            || sink.summary().accepted_bytes != u64::try_from(sink.bytes.len())?
            || sink.summary().largest_write > 64 * 1024
        {
            return Err(
                "PPTX cross-copy sequential publication differs from the expected output".into(),
            );
        }

        let started = Instant::now();
        let reopened = litchi_pptx::Package::from_bytes(&sink.bytes)?;
        let reopened_snapshot = reopened.opened_presentation()?;
        let reopen_duration = started.elapsed();
        if reopened_snapshot.slides().len() != corpus.destination_slide_count + 1 {
            return Err("PPTX cross-copy reopened output has the wrong slide count".into());
        }
        let _output_checks = verify_pptx_cross_copy_output(
            &corpus.source_archive,
            &corpus.destination_archive,
            &sink.bytes,
            &plan,
            PptxCrossCopySemanticExpectation {
                source_slide_name: &corpus.source_slide_name,
                source_slide_text: &source_text,
                source_slide_index: corpus.source_slide,
                destination_slide_count: corpus.destination_slide_count,
                insertion_position: corpus.insertion_position,
            },
        )?;
        if source.to_bytes()? != corpus.source_archive {
            return Err("PPTX cross-copy publication mutated its source package".into());
        }
        let digest = sha256_hex(&sink.bytes);
        if digest != expected_digest {
            return Err("PPTX cross-copy output digest differs from expected output".into());
        }
        let plan_elapsed_ns = elapsed_ns(plan_duration)?;
        let commit_elapsed_ns = elapsed_ns(commit_duration)?;
        let publication_elapsed_ns = elapsed_ns(publication_duration)?;
        let total = plan_elapsed_ns
            .checked_add(commit_elapsed_ns)
            .and_then(|value| value.checked_add(publication_elapsed_ns))
            .ok_or("PPTX cross-copy timed phases overflow nanoseconds")?;
        if iteration >= warmup_iterations {
            elapsed.push(total);
            plan_ns.push(plan_elapsed_ns);
            commit_ns.push(commit_elapsed_ns);
            publication_ns.push(publication_elapsed_ns);
            reopen_ns.push(elapsed_ns(reopen_duration)?);
            sink_summaries.push(sink.summary());
            output_digests.push(digest);
        }
        std::hint::black_box(&sink.bytes);
    }

    let sink = deterministic_sink_summary(&sink_summaries, case.name())?;
    if output_digests
        .iter()
        .any(|digest| digest != &expected_digest)
    {
        return Err("PPTX cross-copy measured output digests are not stable".into());
    }
    let cross_copy = PptxCrossCopySummary {
        implementation: "opened::CrossSlideCopyPlan + Package::apply_cross_slide_copy_plan + OpcPackage::to_stream",
        timing_scope: "plan only; commit only; OPC sequential publication only; setup, reopen, semantic/package/closure/refusal verification excluded",
        performance_claim: "none: opt-in correctness/evidence only; no release ABBA, speedup, allocation, RSS, or physical-I/O claim",
        source_archive_sha256: sha256_hex(&corpus.source_archive),
        destination_archive_sha256: sha256_hex(&corpus.destination_archive),
        expected_output_sha256: expected_digest.clone(),
        source_slide: corpus.source_slide,
        destination_slide: corpus.destination_slide,
        insertion_position: corpus.insertion_position,
        source_slide_name: corpus.source_slide_name.clone(),
        destination_slide_name: corpus.destination_slide_name.clone(),
        destination_slide_count_before: corpus.destination_slide_count,
        destination_slide_count_after: corpus.destination_slide_count + 1,
        planned_part_count: corpus.plan_parts,
        planned_bytes: corpus.planned_bytes,
        external_relationship_count: corpus.external_relationships,
        collision_remapped_parts: corpus.collision_remapped_parts,
        gates: corpus.gates.clone(),
        plan_ns,
        commit_ns,
        publication_ns,
        reopen_ns,
        output_sha256: output_digests,
    };
    let source_summary = SourceSummary {
        pptx_cross_copy: Some(cross_copy),
        ..SourceSummary::default()
    };
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: Some(source_summary),
        execution: None,
        output_sha256: Some(expected_digest),
        operation_metrics: None,
    })
}

fn run_pptx_source_backed_cross_copy(
    case: Case,
    corpus: &PptxSourceBackedCrossCopyCorpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_pptx_source_backed_cross_copy()
        || corpus.manifest.name != case.name()
        || corpus.manifest.generator != PPTX_SOURCE_BACKED_CROSS_COPY_CORPUS_GENERATOR
    {
        return Err("source-backed PPTX cross-copy case requires its fixed plain corpus".into());
    }
    let source_archive_digest = sha256_hex(&corpus.source_archive);
    let destination_archive_digest = sha256_hex(&corpus.destination_archive);
    if destination_archive_digest != corpus.manifest.archive_sha256
        || source_archive_digest == destination_archive_digest
    {
        return Err("source-backed PPTX cross-copy archive identity is invalid".into());
    }
    let gates = &corpus.gates;
    if !gates.matched_existing_plain_corpus_verified
        || !gates.semantic_output_verified
        || !gates.package_topology_verified
        || !gates.dependency_boundary_verified
        || !gates.layout_reuse_verified
        || !gates.untouched_destination_members_verified
        || !gates.deterministic_output_verified
        || !gates.source_version_stability_verified
        || !gates.source_revision_refusal_verified
        || !gates.destination_revision_refusal_verified
        || !gates.foreign_destination_refusal_verified
    {
        return Err(
            "source-backed PPTX cross-copy corpus has an incomplete untimed gate set".into(),
        );
    }
    if corpus.destination_slide_count == 0
        || corpus.source_slide >= PPTX_CROSS_COPY_SOURCE_SLIDE_COUNT
        || corpus.destination_slide >= corpus.destination_slide_count
        || corpus.insertion_position > corpus.destination_slide_count
    {
        return Err("source-backed PPTX cross-copy corpus has an invalid slide selector".into());
    }
    let expected_digest = sha256_hex(&corpus.source_backed_expected_output);
    let maximum = u64::try_from(corpus.source_backed_expected_output.len())?
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("source-backed PPTX sequential output ceiling overflows u64")?;
    let iterations = iteration_count(warmup_iterations, samples)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut plan_ns = Vec::with_capacity(samples);
    let mut publication_ns = Vec::with_capacity(samples);
    let mut sink_summaries = Vec::with_capacity(samples);
    let mut output_digests = Vec::with_capacity(samples);
    let mut source_read_calls = Vec::with_capacity(samples);
    let mut source_read_bytes = Vec::with_capacity(samples);
    let mut destination_read_calls = Vec::with_capacity(samples);
    let mut destination_read_bytes = Vec::with_capacity(samples);

    for iteration in 0..iterations {
        // Opening and all semantic setup are deliberately outside the timed
        // plan/publication phases.
        let source = Arc::new(InstrumentedSource::new(
            corpus.source_archive.clone(),
            Vec::new(),
        ));
        let destination = Arc::new(InstrumentedSource::new(
            corpus.destination_archive.clone(),
            Vec::new(),
        ));
        let source_read: Arc<dyn ReadAt> = source.clone();
        let destination_read: Arc<dyn ReadAt> = destination.clone();
        let source_view = litchi_pptx::SourceBackedPresentation::from_read_at(source_read)?;
        let editor = litchi_pptx::SourceBackedPresentationEditor::from_read_at(destination_read)?;
        if source_view.slide_count() != PPTX_CROSS_COPY_SOURCE_SLIDE_COUNT
            || editor.slide_count() != corpus.destination_slide_count
        {
            return Err("source-backed PPTX cross-copy setup changed slide counts".into());
        }
        // Do not query the selected slide on the measured source here. Such a
        // semantic read would populate the payload cache before the plan timer
        // starts. Corpus construction and the untimed gate set already verify
        // the selected source name/text.
        source.reset();
        destination.reset();

        let started = Instant::now();
        let plan = editor.plan_cross_slide_copy(
            &source_view,
            corpus.source_slide,
            corpus.destination_slide,
            corpus.insertion_position,
        )?;
        let plan_duration = started.elapsed();
        if plan.source_position() != corpus.source_slide
            || plan.destination_slide_position() != corpus.destination_slide
            || plan.insertion_position() != corpus.insertion_position
            || plan.destination_slide_count() != corpus.destination_slide_count + 1
        {
            return Err("source-backed PPTX cross-copy plan metadata is not deterministic".into());
        }
        let mut sink = CountingSink::bounded(maximum, 64 * 1024);
        sink.reserve_budget()?;
        let started = Instant::now();
        let snapshot = editor.publish_cross_slide_copy_to_stream(&mut sink, &plan)?;
        let publication_duration = started.elapsed();
        if snapshot.destination_slide_count() != corpus.destination_slide_count + 1
            || snapshot.insertion_position() != corpus.insertion_position
            || snapshot.name() != corpus.source_slide_name
            || sink.bytes != corpus.source_backed_expected_output
            || sink.summary().accepted_bytes != u64::try_from(sink.bytes.len())?
            || sink.summary().largest_write > 64 * 1024
        {
            return Err(
                "source-backed PPTX cross-copy publication differs from expected output".into(),
            );
        }

        // Reopen and output checks are correctness gates outside the reported
        // plan/publication timing boundary.
        let reopened = litchi_pptx::Package::from_bytes(&sink.bytes)?;
        let reopened_slides = reopened.presentation()?.slides()?;
        if reopened_slides.len() != corpus.destination_slide_count + 1
            || reopened_slides
                .get(corpus.insertion_position)
                .ok_or("source-backed PPTX reopened inserted slide is missing")?
                .name()?
                != corpus.source_slide_name
            || reopened_slides
                .get(corpus.insertion_position)
                .ok_or("source-backed PPTX reopened inserted slide is missing")?
                .text()?
                != corpus.source_slide_text
        {
            return Err("source-backed PPTX reopened output failed semantic checks".into());
        }
        let source_snapshot = source.snapshot();
        let destination_snapshot = destination.snapshot();
        if source_snapshot.read_calls == 0
            || source_snapshot.read_bytes == 0
            || destination_snapshot.read_calls == 0
            || destination_snapshot.read_bytes == 0
        {
            return Err("source-backed PPTX cross-copy performed no logical source reads".into());
        }

        let plan_elapsed_ns = elapsed_ns(plan_duration)?;
        let publication_elapsed_ns = elapsed_ns(publication_duration)?;
        let total = plan_elapsed_ns
            .checked_add(publication_elapsed_ns)
            .ok_or("source-backed PPTX cross-copy timed phases overflow nanoseconds")?;
        let digest = sha256_hex(&sink.bytes);
        if digest != expected_digest {
            return Err(
                "source-backed PPTX cross-copy output digest differs from expected output".into(),
            );
        }
        if iteration >= warmup_iterations {
            elapsed.push(total);
            plan_ns.push(plan_elapsed_ns);
            publication_ns.push(publication_elapsed_ns);
            sink_summaries.push(sink.summary());
            output_digests.push(digest);
            source_read_calls.push(source_snapshot.read_calls);
            source_read_bytes.push(source_snapshot.read_bytes);
            destination_read_calls.push(destination_snapshot.read_calls);
            destination_read_bytes.push(destination_snapshot.read_bytes);
        }
        std::hint::black_box(&sink.bytes);
    }

    let sink = deterministic_sink_summary(&sink_summaries, case.name())?;
    if output_digests
        .iter()
        .any(|digest| digest != &expected_digest)
    {
        return Err("source-backed PPTX cross-copy measured output digests are not stable".into());
    }
    let cross_copy = PptxSourceBackedCrossCopySummary {
        implementation: "presentation::SourceBackedPresentationEditor + SourceTopologyPlan + publish_cross_slide_copy_to_stream",
        workload: "matched plain corpus / existing pptx_cross_copy_plain input",
        timing_scope: "source-backed plan only + public publish_cross_slide_copy_to_stream; setup, reopen, verification, topology gates, and cache diagnostics excluded",
        performance_claim: "none: opt-in correctness/counter evidence only; no eager/source speedup, ABBA, allocation, RSS, physical-I/O, or cold-cache claim",
        source_archive_sha256: sha256_hex(&corpus.source_archive),
        destination_archive_sha256: sha256_hex(&corpus.destination_archive),
        expected_output_sha256: expected_digest.clone(),
        source_slide: corpus.source_slide,
        destination_slide: corpus.destination_slide,
        insertion_position: corpus.insertion_position,
        source_slide_name: corpus.source_slide_name.clone(),
        destination_slide_name: corpus.destination_slide_name.clone(),
        destination_slide_count_before: corpus.destination_slide_count,
        destination_slide_count_after: corpus.destination_slide_count + 1,
        added_opc_part_count: 1,
        added_archive_member_count: 2,
        added_slide_payload_bytes: corpus.added_slide_payload_bytes,
        gates: corpus.gates.clone(),
        plan_ns,
        publication_ns,
        output_sha256: output_digests,
        source_read_calls,
        source_read_bytes,
        destination_read_calls,
        destination_read_bytes,
    };
    let source_summary = SourceSummary {
        pptx_source_backed_cross_copy: Some(cross_copy),
        ..SourceSummary::default()
    };
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: Some(source_summary),
        execution: None,
        output_sha256: Some(expected_digest),
        operation_metrics: None,
    })
}

fn xlsx_defined_names_target() -> Vec<litchi_xlsx::raw::DefinedName> {
    vec![
        litchi_xlsx::raw::DefinedName {
            name: "PerformanceRange".to_owned(),
            reference: "'Sheet1'!$A$1:$B$2".to_owned(),
            comment: Some("deterministic source-backed benchmark".to_owned()),
            ..litchi_xlsx::raw::DefinedName::default()
        },
        litchi_xlsx::raw::DefinedName {
            name: "LocalPerformanceCell".to_owned(),
            reference: "'Sheet1'!$C$3".to_owned(),
            local_sheet_id: Some(0),
            hidden: true,
            ..litchi_xlsx::raw::DefinedName::default()
        },
    ]
}

fn verify_xlsx_defined_names_edit_output(
    corpus: &Corpus,
    output: &[u8],
) -> Result<(), Box<dyn Error>> {
    let reopened = litchi_xlsx::Package::from_slice(output)?;
    if reopened.workbook()?.defined_names() != xlsx_defined_names_target() {
        return Err("XLSX defined-name output has unexpected catalog semantics".into());
    }
    if reopened
        .calculation_metadata()?
        .properties()
        .ok_or("XLSX defined-name output has no calcPr")?
        .calculation_id()
        != 7
    {
        return Err("XLSX defined-name output changed calculation metadata".into());
    }

    let source = OpcPackage::from_bytes(&corpus.archive)?;
    let candidate = OpcPackage::from_bytes(output)?;
    if source.part_count() != corpus.manifest.entry_count
        || candidate.part_count() != source.part_count()
        || relationship_signatures(source.rels()) != relationship_signatures(candidate.rels())
    {
        return Err("XLSX defined-name package topology differs from source".into());
    }
    let target_uri = PackURI::new(format!("/{}", corpus.target_name))?;
    for source_part in source.iter_parts() {
        let candidate_part = candidate.get_part(source_part.partname())?;
        if candidate_part.content_type() != source_part.content_type()
            || relationship_signatures(candidate_part.rels())
                != relationship_signatures(source_part.rels())
        {
            return Err("XLSX defined-name Part metadata differs from source".into());
        }
        if source_part.partname() == &target_uri {
            if source_part.blob() == candidate_part.blob() {
                return Err("XLSX defined-name workbook XML did not change".into());
            }
        } else if source_part.blob() != candidate_part.blob() {
            return Err("XLSX defined-name edit changed an unselected Part payload".into());
        }
    }
    for index in 0..XLSX_CALC_MEDIA_ENTRY_COUNT {
        let uri = PackURI::new(format!("/xl/media/image{}.png", index + 1))?;
        if candidate.get_part(&uri)?.blob() != xlsx_calculation_media_payload(index) {
            return Err("XLSX defined-name media readback differs from specification".into());
        }
    }
    Ok(())
}

fn publish_xlsx_defined_names_edit<W: Write>(
    source: Arc<dyn ReadAt>,
    writer: W,
    source_backed: bool,
) -> Result<usize, Box<dyn Error>> {
    if source_backed {
        let editor = litchi_xlsx::defined_names::SourceBackedEditor::from_read_at(source)?;
        let mut edit = editor.edit();
        if !edit.replace(xlsx_defined_names_target())? {
            return Err("XLSX source-backed defined-name edit reported an exact no-op".into());
        }
        let commit = edit.commit()?;
        if !commit.changed()
            || commit.patch().is_empty()
            || commit.patch().inverse().after() != commit.patch().before()
        {
            return Err("XLSX source-backed defined-name edit produced an invalid patch".into());
        }
        let materializations = usize::try_from(editor.cache_diagnostics().successful_loads)?;
        let published = editor.publish_commit_to_stream(writer, &commit)?;
        if published != *commit.snapshot() {
            return Err("XLSX source-backed defined-name edit published another snapshot".into());
        }
        Ok(materializations)
    } else {
        let source_backed = SourceBackedPackage::from_read_at(source)?;
        let opc = source_backed.into_opc_package()?;
        let materializations = opc.part_count();
        let package = litchi_xlsx::Package::from_opc(opc)?;
        let workbook = package.into_workbook()?;
        let mut edit = workbook.edit()?;
        edit.replace_defined_names(xlsx_defined_names_target())?;
        let commit = edit.commit()?;
        if commit.patch().is_empty() {
            return Err("XLSX eager defined-name edit produced an empty patch".into());
        }
        commit.workbook().write_to(writer)?;
        Ok(materializations)
    }
}

fn run_xlsx_defined_names_edit_save(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if corpus.manifest.generator != XLSX_DEFINED_NAMES_SOURCE_EDIT_CORPUS_GENERATOR
        || !case.is_xlsx_defined_names_edit_save()
    {
        return Err("XLSX defined-name case requires its fixed media-rich corpus".into());
    }
    let source_backed = case == Case::XlsxSourceBackedDefinedNamesEditSave;
    let expected_source: Arc<dyn ReadAt> = Arc::new(OwnedSource::new(corpus.archive.clone()));
    let mut expected = Vec::new();
    let expected_materializations =
        publish_xlsx_defined_names_edit(expected_source, &mut expected, source_backed)?;
    let required_materializations = if source_backed {
        1
    } else {
        corpus.manifest.entry_count
    };
    if expected == corpus.archive || expected_materializations != required_materializations {
        return Err("XLSX defined-name edit materialized an unexpected Part count".into());
    }
    verify_xlsx_defined_names_edit_output(corpus, &expected)?;
    let expected_digest = sha256_hex(&expected);
    let maximum = u64::try_from(expected.len())?
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("XLSX defined-name sequential output ceiling overflows u64")?;
    let payload_ranges = xlsx_calculation_payload_ranges(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut sink_summaries = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    let mut measured_digests = Vec::with_capacity(samples);

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = Arc::new(InstrumentedSource::new(
            corpus.archive.clone(),
            payload_ranges.clone(),
        ));
        let read_at: Arc<dyn ReadAt> = source.clone();
        let mut sink = CountingSink::bounded(maximum, 64 * 1024);
        sink.reserve_budget()?;
        let started = Instant::now();
        let materializations = publish_xlsx_defined_names_edit(read_at, &mut sink, source_backed)?;
        let duration = started.elapsed();

        if materializations != expected_materializations || sink.bytes != expected {
            return Err("XLSX defined-name edit differs between iterations".into());
        }
        if sink.summary().largest_write > 64 * 1024 {
            return Err("XLSX defined-name edit exceeded the sequential sink write bound".into());
        }
        verify_xlsx_defined_names_edit_output(corpus, &sink.bytes)?;
        let digest = sha256_hex(&sink.bytes);
        if digest != expected_digest {
            return Err("XLSX defined-name output digest differs from expected output".into());
        }
        let metrics = source.snapshot();
        if metrics.ordinary_payload_read_calls == 0 || metrics.ordinary_payload_read_bytes == 0 {
            return Err("XLSX defined-name edit performed no ordinary source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record_opc(metrics, u64::try_from(materializations)?);
            sink_summaries.push(sink.summary());
            measured_digests.push(digest);
        }
        std::hint::black_box(&sink.bytes);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let sink = deterministic_sink_summary(&sink_summaries, case.name())?;
    if measured_digests
        .iter()
        .any(|digest| digest != &expected_digest)
    {
        return Err("XLSX defined-name measured output digests are not stable".into());
    }
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: Some(source_summary),
        execution: None,
        output_sha256: Some(expected_digest),
        operation_metrics: None,
    })
}

fn verify_xlsx_calculation_metadata_edit_output(
    corpus: &Corpus,
    output: &[u8],
) -> Result<(), Box<dyn Error>> {
    let reopened = litchi_xlsx::Package::from_slice(output)?;
    if reopened
        .calculation_metadata()?
        .properties()
        .ok_or("XLSX calculation-edit output has no calcPr")?
        .calculation_id()
        != 91
    {
        return Err("XLSX calculation-edit output has unexpected calculation ID".into());
    }

    let source = OpcPackage::from_bytes(&corpus.archive)?;
    let candidate = OpcPackage::from_bytes(output)?;
    if source.part_count() != corpus.manifest.entry_count
        || candidate.part_count() != source.part_count()
        || relationship_signatures(source.rels()) != relationship_signatures(candidate.rels())
    {
        return Err("XLSX calculation-edit package topology differs from source".into());
    }
    let target_uri = PackURI::new(format!("/{}", corpus.target_name))?;
    for source_part in source.iter_parts() {
        let candidate_part = candidate.get_part(source_part.partname())?;
        if candidate_part.content_type() != source_part.content_type()
            || relationship_signatures(candidate_part.rels())
                != relationship_signatures(source_part.rels())
        {
            return Err("XLSX calculation-edit Part metadata differs from source".into());
        }
        if source_part.partname() == &target_uri {
            if source_part.blob() == candidate_part.blob() {
                return Err("XLSX calculation-edit workbook XML did not change".into());
            }
        } else if source_part.blob() != candidate_part.blob() {
            return Err("XLSX calculation-edit changed an unselected Part payload".into());
        }
    }
    for index in 0..XLSX_CALC_MEDIA_ENTRY_COUNT {
        let uri = PackURI::new(format!("/xl/media/image{}.png", index + 1))?;
        if candidate.get_part(&uri)?.blob() != xlsx_calculation_media_payload(index) {
            return Err("XLSX calculation-edit media readback differs from specification".into());
        }
    }
    Ok(())
}

fn publish_xlsx_calculation_metadata_edit<W: Write>(
    source: Arc<dyn ReadAt>,
    writer: W,
    source_backed: bool,
) -> Result<usize, Box<dyn Error>> {
    let properties =
        litchi_xlsx::calculation_properties::Properties::new().with_calculation_id(Some(91));
    if source_backed {
        let editor = litchi_xlsx::calculation_properties::SourceBackedEditor::from_read_at(source)?;
        let mut edit = editor.edit();
        if !edit.set_properties(properties) {
            return Err("XLSX source-backed calculation edit reported an exact no-op".into());
        }
        let commit = edit.commit()?;
        if !commit.changed()
            || commit.patch().is_empty()
            || commit.patch().inverse().after() != commit.patch().before()
        {
            return Err("XLSX source-backed calculation edit produced an invalid patch".into());
        }
        let materializations = usize::try_from(editor.cache_diagnostics().successful_loads)?;
        let published = editor.publish_commit_to_stream(writer, &commit)?;
        if published != *commit.snapshot() {
            return Err("XLSX source-backed calculation edit published another snapshot".into());
        }
        Ok(materializations)
    } else {
        let package = SourceBackedPackage::from_read_at(source)?;
        let opc = package.into_opc_package()?;
        let materializations = opc.part_count();
        let mut package = litchi_xlsx::Package::from_opc(opc)?;
        let mut edit = package.edit_calculation_metadata()?;
        if !edit.set_properties(properties) {
            return Err("XLSX eager calculation edit reported an exact no-op".into());
        }
        let commit = edit.commit()?;
        if !commit.changed() || commit.patch().is_empty() {
            return Err("XLSX eager calculation edit produced an invalid patch".into());
        }
        package.write_to(writer)?;
        Ok(materializations)
    }
}

