fn cfb_instrumented_source(corpus: &Corpus) -> Arc<InstrumentedSource> {
    Arc::new(InstrumentedSource::new(corpus.archive.clone(), Vec::new()))
}

fn cfb_shared_limits(corpus: &Corpus) -> Result<SharedOleFileLimits, Box<dyn Error>> {
    Ok(SharedOleFileLimits::new(u64::try_from(
        corpus.archive.len(),
    )?)?)
}

fn run_cfb_shared_open(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let limits = cfb_shared_limits(corpus)?;
    let expected_size = u64::try_from(corpus.archive.len())?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = cfb_instrumented_source(corpus);
        let started = Instant::now();
        let ole = SharedOleFile::open_with_limits(source.clone(), limits)?;
        let duration = started.elapsed();
        if ole.file_size() != expected_size {
            return Err("shared CFB open file size differs from corpus manifest".into());
        }
        std::hint::black_box(&ole);
        let metrics = source.snapshot();
        if metrics.read_calls == 0 || metrics.read_bytes == 0 {
            return Err("shared CFB open performed no positional source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record(metrics);
        }
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result_with_source(
        Case::CfbSharedOpen,
        corpus,
        elapsed,
        source_summary,
    ))
}

fn run_cfb_shared_read_one(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let limits = cfb_shared_limits(corpus)?;
    let path = [corpus.target_name.as_str()];
    let mut elapsed = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = cfb_instrumented_source(corpus);
        let ole = SharedOleFile::open_with_limits(source.clone(), limits)?;
        source.reset();
        let started = Instant::now();
        let bytes = ole.open_stream(&path)?;
        let duration = started.elapsed();
        if bytes != corpus.target_payload {
            return Err("shared CFB read differs from deterministic stream payload".into());
        }
        std::hint::black_box(&bytes);
        let metrics = source.snapshot();
        if metrics.read_calls == 0 || metrics.read_bytes == 0 {
            return Err("shared CFB stream read performed no positional source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record(metrics);
        }
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result_with_source(
        Case::CfbSharedReadOne,
        corpus,
        elapsed,
        source_summary,
    ))
}

fn run_cfb_selective_read(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let shared = matches!(
        case,
        Case::CfbSelectiveMiniSharedRead
            | Case::CfbSelectiveMini4095SharedRead
            | Case::CfbSelectiveFatSharedRead
    );
    let implementation = if shared {
        "shared-positional-exact-range"
    } else {
        "legacy-cursor-full-stream"
    };
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut read_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_range_sizes = Vec::with_capacity(samples);
    let mut read_calls = Vec::with_capacity(samples);
    let mut read_bytes = Vec::with_capacity(samples);
    let mut read_range_sizes = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let mut selected_hash = None;
    let limits = cfb_shared_limits(corpus)?;
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SelectiveReadMetrics::default());
        let total_started = Instant::now();
        let open_started = Instant::now();
        let selected = if shared {
            let source = Arc::new(SelectiveReadAt::new(bytes, Arc::clone(&metrics)));
            let ole = SharedOleFile::open_with_limits(source, limits)?;
            let open_duration = open_started.elapsed();
            let open_snapshot = metrics.snapshot()?;
            metrics.reset()?;
            let read_started = Instant::now();
            let path = [corpus.target_name.as_str()];
            let mut payload = Vec::new();
            payload.try_reserve_exact(corpus.target_payload.len())?;
            payload.resize(corpus.target_payload.len(), 0);
            ole.read_stream_range(&path, 0, &mut payload)?;
            let read_duration = read_started.elapsed();
            (payload, open_duration, read_duration, open_snapshot)
        } else {
            let cursor = SelectiveCursor::new(bytes, Arc::clone(&metrics));
            let mut ole = OleFile::open(cursor)?;
            let open_duration = open_started.elapsed();
            let open_snapshot = metrics.snapshot()?;
            metrics.reset()?;
            let read_started = Instant::now();
            let path = [corpus.target_name.as_str()];
            let payload = ole.open_stream(&path)?;
            let read_duration = read_started.elapsed();
            (payload, open_duration, read_duration, open_snapshot)
        };
        let (payload, open_duration, read_duration, open_snapshot) = selected;
        let total_duration = total_started.elapsed();
        if payload != corpus.target_payload {
            return Err("CFB selective read differs from deterministic target payload".into());
        }
        let read_snapshot = metrics.snapshot()?;
        if open_snapshot.read_calls == 0
            || open_snapshot.read_bytes == 0
            || read_snapshot.read_calls == 0
            || read_snapshot.read_bytes == 0
        {
            return Err("CFB selective read performed no measured source I/O".into());
        }
        let hash = sha256_hex(&payload);
        if let Some(expected) = selected_hash.as_deref() {
            if expected != hash {
                return Err("CFB selective read hash changed across samples".into());
            }
        } else {
            selected_hash = Some(hash);
        }
        std::hint::black_box(&payload);
        if iteration >= warmup_iterations {
            let open_duration = elapsed_ns(open_duration)?;
            let read_duration = elapsed_ns(read_duration)?;
            let total_duration = elapsed_ns(total_duration)?;
            elapsed.push(total_duration);
            open_ns.push(open_duration);
            read_ns.push(read_duration);
            total_ns.push(total_duration);
            open_read_calls.push(open_snapshot.read_calls);
            open_read_bytes.push(open_snapshot.read_bytes);
            open_range_sizes.push(open_snapshot.range_sizes);
            read_calls.push(read_snapshot.read_calls);
            read_bytes.push(read_snapshot.read_bytes);
            read_range_sizes.push(read_snapshot.range_sizes);
            returned_payload_bytes.push(u64::try_from(payload.len())?);
        }
    }
    let selected_payload_sha256 = selected_hash.ok_or("CFB selective read produced no hash")?;
    let evidence = CfbSelectiveEvidence {
        timing_scope: "open and selected read are separate stages; legacy materializes the full stream, while shared fills a newly allocated exact-length caller range; corpus construction and validation excluded",
        sink: "none",
        selected_target_kind: if corpus.target_payload.len() < 4096 {
            if corpus.target_payload.len() == 4095 {
                "minifat-4095-byte"
            } else {
                "minifat-36-byte"
            }
        } else {
            "fat-4mib"
        },
        legacy_or_positional: CfbSelectiveImplementationEvidence {
            implementation,
            open_ns,
            read_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_range_sizes,
            read_calls,
            read_bytes,
            read_range_sizes,
            returned_payload_bytes,
            selected_payload_sha256,
        },
        simulation: None,
    };
    let source = SourceSummary {
        cfb_selective: Some(evidence),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn cfb_open_stream_identity(corpus: &Corpus) -> Result<(usize, u32, bool, u64), Box<dyn Error>> {
    let parsed = OleFile::open(Cursor::new(corpus.archive.as_slice()))?;
    let root_ministream_bytes = parsed
        .root_entry()
        .ok_or("CFB open_stream source has no root directory entry")?
        .size;
    let entries = parsed.list_directory_entries(&[])?;
    let target = entries
        .iter()
        .find(|entry| entry.name == corpus.target_name)
        .ok_or("CFB open_stream target is absent from the root directory")?;
    if !target.is_minifat || usize::try_from(target.size)? != corpus.target_payload.len() {
        return Err("CFB open_stream target identity differs from MiniFAT corpus".into());
    }
    Ok((
        parsed.sector_size(),
        target.start_sector,
        target.is_minifat,
        root_ministream_bytes,
    ))
}

fn cfb_expected_direct_physical_range(
    events: &[[u64; 3]],
    target_len: usize,
) -> Result<Option<[u64; 2]>, Box<dyn Error>> {
    let target_len = u64::try_from(target_len)?;
    let Some(&[offset, requested, returned]) = events.first() else {
        return Ok(None);
    };
    if events.len() != 1 || requested != target_len || returned != target_len {
        return Ok(None);
    }
    let end = offset
        .checked_add(returned)
        .ok_or("CFB open_stream direct physical range overflows u64")?;
    Ok(Some([offset, end]))
}

fn cfb_root_cache_read_bytes(snapshot: &SelectiveReadSnapshot, root_bytes: u64) -> Option<u64> {
    snapshot
        .ranges
        .iter()
        .any(|&[offset, requested, returned]| {
            offset == 512 && requested == root_bytes && returned == root_bytes
        })
        .then_some(root_bytes)
}

fn cfb_open_stream_names(corpus: &Corpus, operation: CfbOpenStreamOperation) -> Vec<String> {
    match operation {
        CfbOpenStreamOperation::OneShot
        | CfbOpenStreamOperation::Repeat
        | CfbOpenStreamOperation::Repeat8 => vec![corpus.target_name.clone(); operation.count()],
        CfbOpenStreamOperation::DifferentSid | CfbOpenStreamOperation::Bulk => vec![
            corpus.target_name.clone(),
            cfb_entry_name(0),
            corpus.target_name.clone(),
        ],
        CfbOpenStreamOperation::Concurrent => {
            vec![corpus.target_name.clone(), corpus.target_name.clone()]
        },
    }
}

fn cfb_open_stream_expected_payload(
    corpus: &Corpus,
    name: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    if name == corpus.target_name {
        Ok(corpus.target_payload.clone())
    } else if name == cfb_entry_name(0) {
        Ok(payload_bytes(
            PayloadKind::Incompressible,
            0,
            corpus.manifest.entry_bytes,
        ))
    } else {
        Err(format!("unknown CFB open_stream workload path: {name}").into())
    }
}

fn cfb_open_stream_expected_hash(corpus: &Corpus, name: &str) -> Result<String, Box<dyn Error>> {
    Ok(sha256_hex(&cfb_open_stream_expected_payload(corpus, name)?))
}

#[cfg(test)]
fn cfb_target_aware_repeat_formula(target_bytes: u64, invocations: usize) -> Vec<u64> {
    vec![target_bytes; invocations]
}

fn run_cfb_open_stream(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_cfb_open_stream_evidence() || case.cfb_open_stream_simulated() {
        return Err("non-production CFB open_stream case reached production runner".into());
    }
    let operation = case
        .cfb_open_stream_operation()
        .ok_or("CFB open_stream case has no operation")?;
    if operation.is_bulk() {
        return run_cfb_open_stream_bulk(case, corpus, warmup_iterations, samples);
    }
    if operation.is_concurrent() {
        return run_cfb_open_stream_concurrent(case, corpus, warmup_iterations, samples);
    }
    let invocation_count = operation.count();
    let invocation_stream_names = cfb_open_stream_names(corpus, operation);
    let implementation = "shared-open-stream-read-at";
    let (sector_size, target_start_sector, target_is_minifat, root_ministream_bytes) =
        cfb_open_stream_identity(corpus)?;
    let limits = cfb_shared_limits(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut operation_ns = Vec::with_capacity(samples);
    let mut per_operation_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_read_range_sizes = Vec::with_capacity(samples);
    let mut open_read_ranges = Vec::with_capacity(samples);
    let mut logical_read_calls = Vec::with_capacity(samples);
    let mut logical_read_bytes = Vec::with_capacity(samples);
    let mut logical_read_range_sizes = Vec::with_capacity(samples);
    let mut logical_read_ranges = Vec::with_capacity(samples);
    let mut per_operation_read_calls = Vec::with_capacity(samples);
    let mut per_operation_read_bytes = Vec::with_capacity(samples);
    let mut per_operation_read_range_sizes = Vec::with_capacity(samples);
    let mut per_operation_read_ranges = Vec::with_capacity(samples);
    let mut root_cache_read_bytes = Vec::with_capacity(samples);
    let mut expected_direct_physical_range = Vec::with_capacity(samples);
    let mut output_sha256 = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let mut expected_payload_sha256 = None;
    let source_version_check =
        "public SharedOleFile::source_version verified before and after open_stream operations";

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SelectiveReadMetrics::default());
        let mut operation_durations = Vec::with_capacity(invocation_count);
        let mut operation_snapshots = Vec::with_capacity(invocation_count);
        let mut outputs = Vec::with_capacity(invocation_count);
        let source = Arc::new(SelectiveReadAt::new(bytes, Arc::clone(&metrics)));
        let open_started = Instant::now();
        let ole = SharedOleFile::open_with_limits(source, limits)?;
        let open_duration = open_started.elapsed();
        let open_snapshot = metrics.snapshot()?;
        metrics.reset()?;
        let source_version_before = ole.source_version()?;
        for name in &invocation_stream_names {
            metrics.reset()?;
            let started = Instant::now();
            let path = [name.as_str()];
            let output = ole.open_stream(&path)?;
            let duration = started.elapsed();
            let snapshot = metrics.snapshot()?;
            operation_durations.push(duration);
            operation_snapshots.push(snapshot);
            outputs.push(output);
        }
        let source_version_after = ole.source_version()?;
        if source_version_before != source_version_after {
            return Err("CFB open_stream source version changed across a stable operation".into());
        }
        if !matches!(
            ole.open_stream(&["__litchi_open_stream_missing__"]),
            Err(OleError::StreamNotFound)
        ) {
            return Err("CFB open_stream missing-path error variant was not preserved".into());
        }
        if outputs.len() != invocation_count {
            return Err("CFB open_stream returned an unexpected output count".into());
        }
        for (name, output) in invocation_stream_names.iter().zip(&outputs) {
            if output != &cfb_open_stream_expected_payload(corpus, name)? {
                return Err(
                    "CFB open_stream output differs from deterministic workload payload".into(),
                );
            }
        }
        let hashes = outputs
            .iter()
            .map(|output| sha256_hex(output))
            .collect::<Vec<_>>();
        for (name, hash) in invocation_stream_names.iter().zip(&hashes) {
            if hash != &cfb_open_stream_expected_hash(corpus, name)? {
                return Err("CFB open_stream output hash differs from manifest".into());
            }
        }
        if let Some(expected) = expected_payload_sha256.as_deref() {
            if expected != corpus.manifest.target_payload_sha256 {
                return Err("CFB open_stream expected hash changed across samples".into());
            }
        } else {
            expected_payload_sha256 = Some(corpus.manifest.target_payload_sha256.clone());
        }
        let aggregate_calls = operation_snapshots
            .iter()
            .try_fold(0_u64, |total, snapshot| {
                total.checked_add(snapshot.read_calls)
            })
            .ok_or("CFB open_stream logical call count overflowed")?;
        let aggregate_bytes = operation_snapshots
            .iter()
            .try_fold(0_u64, |total, snapshot| {
                total.checked_add(snapshot.read_bytes)
            })
            .ok_or("CFB open_stream logical byte count overflowed")?;
        let mut aggregate_sizes = Vec::new();
        let mut aggregate_ranges = Vec::new();
        let mut op_calls = Vec::with_capacity(operation_snapshots.len());
        let mut op_bytes = Vec::with_capacity(operation_snapshots.len());
        let mut op_sizes = Vec::with_capacity(operation_snapshots.len());
        let mut op_ranges = Vec::with_capacity(operation_snapshots.len());
        for snapshot in &operation_snapshots {
            op_calls.push(snapshot.read_calls);
            op_bytes.push(snapshot.read_bytes);
            aggregate_sizes.extend_from_slice(&snapshot.range_sizes);
            aggregate_ranges.extend_from_slice(&snapshot.ranges);
            op_sizes.push(snapshot.range_sizes.clone());
            op_ranges.push(snapshot.ranges.clone());
        }
        aggregate_sizes.sort_unstable();
        let operation_duration = operation_durations
            .iter()
            .try_fold(Duration::ZERO, |total, duration| {
                total.checked_add(*duration)
            })
            .ok_or("CFB open_stream operation duration overflowed")?;
        let total_duration = open_duration
            .checked_add(operation_duration)
            .ok_or("CFB open_stream combined duration overflows")?;
        if open_snapshot.read_calls == 0 || open_snapshot.read_bytes == 0 {
            return Err("CFB open_stream open phase performed no measured source reads".into());
        }
        if aggregate_calls == 0 || aggregate_bytes == 0 {
            return Err("CFB open_stream operation performed no measured source reads".into());
        }
        if iteration >= warmup_iterations {
            record_elapsed(&mut elapsed, iteration, warmup_iterations, total_duration)?;
            open_ns.push(elapsed_ns(open_duration)?);
            operation_ns.push(elapsed_ns(operation_duration)?);
            per_operation_ns.push(
                operation_durations
                    .iter()
                    .copied()
                    .map(elapsed_ns)
                    .collect::<Result<Vec<_>, _>>()?,
            );
            total_ns.push(elapsed_ns(total_duration)?);
            open_read_calls.push(open_snapshot.read_calls);
            open_read_bytes.push(open_snapshot.read_bytes);
            open_read_range_sizes.push(open_snapshot.range_sizes);
            open_read_ranges.push(open_snapshot.ranges);
            logical_read_calls.push(aggregate_calls);
            logical_read_bytes.push(aggregate_bytes);
            logical_read_range_sizes.push(aggregate_sizes);
            logical_read_ranges.push(aggregate_ranges);
            per_operation_read_calls.push(op_calls);
            per_operation_read_bytes.push(op_bytes);
            per_operation_read_range_sizes.push(op_sizes);
            per_operation_read_ranges.push(op_ranges);
            expected_direct_physical_range.push(cfb_expected_direct_physical_range(
                operation_snapshots
                    .first()
                    .map_or(&[][..], |snapshot| snapshot.ranges.as_slice()),
                corpus.target_payload.len(),
            )?);
            root_cache_read_bytes.push(
                operation_snapshots.iter().find_map(|snapshot| {
                    cfb_root_cache_read_bytes(snapshot, root_ministream_bytes)
                }),
            );
            output_sha256.push(hashes);
            returned_payload_bytes.push(
                outputs
                    .iter()
                    .map(|output| u64::try_from(output.len()))
                    .collect::<Result<Vec<_>, _>>()?,
            );
        }
    }

    let expected_payload_sha256 =
        expected_payload_sha256.ok_or("CFB open_stream produced no expected payload hash")?;
    let cache_state_diagnostic = match operation {
        CfbOpenStreamOperation::OneShot => {
            "private MiniFAT cache state is not public; one-shot source counters distinguish a candidate direct target read from baseline root materialization"
        },
        CfbOpenStreamOperation::Repeat | CfbOpenStreamOperation::Repeat8 => {
            "private MiniFAT cache state is not public; per-invocation source counters distinguish candidate direct-then-root materialization from baseline root materialization, and later zero-read phases are inferred cache hits"
        },
        CfbOpenStreamOperation::DifferentSid => {
            "private MiniFAT cache state is not public; the A-B-A source vector distinguishes root-only control from direct-target then root-cache takeover, while preserving sibling correctness"
        },
        CfbOpenStreamOperation::Bulk => {
            "private MiniFAT cache state is not public; the public bulk-read source vector distinguishes root-only control from direct-target plus root-cache materialization"
        },
        CfbOpenStreamOperation::Concurrent => {
            "private MiniFAT cache state is not public; a harness-only overlap gate makes two same-target callers deterministic while source counters distinguish root-only control from direct-target plus root-cache takeover"
        },
    };
    let source = SourceSummary {
        cfb_open_stream: Some(CfbOpenStreamEvidence {
            timing_scope: "fresh validated open plus bounded open_stream operation; corpus construction, refusal check, source snapshots, hashes, and output validation are excluded from elapsed_ns",
            sink: "none",
            implementation,
            operation: operation.name(),
            invocation_count,
            invocation_stream_names,
            requested_stream_count: invocation_count,
            shape: corpus.manifest.shape,
            sibling_count: corpus.manifest.entry_count,
            sector_size,
            mini_sector_size: 64,
            target_stream_name: corpus.target_name.clone(),
            target_start_sector,
            target_is_minifat,
            root_ministream_bytes,
            selected_target_kind: if corpus.target_payload.len() == 4095 {
                "minifat-4095-byte"
            } else {
                "minifat-36-byte"
            },
            cache_state_diagnostic,
            source_version_check,
            typed_refusal_verified: true,
            expected_payload_sha256,
            output_sha256,
            returned_payload_bytes,
            open_ns,
            operation_ns,
            per_operation_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_read_range_sizes,
            open_read_ranges,
            logical_read_calls,
            logical_read_bytes,
            logical_read_range_sizes,
            logical_read_ranges,
            per_operation_read_calls,
            per_operation_read_bytes,
            per_operation_read_range_sizes,
            per_operation_read_ranges,
            root_cache_read_bytes,
            expected_direct_physical_range,
            simulation: None,
        }),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn run_cfb_open_stream_bulk(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let operation = CfbOpenStreamOperation::Bulk;
    let invocation_stream_names = cfb_open_stream_names(corpus, operation);
    let (sector_size, target_start_sector, target_is_minifat, root_ministream_bytes) =
        cfb_open_stream_identity(corpus)?;
    let limits = cfb_shared_limits(corpus)?;
    // Prepare the deterministic oracle before any measured sample. Hashes
    // recorded below are computed from the actual returned buffers, while
    // these independent expected values continue to guard correctness.
    let expected_outputs = invocation_stream_names
        .iter()
        .map(|name| cfb_open_stream_expected_payload(corpus, name))
        .collect::<Result<Vec<_>, _>>()?;
    let expected_hashes = expected_outputs
        .iter()
        .map(|output| sha256_hex(output))
        .collect::<Vec<_>>();
    let expected_payload_sha256 = invocation_stream_names
        .iter()
        .zip(&expected_hashes)
        .find_map(|(name, hash)| (name == &corpus.target_name).then(|| hash.clone()))
        .ok_or("CFB bulk workload has no target payload hash")?;
    if expected_payload_sha256 != corpus.manifest.target_payload_sha256 {
        return Err("CFB bulk deterministic target hash differs from manifest".into());
    }
    let total_requested_bytes = expected_outputs
        .iter()
        .try_fold(0usize, |total, output| total.checked_add(output.len()))
        .ok_or("CFB bulk workload bytes overflow")?;
    let path_storage = invocation_stream_names
        .iter()
        .map(|name| vec![name.as_str()])
        .collect::<Vec<_>>();
    let paths = path_storage.iter().map(Vec::as_slice).collect::<Vec<_>>();
    let input_bytes = u64::try_from(corpus.archive.len())?;
    let work_bytes = u64::try_from(total_requested_bytes)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut operation_ns = Vec::with_capacity(samples);
    let mut per_operation_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_read_range_sizes = Vec::with_capacity(samples);
    let mut open_read_ranges = Vec::with_capacity(samples);
    let mut logical_read_calls = Vec::with_capacity(samples);
    let mut logical_read_bytes = Vec::with_capacity(samples);
    let mut logical_read_range_sizes = Vec::with_capacity(samples);
    let mut logical_read_ranges = Vec::with_capacity(samples);
    let mut per_operation_read_calls = Vec::with_capacity(samples);
    let mut per_operation_read_bytes = Vec::with_capacity(samples);
    let mut per_operation_read_range_sizes = Vec::with_capacity(samples);
    let mut per_operation_read_ranges = Vec::with_capacity(samples);
    let mut root_cache_read_bytes = Vec::with_capacity(samples);
    let mut expected_direct_physical_range = Vec::with_capacity(samples);
    let mut output_sha256 = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let source_version_check =
        "public SharedOleFile::source_version verified before and after bulk_read operations";

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SelectiveReadMetrics::default());
        let source = Arc::new(SelectiveReadAt::new(bytes, Arc::clone(&metrics)));
        let open_started = Instant::now();
        let ole = SharedOleFile::open_with_limits(source, limits)?;
        let open_duration = open_started.elapsed();
        let open_snapshot = metrics.snapshot()?;
        metrics.reset()?;
        let source_version_before = ole.source_version()?;
        let context = execution_context(
            1,
            invocation_stream_names.len(),
            work_bytes,
            input_bytes,
            work_bytes,
        )?;
        let started = Instant::now();
        let outputs = ole.bulk_read(context).read_streams(&paths)?;
        let operation_duration = started.elapsed();
        let operation_snapshot = metrics.snapshot()?;
        let source_version_after = ole.source_version()?;
        if source_version_before != source_version_after {
            return Err(
                "CFB bulk open_stream source version changed across a stable operation".into(),
            );
        }
        let missing_path = ["__litchi_open_stream_missing__"];
        let missing_paths = [&missing_path[..]];
        let missing_context = execution_context(1, 1, work_bytes, input_bytes, work_bytes)?;
        if !matches!(
            ole.bulk_read(missing_context).read_streams(&missing_paths),
            Err(SharedOleBulkError::Ole(OleError::StreamNotFound))
        ) {
            return Err("CFB bulk missing-path error variant was not preserved".into());
        }
        if outputs.len() != invocation_stream_names.len() {
            return Err("CFB bulk output count differs from workload".into());
        }
        for (output, expected) in outputs.iter().zip(&expected_outputs) {
            if output != expected {
                return Err("CFB bulk output differs from deterministic workload payload".into());
            }
        }
        let hashes = outputs
            .iter()
            .map(|output| sha256_hex(output))
            .collect::<Vec<_>>();
        for (hash, expected) in hashes.iter().zip(&expected_hashes) {
            if hash != expected {
                return Err("CFB bulk output hash differs from deterministic workload".into());
            }
        }
        let total_duration = open_duration
            .checked_add(operation_duration)
            .ok_or("CFB bulk combined duration overflows")?;
        if open_snapshot.read_calls == 0 || operation_snapshot.read_calls == 0 {
            return Err("CFB bulk workload performed no measured source reads".into());
        }
        if iteration >= warmup_iterations {
            record_elapsed(&mut elapsed, iteration, warmup_iterations, total_duration)?;
            open_ns.push(elapsed_ns(open_duration)?);
            operation_ns.push(elapsed_ns(operation_duration)?);
            per_operation_ns.push(vec![elapsed_ns(operation_duration)?]);
            total_ns.push(elapsed_ns(total_duration)?);
            open_read_calls.push(open_snapshot.read_calls);
            open_read_bytes.push(open_snapshot.read_bytes);
            open_read_range_sizes.push(open_snapshot.range_sizes);
            open_read_ranges.push(open_snapshot.ranges);
            logical_read_calls.push(operation_snapshot.read_calls);
            logical_read_bytes.push(operation_snapshot.read_bytes);
            logical_read_range_sizes.push(operation_snapshot.range_sizes.clone());
            logical_read_ranges.push(operation_snapshot.ranges.clone());
            per_operation_read_calls.push(vec![operation_snapshot.read_calls]);
            per_operation_read_bytes.push(vec![operation_snapshot.read_bytes]);
            per_operation_read_range_sizes.push(vec![operation_snapshot.range_sizes.clone()]);
            per_operation_read_ranges.push(vec![operation_snapshot.ranges.clone()]);
            root_cache_read_bytes.push(cfb_root_cache_read_bytes(
                &operation_snapshot,
                root_ministream_bytes,
            ));
            expected_direct_physical_range.push(None);
            output_sha256.push(hashes);
            returned_payload_bytes.push(
                outputs
                    .iter()
                    .map(|output| u64::try_from(output.len()))
                    .collect::<Result<Vec<_>, _>>()?,
            );
        }
    }
    let source = SourceSummary {
        cfb_open_stream: Some(CfbOpenStreamEvidence {
            timing_scope: "fresh validated open plus one bounded public bulk-read operation; corpus construction, refusal check, source snapshots, hashes, and output validation are excluded from elapsed_ns",
            sink: "none",
            implementation: "shared-open-stream-read-at",
            operation: operation.name(),
            invocation_count: 1,
            invocation_stream_names,
            requested_stream_count: 3,
            shape: corpus.manifest.shape,
            sibling_count: corpus.manifest.entry_count,
            sector_size,
            mini_sector_size: 64,
            target_stream_name: corpus.target_name.clone(),
            target_start_sector,
            target_is_minifat,
            root_ministream_bytes,
            selected_target_kind: if corpus.target_payload.len() == 4095 {
                "minifat-4095-byte"
            } else {
                "minifat-36-byte"
            },
            cache_state_diagnostic: "private MiniFAT cache state is not public; the public bulk-read source vector distinguishes root-only control from direct-target plus root-cache materialization",
            source_version_check,
            typed_refusal_verified: true,
            expected_payload_sha256,
            output_sha256,
            returned_payload_bytes,
            open_ns,
            operation_ns,
            per_operation_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_read_range_sizes,
            open_read_ranges,
            logical_read_calls,
            logical_read_bytes,
            logical_read_range_sizes,
            logical_read_ranges,
            per_operation_read_calls,
            per_operation_read_bytes,
            per_operation_read_range_sizes,
            per_operation_read_ranges,
            root_cache_read_bytes,
            expected_direct_physical_range,
            simulation: None,
        }),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn run_cfb_open_stream_concurrent(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let operation = CfbOpenStreamOperation::Concurrent;
    let invocation_stream_names = cfb_open_stream_names(corpus, operation);
    let (sector_size, target_start_sector, target_is_minifat, root_ministream_bytes) =
        cfb_open_stream_identity(corpus)?;
    let limits = cfb_shared_limits(corpus)?;
    let target_len = corpus.target_payload.len();
    // Prepare the deterministic oracle before any measured overlap. Hashes
    // recorded below are computed from the actual returned buffers, while
    // these independent expected values continue to guard correctness.
    let expected_output = cfb_open_stream_expected_payload(corpus, &corpus.target_name)?;
    let expected_payload_sha256 = cfb_open_stream_expected_hash(corpus, &corpus.target_name)?;
    if expected_payload_sha256 != corpus.manifest.target_payload_sha256 {
        return Err("CFB concurrent deterministic target hash differs from manifest".into());
    }
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut operation_ns = Vec::with_capacity(samples);
    let mut per_operation_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_read_range_sizes = Vec::with_capacity(samples);
    let mut open_read_ranges = Vec::with_capacity(samples);
    let mut logical_read_calls = Vec::with_capacity(samples);
    let mut logical_read_bytes = Vec::with_capacity(samples);
    let mut logical_read_range_sizes = Vec::with_capacity(samples);
    let mut logical_read_ranges = Vec::with_capacity(samples);
    let mut per_operation_read_calls = Vec::with_capacity(samples);
    let mut per_operation_read_bytes = Vec::with_capacity(samples);
    let mut per_operation_read_range_sizes = Vec::with_capacity(samples);
    let mut per_operation_read_ranges = Vec::with_capacity(samples);
    let mut root_cache_read_bytes = Vec::with_capacity(samples);
    let mut expected_direct_physical_range = Vec::with_capacity(samples);
    let mut output_sha256 = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let source_version_check = "public SharedOleFile::source_version verified before and after overlapping open_stream operations";

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SelectiveReadMetrics::default());
        let gate = Arc::new(ConcurrentReadGate::default());
        let source = Arc::new(SelectiveReadAt::with_concurrent_gate(
            bytes,
            Arc::clone(&metrics),
            Arc::clone(&gate),
            target_len,
        ));
        let open_started = Instant::now();
        let ole = SharedOleFile::open_with_limits(source, limits)?;
        let open_duration = open_started.elapsed();
        let open_snapshot = metrics.snapshot()?;
        metrics.reset()?;
        let source_version_before = ole.source_version()?;
        let start = Arc::new(Barrier::new(3));
        let target_name = corpus.target_name.clone();
        let started = Instant::now();
        let (first, second) = std::thread::scope(|scope| {
            let first_start = Arc::clone(&start);
            let first_gate = Arc::clone(&gate);
            let first_ole = &ole;
            let first_name = target_name.as_str();
            let first_task = scope.spawn(move || -> Result<_, String> {
                first_start.wait();
                first_gate
                    .mark_entered()
                    .map_err(|error| error.to_string())?;
                let operation_started = Instant::now();
                let output = first_ole
                    .open_stream(&[first_name])
                    .map_err(|error| error.to_string())?;
                Ok((output, operation_started.elapsed()))
            });
            let second_start = Arc::clone(&start);
            let second_gate = Arc::clone(&gate);
            let second_ole = &ole;
            let second_name = target_name.as_str();
            let second_task = scope.spawn(move || -> Result<_, String> {
                second_start.wait();
                second_gate
                    .mark_entered()
                    .map_err(|error| error.to_string())?;
                let operation_started = Instant::now();
                let output = second_ole
                    .open_stream(&[second_name])
                    .map_err(|error| error.to_string())?;
                Ok((output, operation_started.elapsed()))
            });
            start.wait();
            (
                first_task
                    .join()
                    .map_err(|_| "first CFB concurrent worker panicked".to_owned())
                    .and_then(|result| result),
                second_task
                    .join()
                    .map_err(|_| "second CFB concurrent worker panicked".to_owned())
                    .and_then(|result| result),
            )
        });
        let (first, first_duration) = first.map_err(io::Error::other)?;
        let (second, second_duration) = second.map_err(io::Error::other)?;
        let operation_duration = started.elapsed();
        let source_version_after = ole.source_version()?;
        if source_version_before != source_version_after {
            return Err(
                "CFB concurrent open_stream source version changed across a stable operation"
                    .into(),
            );
        }
        if !matches!(
            ole.open_stream(&["__litchi_open_stream_missing__"]),
            Err(OleError::StreamNotFound)
        ) {
            return Err("CFB concurrent missing-path error variant was not preserved".into());
        }
        if first != expected_output || second != expected_output {
            return Err("CFB concurrent output differs from deterministic target payload".into());
        }
        let operation_snapshot = metrics.snapshot()?;
        if open_snapshot.read_calls == 0 || operation_snapshot.read_calls == 0 {
            return Err("CFB concurrent workload performed no measured source reads".into());
        }
        let hashes = vec![sha256_hex(&first), sha256_hex(&second)];
        if hashes.iter().any(|hash| hash != &expected_payload_sha256) {
            return Err("CFB concurrent output hash differs from deterministic workload".into());
        }
        let total_duration = open_duration
            .checked_add(operation_duration)
            .ok_or("CFB concurrent combined duration overflows")?;
        if iteration >= warmup_iterations {
            record_elapsed(&mut elapsed, iteration, warmup_iterations, total_duration)?;
            open_ns.push(elapsed_ns(open_duration)?);
            operation_ns.push(elapsed_ns(operation_duration)?);
            per_operation_ns.push(vec![
                elapsed_ns(first_duration)?,
                elapsed_ns(second_duration)?,
            ]);
            total_ns.push(elapsed_ns(total_duration)?);
            open_read_calls.push(open_snapshot.read_calls);
            open_read_bytes.push(open_snapshot.read_bytes);
            open_read_range_sizes.push(open_snapshot.range_sizes);
            open_read_ranges.push(open_snapshot.ranges);
            logical_read_calls.push(operation_snapshot.read_calls);
            logical_read_bytes.push(operation_snapshot.read_bytes);
            logical_read_range_sizes.push(operation_snapshot.range_sizes.clone());
            logical_read_ranges.push(operation_snapshot.ranges.clone());
            per_operation_read_calls.push(vec![operation_snapshot.read_calls]);
            per_operation_read_bytes.push(vec![operation_snapshot.read_bytes]);
            per_operation_read_range_sizes.push(vec![operation_snapshot.range_sizes.clone()]);
            per_operation_read_ranges.push(vec![operation_snapshot.ranges.clone()]);
            root_cache_read_bytes.push(cfb_root_cache_read_bytes(
                &operation_snapshot,
                root_ministream_bytes,
            ));
            expected_direct_physical_range.push(None);
            output_sha256.push(hashes);
            returned_payload_bytes.push(vec![
                u64::try_from(first.len())?,
                u64::try_from(second.len())?,
            ]);
        }
    }
    let source = SourceSummary {
        cfb_open_stream: Some(CfbOpenStreamEvidence {
            timing_scope: "fresh validated open plus two overlapping same-target open_stream operations; a harness-only source gate releases the direct target reads after both workers enter; corpus construction, refusal check, source snapshots, hashes, and output validation are excluded from elapsed_ns",
            sink: "none",
            implementation: "shared-open-stream-read-at",
            operation: operation.name(),
            invocation_count: 2,
            invocation_stream_names,
            requested_stream_count: 2,
            shape: corpus.manifest.shape,
            sibling_count: corpus.manifest.entry_count,
            sector_size,
            mini_sector_size: 64,
            target_stream_name: corpus.target_name.clone(),
            target_start_sector,
            target_is_minifat,
            root_ministream_bytes,
            selected_target_kind: if corpus.target_payload.len() == 4095 {
                "minifat-4095-byte"
            } else {
                "minifat-36-byte"
            },
            cache_state_diagnostic: "private MiniFAT cache state is not public; the harness-only overlap gate makes same-target caller interleaving reproducible while aggregate source counters distinguish root-only control from direct-target plus root-cache takeover",
            source_version_check,
            typed_refusal_verified: true,
            expected_payload_sha256,
            output_sha256,
            returned_payload_bytes,
            open_ns,
            operation_ns,
            per_operation_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_read_range_sizes,
            open_read_ranges,
            logical_read_calls,
            logical_read_bytes,
            logical_read_range_sizes,
            logical_read_ranges,
            per_operation_read_calls,
            per_operation_read_bytes,
            per_operation_read_range_sizes,
            per_operation_read_ranges,
            root_cache_read_bytes,
            expected_direct_physical_range,
            simulation: None,
        }),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn run_cfb_open_stream_simulated(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
    config: RangeSimulationConfig,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_cfb_open_stream_evidence() || !case.cfb_open_stream_simulated() {
        return Err("non-simulated CFB open_stream case reached simulator runner".into());
    }
    if config.max_physical_range_bytes == 0 || config.bandwidth_bytes_per_second == 0 {
        return Err(
            "CFB open_stream simulator requires non-zero range and bandwidth limits".into(),
        );
    }
    let operation = case
        .cfb_open_stream_operation()
        .ok_or("simulated CFB open_stream case has no operation")?;
    let invocation_count = operation.count();
    let implementation = "shared-open-stream-simulated-read-at";
    let (sector_size, target_start_sector, target_is_minifat, root_ministream_bytes) =
        cfb_open_stream_identity(corpus)?;
    let limits = cfb_shared_limits(corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut operation_ns = Vec::with_capacity(samples);
    let mut per_operation_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_read_range_sizes = Vec::with_capacity(samples);
    let mut open_read_ranges = Vec::with_capacity(samples);
    let mut logical_read_calls = Vec::with_capacity(samples);
    let mut logical_read_bytes = Vec::with_capacity(samples);
    let mut logical_read_range_sizes = Vec::with_capacity(samples);
    let mut logical_read_ranges = Vec::with_capacity(samples);
    let mut per_operation_read_calls = Vec::with_capacity(samples);
    let mut per_operation_read_bytes = Vec::with_capacity(samples);
    let mut per_operation_read_range_sizes = Vec::with_capacity(samples);
    let mut per_operation_read_ranges = Vec::with_capacity(samples);
    let mut root_cache_read_bytes = Vec::with_capacity(samples);
    let mut expected_direct_physical_range = Vec::with_capacity(samples);
    let mut output_sha256 = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let mut simulations = Vec::with_capacity(samples);
    let mut expected_payload_sha256 = None;
    let source_version_check =
        "public SharedOleFile::source_version verified before and after open_stream operations";

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SimulatedRangeMetrics::default());
        let path = [corpus.target_name.as_str()];
        let mut operation_snapshots = Vec::with_capacity(invocation_count);
        let mut operation_durations = Vec::with_capacity(invocation_count);
        let mut outputs = Vec::with_capacity(invocation_count);
        let source = Arc::new(SimulatedRangeSource {
            backing: Arc::new(InstrumentedSource::new((*bytes).clone(), Vec::new())),
            config,
            metrics: Arc::clone(&metrics),
        });
        let open_started = Instant::now();
        let ole = SharedOleFile::open_with_limits(source.clone(), limits)?;
        let open_duration = open_started.elapsed();
        let open_snapshot = source.snapshot()?;
        metrics.reset()?;
        let source_version_before = ole.source_version()?;
        for _ in 0..invocation_count {
            metrics.reset()?;
            let started = Instant::now();
            let output = ole.open_stream(&path)?;
            let duration = started.elapsed();
            operation_durations.push(duration);
            operation_snapshots.push(metrics.snapshot()?);
            outputs.push(output);
        }
        let source_version_after = ole.source_version()?;
        if source_version_before != source_version_after {
            return Err("simulated CFB open_stream source version changed across operation".into());
        }
        if !matches!(
            ole.open_stream(&["__litchi_open_stream_missing__"]),
            Err(OleError::StreamNotFound)
        ) {
            return Err(
                "simulated CFB open_stream missing-path error variant was not preserved".into(),
            );
        }
        if outputs.len() != invocation_count
            || outputs
                .iter()
                .any(|output| output != &corpus.target_payload)
        {
            return Err(
                "simulated CFB open_stream output differs from deterministic target".into(),
            );
        }
        let hashes = outputs
            .iter()
            .map(|output| sha256_hex(output))
            .collect::<Vec<_>>();
        if hashes
            .iter()
            .any(|hash| hash != &corpus.manifest.target_payload_sha256)
        {
            return Err("simulated CFB open_stream output hash differs from manifest".into());
        }
        if expected_payload_sha256.is_none() {
            expected_payload_sha256 = Some(corpus.manifest.target_payload_sha256.clone());
        }
        let aggregate = combine_range_simulation_snapshots(
            &operation_snapshots
                .iter()
                .cloned()
                .try_fold(RangeSimulationSnapshot::default(), |a, b| {
                    combine_range_simulation_snapshots(&a, &b)
                })?,
            &RangeSimulationSnapshot::default(),
        )?;
        let aggregate_phase = cfb_simulation_phase(aggregate, config)?;
        let open_phase = cfb_simulation_phase(open_snapshot.clone(), config)?;
        let per_operation = operation_snapshots
            .iter()
            .cloned()
            .map(|snapshot| cfb_simulation_phase_allow_empty(snapshot, config))
            .collect::<Result<Vec<_>, _>>()?;
        let aggregate_calls = aggregate_phase.logical_read_calls;
        let aggregate_bytes = aggregate_phase.logical_read_bytes;
        let mut aggregate_sizes = aggregate_phase.physical_request_sizes.clone();
        aggregate_sizes.sort_unstable();
        let operation_duration = operation_durations
            .iter()
            .try_fold(Duration::ZERO, |total, duration| {
                total.checked_add(*duration)
            })
            .ok_or("simulated CFB open_stream operation duration overflowed")?;
        let total_duration = open_duration
            .checked_add(operation_duration)
            .ok_or("simulated CFB open_stream combined duration overflows")?;
        if open_snapshot.logical_read_calls == 0 || open_snapshot.logical_read_bytes == 0 {
            return Err("simulated CFB open_stream open phase performed no reads".into());
        }
        if iteration >= warmup_iterations {
            record_elapsed(&mut elapsed, iteration, warmup_iterations, total_duration)?;
            open_ns.push(elapsed_ns(open_duration)?);
            operation_ns.push(elapsed_ns(operation_duration)?);
            per_operation_ns.push(
                operation_durations
                    .iter()
                    .copied()
                    .map(elapsed_ns)
                    .collect::<Result<Vec<_>, _>>()?,
            );
            total_ns.push(elapsed_ns(total_duration)?);
            open_read_calls.push(open_snapshot.logical_read_calls);
            open_read_bytes.push(open_snapshot.logical_read_bytes);
            open_read_range_sizes.push(open_snapshot.physical_request_sizes.clone());
            open_read_ranges.push(open_snapshot.physical_ranges.clone());
            logical_read_calls.push(aggregate_calls);
            logical_read_bytes.push(aggregate_bytes);
            logical_read_range_sizes.push(aggregate_sizes);
            logical_read_ranges.push(aggregate_phase.physical_ranges.clone());
            per_operation_read_calls.push(
                per_operation
                    .iter()
                    .map(|phase| phase.logical_read_calls)
                    .collect(),
            );
            per_operation_read_bytes.push(
                per_operation
                    .iter()
                    .map(|phase| phase.logical_read_bytes)
                    .collect(),
            );
            per_operation_read_range_sizes.push(
                per_operation
                    .iter()
                    .map(|phase| phase.physical_request_sizes.clone())
                    .collect(),
            );
            per_operation_read_ranges.push(
                per_operation
                    .iter()
                    .map(|phase| phase.physical_ranges.clone())
                    .collect(),
            );
            expected_direct_physical_range.push(cfb_expected_direct_physical_range(
                per_operation
                    .first()
                    .map_or(&[][..], |phase| phase.physical_ranges.as_slice()),
                corpus.target_payload.len(),
            )?);
            root_cache_read_bytes.push(per_operation.iter().find_map(|phase| {
                phase
                    .physical_ranges
                    .iter()
                    .any(|&[offset, requested, returned]| {
                        offset == 512
                            && requested == root_ministream_bytes
                            && returned == root_ministream_bytes
                    })
                    .then_some(phase.logical_read_bytes)
            }));
            output_sha256.push(hashes);
            returned_payload_bytes.push(
                outputs
                    .iter()
                    .map(|output| u64::try_from(output.len()))
                    .collect::<Result<Vec<_>, _>>()?,
            );
            simulations.push(CfbOpenStreamSimulationSample {
                open: open_phase,
                aggregate: aggregate_phase,
                per_operation,
            });
        }
    }
    let expected_payload_sha256 = expected_payload_sha256
        .ok_or("simulated CFB open_stream produced no expected payload hash")?;
    let cache_state_diagnostic = match operation {
        CfbOpenStreamOperation::OneShot => {
            "private MiniFAT cache state is not public; one-shot source counters distinguish a candidate direct target read from baseline root materialization"
        },
        CfbOpenStreamOperation::Repeat | CfbOpenStreamOperation::Repeat8 => {
            "private MiniFAT cache state is not public; per-invocation source counters distinguish candidate direct-then-root materialization from baseline root materialization, and later zero-read phases are inferred cache hits"
        },
        CfbOpenStreamOperation::DifferentSid => {
            "private MiniFAT cache state is not public; the A-B-A source vector distinguishes root-only control from direct-target then root-cache takeover, while preserving sibling correctness"
        },
        CfbOpenStreamOperation::Bulk => {
            "private MiniFAT cache state is not public; the public bulk-read source vector distinguishes root-only control from direct-target plus root-cache materialization"
        },
        CfbOpenStreamOperation::Concurrent => {
            "private MiniFAT cache state is not public; a harness-only overlap gate makes two same-target callers deterministic while source counters distinguish root-only control from direct-target plus root-cache takeover"
        },
    };
    let source = SourceSummary {
        cfb_open_stream: Some(CfbOpenStreamEvidence {
            timing_scope: "fresh validated open plus bounded open_stream operation; every simulated source request pays the configured deterministic delay; snapshots, hashes, and refusal checks are excluded from elapsed_ns",
            sink: "none",
            implementation,
            operation: operation.name(),
            invocation_count,
            invocation_stream_names: cfb_open_stream_names(corpus, operation),
            requested_stream_count: invocation_count,
            shape: corpus.manifest.shape,
            sibling_count: corpus.manifest.entry_count,
            sector_size,
            mini_sector_size: 64,
            target_stream_name: corpus.target_name.clone(),
            target_start_sector,
            target_is_minifat,
            root_ministream_bytes,
            selected_target_kind: if corpus.target_payload.len() == 4095 {
                "minifat-4095-byte"
            } else {
                "minifat-36-byte"
            },
            cache_state_diagnostic,
            source_version_check,
            typed_refusal_verified: true,
            expected_payload_sha256,
            output_sha256,
            returned_payload_bytes,
            open_ns,
            operation_ns,
            per_operation_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_read_range_sizes,
            open_read_ranges,
            logical_read_calls,
            logical_read_bytes,
            logical_read_range_sizes,
            logical_read_ranges,
            per_operation_read_calls,
            per_operation_read_bytes,
            per_operation_read_range_sizes,
            per_operation_read_ranges,
            root_cache_read_bytes,
            expected_direct_physical_range,
            simulation: Some(CfbOpenStreamSimulationEvidence {
                implementation,
                config,
                samples: simulations,
            }),
        }),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn cfb_simulation_phase_allow_empty(
    snapshot: RangeSimulationSnapshot,
    config: RangeSimulationConfig,
) -> Result<CfbSelectiveSimulationPhase, Box<dyn Error>> {
    if snapshot.logical_read_calls == 0
        && snapshot.logical_read_bytes == 0
        && snapshot.physical_request_count == 0
        && snapshot.physical_request_bytes == 0
        && snapshot.physical_request_sizes.is_empty()
        && snapshot.physical_ranges.is_empty()
        && snapshot.physical_request_size_buckets == RequestSizeBuckets::default()
    {
        return Ok(CfbSelectiveSimulationPhase {
            logical_read_calls: 0,
            logical_read_bytes: 0,
            physical_request_count: 0,
            physical_request_bytes: 0,
            physical_request_sizes: Vec::new(),
            physical_ranges: Vec::new(),
            physical_request_size_buckets: RequestSizeBuckets::default(),
            simulated_service_floor_ns: 0,
        });
    }
    cfb_simulation_phase(snapshot, config)
}

fn cfb_simulation_phase(
    snapshot: RangeSimulationSnapshot,
    config: RangeSimulationConfig,
) -> Result<CfbSelectiveSimulationPhase, Box<dyn Error>> {
    if snapshot.logical_read_calls == 0
        || snapshot.logical_read_bytes == 0
        || snapshot.physical_request_count == 0
        || snapshot.physical_request_bytes == 0
    {
        return Err("simulated CFB selective phase performed no source I/O".into());
    }
    if snapshot.logical_read_bytes != snapshot.physical_request_bytes {
        return Err("simulated CFB logical and physical bytes differ".into());
    }
    let max_physical_range_bytes = u64::try_from(config.max_physical_range_bytes)?;
    if snapshot.physical_request_count != u64::try_from(snapshot.physical_request_sizes.len())?
        || snapshot
            .physical_request_sizes
            .iter()
            .any(|&bytes| bytes == 0 || bytes > max_physical_range_bytes)
        || snapshot.physical_request_count != u64::try_from(snapshot.physical_ranges.len())?
        || snapshot
            .physical_ranges
            .iter()
            .any(|&[_offset, requested, returned]| {
                requested == 0 || requested > max_physical_range_bytes || returned > requested
            })
    {
        return Err("simulated CFB physical request distribution is invalid".into());
    }
    let simulated_service_floor_ns = simulated_service_floor_ns(&snapshot, config)?;
    Ok(CfbSelectiveSimulationPhase {
        logical_read_calls: snapshot.logical_read_calls,
        logical_read_bytes: snapshot.logical_read_bytes,
        physical_request_count: snapshot.physical_request_count,
        physical_request_bytes: snapshot.physical_request_bytes,
        physical_request_sizes: snapshot.physical_request_sizes,
        physical_ranges: snapshot.physical_ranges,
        physical_request_size_buckets: snapshot.physical_request_size_buckets,
        simulated_service_floor_ns,
    })
}

fn combine_range_simulation_snapshots(
    open: &RangeSimulationSnapshot,
    read: &RangeSimulationSnapshot,
) -> Result<RangeSimulationSnapshot, Box<dyn Error>> {
    let capacity = open
        .physical_request_sizes
        .len()
        .checked_add(read.physical_request_sizes.len())
        .ok_or("simulated CFB request-size vector overflows usize")?;
    let mut physical_request_sizes = Vec::with_capacity(capacity);
    physical_request_sizes.extend_from_slice(&open.physical_request_sizes);
    physical_request_sizes.extend_from_slice(&read.physical_request_sizes);
    physical_request_sizes.sort_unstable();
    let mut physical_ranges = Vec::with_capacity(
        open.physical_ranges
            .len()
            .checked_add(read.physical_ranges.len())
            .ok_or("simulated CFB physical-range vector overflows usize")?,
    );
    physical_ranges.extend_from_slice(&open.physical_ranges);
    physical_ranges.extend_from_slice(&read.physical_ranges);
    Ok(RangeSimulationSnapshot {
        logical_read_calls: open
            .logical_read_calls
            .checked_add(read.logical_read_calls)
            .ok_or("simulated CFB logical request count overflows u64")?,
        logical_read_bytes: open
            .logical_read_bytes
            .checked_add(read.logical_read_bytes)
            .ok_or("simulated CFB logical byte count overflows u64")?,
        physical_request_count: open
            .physical_request_count
            .checked_add(read.physical_request_count)
            .ok_or("simulated CFB physical request count overflows u64")?,
        physical_request_bytes: open
            .physical_request_bytes
            .checked_add(read.physical_request_bytes)
            .ok_or("simulated CFB physical byte count overflows u64")?,
        physical_request_sizes,
        physical_ranges,
        physical_request_size_buckets: RequestSizeBuckets {
            bytes_1_to_512: open
                .physical_request_size_buckets
                .bytes_1_to_512
                .checked_add(read.physical_request_size_buckets.bytes_1_to_512)
                .ok_or("simulated CFB request bucket overflows u64")?,
            bytes_513_to_4096: open
                .physical_request_size_buckets
                .bytes_513_to_4096
                .checked_add(read.physical_request_size_buckets.bytes_513_to_4096)
                .ok_or("simulated CFB request bucket overflows u64")?,
            bytes_4097_to_16384: open
                .physical_request_size_buckets
                .bytes_4097_to_16384
                .checked_add(read.physical_request_size_buckets.bytes_4097_to_16384)
                .ok_or("simulated CFB request bucket overflows u64")?,
            bytes_16385_to_65536: open
                .physical_request_size_buckets
                .bytes_16385_to_65536
                .checked_add(read.physical_request_size_buckets.bytes_16385_to_65536)
                .ok_or("simulated CFB request bucket overflows u64")?,
            bytes_over_65536: open
                .physical_request_size_buckets
                .bytes_over_65536
                .checked_add(read.physical_request_size_buckets.bytes_over_65536)
                .ok_or("simulated CFB request bucket overflows u64")?,
        },
    })
}

fn run_cfb_selective_simulated_read(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
    config: RangeSimulationConfig,
) -> Result<CaseResult, Box<dyn Error>> {
    if !case.is_cfb_selective_simulated() {
        return Err("non-simulated CFB case reached simulated selective runner".into());
    }
    if config.max_physical_range_bytes == 0 {
        return Err("range simulator maximum physical request must be non-zero".into());
    }
    if config.bandwidth_bytes_per_second == 0 {
        return Err("range simulator bandwidth must be non-zero".into());
    }
    let shared = case.cfb_selective_shared();
    let implementation = if shared {
        "shared-positional-simulated-read-at"
    } else {
        "legacy-cursor-bounded-delayed-read"
    };
    let mut elapsed = Vec::with_capacity(samples);
    let mut open_ns = Vec::with_capacity(samples);
    let mut read_ns = Vec::with_capacity(samples);
    let mut total_ns = Vec::with_capacity(samples);
    let mut open_read_calls = Vec::with_capacity(samples);
    let mut open_read_bytes = Vec::with_capacity(samples);
    let mut open_range_sizes = Vec::with_capacity(samples);
    let mut read_calls = Vec::with_capacity(samples);
    let mut read_bytes = Vec::with_capacity(samples);
    let mut read_range_sizes = Vec::with_capacity(samples);
    let mut returned_payload_bytes = Vec::with_capacity(samples);
    let mut simulation_open = Vec::with_capacity(samples);
    let mut simulation_read = Vec::with_capacity(samples);
    let mut simulation_total = Vec::with_capacity(samples);
    let mut selected_hash = None;
    let limits = cfb_shared_limits(corpus)?;
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let bytes = Arc::new(corpus.archive.clone());
        let metrics = Arc::new(SimulatedRangeMetrics::default());
        let shared_source = shared.then(|| {
            Arc::new(SimulatedRangeSource {
                backing: Arc::new(InstrumentedSource::new((*bytes).clone(), Vec::new())),
                config,
                metrics: Arc::clone(&metrics),
            })
        });
        let legacy_cursor = (!shared)
            .then(|| SimulatedCursor::new(Arc::clone(&bytes), config, Arc::clone(&metrics)));
        let open_started = Instant::now();
        let selected = if shared {
            let source = shared_source.ok_or("simulated shared CFB source is absent")?;
            let ole = SharedOleFile::open_with_limits(source.clone(), limits)?;
            let open_duration = open_started.elapsed();
            let open_snapshot = source.snapshot()?;
            metrics.reset()?;
            let read_started = Instant::now();
            let path = [corpus.target_name.as_str()];
            let mut payload = Vec::new();
            payload.try_reserve_exact(corpus.target_payload.len())?;
            payload.resize(corpus.target_payload.len(), 0);
            ole.read_stream_range(&path, 0, &mut payload)?;
            let read_duration = read_started.elapsed();
            (payload, open_duration, read_duration, open_snapshot)
        } else {
            let cursor = legacy_cursor.ok_or("simulated legacy CFB cursor is absent")?;
            let mut ole = OleFile::open(cursor)?;
            let open_duration = open_started.elapsed();
            let open_snapshot = metrics.snapshot()?;
            metrics.reset()?;
            let read_started = Instant::now();
            let path = [corpus.target_name.as_str()];
            let payload = ole.open_stream(&path)?;
            let read_duration = read_started.elapsed();
            (payload, open_duration, read_duration, open_snapshot)
        };
        let (payload, open_duration, read_duration, open_snapshot) = selected;
        let total_duration = open_duration
            .checked_add(read_duration)
            .ok_or("simulated CFB combined duration overflows")?;
        let read_snapshot = metrics.snapshot()?;
        if payload != corpus.target_payload {
            return Err(
                "simulated CFB selective read differs from deterministic target payload".into(),
            );
        }
        let total_snapshot = combine_range_simulation_snapshots(&open_snapshot, &read_snapshot)?;
        let hash = sha256_hex(&payload);
        if let Some(expected) = selected_hash.as_deref() {
            if expected != hash {
                return Err("simulated CFB selective payload hash changed across samples".into());
            }
        } else {
            selected_hash = Some(hash);
        }
        let open_phase = cfb_simulation_phase(open_snapshot, config)?;
        let read_phase = cfb_simulation_phase(read_snapshot, config)?;
        let total_phase = cfb_simulation_phase(total_snapshot, config)?;
        std::hint::black_box(&payload);
        if iteration >= warmup_iterations {
            let open_duration = elapsed_ns(open_duration)?;
            let read_duration = elapsed_ns(read_duration)?;
            let total_duration = elapsed_ns(total_duration)?;
            elapsed.push(total_duration);
            open_ns.push(open_duration);
            read_ns.push(read_duration);
            total_ns.push(total_duration);
            open_read_calls.push(open_phase.logical_read_calls);
            open_read_bytes.push(open_phase.logical_read_bytes);
            open_range_sizes.push(open_phase.physical_request_sizes.clone());
            read_calls.push(read_phase.logical_read_calls);
            read_bytes.push(read_phase.logical_read_bytes);
            read_range_sizes.push(read_phase.physical_request_sizes.clone());
            returned_payload_bytes.push(u64::try_from(payload.len())?);
            simulation_open.push(open_phase);
            simulation_read.push(read_phase);
            simulation_total.push(total_phase);
        }
    }
    let selected_payload_sha256 =
        selected_hash.ok_or("simulated CFB selective read produced no hash")?;
    let evidence = CfbSelectiveEvidence {
        timing_scope: "open and selected read are separate stages and total is their checked sum; every bounded source request pays the configured deterministic delay; adapter construction, corpus construction, validation, evidence snapshots, and hash generation are excluded",
        sink: "none",
        selected_target_kind: match corpus.manifest.target_payload_bytes {
            36 => Some("minifat-36-byte"),
            4095 => Some("minifat-4095-byte"),
            bytes if bytes == 4 * 1024 * 1024 => Some("fat-4mib"),
            _ => None,
        }
        .ok_or("simulated CFB selective target has unknown size")?,
        legacy_or_positional: CfbSelectiveImplementationEvidence {
            implementation,
            open_ns,
            read_ns,
            total_ns,
            open_read_calls,
            open_read_bytes,
            open_range_sizes,
            read_calls,
            read_bytes,
            read_range_sizes,
            returned_payload_bytes,
            selected_payload_sha256,
        },
        simulation: Some(CfbSelectiveSimulationEvidence {
            implementation,
            config,
            open: simulation_open,
            read: simulation_read,
            total: simulation_total,
        }),
    };
    let source = SourceSummary {
        cfb_selective: Some(evidence),
        ..SourceSummary::default()
    };
    Ok(result_with_source(case, corpus, elapsed, source))
}

fn corpus_payload_kind(corpus: &Corpus) -> Result<PayloadKind, Box<dyn Error>> {
    match corpus.manifest.payload_kind {
        "compressible" => Ok(PayloadKind::Compressible),
        "incompressible" => Ok(PayloadKind::Incompressible),
        _ => Err("container corpus has an unknown payload kind".into()),
    }
}

fn run_cfb_shared_concurrent_reads(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let limits = cfb_shared_limits(corpus)?;
    let first_name = cfb_entry_name(0);
    let first_expected =
        payload_bytes(corpus_payload_kind(corpus)?, 0, corpus.manifest.entry_bytes);
    let mut elapsed = Vec::with_capacity(samples);
    let mut source_summary = SourceSummary::default();
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = cfb_instrumented_source(corpus);
        let ole = SharedOleFile::open_with_limits(source.clone(), limits)?;
        source.reset();
        let start = Arc::new(Barrier::new(3));
        let started = Instant::now();
        let (first, second) = std::thread::scope(|scope| {
            let first_start = Arc::clone(&start);
            let first_ole = &ole;
            let first_name = first_name.as_str();
            let first_task = scope.spawn(move || {
                first_start.wait();
                first_ole.open_stream(&[first_name])
            });
            let second_start = Arc::clone(&start);
            let second_ole = &ole;
            let second_name = corpus.target_name.as_str();
            let second_task = scope.spawn(move || {
                second_start.wait();
                second_ole.open_stream(&[second_name])
            });
            start.wait();
            (first_task.join(), second_task.join())
        });
        let first = first.map_err(|_panic| "first shared CFB worker panicked")??;
        let second = second.map_err(|_panic| "second shared CFB worker panicked")??;
        let duration = started.elapsed();
        if first != first_expected || second != corpus.target_payload {
            return Err("concurrent shared CFB reads returned unexpected stream bytes".into());
        }
        std::hint::black_box((&first, &second));
        let metrics = source.snapshot();
        if metrics.read_calls == 0 || metrics.read_bytes == 0 {
            return Err("concurrent shared CFB reads performed no positional source reads".into());
        }
        if iteration >= warmup_iterations {
            source_summary.record(metrics);
        }
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result_with_source(
        Case::CfbSharedConcurrentReads,
        corpus,
        elapsed,
        source_summary,
    ))
}

fn run_cfb_create_stream(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
    owned: bool,
) -> Result<CaseResult, Box<dyn Error>> {
    let case = if owned {
        Case::CfbCreateStreamOwned
    } else {
        Case::CfbCreateStreamBorrowed
    };
    let path = [corpus.target_name.as_str()];
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let prepared = std::hint::black_box(corpus.target_payload.clone());
        let mut writer = OleWriter::new();
        let started = Instant::now();
        if owned {
            writer.create_stream_owned(&path, prepared)?;
        } else {
            writer.create_stream(&path, &prepared)?;
        }
        let duration = started.elapsed();
        std::hint::black_box(&writer);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result(case, corpus, elapsed, None))
}

fn run_ole_common_one_edit_save(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let corpus = build_ole_common_corpus(corpus)?;
    let expected = ole_common_changed_output(&corpus)?;
    let path = vec![corpus.target_name.clone()];
    let targets = OleObjectTargets::default();
    let limits = ole_common_limits(&corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut final_output = None;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = corpus.archive.clone();
        let replacement = OLE_COMMON_REPLACEMENT.to_vec();
        let targets = targets.clone();
        let started = Instant::now();
        let mut editor = OleObjectEditor::open(source, targets, limits)?;
        editor.put_stream(&path, replacement)?;
        let output = editor.finish()?;
        let duration = started.elapsed();
        if output != expected {
            return Err("OLE common edit/save output is not deterministic".into());
        }
        std::hint::black_box(&output);
        final_output = Some(output);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    verify_ole_common_changed_output(
        &corpus,
        final_output
            .as_deref()
            .ok_or("OLE common edit/save produced no final output")?,
    )?;
    Ok(result(Case::OleCommonOneEditSave, &corpus, elapsed, None))
}

fn run_ole_common_open(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let corpus = build_ole_common_corpus(corpus)?;
    let targets = OleObjectTargets::default();
    let limits = ole_common_limits(&corpus)?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut final_editor = None;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let source = corpus.archive.clone();
        let targets = targets.clone();
        let started = Instant::now();
        let editor = OleObjectEditor::open(source, targets, limits)?;
        let duration = started.elapsed();
        if editor.is_changed() {
            return Err("fresh OLE common editor unexpectedly reports a change".into());
        }
        std::hint::black_box(&editor);
        final_editor = Some(editor);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    verify_ole_common_source_editor(
        &corpus,
        final_editor
            .as_ref()
            .ok_or("OLE common open produced no final editor")?,
    )?;
    Ok(result(Case::OleCommonOpen, &corpus, elapsed, None))
}

fn run_ole_common_put_stream_publish(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let corpus = build_ole_common_corpus(corpus)?;
    let expected = ole_common_changed_output(&corpus)?;
    let path = vec![corpus.target_name.clone()];
    let opened = OleObjectEditor::open(
        corpus.archive.clone(),
        OleObjectTargets::default(),
        ole_common_limits(&corpus)?,
    )?;
    let source = opened.snapshot();
    let mut elapsed = Vec::with_capacity(samples);
    let mut final_editor = None;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let mut editor = source.edit();
        let replacement = OLE_COMMON_REPLACEMENT.to_vec();
        let started = Instant::now();
        editor.put_stream(&path, replacement)?;
        let duration = started.elapsed();
        if !editor.is_changed()
            || editor
                .stream(&path)
                .ok_or("OLE common target disappeared")?
                != OLE_COMMON_REPLACEMENT
        {
            return Err("OLE common candidate publication did not retain the replacement".into());
        }
        std::hint::black_box(&editor);
        final_editor = Some(editor);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let output = final_editor
        .ok_or("OLE common candidate publication produced no final editor")?
        .finish()?;
    if output != expected {
        return Err("OLE common candidate publication changed deterministic output".into());
    }
    verify_ole_common_changed_output(&corpus, &output)?;
    Ok(result(
        Case::OleCommonPutStreamPublish,
        &corpus,
        elapsed,
        None,
    ))
}

fn run_ole_common_finish_render(
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let corpus = build_ole_common_corpus(corpus)?;
    let expected = ole_common_changed_output(&corpus)?;
    let path = vec![corpus.target_name.clone()];
    let mut editor = OleObjectEditor::open(
        corpus.archive.clone(),
        OleObjectTargets::default(),
        ole_common_limits(&corpus)?,
    )?;
    editor.put_stream(&path, OLE_COMMON_REPLACEMENT.to_vec())?;
    let changed = editor.snapshot();
    let mut elapsed = Vec::with_capacity(samples);
    let mut final_output = None;

    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let editor = changed.edit();
        let started = Instant::now();
        let output = editor.finish()?;
        let duration = started.elapsed();
        std::hint::black_box(&output);
        final_output = Some(output);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }

    let output = final_output
        .as_deref()
        .ok_or("OLE common changed finish produced no final output")?;
    if output != expected {
        return Err("OLE common changed finish changed deterministic output".into());
    }
    verify_ole_common_changed_output(&corpus, output)?;
    Ok(result(Case::OleCommonFinishRender, &corpus, elapsed, None))
}

fn verify_ole_common_source_editor(
    corpus: &Corpus,
    editor: &OleObjectEditor,
) -> Result<(), Box<dyn Error>> {
    let kind = corpus_payload_kind(corpus)?;
    let unchanged_stream_count = corpus
        .manifest
        .entry_count
        .checked_sub(1)
        .ok_or("OLE common corpus has no edit target")?;
    for index in 0..unchanged_stream_count {
        let name = cfb_entry_name(index);
        let path = [name];
        if editor
            .stream(&path)
            .ok_or("OLE common source stream disappeared")?
            != payload_bytes(kind, index, corpus.manifest.entry_bytes)
        {
            return Err("OLE common open changed an opaque source stream".into());
        }
    }
    let target = [corpus.target_name.clone()];
    if editor
        .stream(&target)
        .ok_or("OLE common source target disappeared")?
        != OLE_COMMON_ORIGINAL
    {
        return Err("OLE common open changed its source target".into());
    }
    Ok(())
}

fn ole_common_changed_output(corpus: &Corpus) -> Result<Vec<u8>, Box<dyn Error>> {
    let path = vec![corpus.target_name.clone()];
    let mut editor = OleObjectEditor::open(
        corpus.archive.clone(),
        OleObjectTargets::default(),
        ole_common_limits(corpus)?,
    )?;
    editor.put_stream(&path, OLE_COMMON_REPLACEMENT.to_vec())?;
    let output = editor.finish()?;
    verify_ole_common_changed_output(corpus, &output)?;
    Ok(output)
}

fn ole_common_limits(corpus: &Corpus) -> Result<OleObjectLimits, Box<dyn Error>> {
    Ok(OleObjectLimits {
        max_objects: 1,
        max_storage_depth: 1,
        max_streams_per_object: 1,
        max_streams: corpus.manifest.entry_count,
        max_stream_size: u64::try_from(
            corpus
                .manifest
                .entry_bytes
                .max(OLE_COMMON_ORIGINAL.len())
                .max(OLE_COMMON_REPLACEMENT.len()),
        )?,
        max_object_size: 1,
        max_total_size: u64::try_from(corpus.manifest.uncompressed_payload_bytes)?,
    })
}

fn verify_ole_common_changed_output(corpus: &Corpus, output: &[u8]) -> Result<(), Box<dyn Error>> {
    let kind = corpus_payload_kind(corpus)?;
    let mut ole = OleFile::open(Cursor::new(output))?;
    let streams = ole.list_streams();
    if streams.len() != corpus.manifest.entry_count {
        return Err("OLE common output stream count differs from its corpus".into());
    }
    let unchanged_stream_count = corpus
        .manifest
        .entry_count
        .checked_sub(1)
        .ok_or("OLE common corpus has no edit target")?;
    for index in 0..unchanged_stream_count {
        let name = cfb_entry_name(index);
        let actual = ole.open_stream(&[name.as_str()])?;
        if actual != payload_bytes(kind, index, corpus.manifest.entry_bytes) {
            return Err("OLE common edit changed an untouched stream".into());
        }
    }
    if ole.open_stream(&[corpus.target_name.as_str()])? != OLE_COMMON_REPLACEMENT {
        return Err("OLE common changed stream differs from its replacement".into());
    }
    Ok(())
}

fn streaming_context(
    memory_bytes: u64,
    input_bytes: u64,
    output_bytes: u64,
    objects: u64,
    work: u64,
) -> Result<ExecutionContext, Box<dyn Error>> {
    let one = NonZeroUsize::new(1).ok_or("streaming worker count must be nonzero")?;
    let in_flight = NonZeroU64::new(memory_bytes.max(1))
        .ok_or("streaming in-flight byte limit must be nonzero")?;
    let execution_limits = ExecutionLimits::new(one, one, in_flight, 0)?;
    let (_cancellation, token) = CancellationSource::pair();
    Ok(ExecutionContext::new(
        Budget::root(
            "litchi-perf-streaming-create",
            Limits::new(memory_bytes, input_bytes, output_bytes, objects, 32, work),
        ),
        token,
        execution_limits,
    ))
}

fn streaming_xlsx_text(row: usize) -> String {
    format!("litchi-perf-streaming-xlsx-row-{row:06}-café-<&>")
}

fn streaming_rtf_text(paragraph: usize) -> String {
    format!("litchi-perf-streaming-rtf-paragraph-{paragraph:06}-café-\\{{}}")
}

fn write_streaming_xlsx<W: Write>(
    sink: W,
    shape: SemanticShape,
) -> Result<(W, StreamingMetrics), Box<dyn Error>> {
    let rows = u64::try_from(shape.streaming_units())?;
    let cells = rows
        .checked_mul(4)
        .ok_or("streaming XLSX cell count overflows")?;
    let max_sheet_xml_bytes = rows
        .checked_mul(512)
        .and_then(|value| value.checked_add(4 * 1024))
        .ok_or("streaming XLSX worksheet ceiling overflows")?;
    let max_output_bytes = max_sheet_xml_bytes
        .checked_mul(2)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("streaming XLSX output ceiling overflows")?;
    let objects = rows
        .checked_add(cells)
        .and_then(|value| value.checked_add(16))
        .ok_or("streaming XLSX object budget overflows")?;
    let work = objects
        .checked_mul(2)
        .ok_or("streaming XLSX work budget overflows")?;
    let limits = StreamingWorkbookLimits::new(
        u32::try_from(rows)?,
        cells,
        256,
        XLSX_STREAMING_ROW_BYTES,
        max_sheet_xml_bytes,
        max_output_bytes,
    );
    let context = streaming_context(XLSX_STREAMING_ROW_BYTES, 0, max_output_bytes, objects, work)?;
    let mut writer = StreamingWorkbookWriter::new(sink, context, limits)?;
    let mut input_bytes = 0u64;
    for row in 1..=shape.streaming_units() {
        let text = streaming_xlsx_text(row);
        let row_number = u32::try_from(row)?;
        input_bytes = input_bytes
            .checked_add(u64::try_from(text.len())?)
            .ok_or("streaming XLSX input byte count overflows")?;
        writer.write_row(
            row_number,
            [
                StreamingCell::new(1, StreamingCellValue::Number(f64::from(row_number))),
                StreamingCell::new(2, StreamingCellValue::Text(&text)),
                StreamingCell::new(3, StreamingCellValue::Bool(row % 2 == 0)),
                StreamingCell::new(4, StreamingCellValue::Blank),
            ],
        )?;
    }
    if writer.cell_count() != cells {
        return Err("streaming XLSX writer cell count differs from its shape".into());
    }
    let authored_part_bytes = writer
        .worksheet_xml_bytes()
        .checked_add(u64::try_from(b"</sheetData></worksheet>".len())?)
        .ok_or("streaming XLSX authored XML count overflows")?;
    let output = writer.finish()?;
    Ok((
        output,
        StreamingMetrics {
            rows,
            cells,
            paragraphs: 0,
            runs: 0,
            input_bytes,
            authored_part_bytes,
            retained_authoring_window_bytes: XLSX_STREAMING_ROW_BYTES,
        },
    ))
}

fn write_streaming_rtf<W: Write>(
    sink: W,
    shape: SemanticShape,
) -> Result<(W, StreamingMetrics), Box<dyn Error>> {
    let paragraphs = u64::try_from(shape.streaming_units())?;
    let runs = paragraphs;
    let input_bytes = (0..shape.streaming_units()).try_fold(
        0u64,
        |total, paragraph| -> Result<u64, Box<dyn Error>> {
            let text_bytes = u64::try_from(streaming_rtf_text(paragraph).len())?;
            Ok(total
                .checked_add(text_bytes)
                .ok_or("streaming RTF input byte count overflows")?)
        },
    )?;
    let max_output_bytes = input_bytes
        .checked_mul(8)
        .and_then(|value| value.checked_add(64 * 1024))
        .ok_or("streaming RTF output ceiling overflows")?;
    let objects = paragraphs
        .checked_add(runs)
        .and_then(|value| value.checked_add(8))
        .ok_or("streaming RTF object budget overflows")?;
    let work = input_bytes
        .checked_mul(2)
        .and_then(|value| value.checked_add(objects))
        .ok_or("streaming RTF work budget overflows")?;
    let context = streaming_context(
        RTF_STREAMING_SCRATCH_BYTES,
        input_bytes,
        max_output_bytes,
        objects,
        work,
    )?;
    let limits = litchi_rtf::write::StreamingRtfLimits::new(
        input_bytes,
        max_output_bytes,
        paragraphs,
        runs,
        RTF_STREAMING_SCRATCH_BYTES,
    );
    let mut writer = litchi_rtf::write::StreamingRtfWriter::new(sink, context, limits)?;
    for paragraph in 0..shape.streaming_units() {
        let text = streaming_rtf_text(paragraph);
        writer.start_paragraph()?;
        writer.start_run()?;
        writer.write_all(text.as_bytes())?;
        writer.finish_run()?;
        writer.finish_paragraph()?;
    }
    if writer.paragraph_count() != paragraphs
        || writer.run_count() != runs
        || writer.input_bytes() != input_bytes
    {
        return Err("streaming RTF writer counters differ from its shape".into());
    }
    let authored_part_bytes = writer
        .output_bytes()
        .checked_add(1)
        .ok_or("streaming RTF authored byte count overflows")?;
    let output = writer.finish()?;
    Ok((
        output,
        StreamingMetrics {
            rows: 0,
            cells: 0,
            paragraphs,
            runs,
            input_bytes,
            authored_part_bytes,
            retained_authoring_window_bytes: RTF_STREAMING_SCRATCH_BYTES,
        },
    ))
}

fn verify_streaming_xlsx(bytes: Vec<u8>, shape: SemanticShape) -> Result<(), Box<dyn Error>> {
    let workbook = Workbook::from_bytes(bytes)?;
    if workbook.len() != 1 {
        return Err("streaming XLSX workbook does not contain exactly one sheet".into());
    }
    let sheet = workbook
        .sheet("Sheet1")?
        .ok_or("streaming XLSX Sheet1 is missing")?;
    if sheet.rows()?.count() != shape.streaming_units() {
        return Err("streaming XLSX explicit row count differs from its shape".into());
    }
    let area = format!("A1:D{}", shape.streaming_units());
    let mut visited = 0usize;
    for (address, cell) in sheet.cells(area.as_str())? {
        let row = usize::try_from(address.row().get())? + 1;
        let column = address.column().get();
        let matches = match (column, cell) {
            (0, XlsxCell::Value(XlsxValue::Number(value))) => value.as_f64() == Some(row as f64),
            (1, XlsxCell::Value(XlsxValue::Text(value))) => {
                value.as_str() == streaming_xlsx_text(row)
            },
            (2, XlsxCell::Value(XlsxValue::Bool(value))) => *value == (row % 2 == 0),
            (3, XlsxCell::Empty) => true,
            _ => false,
        };
        if !matches {
            return Err(
                format!("streaming XLSX cell differs at row {row}, column {column}").into(),
            );
        }
        visited = visited
            .checked_add(1)
            .ok_or("streaming XLSX visited-cell count overflows")?;
    }
    if visited != shape.streaming_units().saturating_mul(4) {
        return Err("streaming XLSX stored-cell count differs from its shape".into());
    }
    Ok(())
}

fn verify_streaming_rtf(bytes: &[u8], shape: SemanticShape) -> Result<(), Box<dyn Error>> {
    let document = litchi_rtf::Document::from_bytes(bytes)?;
    if document.paragraph_count() != shape.streaming_units() {
        return Err("streaming RTF paragraph count differs from its shape".into());
    }
    for (index, paragraph) in document.body().paragraphs().enumerate() {
        let expected = streaming_rtf_text(index);
        let mut runs = paragraph.runs();
        if runs.next().map(|run| run.text()) != Some(expected.as_str()) || runs.next().is_some() {
            return Err(format!("streaming RTF paragraph {index} differs from its shape").into());
        }
    }
    Ok(())
}

fn build_streaming_corpus(
    case: Case,
    shape: SemanticShape,
) -> Result<StreamingCorpus, Box<dyn Error>> {
    let (artifact, mut metrics, generator, package_format, compression, target_entry, members) =
        match case {
            Case::XlsxStreamingCreate => {
                let (artifact, metrics) = write_streaming_xlsx(Vec::new(), shape)?;
                verify_streaming_xlsx(artifact.clone(), shape)?;
                (
                    artifact,
                    metrics,
                    XLSX_STREAMING_CORPUS_GENERATOR,
                    "xlsx",
                    "deflate",
                    "xl/worksheets/sheet1.xml".to_string(),
                    6,
                )
            },
            Case::RtfStreamingCreate => {
                let (artifact, metrics) = write_streaming_rtf(Vec::new(), shape)?;
                verify_streaming_rtf(&artifact, shape)?;
                (
                    artifact,
                    metrics,
                    RTF_STREAMING_CORPUS_GENERATOR,
                    "rtf",
                    "none",
                    "document".to_string(),
                    0,
                )
            },
            _ => return Err("non-streaming case requested a streaming corpus".into()),
        };
    let target = if case == Case::XlsxStreamingCreate {
        ArchiveReader::new(&artifact)?.read(&target_entry)?
    } else {
        artifact.clone()
    };
    metrics.authored_part_bytes = u64::try_from(target.len())?;
    let archive_sha256 = sha256_hex(&artifact);
    let target_payload_sha256 = sha256_hex(&target);
    let manifest = CorpusManifest {
        name: format!("{package_format}-streaming-create-{}", shape.name()),
        generator,
        package_format,
        shape: shape.name(),
        payload_kind: "deterministic-scalar-text",
        compression,
        entry_count: usize::try_from(metrics.cells.max(metrics.runs))?,
        archive_member_count: members,
        entry_bytes: 0,
        uncompressed_payload_bytes: usize::try_from(metrics.input_bytes)?,
        archive_bytes: artifact.len(),
        archive_sha256,
        target_entry,
        target_payload_bytes: target.len(),
        target_payload_sha256,
        rtf_variant: (case == Case::RtfStreamingCreate).then_some("plain-streaming"),
        xlsx: (case == Case::XlsxStreamingCreate).then_some(XlsxManifest {
            sheet_count: 1,
            rows_per_sheet: shape.streaming_units(),
            columns_per_sheet: 4,
            one_percent_update_count: 0,
            source_members: XlsxSourceMembersManifest {
                workbook: "xl/workbook.xml".to_string(),
                worksheets: vec!["xl/worksheets/sheet1.xml".to_string()],
                shared_strings: None,
                styles: Some("xl/styles.xml".to_string()),
            },
        }),
    };
    drop(target);
    drop(artifact);
    Ok(StreamingCorpus {
        manifest,
        shape,
        metrics,
    })
}

fn run_streaming_creation(
    case: Case,
    corpus: &StreamingCorpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let maximum = u64::try_from(corpus.manifest.archive_bytes)?
        .checked_add(64 * 1024)
        .ok_or("streaming sink ceiling overflows")?;
    let mut elapsed = Vec::with_capacity(samples);
    let mut summaries = Vec::with_capacity(samples);
    let mut digests = Vec::with_capacity(samples);
    let collect_resource_metrics = case == Case::RtfStreamingCreate;
    let mut resource_observations = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let sink = HashingDiscardSink::new(maximum, corpus.metrics.retained_authoring_window_bytes);
        let process_before = if collect_resource_metrics {
            process_metrics::Snapshot::read().ok()
        } else {
            None
        };
        let allocation_region = collect_resource_metrics.then(allocation_metrics::begin);
        let started = Instant::now();
        let (sink, metrics) = match case {
            Case::XlsxStreamingCreate => write_streaming_xlsx(sink, corpus.shape)?,
            Case::RtfStreamingCreate => write_streaming_rtf(sink, corpus.shape)?,
            _ => return Err("non-streaming case reached streaming runner".into()),
        };
        let duration = started.elapsed();
        let allocation_metrics = allocation_region.and_then(|region| region.finish());
        let process_after = if collect_resource_metrics {
            process_metrics::Snapshot::read().ok()
        } else {
            None
        };
        let process_metrics = process_before
            .zip(process_after)
            .map(|(before, after)| after.delta(before));
        let (mut summary, digest) = sink.finish();
        if metrics != corpus.metrics
            || summary.accepted_bytes != u64::try_from(corpus.manifest.archive_bytes)?
            || digest != corpus.manifest.archive_sha256
        {
            return Err(
                "streaming creation counters or digest differ from untimed artifact".into(),
            );
        }
        summary.rows = (metrics.rows != 0).then_some(metrics.rows);
        summary.cells = (metrics.cells != 0).then_some(metrics.cells);
        summary.paragraphs = (metrics.paragraphs != 0).then_some(metrics.paragraphs);
        summary.runs = (metrics.runs != 0).then_some(metrics.runs);
        summary.input_bytes = Some(metrics.input_bytes);
        summary.authored_part_bytes = Some(metrics.authored_part_bytes);
        if iteration >= warmup_iterations {
            summaries.push(summary);
            digests.push(digest);
            if collect_resource_metrics {
                resource_observations.push(operation_metrics::InProcessObservation {
                    elapsed_ns: elapsed_ns(duration)?,
                    process_metrics,
                    allocation_metrics,
                });
            }
        }
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    let sink = deterministic_sink_summary(&summaries, "streaming creation")?;
    if sink.retained_output_bytes != Some(0)
        || sink.retained_authoring_window_bytes
            != Some(corpus.metrics.retained_authoring_window_bytes)
    {
        return Err("streaming creation did not prove its fixed retained-window bound".into());
    }
    if digests
        .iter()
        .any(|digest| digest != &corpus.manifest.archive_sha256)
    {
        return Err("streaming creation output digest changed across samples".into());
    }
    let operation_metrics = if collect_resource_metrics {
        let sink_observation = operation_metrics::SinkObservation {
            accepted_bytes: sink.accepted_bytes,
            write_calls: sink.write_calls,
            largest_write: sink.largest_write,
            bytes_0: sink.write_size_buckets.bytes_0,
            bytes_1_to_512: sink.write_size_buckets.bytes_1_to_512,
            bytes_513_to_4096: sink.write_size_buckets.bytes_513_to_4096,
            bytes_4097_to_16384: sink.write_size_buckets.bytes_4097_to_16384,
            bytes_16385_to_65536: sink.write_size_buckets.bytes_16385_to_65536,
            bytes_over_65536: sink.write_size_buckets.bytes_over_65536,
        };
        Some(operation_metrics::from_in_process_observations(
            &resource_observations,
            sink_observation,
        )?)
    } else {
        None
    };
    Ok(CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: Some(sink),
        source: None,
        execution: None,
        output_sha256: Some(corpus.manifest.archive_sha256.clone()),
        operation_metrics,
    })
}

fn run_fresh_writer(
    case: Case,
    corpus: &Corpus,
    warmup_iterations: usize,
    samples: usize,
) -> Result<CaseResult, Box<dyn Error>> {
    let shape = match corpus.manifest.shape {
        "tiny" => WriterShape::Tiny,
        "large" => WriterShape::Large,
        "payload-heavy" => WriterShape::PayloadHeavy,
        _ => return Err("fresh writer corpus has an unknown writer shape".into()),
    };
    let mut elapsed = Vec::with_capacity(samples);
    for iteration in 0..iteration_count(warmup_iterations, samples)? {
        let started = Instant::now();
        let (output, entry_count, content_bytes) = match case {
            Case::DocFreshWriteTo => write_fresh_doc(shape)?,
            Case::XlsFreshWriteTo => write_fresh_xls(shape)?,
            Case::PptFreshWriteTo => write_fresh_ppt(shape)?,
            _ => return Err("non-writer case passed to fresh writer runner".into()),
        };
        let duration = started.elapsed();
        if entry_count != corpus.manifest.entry_count
            || content_bytes != corpus.manifest.uncompressed_payload_bytes
        {
            return Err(
                "fresh writer content differs from deterministic corpus specification".into(),
            );
        }
        if output != corpus.archive {
            return Err("fresh writer package differs from deterministic corpus output".into());
        }
        std::hint::black_box(&output);
        record_elapsed(&mut elapsed, iteration, warmup_iterations, duration)?;
    }
    Ok(result(case, corpus, elapsed, None))
}

fn result(case: Case, corpus: &Corpus, elapsed: Vec<u64>, sink: Option<SinkSummary>) -> CaseResult {
    CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink,
        source: None,
        execution: None,
        output_sha256: None,
        operation_metrics: None,
    }
}

fn result_with_source(
    case: Case,
    corpus: &Corpus,
    elapsed: Vec<u64>,
    source: SourceSummary,
) -> CaseResult {
    CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: None,
        source: Some(source),
        execution: None,
        output_sha256: None,
        operation_metrics: None,
    }
}

fn result_with_execution(
    case: Case,
    corpus: &Corpus,
    elapsed: Vec<u64>,
    execution: ExecutionSummary,
) -> CaseResult {
    CaseResult {
        case: case.name(),
        cache_state: None,
        corpus: corpus.manifest.clone(),
        elapsed_ns: statistics(elapsed),
        sink: None,
        source: None,
        execution: Some(execution),
        output_sha256: None,
        operation_metrics: None,
    }
}

fn elapsed_ns(duration: Duration) -> Result<u64, Box<dyn Error>> {
    u64::try_from(duration.as_nanos())
        .map_err(|_error| "duration does not fit u64 nanoseconds".into())
}

fn iteration_count(warmup_iterations: usize, samples: usize) -> Result<usize, Box<dyn Error>> {
    warmup_iterations
        .checked_add(samples)
        .ok_or_else(|| "warm-up and sample iteration count overflows usize".into())
}

fn record_elapsed(
    elapsed: &mut Vec<u64>,
    iteration: usize,
    warmup_iterations: usize,
    duration: Duration,
) -> Result<(), Box<dyn Error>> {
    if iteration >= warmup_iterations {
        elapsed.push(elapsed_ns(duration)?);
    }
    Ok(())
}

fn statistics(samples: Vec<u64>) -> Statistics {
    let mut ordered = samples.into_iter().enumerate().collect::<Vec<_>>();
    ordered.sort_unstable_by_key(|&(index, value)| (value, index));
    let sample_order = ordered
        .iter()
        .map(|&(index, _value)| index)
        .collect::<Vec<_>>();
    let samples = ordered
        .iter()
        .map(|&(_index, value)| value)
        .collect::<Vec<_>>();
    let count = samples.len();
    let (mean, squared_deviation_sum) = samples.iter().enumerate().fold(
        (0.0, 0.0),
        |(mean, squared_deviation_sum), (index, value)| {
            let value = *value as f64;
            let next_count = (index + 1) as f64;
            let delta = value - mean;
            let next_mean = mean + delta / next_count;
            let next_sum = squared_deviation_sum + delta * (value - next_mean);
            (next_mean, next_sum)
        },
    );
    let standard_deviation = if count > 1 {
        (squared_deviation_sum / (count - 1) as f64).sqrt()
    } else {
        0.0
    };
    let margin = if count > 1 {
        student_t_critical_95(count - 1) * standard_deviation / (count as f64).sqrt()
    } else {
        0.0
    };

    Statistics {
        unit: "ns",
        sample_order,
        min: samples[0],
        p50: midpoint(samples[(count - 1) / 2], samples[count / 2]),
        p95: nearest_rank(&samples, 95),
        p99: nearest_rank(&samples, 99),
        max: samples[count - 1],
        mean,
        standard_deviation,
        confidence_interval_95: ConfidenceInterval {
            method: "two-sided Student's t interval for the mean",
            lower: (mean - margin).max(0.0),
            upper: mean + margin,
        },
        samples,
    }
}

fn midpoint(left: u64, right: u64) -> u64 {
    left / 2 + right / 2 + (left % 2 + right % 2) / 2
}

fn nearest_rank(samples: &[u64], percentile: usize) -> u64 {
    let index = percentile
        .saturating_mul(samples.len())
        .saturating_add(99)
        .saturating_div(100)
        .saturating_sub(1)
        .min(samples.len() - 1);
    samples[index]
}

fn student_t_critical_95(degrees_of_freedom: usize) -> f64 {
    const VALUES: [f64; 30] = [
        12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160,
        2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056,
        2.052, 2.048, 2.045, 2.042,
    ];
    match degrees_of_freedom {
        0 => 0.0,
        1..=30 => VALUES[degrees_of_freedom - 1],
        _ => {
            // Cornish-Fisher expansion of the two-sided 0.975 quantile.
            // The exact table above covers the small sample counts where the
            // correction is largest; this converges rapidly thereafter.
            const Z: f64 = 1.959_963_984_540_054;
            let degrees = degrees_of_freedom as f64;
            let z2 = Z * Z;
            let z3 = z2 * Z;
            let z5 = z3 * z2;
            let z7 = z5 * z2;
            Z + (z3 + Z) / (4.0 * degrees)
                + (5.0 * z5 + 16.0 * z3 + 3.0 * Z) / (96.0 * degrees * degrees)
                + (3.0 * z7 + 19.0 * z5 + 17.0 * z3 - 15.0 * Z)
                    / (384.0 * degrees * degrees * degrees)
        },
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    let mut output = String::with_capacity(digest.len() * 2);
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(output, "{byte:02x}");
    }
    output
}

fn executable_profile() -> &'static str {
    if cfg!(debug_assertions) {
        "debug"
    } else {
        "release"
    }
}

#[cfg(unix)]
fn executable_mode_bits(metadata: &fs::Metadata) -> Option<u32> {
    use std::os::unix::fs::PermissionsExt;

    Some(metadata.permissions().mode() & 0o7777)
}

#[cfg(not(unix))]
fn executable_mode_bits(_metadata: &fs::Metadata) -> Option<u32> {
    None
}

/// Capture the exact executable identity outside all benchmark timing.
///
/// This intentionally reads the current process executable only once, after
/// all measured cases have finished.  A missing/unreadable executable is an
/// error rather than an omitted identity: consumers must never mistake a
/// report with unknown executable provenance for a valid comparison.
pub fn current_executable_identity() -> io::Result<BinaryIdentity> {
    let path = std::env::current_exe()?.canonicalize()?;
    let mut file = File::open(&path)?;
    let metadata_before = file.metadata()?;
    if !metadata_before.is_file() {
        return Err(io::Error::other(format!(
            "current executable is not a regular file: {}",
            path.display()
        )));
    }
    let mut hasher = Sha256::new();
    let mut buffer = [0_u8; 64 * 1024];
    loop {
        let count = loop {
            match file.read(&mut buffer) {
                Ok(count) => break count,
                Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
                Err(error) => return Err(error.into()),
            }
        };
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
    }
    let metadata_after = file.metadata()?;
    let path_metadata = fs::metadata(&path)?;
    if metadata_identity(&metadata_before) != metadata_identity(&metadata_after)
        || metadata_before.len() != metadata_after.len()
        || metadata_identity(&metadata_before) != metadata_identity(&path_metadata)
        || metadata_before.len() != path_metadata.len()
    {
        return Err(io::Error::other(format!(
            "current executable changed while being read: before={} bytes, after={} bytes",
            metadata_before.len(),
            metadata_after.len()
        )));
    }
    let digest = hasher.finalize();
    let mut binary_sha256 = String::with_capacity(digest.len() * 2);
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(binary_sha256, "{byte:02x}");
    }
    let executable =
        executable_mode_bits(&metadata_before).map_or(true, |mode_bits| mode_bits & 0o111 != 0);
    Ok(BinaryIdentity {
        path: path.to_string_lossy().into_owned(),
        binary_sha256,
        binary_bytes: metadata_before.len(),
        mode_bits: executable_mode_bits(&metadata_before),
        executable,
        profile: executable_profile(),
    })
}

#[cfg(unix)]
fn metadata_identity(metadata: &fs::Metadata) -> (u64, u64, i64, i64, i64, i64) {
    use std::os::unix::fs::MetadataExt;

    (
        metadata.dev(),
        metadata.ino(),
        metadata.mtime(),
        metadata.mtime_nsec(),
        metadata.ctime(),
        metadata.ctime_nsec(),
    )
}

#[cfg(not(unix))]
fn metadata_identity(metadata: &fs::Metadata) -> (u64, Option<SystemTime>) {
    (metadata.len(), metadata.modified().ok())
}

fn environment(host: filesystem::HostEvidence) -> Environment {
    Environment {
        rustc_version: command_output(
            std::env::var_os("RUSTC").as_deref().unwrap_or_default(),
            &["--version"],
        )
        .or_else(|| command_output(std::ffi::OsStr::new("rustc"), &["--version"])),
        git_revision: git_output(&["rev-parse", "HEAD"]),
        git_worktree_dirty: git_output(&["status", "--porcelain"]).map(|status| !status.is_empty()),
        logical_cpus_available: std::thread::available_parallelism()
            .map_or(1, std::num::NonZeroUsize::get),
        allocator: allocation_metrics::allocator_identity(),
        rustflags: std::env::var("RUSTFLAGS")
            .ok()
            .or_else(|| option_env!("RUSTFLAGS").map(str::to_owned)),
        cargo_build_target: std::env::var("CARGO_BUILD_TARGET")
            .ok()
            .or_else(|| option_env!("CARGO_BUILD_TARGET").map(str::to_owned)),
        perf_event_paranoid: fs::read_to_string("/proc/sys/kernel/perf_event_paranoid")
            .ok()
            .map(|value| value.trim().to_owned()),
        os: host.os,
        kernel: host.kernel,
        cpu_model: host.cpu_model,
        total_memory_bytes: host.total_memory_bytes,
        page_size_bytes: host.page_size_bytes,
        filesystem_type: host.filesystem_type,
        source_destination_same_device: host.source_destination_same_device,
        cpu_affinity: host.cpu_affinity,
        storage_identifier: host.storage_identifier,
    }
}

fn git_output(arguments: &[&str]) -> Option<String> {
    let manifest_directory = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let repository = manifest_directory.parent()?.parent()?;
    let output = Command::new("git")
        .arg("-C")
        .arg(repository)
        .args(arguments)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8(output.stdout)
        .ok()
        .map(|value| value.trim().to_owned())
}

fn command_output(program: &std::ffi::OsStr, arguments: &[&str]) -> Option<String> {
    if program.is_empty() {
        return None;
    }
    let output = Command::new(program).args(arguments).output().ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8(output.stdout)
        .ok()
        .map(|value| value.trim().to_owned())
}

fn write_report(report: &Report, output: Option<&PathBuf>) -> Result<(), Box<dyn Error>> {
    match output {
        Some(path) => {
            if let Some(parent) = path
                .parent()
                .filter(|parent| !parent.as_os_str().is_empty())
            {
                fs::create_dir_all(parent)?;
            }
            let file = File::create(path)?;
            serde_json::to_writer_pretty(file, report)?;
        },
        None => {
            let stdout = io::stdout();
            let mut writer = stdout.lock();
            serde_json::to_writer_pretty(&mut writer, report)?;
            writer.write_all(b"\n")?;
        },
    }
    Ok(())
}

