    #[test]
    fn cfb_open_stream_extended_selectors_preserve_payloads() {
        for shape in [CorpusShape::ManySmall, CorpusShape::WideRoot] {
            for target in [CfbSelectiveTarget::Mini, CfbSelectiveTarget::Mini4095] {
                let corpus = build_cfb_selective_corpus(shape, target).unwrap();
                let (expected_root_bytes, target_start) = match (shape, target) {
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini) => {
                        (261_184_u64, 261_632_u64)
                    },
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini4095) => {
                        (265_216_u64, 261_632_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini) => {
                        (2_096_192_u64, 2_096_640_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini4095) => {
                        (2_100_224_u64, 2_096_640_u64)
                    },
                    (_, CfbSelectiveTarget::Fat) => unreachable!(),
                    _ => unreachable!(),
                };
                let cases = match target {
                    CfbSelectiveTarget::Mini => [
                        Case::CfbOpenStreamMiniSharedDifferentSid,
                        Case::CfbOpenStreamMiniSharedBulk,
                        Case::CfbOpenStreamMiniSharedConcurrent,
                    ],
                    CfbSelectiveTarget::Mini4095 => [
                        Case::CfbOpenStreamMini4095SharedDifferentSid,
                        Case::CfbOpenStreamMini4095SharedBulk,
                        Case::CfbOpenStreamMini4095SharedConcurrent,
                    ],
                    CfbSelectiveTarget::Fat => unreachable!(),
                };
                for case in cases {
                    assert_eq!(parse_case(case.name()), Some(case));
                    let evidence = run_cfb_open_stream(case, &corpus, 0, 1)
                        .unwrap()
                        .source
                        .unwrap()
                        .cfb_open_stream
                        .unwrap();
                    assert!(evidence.typed_refusal_verified);
                    assert_eq!(evidence.shape, shape.name());
                    assert_eq!(evidence.root_ministream_bytes, expected_root_bytes);
                    assert_eq!(
                        evidence.requested_stream_count,
                        case.cfb_open_stream_operation().unwrap().count()
                    );
                    assert_eq!(evidence.output_sha256.len(), 1);
                    assert_eq!(evidence.returned_payload_bytes.len(), 1);
                    assert_eq!(
                        evidence.output_sha256[0].len(),
                        evidence.requested_stream_count
                    );
                    assert_eq!(
                        evidence.returned_payload_bytes[0],
                        evidence
                            .invocation_stream_names
                            .iter()
                            .map(|name| cfb_open_stream_expected_payload(&corpus, name)
                                .unwrap()
                                .len() as u64)
                            .collect::<Vec<_>>()
                    );

                    let target_len = corpus.target_payload.len() as u64;
                    let direct = [target_start, target_len, target_len];
                    let cache = [512_u64, expected_root_bytes, expected_root_bytes];
                    let ranges = &evidence.per_operation_read_ranges[0];
                    match case.cfb_open_stream_operation().unwrap() {
                        CfbOpenStreamOperation::DifferentSid => {
                            assert!(
                                ranges == &vec![vec![cache], vec![], vec![]]
                                    || ranges == &vec![vec![direct], vec![cache], vec![]],
                                "unexpected different-SID source vector for {shape:?}/{target:?}: {ranges:?}"
                            );
                        },
                        CfbOpenStreamOperation::Bulk => {
                            let mut actual = ranges.iter().flatten().copied().collect::<Vec<_>>();
                            actual.sort_unstable();
                            let mut direct_and_cache = vec![direct, cache];
                            direct_and_cache.sort_unstable();
                            assert!(
                                actual == vec![cache] || actual == direct_and_cache,
                                "unexpected bulk source multiset for {shape:?}/{target:?}: {actual:?}"
                            );
                        },
                        CfbOpenStreamOperation::Concurrent => {
                            let mut actual = ranges.iter().flatten().copied().collect::<Vec<_>>();
                            actual.sort_unstable();
                            let mut direct_and_cache = vec![direct, cache];
                            direct_and_cache.sort_unstable();
                            let mut direct_twice = vec![direct, direct];
                            direct_twice.sort_unstable();
                            assert!(
                                actual == vec![cache]
                                    || actual == direct_and_cache
                                    || actual == direct_twice
                                    // A same-target single-flight may serve both
                                    // callers from one physical direct read.
                                    || actual == vec![direct],
                                "unexpected concurrent source multiset for {shape:?}/{target:?}: {actual:?}"
                            );
                        },
                        _ => unreachable!(),
                    }
                }
            }
        }
    }

    #[test]
    fn cfb_open_stream_current_candidate_records_exact_minifat_ranges() {
        let assert_events = |events: &[[u64; 3]]| {
            for &[offset, requested, returned] in events {
                assert!(offset <= u64::MAX - requested);
                assert!(requested > 0);
                assert!(returned <= requested);
            }
        };

        for shape in [CorpusShape::ManySmall, CorpusShape::WideRoot] {
            for target in [CfbSelectiveTarget::Mini, CfbSelectiveTarget::Mini4095] {
                let corpus = build_cfb_selective_corpus(shape, target).unwrap();
                let (expected_root_bytes, expected_direct_start) = match (shape, target) {
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini) => {
                        (261_184_u64, 261_632_u64)
                    },
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini4095) => {
                        (265_216_u64, 261_632_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini) => {
                        (2_096_192_u64, 2_096_640_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini4095) => {
                        (2_100_224_u64, 2_096_640_u64)
                    },
                    (_, CfbSelectiveTarget::Fat) => unreachable!(),
                    _ => unreachable!(),
                };
                let cases = match target {
                    CfbSelectiveTarget::Mini => [
                        (Case::CfbOpenStreamMiniSharedOneShot, 1),
                        (Case::CfbOpenStreamMiniSharedRepeat, 3),
                        (Case::CfbOpenStreamMiniSharedRepeat8, 8),
                    ],
                    CfbSelectiveTarget::Mini4095 => [
                        (Case::CfbOpenStreamMini4095SharedOneShot, 1),
                        (Case::CfbOpenStreamMini4095SharedRepeat, 3),
                        (Case::CfbOpenStreamMini4095SharedRepeat8, 8),
                    ],
                    CfbSelectiveTarget::Fat => unreachable!(),
                };

                for (case, invocation_count) in cases {
                    assert_eq!(parse_case(case.name()), Some(case));
                    let evidence = run_cfb_open_stream(case, &corpus, 0, 1)
                        .unwrap()
                        .source
                        .unwrap()
                        .cfb_open_stream
                        .unwrap();
                    assert_eq!(evidence.shape, shape.name());
                    assert_eq!(evidence.sibling_count, shape.entry_count());
                    assert_eq!(evidence.sector_size, 512);
                    assert_eq!(evidence.mini_sector_size, 64);
                    assert_eq!(evidence.target_stream_name, corpus.target_name);
                    assert!(evidence.target_is_minifat);
                    assert_eq!(evidence.root_ministream_bytes, expected_root_bytes);
                    assert!(evidence.typed_refusal_verified);
                    assert!(evidence.source_version_check.contains("source_version"));
                    assert_eq!(evidence.invocation_count, invocation_count);
                    assert_eq!(evidence.output_sha256.len(), 1);
                    assert_eq!(
                        evidence.output_sha256[0],
                        vec![corpus.manifest.target_payload_sha256.clone(); invocation_count]
                    );
                    assert_eq!(
                        evidence.returned_payload_bytes,
                        vec![vec![corpus.target_payload.len() as u64; invocation_count]]
                    );
                    assert_eq!(evidence.open_ns.len(), 1);
                    assert_eq!(evidence.operation_ns.len(), 1);
                    assert_eq!(evidence.per_operation_ns[0].len(), invocation_count);
                    assert_eq!(evidence.total_ns.len(), 1);
                    assert_eq!(evidence.per_operation_read_calls[0].len(), invocation_count);
                    assert_eq!(evidence.per_operation_read_bytes[0].len(), invocation_count);
                    let target_len = corpus.target_payload.len() as u64;
                    let expected_direct = vec![[expected_direct_start, target_len, target_len]];
                    let expected_root = vec![[512, expected_root_bytes, expected_root_bytes]];
                    let (control_calls, control_bytes, control_ranges) = match invocation_count {
                        1 => (
                            vec![1],
                            vec![expected_root_bytes],
                            vec![expected_root.clone()],
                        ),
                        3 => (
                            vec![1, 0, 0],
                            vec![expected_root_bytes, 0, 0],
                            vec![expected_root.clone(), vec![], vec![]],
                        ),
                        8 => (
                            vec![1, 0, 0, 0, 0, 0, 0, 0],
                            vec![expected_root_bytes, 0, 0, 0, 0, 0, 0, 0],
                            vec![
                                expected_root.clone(),
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                            ],
                        ),
                        _ => unreachable!(),
                    };
                    let (current_calls, current_bytes, current_ranges) = match invocation_count {
                        1 => (vec![1], vec![target_len], vec![expected_direct.clone()]),
                        3 => (
                            vec![1, 1, 0],
                            vec![target_len, expected_root_bytes, 0],
                            vec![expected_direct.clone(), expected_root.clone(), vec![]],
                        ),
                        8 => (
                            vec![1, 1, 0, 0, 0, 0, 0, 0],
                            vec![target_len, expected_root_bytes, 0, 0, 0, 0, 0, 0],
                            vec![
                                expected_direct.clone(),
                                expected_root.clone(),
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                            ],
                        ),
                        _ => unreachable!(),
                    };
                    let candidate_calls = vec![1; invocation_count];
                    let candidate_bytes = vec![target_len; invocation_count];
                    let candidate_ranges = vec![expected_direct.clone(); invocation_count];
                    let actual = (
                        evidence.per_operation_read_calls[0].clone(),
                        evidence.per_operation_read_bytes[0].clone(),
                        evidence.per_operation_read_ranges[0].clone(),
                    );
                    assert!(
                        actual == (control_calls, control_bytes, control_ranges)
                            || actual == (current_calls, current_bytes, current_ranges)
                            || actual == (candidate_calls, candidate_bytes, candidate_ranges)
                    );
                    assert_eq!(
                        evidence.per_operation_read_range_sizes[0].len(),
                        invocation_count
                    );
                    assert_eq!(
                        evidence.per_operation_read_ranges[0].len(),
                        invocation_count
                    );
                    assert_eq!(evidence.expected_direct_physical_range.len(), 1);
                    let expected_direct_range =
                        if evidence.per_operation_read_bytes[0].first() == Some(&target_len) {
                            Some([expected_direct_start, expected_direct_start + target_len])
                        } else {
                            None
                        };
                    assert_eq!(
                        evidence.expected_direct_physical_range[0],
                        expected_direct_range
                    );
                    assert_events(&evidence.open_read_ranges[0]);
                    assert_events(&evidence.logical_read_ranges[0]);
                    for ranges in &evidence.per_operation_read_ranges[0] {
                        assert_events(ranges);
                    }
                    let root_expected = match evidence.per_operation_read_bytes[0].as_slice() {
                        bytes if bytes.first() == Some(&expected_root_bytes) => {
                            Some(expected_root_bytes)
                        },
                        bytes if bytes.get(1) == Some(&expected_root_bytes) => {
                            Some(expected_root_bytes)
                        },
                        _ => None,
                    };
                    assert_eq!(evidence.root_cache_read_bytes, vec![root_expected]);
                }
            }
        }
    }

    fn cfb_expected_minifat_physical_start(archive: &[u8], target_name: &str) -> u64 {
        let parsed = super::OleFile::open(std::io::Cursor::new(archive)).unwrap();
        let sector_size = parsed.sector_size();
        let read_u16 = |bytes: &[u8]| u16::from_le_bytes(bytes.try_into().unwrap());
        let read_u32 = |bytes: &[u8]| u32::from_le_bytes(bytes.try_into().unwrap());
        let mini_sector_size = 1_usize << usize::from(read_u16(&archive[0x20..0x22]));
        let fat_sector_count = usize::try_from(read_u32(&archive[0x2C..0x30])).unwrap();
        let difat_sector_count = usize::try_from(read_u32(&archive[0x48..0x4C])).unwrap();
        let header_fat_count = fat_sector_count.min(109);
        let mut fat_sectors = Vec::with_capacity(fat_sector_count);
        for index in 0..header_fat_count {
            let offset = 0x4C + index * 4;
            fat_sectors.push(read_u32(&archive[offset..offset + 4]));
        }
        let mut difat_sector = read_u32(&archive[0x44..0x48]);
        for _ in 0..difat_sector_count {
            let offset = (usize::try_from(difat_sector).unwrap() + 1) * sector_size;
            let bytes = &archive[offset..offset + sector_size];
            for index in 0..(sector_size / 4 - 1) {
                if fat_sectors.len() == fat_sector_count {
                    break;
                }
                let entry = index * 4;
                fat_sectors.push(read_u32(&bytes[entry..entry + 4]));
            }
            difat_sector = read_u32(&bytes[sector_size - 4..]);
        }
        assert_eq!(fat_sectors.len(), fat_sector_count);

        let mut fat = Vec::with_capacity(fat_sector_count * (sector_size / 4));
        for sector in fat_sectors {
            let offset = (usize::try_from(sector).unwrap() + 1) * sector_size;
            let bytes = &archive[offset..offset + sector_size];
            for index in 0..(sector_size / 4) {
                let entry = index * 4;
                fat.push(read_u32(&bytes[entry..entry + 4]));
            }
        }

        let root_start_sector = parsed.root_entry().unwrap().start_sector;
        let target_start_mini_sector = parsed
            .list_directory_entries(&[])
            .unwrap()
            .into_iter()
            .find(|entry| entry.name == target_name)
            .unwrap()
            .start_sector;
        let mini_offset = usize::try_from(target_start_mini_sector)
            .unwrap()
            .checked_mul(mini_sector_size)
            .unwrap();
        let root_ordinal = mini_offset / sector_size;
        let root_within = mini_offset % sector_size;
        let mut root_sector = root_start_sector;
        for _ in 0..root_ordinal {
            root_sector = *fat.get(usize::try_from(root_sector).unwrap()).unwrap();
        }
        (u64::from(root_sector) + 1) * u64::try_from(sector_size).unwrap()
            + u64::try_from(root_within).unwrap()
    }

    #[test]
    fn cfb_open_stream_current_candidate_concurrent_accepts_d_or_dd() {
        for shape in [CorpusShape::ManySmall, CorpusShape::WideRoot] {
            for target in [CfbSelectiveTarget::Mini, CfbSelectiveTarget::Mini4095] {
                let corpus = build_cfb_selective_corpus(shape, target).unwrap();
                let evidence = run_cfb_open_stream(
                    match target {
                        CfbSelectiveTarget::Mini => Case::CfbOpenStreamMiniSharedConcurrent,
                        CfbSelectiveTarget::Mini4095 => Case::CfbOpenStreamMini4095SharedConcurrent,
                        CfbSelectiveTarget::Fat => unreachable!(),
                    },
                    &corpus,
                    0,
                    1,
                )
                .unwrap()
                .source
                .unwrap()
                .cfb_open_stream
                .unwrap();

                let target_len = u64::try_from(corpus.target_payload.len()).unwrap();
                let direct_start =
                    cfb_expected_minifat_physical_start(&corpus.archive, &corpus.target_name);
                let direct = [direct_start, target_len, target_len];
                let expected_direct_range = [direct_start, direct_start + target_len];
                let target_hash = corpus.manifest.target_payload_sha256.clone();

                assert_eq!(evidence.output_sha256, vec![vec![target_hash; 2]]);
                assert_eq!(
                    evidence.returned_payload_bytes,
                    vec![vec![target_len, target_len]]
                );

                // Production unit tests gate a true in-flight owner/waiter
                // overlap and deterministically prove one direct read. This
                // harness gate only coordinates caller entry; scheduling may
                // let the second claim begin after the owner completes, so
                // aggregate evidence legitimately records [D] or [D,D].
                let direct_events = evidence.logical_read_ranges[0].clone();
                assert!(
                    direct_events == vec![direct] || direct_events == vec![direct, direct],
                    "unexpected concurrent direct-event vector for {shape:?}/{target:?}: actual={direct_events:?}, expected={direct:?}"
                );
                let logical_read_calls = u64::try_from(direct_events.len()).unwrap();
                let logical_read_bytes = logical_read_calls.checked_mul(target_len).unwrap();
                let direct_sizes = vec![target_len; direct_events.len()];
                assert_eq!(evidence.logical_read_calls, vec![logical_read_calls]);
                assert_eq!(evidence.logical_read_bytes, vec![logical_read_bytes]);
                assert_eq!(
                    evidence.logical_read_range_sizes,
                    vec![direct_sizes.clone()]
                );
                assert_eq!(
                    evidence.per_operation_read_calls,
                    vec![vec![logical_read_calls]]
                );
                assert_eq!(
                    evidence.per_operation_read_bytes,
                    vec![vec![logical_read_bytes]]
                );
                assert_eq!(
                    evidence.per_operation_read_range_sizes,
                    vec![vec![direct_sizes]]
                );
                assert_eq!(
                    evidence.per_operation_read_ranges,
                    vec![vec![direct_events]]
                );
                assert_eq!(evidence.root_cache_read_bytes, vec![None]);

                // The field is a derived diagnostic and may remain unset for
                // the unchanged concurrent runner; when present, it must be
                // the exact extent of the raw direct event above.
                assert_eq!(evidence.expected_direct_physical_range.len(), 1);
                if let Some(actual) = evidence.expected_direct_physical_range[0] {
                    assert_eq!(actual, expected_direct_range);
                }
            }
        }
    }

    #[test]
    fn cfb_open_stream_simulation_records_zero_cache_hits_without_losing_events() {
        let config = RangeSimulationConfig {
            fixed_latency_us: 1,
            request_overhead_us: 2,
            bandwidth_bytes_per_second: 1_000_000_000,
            max_physical_range_bytes: 4_096,
        };
        let assert_phase = |phase: &CfbSelectiveSimulationPhase| {
            if phase.logical_read_calls == 0 {
                assert_eq!(phase.logical_read_bytes, 0);
                assert_eq!(phase.physical_request_count, 0);
                assert_eq!(phase.physical_request_bytes, 0);
                assert!(phase.physical_request_sizes.is_empty());
                assert!(phase.physical_ranges.is_empty());
                assert_eq!(phase.simulated_service_floor_ns, 0);
            } else {
                assert_eq!(
                    phase.physical_request_count,
                    u64::try_from(phase.physical_ranges.len()).unwrap()
                );
                assert_eq!(
                    phase.physical_request_count,
                    u64::try_from(phase.physical_request_sizes.len()).unwrap()
                );
                assert_eq!(phase.logical_read_bytes, phase.physical_request_bytes);
                for &[offset, requested, returned] in &phase.physical_ranges {
                    assert!(offset <= u64::MAX - requested);
                    assert!(requested > 0 && returned <= requested);
                }
            }
        };

        for shape in [CorpusShape::ManySmall, CorpusShape::WideRoot] {
            for target in [CfbSelectiveTarget::Mini, CfbSelectiveTarget::Mini4095] {
                let corpus = build_cfb_selective_corpus(shape, target).unwrap();
                let (expected_root_bytes, expected_direct_start) = match (shape, target) {
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini) => {
                        (261_184_u64, 261_632_u64)
                    },
                    (CorpusShape::ManySmall, CfbSelectiveTarget::Mini4095) => {
                        (265_216_u64, 261_632_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini) => {
                        (2_096_192_u64, 2_096_640_u64)
                    },
                    (CorpusShape::WideRoot, CfbSelectiveTarget::Mini4095) => {
                        (2_100_224_u64, 2_096_640_u64)
                    },
                    (_, CfbSelectiveTarget::Fat) => unreachable!(),
                    _ => unreachable!(),
                };
                let cases = match target {
                    CfbSelectiveTarget::Mini => [
                        (Case::CfbOpenStreamSimulatedMiniSharedOneShot, 1),
                        (Case::CfbOpenStreamSimulatedMiniSharedRepeat, 3),
                        (Case::CfbOpenStreamSimulatedMiniSharedRepeat8, 8),
                    ],
                    CfbSelectiveTarget::Mini4095 => [
                        (Case::CfbOpenStreamSimulatedMini4095SharedOneShot, 1),
                        (Case::CfbOpenStreamSimulatedMini4095SharedRepeat, 3),
                        (Case::CfbOpenStreamSimulatedMini4095SharedRepeat8, 8),
                    ],
                    CfbSelectiveTarget::Fat => unreachable!(),
                };

                for (case, invocation_count) in cases {
                    assert_eq!(parse_case(case.name()), Some(case));
                    let evidence = run_cfb_open_stream_simulated(case, &corpus, 0, 1, config)
                        .unwrap()
                        .source
                        .unwrap()
                        .cfb_open_stream
                        .unwrap();
                    let simulation = evidence.simulation.as_ref().unwrap();
                    assert_eq!(simulation.config, config);
                    assert_eq!(simulation.samples.len(), 1);
                    let sample = &simulation.samples[0];
                    assert_eq!(sample.per_operation.len(), invocation_count);
                    assert_eq!(evidence.per_operation_ns[0].len(), invocation_count);
                    assert_phase(&sample.open);
                    assert_eq!(sample.open.logical_read_calls, evidence.open_read_calls[0]);
                    assert_eq!(sample.open.logical_read_bytes, evidence.open_read_bytes[0]);
                    assert_eq!(sample.open.physical_ranges, evidence.open_read_ranges[0]);
                    assert_eq!(evidence.root_ministream_bytes, expected_root_bytes);
                    let target_len = corpus.target_payload.len() as u64;
                    let expected_direct = vec![[expected_direct_start, target_len, target_len]];
                    let mut expected_root_ranges = Vec::new();
                    let mut offset = 512_u64;
                    let mut remaining = expected_root_bytes;
                    while remaining != 0 {
                        let requested = remaining.min(4_096);
                        expected_root_ranges.push([offset, requested, requested]);
                        offset += requested;
                        remaining -= requested;
                    }
                    let actual = (
                        evidence.per_operation_read_calls[0].clone(),
                        evidence.per_operation_read_bytes[0].clone(),
                        evidence.per_operation_read_ranges[0].to_vec(),
                    );
                    let control = match invocation_count {
                        1 => (
                            vec![1],
                            vec![expected_root_bytes],
                            vec![expected_root_ranges.clone()],
                        ),
                        3 => (
                            vec![1, 0, 0],
                            vec![expected_root_bytes, 0, 0],
                            vec![expected_root_ranges.clone(), vec![], vec![]],
                        ),
                        8 => (
                            vec![1, 0, 0, 0, 0, 0, 0, 0],
                            vec![expected_root_bytes, 0, 0, 0, 0, 0, 0, 0],
                            vec![
                                expected_root_ranges.clone(),
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                            ],
                        ),
                        _ => unreachable!(),
                    };
                    let current = match invocation_count {
                        1 => (vec![1], vec![target_len], vec![expected_direct.clone()]),
                        3 => (
                            vec![1, 1, 0],
                            vec![target_len, expected_root_bytes, 0],
                            vec![
                                expected_direct.clone(),
                                expected_root_ranges.clone(),
                                vec![],
                            ],
                        ),
                        8 => (
                            vec![1, 1, 0, 0, 0, 0, 0, 0],
                            vec![target_len, expected_root_bytes, 0, 0, 0, 0, 0, 0],
                            vec![
                                expected_direct.clone(),
                                expected_root_ranges.clone(),
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                                vec![],
                            ],
                        ),
                        _ => unreachable!(),
                    };
                    let candidate = (
                        vec![1; invocation_count],
                        vec![target_len; invocation_count],
                        vec![expected_direct.clone(); invocation_count],
                    );
                    assert!(actual == control || actual == current || actual == candidate);
                    if actual.1.first() == Some(&target_len) {
                        assert_eq!(sample.per_operation[0].physical_ranges, expected_direct);
                    } else {
                        assert_eq!(
                            sample.per_operation[0].physical_ranges,
                            expected_root_ranges
                        );
                    }
                    let expected_root = if actual.1.contains(&expected_root_bytes) {
                        Some(expected_root_bytes)
                    } else {
                        None
                    };
                    assert_eq!(evidence.root_cache_read_bytes, vec![expected_root]);
                    let expected_direct_range = if actual.1.first() == Some(&target_len) {
                        Some([expected_direct_start, expected_direct_start + target_len])
                    } else {
                        None
                    };
                    assert_eq!(
                        evidence.expected_direct_physical_range[0],
                        expected_direct_range
                    );
                    assert_phase(&sample.aggregate);
                    assert!(sample.aggregate.logical_read_calls > 0);
                    for phase in &sample.per_operation {
                        assert_phase(phase);
                    }
                    assert_eq!(evidence.open_read_ranges.len(), 1);
                    assert_eq!(evidence.logical_read_ranges.len(), 1);
                    assert_eq!(
                        evidence.per_operation_read_ranges[0].len(),
                        invocation_count
                    );
                    assert_eq!(evidence.expected_direct_physical_range.len(), 1);
                }
            }
        }
    }

