    #[test]
    fn native_ole2_tiny_corpora_exercise_all_semantic_cases() {
        let families = [
            (
                Case::DocFreshWriteTo,
                [
                    Case::DocSemanticOpen,
                    Case::DocSemanticListParagraphs,
                    Case::DocSemanticOneParagraph,
                    Case::DocSemanticFullText,
                    Case::DocSemanticNoopEditSave,
                    Case::DocSemanticOneEditSave,
                ],
            ),
            (
                Case::XlsFreshWriteTo,
                [
                    Case::XlsSemanticOpen,
                    Case::XlsSemanticListWorksheets,
                    Case::XlsSemanticOneCell,
                    Case::XlsSemanticFullCellScan,
                    Case::XlsSemanticNoopEditSave,
                    Case::XlsSemanticOneEditSave,
                ],
            ),
            (
                Case::PptFreshWriteTo,
                [
                    Case::PptSemanticOpen,
                    Case::PptSemanticListSlides,
                    Case::PptSemanticOneShapeText,
                    Case::PptSemanticFullText,
                    Case::PptSemanticNoopEditSave,
                    Case::PptSemanticOneEditSave,
                ],
            ),
        ];

        for (writer_case, semantic_cases) in families {
            let corpus = build_writer_corpus(writer_case, WriterShape::Tiny).unwrap();
            let again = build_writer_corpus(writer_case, WriterShape::Tiny).unwrap();
            assert_eq!(corpus.archive, again.archive, "{}", writer_case.name());
            for case in semantic_cases {
                let measured = run_case(case, &corpus, 0, 1).unwrap();
                assert_eq!(measured.case, case.name());
                assert_eq!(measured.elapsed_ns.samples.len(), 1);
                assert!(measured.sink.is_none());
            }
        }

        let ppt = build_writer_corpus(Case::PptFreshWriteTo, WriterShape::Tiny).unwrap();
        for case in [
            Case::PptSlideOrderSnapshotOpen,
            Case::PptTextEditOneEditSave,
            Case::PptSourceBackedOneShapeText,
            Case::PptSemanticFreshOpenOneShapeText,
            Case::PptSourceBackedFreshOpenOneShapeText,
        ] {
            let measured = run_case(case, &ppt, 0, 1).unwrap();
            assert_eq!(measured.case, case.name());
            assert_eq!(measured.elapsed_ns.samples.len(), 1);
            assert!(measured.sink.is_none());
            if matches!(
                case,
                Case::PptSourceBackedOneShapeText | Case::PptSourceBackedFreshOpenOneShapeText
            ) {
                let source = measured.source.expect("source-backed PPT query evidence");
                let shape_text = source
                    .ppt_shape_text
                    .expect("selected-shape source evidence");
                assert_eq!(shape_text.source_read_calls.len(), 1);
                assert_eq!(shape_text.source_read_bytes.len(), 1);
                assert!(shape_text.source_read_calls[0] > 0);
                assert!(shape_text.source_read_bytes[0] > 0);
            } else {
                assert!(measured.source.is_none());
            }
        }
    }

    #[test]
    fn native_ppt_repeated_selected_queries_have_matched_semantic_evidence() {
        assert_eq!(
            parse_case("ppt_semantic_repeated_shape_text"),
            Some(Case::PptSemanticRepeatedShapeText)
        );
        assert_eq!(
            parse_case("ppt_source_backed_repeated_shape_text"),
            Some(Case::PptSourceBackedRepeatedShapeText)
        );
        assert_eq!(
            Case::PptSemanticRepeatedShapeText.name(),
            "ppt_semantic_repeated_shape_text"
        );
        assert_eq!(
            Case::PptSourceBackedRepeatedShapeText.name(),
            "ppt_source_backed_repeated_shape_text"
        );
        let corpus = build_writer_corpus(Case::PptFreshWriteTo, WriterShape::Tiny).unwrap();
        let eager = run_case(Case::PptSemanticRepeatedShapeText, &corpus, 1, 2).unwrap();
        let source = run_case(Case::PptSourceBackedRepeatedShapeText, &corpus, 1, 2).unwrap();
        let eager_shape = eager
            .source
            .expect("eager repeated-query evidence")
            .ppt_shape_text
            .expect("eager repeated-query summary");
        let source_shape = source
            .source
            .expect("source repeated-query evidence")
            .ppt_shape_text
            .expect("source repeated-query summary");
        assert_eq!(eager_shape.repeated_query_count, PPT_REPEATED_QUERY_COUNT);
        assert_eq!(source_shape.repeated_query_count, PPT_REPEATED_QUERY_COUNT);
        assert_eq!(
            eager_shape.repeated_semantic_sha256,
            source_shape.repeated_semantic_sha256
        );
        assert_eq!(source_shape.source_read_calls.len(), 2);
        assert_eq!(source_shape.source_read_bytes.len(), 2);
        assert_eq!(source_shape.source_read_range_overlap_bytes.len(), 2);
        assert_eq!(
            source_shape.source_read_calls[0],
            source_shape.source_read_calls[1]
        );
        assert_eq!(
            source_shape.source_read_bytes[0],
            source_shape.source_read_bytes[1]
        );
        assert_eq!(
            source_shape.source_read_range_overlap_bytes[0],
            source_shape.source_read_range_overlap_bytes[1]
        );
        assert!(
            source_shape
                .source_read_calls
                .iter()
                .all(|&count| count > 0)
        );
        assert!(
            source_shape
                .source_read_bytes
                .iter()
                .all(|&bytes| bytes > 0)
        );
        assert!(
            source_shape
                .source_read_range_overlap_bytes
                .iter()
                .zip(&source_shape.source_read_bytes)
                .all(|(&overlap, &bytes)| overlap > 0 && overlap <= bytes)
        );
    }

