    #[test]
    fn semantic_rtf_tiny_variants_are_deterministic_and_capability_bounded() {
        let cases = [
            Case::RtfSemanticOpen,
            Case::RtfSemanticParagraphCount,
            Case::RtfSemanticListParagraphs,
            Case::RtfSemanticCollectParagraphs,
            Case::RtfSemanticOneParagraph,
            Case::RtfSemanticFullText,
            Case::RtfSemanticTextToSink,
            Case::RtfSemanticStreamSave,
            Case::RtfSemanticNoopEditSave,
            Case::RtfSemanticOneEditSave,
            Case::RtfSemanticOnePercentEditSave,
            Case::RtfSemanticRemoveParagraphSave,
            Case::RtfSemanticMoveParagraphSave,
            Case::RtfSemanticSplitParagraphSave,
            Case::RtfSemanticMergeParagraphSave,
            Case::RtfLogicalTailAppend,
            Case::RtfLogicalTailNoopSave,
            Case::RtfLogicalTailCommitAppend,
            Case::RtfLogicalTailPlanAppend,
            Case::RtfLogicalTailCommitNoopSave,
            Case::RtfLogicalTailPlanNoopSave,
        ];

        for variant in RtfSemanticVariant::ALL {
            let rtf = build_semantic_rtf_corpus(SemanticShape::Tiny, variant).unwrap();
            let again = build_semantic_rtf_corpus(SemanticShape::Tiny, variant).unwrap();
            let lifecycle = (variant == RtfSemanticVariant::Plain)
                .then(|| build_rtf_lifecycle_corpus(SemanticShape::Tiny).unwrap());
            assert_eq!(rtf.archive, again.archive, "{}", variant.name());
            assert_eq!(rtf.manifest.rtf_variant, Some(variant.name()));

            for case in cases {
                let selected_corpus = if case.is_rtf_lifecycle()
                    || case.is_rtf_paragraph_split_merge()
                    || case.is_rtf_logical_tail()
                {
                    lifecycle.as_ref().unwrap_or(&rtf)
                } else {
                    &rtf
                };
                let result = run_case(case, selected_corpus, 0, 1);
                if variant.supports_case(case) {
                    let result = result.unwrap();
                    assert_eq!(
                        result.sink.is_some(),
                        case.name().contains("save")
                            || case == Case::RtfSemanticTextToSink
                            || case.is_rtf_logical_tail()
                    );
                } else {
                    assert!(
                        result.is_err(),
                        "{} unexpectedly supports {}",
                        variant.name(),
                        case.name()
                    );
                }
            }
        }

        let plain =
            build_semantic_rtf_corpus(SemanticShape::Tiny, RtfSemanticVariant::Plain).unwrap();
        assert_eq!(plain.manifest.entry_count, 24);
        assert_eq!(
            plain.manifest.archive_sha256,
            "ee4a5c5b5d1c97d5fb4f1e862c2787a859136b237addd0d14a7d52ddc9e62328"
        );
        let lifecycle = build_rtf_lifecycle_corpus(SemanticShape::Tiny).unwrap();
        assert_eq!(lifecycle.manifest.entry_count, 24);
        assert_eq!(
            lifecycle.manifest.archive_sha256,
            "73641cf09b630632deabce8585c67f395a6bd3ac01eedcca6a8b7224ef00d252"
        );

        let byte1252 =
            build_semantic_rtf_corpus(SemanticShape::Tiny, RtfSemanticVariant::Byte1252).unwrap();
        assert!(byte1252.archive.contains(&0xe9));
        assert_eq!(
            byte1252.manifest.archive_sha256,
            "47a20904dfb8107bb1cd9ad099decfed13c76cbde993fdd93eda3d919a9bb1aa"
        );
        let lzfu =
            build_semantic_rtf_corpus(SemanticShape::Tiny, RtfSemanticVariant::Lzfu).unwrap();
        assert!(litchi_rtf::transport::is_compressed_rtf(&lzfu.archive));
        assert_eq!(
            lzfu.manifest.archive_sha256,
            "bf755db7d4afc26a66ffab476884431e6e585f3259df5b6469e2d4fadfc51baf"
        );
        let watermark =
            build_semantic_rtf_corpus(SemanticShape::Tiny, RtfSemanticVariant::Watermark).unwrap();
        assert_eq!(
            watermark.manifest.archive_sha256,
            "48d62dcd959e737b06ebb8255780bcaaf1e88056ff9c3d5a21d3ff5cd3ddf9cb"
        );
        assert!(
            build_semantic_rtf_corpus(SemanticShape::Large, RtfSemanticVariant::Watermark).is_err()
        );
        assert_eq!(
            RtfSemanticVariant::ALL
                .iter()
                .flat_map(|variant| cases.iter().map(move |case| (*variant, *case)))
                .filter(|(variant, case)| variant.supports_case(*case))
                .count(),
            47
        );
    }

    #[test]
    fn semantic_rtf_logical_tail_is_bounded_reopenable_and_reversible() {
        for shape in [
            SemanticShape::Tiny,
            SemanticShape::Medium,
            SemanticShape::Large,
        ] {
            let corpus = build_rtf_lifecycle_corpus(shape).unwrap();
            let append = run_case(Case::RtfLogicalTailAppend, &corpus, 0, 1).unwrap();
            let noop = run_case(Case::RtfLogicalTailNoopSave, &corpus, 0, 1).unwrap();
            let commit_append = run_case(Case::RtfLogicalTailCommitAppend, &corpus, 0, 1).unwrap();
            let plan_append = run_case(Case::RtfLogicalTailPlanAppend, &corpus, 0, 1).unwrap();
            let commit_noop = run_case(Case::RtfLogicalTailCommitNoopSave, &corpus, 0, 1).unwrap();
            let plan_noop = run_case(Case::RtfLogicalTailPlanNoopSave, &corpus, 0, 1).unwrap();
            for result in [
                append,
                noop,
                commit_append,
                plan_append,
                commit_noop,
                plan_noop,
            ] {
                assert_eq!(result.elapsed_ns.samples.len(), 1);
                assert!(result.output_sha256.is_some());
                let sink = result.sink.unwrap();
                let tail = sink.rtf_tail_append.unwrap();
                assert!(tail.exact_noop_verified);
                assert!(tail.in_memory_patch_verified);
                assert!(tail.durable_patch_verified);
                assert!(tail.reopen_verified);
                assert!(tail.source_conflict_verified);
                assert!(!tail.implementation.is_empty());
                assert!(tail.source_retained_bytes > 0);
                assert!(
                    tail.publication_boundary.contains("TailAppendCommit")
                        || tail
                            .publication_boundary
                            .contains("pre-staged publication-call interval")
                );
                if matches!(
                    result.case,
                    "rtf_logical_tail_commit_append"
                        | "rtf_logical_tail_plan_append"
                        | "rtf_logical_tail_commit_noop_save"
                        | "rtf_logical_tail_plan_noop_save"
                ) {
                    let evidence = result
                        .source
                        .unwrap()
                        .rtf_tail_publication
                        .expect("matched RTF publication phase evidence");
                    assert_eq!(evidence.planning_ns.len(), 1);
                    assert_eq!(evidence.publication_ns.len(), 1);
                    assert_eq!(evidence.reopen_ns.len(), 1);
                    assert_eq!(evidence.lifecycle_ns.len(), 1);
                    assert_eq!(evidence.publication_ns, result.elapsed_ns.samples);
                    assert!(
                        evidence
                            .publication_boundary
                            .contains("pre-staged publication-call interval")
                    );
                    assert!(evidence.performance_claim.starts_with("none:"));
                    assert_eq!(
                        evidence.candidate_retained_bytes,
                        if evidence.implementation == "tail_append_publication_plan"
                            || tail.operation == "exact_noop"
                        {
                            0
                        } else {
                            evidence.source_retained_bytes + tail.inserted_bytes
                        }
                    );
                }
                assert_eq!(sink.retained_output_bytes, Some(0));
                assert_eq!(
                    sink.retained_authoring_window_bytes,
                    Some(RTF_LOGICAL_TAIL_SINK_WINDOW_BYTES as u64)
                );
                assert!(sink.largest_write <= RTF_LOGICAL_TAIL_SINK_WINDOW_BYTES as u64);
            }

            if matches!(shape, SemanticShape::Tiny) {
                let multi_sample = run_case(Case::RtfLogicalTailPlanAppend, &corpus, 0, 2).unwrap();
                assert_eq!(multi_sample.elapsed_ns.samples.len(), 2);
                let evidence = multi_sample
                    .source
                    .unwrap()
                    .rtf_tail_publication
                    .expect("matched multi-sample RTF publication phase evidence");
                assert_eq!(evidence.planning_ns.len(), 2);
                assert_eq!(evidence.publication_ns.len(), 2);
                assert_eq!(evidence.reopen_ns.len(), 1);
                assert_eq!(evidence.lifecycle_ns.len(), 1);
                assert_ne!(evidence.publication_ns.len(), evidence.reopen_ns.len());
                assert_ne!(evidence.publication_ns.len(), evidence.lifecycle_ns.len());
                assert!(evidence.reopen_scope.contains("one-element preflight-only"));
                assert!(
                    evidence
                        .lifecycle_scope
                        .contains("one-element preflight-only")
                );
            }
        }
    }

    #[test]
    fn rtf_picture_crud_selectors_are_opt_in_bounded_and_gate_complete() {
        let cases = [
            Case::RtfPicturePayloadBatchReplace,
            Case::RtfPictureBatchRemove,
        ];
        for case in cases {
            assert_eq!(parse_case(case.name()), Some(case));
            assert!(!Case::DEFAULT.contains(&case));
            let corpus = build_rtf_picture_corpus(SemanticShape::Tiny).unwrap();
            let again = build_rtf_picture_corpus(SemanticShape::Tiny).unwrap();
            assert_eq!(corpus.archive, again.archive);
            assert!(corpus.archive.iter().any(|byte| byte.is_ascii_uppercase()));
            assert!(corpus.archive.contains(&b'\n'));

            let result = run_rtf_picture_crud(case, &corpus, 0, 1).unwrap();
            assert_eq!(result.case, case.name());
            assert_eq!(result.elapsed_ns.samples.len(), 1);
            assert_eq!(
                result.output_sha256.as_deref(),
                Some(
                    result
                        .source
                        .as_ref()
                        .unwrap()
                        .rtf_picture_crud
                        .as_ref()
                        .unwrap()
                        .expected_output_sha256
                        .as_str(),
                )
            );
            let evidence = result.source.unwrap().rtf_picture_crud.unwrap();
            assert!(evidence.selected_count > 0);
            assert!(evidence.selected_count <= 64);
            assert_eq!(evidence.open_ns.len(), 1);
            assert_eq!(evidence.stage_ns.len(), 1);
            assert_eq!(evidence.commit_ns.len(), 1);
            assert_eq!(evidence.publication_ns.len(), 1);
            assert_eq!(evidence.lifecycle_ns.len(), 1);
            assert_eq!(evidence.publication_output_sha256.len(), 1);
            assert!(evidence.gates.semantic_reopen_verified);
            assert!(evidence.gates.raw_unselected_preservation_verified);
            assert!(evidence.gates.exact_noop_verified);
            assert!(evidence.gates.volatile_forward_verified);
            assert!(evidence.gates.volatile_inverse_verified);
            assert!(evidence.gates.durable_forward_verified);
            assert!(evidence.gates.durable_inverse_verified);
            assert!(evidence.gates.durable_deterministic_verified);
            assert!(evidence.gates.stale_source_refusal_verified);
            assert!(evidence.gates.foreign_source_refusal_verified);
            assert!(evidence.gates.refusal_verified);
            assert!(evidence.gates.partial_sink_verified);
            assert!(evidence.gates.zero_sink_verified);
            assert!(evidence.gates.source_hash_verified);
            assert!(evidence.gates.output_hash_verified);
        }

        let large = build_rtf_picture_corpus(SemanticShape::Large).unwrap();
        let replacement =
            run_rtf_picture_crud(Case::RtfPicturePayloadBatchReplace, &large, 0, 1).unwrap();
        let removal = run_rtf_picture_crud(Case::RtfPictureBatchRemove, &large, 0, 1).unwrap();
        assert_eq!(
            replacement
                .source
                .unwrap()
                .rtf_picture_crud
                .unwrap()
                .selected_count,
            63
        );
        assert_eq!(
            removal
                .source
                .unwrap()
                .rtf_picture_crud
                .unwrap()
                .selected_count,
            32
        );
    }

    #[test]
    fn semantic_rtf_lifecycle_cases_are_matched_durable_and_transport_bounded() {
        let corpus = build_rtf_lifecycle_corpus(SemanticShape::Tiny).unwrap();
        let source = litchi_rtf::Document::from_bytes(&corpus.archive).unwrap();

        for case in [
            Case::RtfSemanticRemoveParagraphSave,
            Case::RtfSemanticMoveParagraphSave,
        ] {
            let result = run_case(case, &corpus, 0, 1).unwrap();
            assert_eq!(result.case, case.name());
            assert_eq!(result.elapsed_ns.samples.len(), 1);
            let (expected_bytes, expected_sha256) = match case {
                Case::RtfSemanticRemoveParagraphSave => (
                    1_250,
                    "49ef949a6ee85cc3a1bce19026e10a3b953136c73997eec6f719940e2c0b37a2",
                ),
                Case::RtfSemanticMoveParagraphSave => (
                    1_304,
                    "9c7e42060e71be8cedf54fed9907d6a189efa45f1fec0f57d483e02af756f1fd",
                ),
                _ => unreachable!(),
            };
            assert_eq!(result.output_sha256.as_deref(), Some(expected_sha256));
            let sink = result.sink.unwrap();
            assert_eq!(sink.accepted_bytes, expected_bytes);
            assert!(sink.write_calls > 0);
            assert!(sink.largest_write <= sink.accepted_bytes);
        }

        let mut noop = source.edit();
        noop.move_paragraph(0, 0).unwrap();
        let noop = noop.commit().unwrap();
        assert!(!noop.diagnostics().changed());
        assert!(noop.snapshot().same_snapshot(&source));
        assert_eq!(noop.snapshot().to_bytes().unwrap(), corpus.archive);

        for variant in [RtfSemanticVariant::Byte1252, RtfSemanticVariant::Lzfu] {
            let corpus = build_semantic_rtf_corpus(SemanticShape::Tiny, variant).unwrap();
            let document = litchi_rtf::Document::from_bytes(&corpus.archive).unwrap();
            let exact = document.to_bytes().unwrap();
            let selected = document.paragraph_count() / 2;

            let mut remove = document.edit();
            remove.remove_paragraph(selected).unwrap();
            assert!(matches!(
                remove.commit(),
                Err(litchi_rtf::edit::Error::UnsupportedSource(_))
            ));
            assert_eq!(document.to_bytes().unwrap(), exact);

            let mut reorder = document.edit();
            reorder
                .move_paragraph(0, document.paragraph_count() - 1)
                .unwrap();
            assert!(matches!(
                reorder.commit(),
                Err(litchi_rtf::edit::Error::UnsupportedSource(_))
            ));
            assert_eq!(document.to_bytes().unwrap(), exact);

            let mut noop = document.edit();
            noop.move_paragraph(0, 0).unwrap();
            let noop = noop.commit().unwrap();
            assert!(!noop.diagnostics().changed());
            assert!(noop.snapshot().same_snapshot(&document));
            assert_eq!(noop.snapshot().to_bytes().unwrap(), exact);
        }

        let watermark =
            build_semantic_rtf_corpus(SemanticShape::Tiny, RtfSemanticVariant::Watermark).unwrap();
        let watermark = litchi_rtf::Document::from_bytes(&watermark.archive).unwrap();
        let exact = watermark.to_bytes().unwrap();
        let mut remove = watermark.edit();
        remove.remove_paragraph(0).unwrap();
        assert!(matches!(
            remove.commit(),
            Err(litchi_rtf::edit::Error::UnsupportedSource(_))
        ));
        assert_eq!(watermark.to_bytes().unwrap(), exact);
        let mut noop = watermark.edit();
        noop.move_paragraph(0, 0).unwrap();
        let noop = noop.commit().unwrap();
        assert!(!noop.diagnostics().changed());
        assert!(noop.snapshot().same_snapshot(&watermark));
        assert_eq!(noop.snapshot().to_bytes().unwrap(), exact);

        let opaque =
            litchi_rtf::Document::parse(r"{\rtf1\ansi First\par \b Opaque\b0\par Third}").unwrap();
        let exact = opaque.to_bytes().unwrap();
        for case in [
            Case::RtfSemanticRemoveParagraphSave,
            Case::RtfSemanticMoveParagraphSave,
        ] {
            let mut edit = opaque.edit();
            match case {
                Case::RtfSemanticRemoveParagraphSave => {
                    edit.remove_paragraph(1).unwrap();
                },
                Case::RtfSemanticMoveParagraphSave => {
                    edit.move_paragraph(0, 2).unwrap();
                },
                _ => unreachable!(),
            }
            assert!(matches!(
                edit.commit(),
                Err(litchi_rtf::edit::Error::UnsupportedSource(_))
            ));
            assert_eq!(opaque.to_bytes().unwrap(), exact);
        }
        let mut opaque_noop = opaque.edit();
        opaque_noop.move_paragraph(0, 0).unwrap();
        let opaque_noop = opaque_noop.commit().unwrap();
        assert!(!opaque_noop.diagnostics().changed());
        assert!(opaque_noop.snapshot().same_snapshot(&opaque));
        assert_eq!(opaque_noop.snapshot().to_bytes().unwrap(), exact);
    }

    #[test]
    fn rtf_paragraph_split_merge_selectors_are_opt_in_bounded_and_gate_complete() {
        let corpus = build_rtf_lifecycle_corpus(SemanticShape::Tiny).unwrap();
        let cases = [
            Case::RtfSemanticSplitParagraphSave,
            Case::RtfSemanticMergeParagraphSave,
        ];
        for case in cases {
            assert_eq!(parse_case(case.name()), Some(case));
            let result = run_case(case, &corpus, 0, 1).unwrap();
            assert_eq!(result.case, case.name());
            assert_eq!(result.elapsed_ns.samples.len(), 1);
            let evidence = result
                .source
                .unwrap()
                .rtf_paragraph_split_merge
                .expect("RTF paragraph split/merge evidence");
            assert_eq!(evidence.shape, SemanticShape::Tiny.name());
            assert_eq!(evidence.paragraph_count_before, 24);
            assert_eq!(
                evidence.output_bytes as isize - evidence.source_bytes as isize,
                if case == Case::RtfSemanticSplitParagraphSave {
                    5
                } else {
                    -5
                }
            );
            for phases in [
                &evidence.open_ns,
                &evidence.stage_ns,
                &evidence.commit_ns,
                &evidence.publication_ns,
                &evidence.lifecycle_ns,
            ] {
                assert_eq!(phases.len(), 1, "{}", case.name());
            }
            assert_eq!(evidence.publication_output_sha256.len(), 1);
            let gates = &evidence.gates;
            assert!(gates.semantic_reopen_verified);
            assert!(gates.exact_source_splice_verified);
            assert!(gates.unchanged_surrounding_bytes_verified);
            assert!(gates.exact_noop_verified);
            assert!(gates.volatile_forward_verified);
            assert!(gates.volatile_inverse_verified);
            assert!(gates.durable_forward_verified);
            assert!(gates.durable_inverse_verified);
            assert!(gates.durable_deterministic_verified);
            assert!(gates.stale_source_refusal_verified);
            assert!(gates.foreign_source_refusal_verified);
            assert!(gates.forged_result_artifact_refusal_verified);
            assert!(gates.refusal_verified);
            assert!(gates.partial_sink_verified);
            assert!(gates.zero_sink_verified);
            assert!(gates.source_hash_verified);
            assert!(gates.output_hash_verified);
            let sink = result.sink.expect("RTF paragraph publication sink");
            assert_eq!(sink.retained_output_bytes, Some(0));
            assert_eq!(
                sink.retained_authoring_window_bytes,
                Some(u64::try_from(RTF_LOGICAL_TAIL_SINK_WINDOW_BYTES).unwrap())
            );
            assert!(sink.largest_write <= 16 * 1024);
            assert_eq!(sink.accepted_bytes, evidence.output_bytes);
        }

        for variant in [RtfSemanticVariant::Byte1252, RtfSemanticVariant::Lzfu] {
            let corpus = build_semantic_rtf_corpus(SemanticShape::Tiny, variant).unwrap();
            assert!(!variant.supports_case(Case::RtfSemanticSplitParagraphSave));
            assert!(!variant.supports_case(Case::RtfSemanticMergeParagraphSave));
            assert!(run_case(Case::RtfSemanticSplitParagraphSave, &corpus, 0, 1).is_err());
            assert!(run_case(Case::RtfSemanticMergeParagraphSave, &corpus, 0, 1).is_err());
        }
    }

