    #[test]
    fn xlsx_tiny_corpus_is_deterministic_and_all_xlsx_cases_smoke() {
        let first = build_xlsx_corpus(XlsxShape::Tiny).unwrap();
        let second = build_xlsx_corpus(XlsxShape::Tiny).unwrap();

        assert_eq!(first.archive, second.archive);
        assert_eq!(first.manifest.generator, "litchi-xlsx-synthetic-v1");
        assert_eq!(first.manifest.package_format, "XLSX/OPC/ZIP");
        assert_eq!(first.manifest.entry_count, 192);
        assert_eq!(
            first.manifest.archive_sha256,
            "69ef199769a316eaa465a41ebf08f7a1b501f708775fabd7a084a90dc6a9b428"
        );
        let xlsx = first.manifest.xlsx.as_ref().unwrap();
        assert_eq!(xlsx.sheet_count, 3);
        assert_eq!(xlsx.rows_per_sheet, 8);
        assert_eq!(xlsx.columns_per_sheet, 8);
        assert_eq!(xlsx.one_percent_update_count, 2);
        assert_eq!(xlsx.source_members.workbook, "xl/workbook.xml");
        assert_eq!(
            xlsx.source_members.worksheets,
            [
                "xl/worksheets/sheet1.xml",
                "xl/worksheets/sheet2.xml",
                "xl/worksheets/sheet3.xml",
            ]
        );
        assert_eq!(xlsx.source_members.shared_strings, None);
        assert_eq!(xlsx.source_members.styles.as_deref(), Some("xl/styles.xml"));

        for case in Case::DEFAULT.into_iter().filter(|case| case.uses_xlsx()) {
            let measured = run_case(case, &first, 0, 1).unwrap();
            assert_eq!(measured.case, case.name());
            assert_eq!(measured.elapsed_ns.samples.len(), 1);
            if matches!(
                case,
                Case::XlsxSourceOpen
                    | Case::XlsxSourceListSheets
                    | Case::XlsxSourceFirstCell
                    | Case::XlsxSourceNarrowColumnRangeScan
            ) {
                let xlsx_source = measured.source.unwrap().xlsx.unwrap();
                assert_eq!(xlsx_source.workbook_read_calls.len(), 1);
                assert_eq!(xlsx_source.selected_worksheet_read_calls.len(), 1);
                assert_eq!(xlsx_source.unselected_worksheet_read_calls.len(), 1);
            }
        }

        let measured = run_case(Case::XlsxOneCellCommitFirstRead, &first, 0, 1).unwrap();
        assert_eq!(measured.case, "xlsx_one_cell_commit_first_read");
        assert_eq!(measured.elapsed_ns.samples.len(), 1);
    }

    #[test]
    fn xlsx_row_visibility_matched_controls_cover_single_and_bounded_batch() {
        assert_eq!(Case::DEFAULT.len(), 36);
        assert_eq!(XlsxRowVisibilityShape::ALL.len(), 2);
        assert_eq!(XlsxRowVisibilityShape::Medium.row_count(), 512);
        assert_eq!(XlsxRowVisibilityShape::Large.row_count(), 2_048);
        assert_eq!(
            parse_case("xlsx_eager_row_visibility_edit_save"),
            Some(Case::XlsxEagerRowVisibilityEditSave)
        );
        assert_eq!(
            parse_case("xlsx_source_backed_row_visibility_edit_save"),
            Some(Case::XlsxSourceBackedRowVisibilityEditSave)
        );
        assert_eq!(
            parse_case("xlsx_eager_row_visibility_batch_edit_save"),
            Some(Case::XlsxEagerRowVisibilityBatchEditSave)
        );
        assert_eq!(
            parse_case("xlsx_source_backed_row_visibility_batch_edit_save"),
            Some(Case::XlsxSourceBackedRowVisibilityBatchEditSave)
        );
        let visible =
            build_xlsx_row_visibility_corpus(XlsxRowVisibilityShape::Medium, false).unwrap();
        let hidden =
            build_xlsx_row_visibility_corpus(XlsxRowVisibilityShape::Medium, true).unwrap();
        assert_eq!(
            visible.archive,
            build_xlsx_row_visibility_corpus(XlsxRowVisibilityShape::Medium, false)
                .unwrap()
                .archive
        );
        assert_eq!(
            visible.manifest.generator,
            XLSX_ROW_VISIBILITY_SOURCE_EDIT_CORPUS_GENERATOR
        );
        assert!(visible.manifest.archive_member_count >= XLSX_CELL_VALUES_MEDIA_ENTRY_COUNT);
        assert_ne!(visible.archive, hidden.archive);
        let mut semantic_by_operation = BTreeMap::new();

        for (case, corpus, operation, update_count) in [
            (
                Case::XlsxEagerRowVisibilityEditSave,
                &visible,
                "hide-one",
                1,
            ),
            (
                Case::XlsxSourceBackedRowVisibilityEditSave,
                &visible,
                "hide-one",
                1,
            ),
            (
                Case::XlsxEagerRowVisibilityBatchEditSave,
                &hidden,
                "unhide-256",
                256,
            ),
            (
                Case::XlsxSourceBackedRowVisibilityBatchEditSave,
                &hidden,
                "unhide-256",
                256,
            ),
        ] {
            assert!(!Case::DEFAULT.contains(&case));
            let measured = run_case(case, corpus, 0, 1).unwrap();
            assert_eq!(measured.elapsed_ns.samples.len(), 1);
            assert_eq!(
                measured.sink.as_ref().unwrap().retained_output_bytes,
                Some(0)
            );
            let evidence = measured.source.unwrap().xlsx_row_visibility.unwrap();
            assert_eq!(evidence.operation, operation);
            assert_eq!(evidence.update_count, update_count);
            assert_eq!(evidence.open_ns.len(), 1);
            assert_eq!(evidence.plan_or_stage_ns.len(), 1);
            assert_eq!(evidence.commit_ns.len(), 1);
            assert_eq!(evidence.publication_ns.len(), 1);
            assert_eq!(evidence.lifecycle_ns.len(), 1);
            assert_eq!(evidence.output_sha256.len(), 1);
            assert_eq!(evidence.semantic_sha256.len(), 1);
            if let Some(previous) =
                semantic_by_operation.insert(operation, evidence.semantic_sha256[0].clone())
            {
                assert_eq!(previous, evidence.semantic_sha256[0]);
            }
            assert!(evidence.untouched_member_count > 0);
            assert!(evidence.gates.exact_output_verified);
            assert!(evidence.gates.semantic_reopen_verified);
            assert!(evidence.gates.untouched_member_preservation_verified);
            let source_only_gates = [
                evidence.gates.exact_noop_verified,
                evidence.gates.stale_source_refusal_verified,
                evidence.gates.foreign_source_refusal_verified,
                evidence.gates.protected_source_refusal_verified,
                evidence.gates.formula_source_refusal_verified,
                evidence.gates.markup_compatibility_source_refusal_verified,
                evidence.gates.macro_source_refusal_verified,
                evidence.gates.relationship_source_refusal_verified,
                evidence.gates.signed_source_refusal_verified,
                evidence.gates.partial_sink_verified,
                evidence.gates.zero_output_on_refusal_verified,
                evidence.gates.source_counter_gate_verified,
            ];
            if case.is_xlsx_row_visibility_source_backed() {
                assert!(source_only_gates.iter().all(|gate| *gate == Some(true)));
                assert!(evidence.source_read_calls[0] > 0);
                assert!(evidence.selected_worksheet_read_calls[0] > 0);
                assert_eq!(evidence.unselected_worksheet_read_calls[0], 0);
                assert!(evidence.source_version_calls[0] > 0);
            } else {
                assert!(source_only_gates.iter().all(Option::is_none));
                assert!(evidence.source_read_calls.is_empty());
                assert!(evidence.source_version_calls.is_empty());
            }
        }
    }

    #[test]
    fn xlsx_cell_values_matched_controls_are_deterministic_and_bounded() {
        let first = build_xlsx_cell_crud_corpus(XlsxCellCrudShape::Medium).unwrap();
        let second = build_xlsx_cell_crud_corpus(XlsxCellCrudShape::Medium).unwrap();
        assert_eq!(first.archive, second.archive);
        assert_eq!(
            first.manifest.generator,
            XLSX_CELL_VALUES_SOURCE_EDIT_CORPUS_GENERATOR
        );
        assert!(first.manifest.archive_member_count >= XLSX_CELL_VALUES_MEDIA_ENTRY_COUNT);
        let spec = first.xlsx.as_ref().unwrap();
        assert_eq!(spec.sheet_count, 4);
        assert_eq!(xlsx_cell_count(spec).unwrap(), 9_216);
        assert_eq!(spec.one_percent_updates.len(), 93);
        assert_eq!(XlsxCellCrudShape::ALL.len(), 2);
        let mut semantic_hashes = BTreeMap::new();

        for case in [
            Case::XlsxEagerCellValuesOneEditSave,
            Case::XlsxSourceBackedCellValuesOneEditSave,
            Case::XlsxEagerCellValuesOnePercentEditSave,
            Case::XlsxSourceBackedCellValuesOnePercentEditSave,
            Case::XlsxEagerCellValuesBatchEditSave,
            Case::XlsxSourceBackedCellValuesBatchEditSave,
            Case::XlsxSourceBackedCellValuesMultiSheetEditSave,
            Case::XlsxSourceBackedManagedCellValuesOneEditSave,
            Case::XlsxSourceBackedManagedCellValuesOnePercentEditSave,
            Case::XlsxSourceBackedManagedCellValuesBatchEditSave,
            Case::XlsxSourceBackedManagedCellValuesMultiSheetEditSave,
        ] {
            let measured = run_case(case, &first, 0, 1).unwrap();
            assert_eq!(measured.case, case.name());
            assert_eq!(measured.elapsed_ns.samples.len(), 1);
            assert!(measured.output_sha256.is_some());
            let measured_json = serde_json::to_value(&measured).unwrap();
            let sink = measured.sink.unwrap();
            assert!(sink.largest_write <= 64 * 1024, "{}", case.name());
            if case.is_xlsx_cell_values_edit_save() {
                assert_eq!(
                    measured.corpus.generator,
                    XLSX_CELL_VALUES_SOURCE_EDIT_CORPUS_GENERATOR
                );
            }
            if case.is_xlsx_cell_values_source_backed() {
                let json_evidence = &measured_json["source"]["xlsx_cell_values"];
                assert!(json_evidence.is_object(), "{}", case.name());
                assert!(json_evidence["pre_publication_budget"].is_array());
                assert!(json_evidence["post_publication_budget"].is_array());
                assert!(json_evidence["budget_objects_used_after_handles_drop"].is_array());
                assert!(json_evidence["output_budget_refusal"].is_object());
                let json_pre = &json_evidence["pre_publication_budget"][0];
                let json_post = &json_evidence["post_publication_budget"][0];
                for key in [
                    "input_bytes_used",
                    "input_bytes_limit",
                    "output_bytes_used",
                    "output_bytes_limit",
                    "work_used",
                    "work_limit",
                    "objects_used",
                    "objects_limit",
                    "catalog_reserved_objects",
                    "cache_reserved_objects",
                ] {
                    assert!(json_pre.get(key).is_some(), "missing pre key {key}");
                    assert!(json_post.get(key).is_some(), "missing post key {key}");
                }
                assert!(json_post["input_bytes_used"].is_u64());
                assert!(json_post["output_bytes_used"].is_u64());
                assert!(json_post["work_used"].is_u64());
                assert!(json_post["objects_used"].is_u64());
                assert!(json_post["catalog_reserved_objects"].is_null());
                assert!(json_post["cache_reserved_objects"].is_null());
                for key in [
                    "successful_output_ceiling",
                    "first_output_request_bytes",
                    "one_under_output_limit",
                    "accepted_output_bytes",
                    "source_read_calls",
                    "source_read_bytes",
                    "output_bytes_used",
                ] {
                    assert!(
                        json_evidence["output_budget_refusal"][key].is_u64(),
                        "missing numeric refusal key {key}"
                    );
                }
                for key in [
                    "typed_output_resource_refusal",
                    "zero_output_verified",
                    "source_identity_preserved",
                ] {
                    assert!(
                        json_evidence["output_budget_refusal"][key].is_boolean(),
                        "missing boolean refusal key {key}"
                    );
                }
                assert_eq!(json_evidence["budget_used_after_handles_drop"][0], 0);
                assert_eq!(
                    json_evidence["budget_objects_used_after_handles_drop"][0],
                    0
                );
                let source = measured.source.as_ref().expect("source evidence");
                let evidence = source
                    .xlsx_cell_values
                    .as_ref()
                    .expect("cell-values source evidence");
                assert_eq!(evidence.open_ns.len(), 1, "{}", case.name());
                assert_eq!(evidence.plan_ns.len(), 1, "{}", case.name());
                assert_eq!(evidence.commit_ns.len(), 1, "{}", case.name());
                assert_eq!(evidence.publication_ns.len(), 1, "{}", case.name());
                assert_eq!(evidence.reopen_ns.len(), 1, "{}", case.name());
                assert_eq!(
                    evidence.cache_budget_managed,
                    case.is_xlsx_cell_values_managed(),
                    "{}",
                    case.name()
                );
                if case.is_xlsx_cell_values_managed() {
                    for key in [
                        "input_bytes_used",
                        "input_bytes_limit",
                        "output_bytes_used",
                        "output_bytes_limit",
                        "work_used",
                        "work_limit",
                        "objects_used",
                        "objects_limit",
                        "catalog_reserved_objects",
                        "cache_reserved_objects",
                    ] {
                        assert!(json_pre[key].is_u64(), "managed pre key is not u64: {key}");
                    }
                    for key in [
                        "input_bytes_used",
                        "input_bytes_limit",
                        "output_bytes_used",
                        "output_bytes_limit",
                        "work_used",
                        "work_limit",
                        "objects_used",
                        "objects_limit",
                    ] {
                        assert!(
                            json_post[key].is_u64(),
                            "managed post key is not u64: {key}"
                        );
                    }
                    assert!(
                        evidence.budget_used_after_package_drop[0] > 0,
                        "{} did not retain a managed payload reservation",
                        case.name()
                    );
                    assert_eq!(evidence.pre_publication_budget.len(), 1);
                    assert_eq!(evidence.post_publication_budget.len(), 1);
                    let pre = evidence.pre_publication_budget[0];
                    let post = evidence.post_publication_budget[0];
                    assert_eq!(pre.output_bytes_used, 0, "{}", case.name());
                    assert_eq!(pre.input_bytes_limit, Some(u64::MAX));
                    assert_eq!(pre.work_limit, Some(u64::MAX));
                    assert_eq!(pre.objects_limit, Some(1_000_000));
                    assert!(pre.input_bytes_used > 0, "{}", case.name());
                    assert!(pre.work_used > 0, "{}", case.name());
                    assert!(pre.objects_used > 0, "{}", case.name());
                    assert!(pre.catalog_reserved_objects.is_some());
                    assert!(pre.cache_reserved_objects.is_some());
                    assert!(
                        pre.output_bytes_limit.is_some_and(|limit| limit > 0),
                        "{} has no finite OutputBytes limit",
                        case.name()
                    );
                    assert_eq!(pre.output_bytes_limit, post.output_bytes_limit);
                    assert_eq!(post.output_bytes_used, sink.accepted_bytes);
                    assert!(post.output_bytes_used > 0, "{}", case.name());
                    assert!(post.input_bytes_used >= pre.input_bytes_used);
                    assert!(post.work_used >= pre.work_used);
                    assert_eq!(post.input_bytes_limit, pre.input_bytes_limit);
                    assert_eq!(post.work_limit, pre.work_limit);
                    assert_eq!(post.objects_limit, pre.objects_limit);
                    assert!(post.objects_used > 0, "{}", case.name());
                    assert!(post.catalog_reserved_objects.is_none());
                    assert!(post.cache_reserved_objects.is_none());
                    let refusal = &evidence.output_budget_refusal;
                    assert_eq!(
                        refusal.successful_output_ceiling,
                        pre.output_bytes_limit.unwrap()
                    );
                    assert!(refusal.first_output_request_bytes > 0);
                    assert_eq!(
                        refusal.one_under_output_limit + 1,
                        refusal.first_output_request_bytes
                    );
                    assert_eq!(refusal.accepted_output_bytes, 0);
                    assert_eq!(refusal.output_bytes_used, 0);
                    assert!(refusal.typed_output_resource_refusal);
                    assert!(refusal.zero_output_verified);
                    assert!(refusal.source_identity_preserved);
                    assert!(refusal.source_read_calls > 0);
                    assert!(refusal.source_read_bytes > 0);
                } else {
                    assert_eq!(evidence.pre_publication_budget.len(), 1);
                    assert_eq!(evidence.post_publication_budget.len(), 1);
                    let pre = evidence.pre_publication_budget[0];
                    let post = evidence.post_publication_budget[0];
                    assert!(super::xlsx_cell_values_is_zero_budget_snapshot(pre));
                    assert!(super::xlsx_cell_values_is_zero_budget_snapshot(post));
                    assert_eq!(pre.catalog_reserved_objects, Some(0));
                    assert_eq!(pre.cache_reserved_objects, Some(0));
                    assert_eq!(evidence.output_budget_refusal, Default::default());
                    for key in [
                        "input_bytes_used",
                        "output_bytes_used",
                        "work_used",
                        "objects_used",
                    ] {
                        assert_eq!(json_pre[key], 0, "unmanaged pre usage is nonzero: {key}");
                        assert_eq!(json_post[key], 0, "unmanaged post usage is nonzero: {key}");
                    }
                    for key in [
                        "input_bytes_limit",
                        "output_bytes_limit",
                        "work_limit",
                        "objects_limit",
                    ] {
                        assert!(json_pre[key].is_null(), "unmanaged pre limit is set: {key}");
                        assert!(
                            json_post[key].is_null(),
                            "unmanaged post limit is set: {key}"
                        );
                    }
                    assert_eq!(json_pre["catalog_reserved_objects"], 0);
                    assert_eq!(json_pre["cache_reserved_objects"], 0);
                    assert!(json_post["catalog_reserved_objects"].is_null());
                    assert!(json_post["cache_reserved_objects"].is_null());
                    for key in [
                        "successful_output_ceiling",
                        "first_output_request_bytes",
                        "one_under_output_limit",
                        "accepted_output_bytes",
                        "source_read_calls",
                        "source_read_bytes",
                        "output_bytes_used",
                    ] {
                        assert_eq!(json_evidence["output_budget_refusal"][key], 0);
                    }
                    for key in [
                        "typed_output_resource_refusal",
                        "zero_output_verified",
                        "source_identity_preserved",
                    ] {
                        assert_eq!(json_evidence["output_budget_refusal"][key], false);
                    }
                }
                assert_eq!(evidence.budget_used_after_handles_drop, vec![0]);
                assert_eq!(evidence.budget_objects_used_after_handles_drop, vec![0]);
                assert_eq!(evidence.cache_budget_reservation_failures, vec![0]);
                assert!(evidence.untouched_member_count > 0);
                assert_eq!(evidence.output_sha256.len(), 1);
                assert_eq!(evidence.semantic_sha256.len(), 1);
                assert_eq!(evidence.source_read_bytes.len(), 1);
                let key = (evidence.update_count, evidence.selected_worksheet_count);
                let semantic = evidence.semantic_sha256[0].clone();
                if let Some(previous) = semantic_hashes.insert(key, semantic.clone()) {
                    assert_eq!(previous, semantic, "{} semantic mismatch", case.name());
                }
            }
        }
        assert_eq!(semantic_hashes.len(), 4);

        let dense_first = build_xlsx_cell_crud_corpus(XlsxCellCrudShape::DenseSparse).unwrap();
        let dense_second = build_xlsx_cell_crud_corpus(XlsxCellCrudShape::DenseSparse).unwrap();
        assert_eq!(dense_first.archive, dense_second.archive);
        let dense_spec = dense_first.xlsx.as_ref().unwrap();
        assert_eq!(dense_spec.row_count, 128);
        assert_eq!(dense_spec.column_count, 128);
        assert_eq!(xlsx_cell_count(dense_spec).unwrap(), 17_792);
        assert_eq!(dense_spec.one_percent_updates.len(), 178);
        assert!(dense_first.manifest.archive_member_count >= XLSX_CELL_VALUES_MEDIA_ENTRY_COUNT);
    }

    #[test]
    fn xlsx_cell_lifecycle_clear_and_remove_controls_are_matched_and_bounded() {
        let corpus = build_xlsx_cell_crud_corpus(XlsxCellCrudShape::Medium).unwrap();
        let cases = [
            Case::XlsxEagerCellClearEditSave,
            Case::XlsxSourceBackedCellClearEditSave,
            Case::XlsxEagerCellRemoveEditSave,
            Case::XlsxSourceBackedCellRemoveEditSave,
        ];
        let mut semantic_by_operation = BTreeMap::new();
        for case in cases {
            assert_eq!(parse_case(case.name()), Some(case));
            let measured = run_case(case, &corpus, 0, 1).unwrap();
            assert_eq!(measured.case, case.name());
            assert_eq!(measured.elapsed_ns.samples.len(), 1);
            let sink = measured.sink.as_ref().unwrap();
            assert_eq!(sink.retained_output_bytes, Some(0));
            assert!(sink.accepted_bytes > 0);
            let source = measured.source.unwrap();
            let evidence = source.xlsx_cell_values.unwrap();
            assert_eq!(evidence.open_ns.len(), 1);
            assert_eq!(evidence.plan_ns.len(), 1);
            assert_eq!(evidence.commit_ns.len(), 1);
            assert_eq!(evidence.publication_ns.len(), 1);
            assert_eq!(evidence.reopen_ns.len(), 1);
            assert_eq!(evidence.update_count, 1);
            assert_eq!(evidence.selected_worksheet_count, 1);
            assert_eq!(evidence.output_sha256.len(), 1);
            assert_eq!(evidence.semantic_sha256.len(), 1);
            assert_eq!(
                evidence.untouched_member_count > 0,
                case.is_xlsx_cell_lifecycle_source_backed()
            );
            if case.is_xlsx_cell_lifecycle_source_backed() {
                assert!(evidence.source_read_calls[0] > 0);
                assert!(evidence.source_read_bytes[0] > 0);
                assert!(evidence.payload_materializations[0] > 0);
                assert_eq!(evidence.implementation, "source-backed");
            } else {
                assert_eq!(evidence.source_read_calls, vec![0]);
                assert_eq!(evidence.source_read_bytes, vec![0]);
                assert_eq!(evidence.payload_materializations, vec![0]);
                assert_eq!(evidence.implementation, "eager");
            }
            let operation = if case.is_xlsx_cell_lifecycle_remove() {
                "remove"
            } else {
                "clear"
            };
            if let Some(previous) =
                semantic_by_operation.insert(operation, evidence.semantic_sha256[0].clone())
            {
                assert_eq!(previous, evidence.semantic_sha256[0]);
            }
        }
        assert_eq!(semantic_by_operation.len(), 2);
    }

